// translations of Sua's scenes (ep_sua.js); built by build_sua.py
window.T=window.T||{};
T.en=T.en||{};Object.assign(T.en,{"아침. 수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "Morning. Sua was at the front of the classroom, checking something off with a highlighter. I went over to her.", "수아야. 규칙…… 외워 왔어.": "Sua. I... memorized the rules.", "진짜? 그럼 확인해 볼까.": "Really? Then let's check.", "수아가 형광펜 뚜껑을 딸깍 닫았다.": "Sua clicked the cap back onto her highlighter.", "규칙 3번.": "Rule 3.", "교실에서 뛰지 않기.": "No running in the classroom.", "5번.": "Rule 5.", "친구 밀지 않기.": "No pushing friends.", "오, 좀 하는데? 그럼 7번.": "Oh, not bad. Then Rule 7.", "비상시에는 {@handkerchief}으로 입을 막고, 자세를 낮춰 이동한다.": "In an emergency, cover your mouth with a {@handkerchief} and keep low as you move.", "완벽해.": "Perfect.", "(……근데 ‘자세를 낮춰’가 무슨 뜻이지? 소리만 외웠어.)": "(...But what does 'keep low' mean? I only memorized the sounds.)", "삐— 삐— 삐—!": "Beep! Beep! Beep!", "방송: 「지금부터 화재 대피 훈련을 시작합니다. 담임 선생님의 안내에 따라…….」": "Announcement: \"We will now begin the fire drill. Please follow your homeroom teacher's directions...\"", "아이들이 한꺼번에 일어났다. 선생님은 교실 뒤에서 남은 아이가 없는지 확인하고 계셨다.": "All the kids stood up at once. The teacher was at the back of the room, checking that no one was left behind.", "규칙 7번! {@handkerchief} 꺼내! 입 막고, 자세 낮추고, 오른쪽 {@stairs}!": "Rule 7! Take out your {@handkerchief}! Cover your mouth, keep low, right {@stairs}!", "수아 말이 너무 빨랐다. 아이들이 줄줄이 복도로 나갔다.": "Sua talked way too fast. The kids filed out into the hallway one after another.", "({@handkerchief}…… {@handkerchief}이 뭐였지?)": "({@handkerchief}... What was a {@handkerchief} again?)", "{@handkerchief}으로 입을 막았다. 그런데 ‘자세를 낮춰’는 아직도 모르겠다. 앞 친구들은 벌써 복도 끝에 있었다.": "I covered my mouth with my {@handkerchief}. But I still didn't know what 'keep low' meant. The kids in front were already at the end of the hallway.", "왜 안 와? 내가 7번 말했잖아!": "Why aren't you coming? I said Rule 7!", "(외운 건 맞는데…… 뜻을 몰라.)": "(I did memorize it... I just don't know what it means.)", "「{x}」으로 내려가기": "Go down the 「{x}」", "운동장. 훈련이 끝났다. 수아가 출석부를 들고 내 옆으로 왔다.": "The playground. The drill was over. Sua came over to me with the attendance book.", "아까 ‘낮춰’ 몰랐던 거지? 이렇게, 몸을 낮게.": "You didn't know 'keep low' back there, right? Like this. Get your body low.", "……응. 이제 알아.": "...Yeah. I get it now.", "규칙은 외우면 끝인 줄 알았어. 뜻을 모를 수도 있구나.": "I thought memorizing the rules was enough. I didn't know you might not get what they mean.", "반장은 이런 것까지 다 챙겨야 해. 생각보다 어려워.": "A class president has to think about stuff like this too. It's harder than it looks.", "알아. 그래서 나도 하고 싶어.": "I know. That's why I want to do it too.", "……뭐?": "...What?", "나도 반장 선거 나갈 거야.": "I'm running for class president too.", "수아가 나를 빤히 봤다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "Sua stared at me. Then she clicked the cap back onto her highlighter.", "좋아. 그럼 경쟁이네.": "Fine. Then we're rivals.", "근데 너, 아까 뭐가 어려웠는지는 나보다 잘 알겠다.": "But you probably know better than me what was hard back there.", "그 자리에서 수아에게 묻는다. 「천천히! ‘낮춰’가 뭐야?」": "Ask Sua right there. \"Slow down! What does 'keep low' mean?\"", "수아야, 천천히! ‘자세를 낮춰’가 뭐야?": "Sua, slow down! What does 'keep low' mean?", "수아가 멈칫했다. 그러더니 바로 허리를 숙여 보였다.": "Sua stopped for a second. Then she bent over at the waist to show me.", "이렇게! 몸을 낮게. 연기는 위로 올라가니까.": "Like this! Get your body low. Because smoke goes up.", "아! 낮춰!": "Oh! Keep low!", "나는 허리를 숙이고 수아 옆에서 오른쪽 {@stairs}으로 걸었다.": "I bent over and walked next to Sua to the right {@stairs}.", "뛰지 마. 걸어.": "Don't run. Walk.", "알아. 3번.": "I know. Rule 3.", "아는 척 고개를 끄덕이고 앞 친구를 따라 한다.": "Nod like you know and copy the kid in front.", "나는 고개를 끄덕이고 바로 앞 친구를 따라 했다. 그런데 그 친구는 쪼그려 앉아서 뒤뚱뒤뚱 걷고 있었다.": "I nodded and copied the kid right in front of me. But that kid was squatting down and waddling along.", "그건 오리걸음이잖아!": "That's a duck walk!", "앞 친구는 장난을 치던 거였다. 나는 얼굴이 빨개졌다.": "The kid in front was just goofing around. My face turned red.", "허리만 숙여. 이렇게.": "Just bend at the waist. Like this.", "(모르는데 아는 척하니까 더 이상해졌어.)": "(I pretended to know when I didn't, and it got even weirder.)", "내 나라에서 했던 훈련을 떠올려 판단한다.": "Think back to the drills in your country and figure it out.", "(우리 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "(We did this at my school too. When there's a fire, smoke goes up, so we bent down.)", "(‘낮춰’는 그거구나!)": "(So that's what 'keep low' means!)", "나는 허리를 숙이고, 벽에 붙은 초록색 비상구 {@picture}을 따라 {@stairs} 쪽으로 걸었다.": "I bent over and followed the green emergency exit {@picture} on the wall toward the {@stairs}.", "수아가 뒤돌아보다가 눈을 동그랗게 떴다.": "Sua looked back and her eyes went wide.", "어? 맞게 하네?": "Huh? You're doing it right?", "우리 학교에서도 했어.": "We did this at my school too.", "「너 말 너무 빨라!」 하고 화부터 낸다.": "Get angry first. \"You talk way too fast!\"", "너 말 너무 빨라! 하나도 몰라!": "You talk way too fast! I don't get any of it!", "지금 훈련 중이야! 그냥 따라와!": "We're in the middle of a drill! Just follow me!", "수아가 내 팔을 잡아끌었다. 둘 다 얼굴이 빨개진 채로 {@stairs}까지 갔다.": "Sua grabbed my arm and pulled me along. We both went red in the face all the way to the {@stairs}.", "(화는 났는데, ‘낮춰’는 아직도 몰라.)": "(I got mad, but I still don't know what 'keep low' means.)", "{m}, 오늘 대피 훈련 했어. 어제 외운 규칙 7번이 나왔어.": "{m}, we had a fire drill today. Rule 7, the one I memorized yesterday, came up.", "어머, 바로 써먹었네?": "Oh my, you used it right away?", "근데 나 ‘자세를 낮춰’가 무슨 뜻인지 몰랐어. 소리만 외웠거든.": "But I didn't know what 'keep low' meant. I'd only memorized the sounds.", "그래서 수아한테 천천히 말해 달라고, 낮춰가 뭐냐고 물었어. 수아가 허리 숙여서 보여 줬어.": "So I asked Sua to talk slowly and asked what 'keep low' meant. Sua bent over to show me.", "모르는 거 그 자리에서 물어봤구나. {m}가 첫날 말한 거 기억했네.": "You asked about what you didn't know right then. You remembered what {m} said on your first day.", "응. 물어보니까 금방이었어.": "Yeah. Once I asked, it was quick.", "아는 척하고 앞에 애를 따라 했는데, 걔가 오리걸음으로 장난치는 거였어.": "I pretended to know and copied the kid in front, but he was goofing around doing a duck walk.", "너도 오리걸음 했어?": "You did a duck walk too?", "{m}! 웃지 마. 수아가 그건 오리걸음이라고 소리쳤어.": "{m}! Don't laugh. Sua yelled that it was a duck walk.", "미안, 미안. 모를 땐 그냥 물어봐도 돼.": "Sorry, sorry. When you don't know, it's okay to just ask.", "우리 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "I remembered the drills we did at my school. We bent down because of the smoke. So I did it right.", "아, 거기서도 했었지! 기억하고 있었구나.": "Oh, you did those there too! You remembered.", "수아가 어? 맞게 하네? 그러더라.": "Sua said, \"Huh? You're doing it right?\"", "모르는 말도 아는 걸로 알아낼 수 있구나.": "So you can figure out words you don't know with things you already know.", "수아한테 너무 빠르다고 화냈어. 수아도 지금 훈련 중이라고 화냈고.": "I got mad at Sua for being too fast. Sua got mad too, saying we were in the middle of a drill.", "둘 다 급했구나.": "You were both in a hurry.", "응. 나중에 수아가 낮춰가 뭔지 알려 줬어.": "Yeah. Later Sua told me what 'keep low' meant.", "다음엔 화내기 전에 ‘천천히’부터 말해 볼까?": "Next time, how about saying 'slow down' before getting mad?", "그리고 {m}. 나 수아한테 반장 선거 나간다고 말했어.": "And {m}, I told Sua I'm running for class president.", "정말? 수아가 뭐래?": "Really? What did Sua say?", "좋아, 그럼 경쟁이네, 그랬어.": "She said, \"Fine. Then we're rivals.\"", "멋있는 경쟁자네.": "What a cool rival.", "도서관 구석 {@desk}. 수아가 큰 {@paper}를 펼쳐 놓고 있었다. 나는 수아 맞은편에 앉았다.": "A {@desk} in the corner of the library. Sua had a big {@paper} spread out. I sat down across from her.", "수아야, 뭐 해?": "Sua, what are you doing?", "규칙표 다시 만들어. {@picture}으로.": "Making the rules chart again. With {@picture}s.", "어제 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "There might be other kids who only memorized the sounds, like you did at the drill yesterday.", "……그거 좋다.": "...That's a good idea.", "같이 할래? 내가 글 쓰고, 넌 {@picture}.": "Want to do it together? I'll write, and you do the {@picture}s.", "좋아.": "Okay.", "「{x}」 고르기": "Pick 「{x}」", "수아는 정말 빨랐다. 순식간에 문장 다섯 개를 써 내려갔다.": "Sua was really fast. She wrote five sentences in no time.", "1번, 3번, 5번은 읽을 수 있었다. 그런데 7번 아래 새로 쓴 문장 하나가 걸렸다.": "I could read numbers 1, 3 and 5. But one new sentence under number 7 stopped me.", "{@paper}에 쓰인 글: 「연기가 나면 몸을 낮추고 벽을 짚으며 이동한다.」": "Writing on the {@paper}: \"If there is smoke, keep low and move while feeling along the wall.\"", "(낮추고는 알아. 근데 ‘벽을 짚으며’는 뭐지?)": "(I know 'keep low.' But what's 'feeling along the wall'?)", "자, {@picture} 그리면 돼. 쉬는 시간 10분 남았어.": "Okay, you just draw the {@picture}s. We have 10 minutes of break left.", "수아는 벌써 다음 줄을 쓰고 있었다.": "Sua was already writing the next line.", "그러다 수아가 {@stairs} {@picture}을 직접 그려 보겠다며 펜을 들었다. {@paper}에 꼬불꼬불한 선이 생겼다.": "Then Sua picked up a pen, saying she'd try drawing the {@stairs} {@picture} herself. Squiggly lines appeared on the {@paper}.", "……그건 뭐야?": "...What's that?", "{@stairs}.": "{@stairs}.", "빨래판인 줄 알았어.": "I thought it was a washboard.", "……그러니까 네가 그려.": "...So you draw it.", "({@picture}은 내가 잘할 수 있어. 근데 ‘짚으며’를 모르면 뭘 그려야 하지?)": "(I'm good at {@picture}s. But if I don't know 'feeling along,' what am I supposed to draw?)", "쉬는 시간이 끝나기 전에 규칙표가 완성됐다. 수아는 맨 아래에 두 사람 이름을 나란히 적었다.": "The rules chart was finished before the break ended. Sua wrote our two names side by side at the bottom.", "정리하면, 글은 나, {@picture}은 너.": "So, to sum up, the writing is me, the {@picture}s are you.", "{@stairs}도 나.": "The {@stairs} too.", "……{@stairs}도 너.": "...The {@stairs} too, you.", "아는 문장만 그리고, 모르는 문장 칸은 비워 둔다.": "Draw only the sentences you know, and leave the ones you don't know blank.", "나는 1번, 3번, 5번만 그렸다. 7번 칸은 비워 뒀다.": "I only drew numbers 1, 3 and 5. I left the box for number 7 blank.", "7번은?": "What about 7?", "……그건 나중에.": "...Later.", "제일 중요한 건데?": "But that's the most important one!", "‘짚으며’를 몰라서.": "I don't know what 'feeling along' means.", "아, 그래? 그럼 처음부터 말하지.": "Oh, really? You should've said so from the start.", "모르는 말에 동그라미를 치고 묻는다. 「이거 무슨 뜻이야?」": "Circle the word you don't know and ask. \"What does this mean?\"", "나는 ‘짚으며’에 {@pencil}로 동그라미를 쳤다.": "I circled 'feeling along' with my {@pencil}.", "이거 무슨 뜻이야?": "What does this mean?", "벽을 짚으며? {@hand}을 벽에 대고 가는 거.": "Feeling along the wall? It means you walk with your {@hand} on the wall.", "수아가 손바닥을 책장에 붙여 보였다.": "Sua pressed her palm against the bookshelf to show me.", "아! 그럼 {@hand}을 벽에 대고, 허리 숙이고, 걷는 사람.": "Oh! So a person with a {@hand} on the wall, bent over, walking.", "응. 그거.": "Yeah. That.", "나는 그 모습을 그렸다. 수아가 {@picture}을 보더니 고개를 끄덕였다.": "I drew it like that. Sua looked at the {@picture} and nodded.", "내가 이해한 대로 먼저 그려서 보여 준다. 「이거 맞아?」": "Draw it the way you understood it first and show her. \"Is this right?\"", "나는 내가 이해한 대로 그렸다. 연기 아래에서 바닥을 짚고 엉금엉금 기어가는 사람.": "I drew it the way I understood it. A person crawling on all fours under the smoke, feeling along the floor.", "이거 맞아?": "Is this right?", "……기어가라는 게 아니고!": "...Not crawling!", "수아가 웃음을 터뜨렸다. 도서관이라 둘 다 입을 막았다.": "Sua burst out laughing. We were in the library, so we both covered our mouths.", "바닥 말고 벽. {@hand}을 벽에 대고 걷는 거야.": "Not the floor, the wall. You walk with your {@hand} on the wall.", "아, 벽! 그럼 이렇게?": "Oh, the wall! Then like this?", "나는 {@picture}을 고쳤다. 수아가 {@picture}을 보더니 자기 문장을 다시 봤다.": "I fixed the {@picture}. Sua looked at the {@picture}, then looked at her sentence again.", "{@picture} 보니까 내 문장이 너무 기네. 줄일게.": "Looking at the {@picture}, my sentence is too long. I'll make it shorter.", "「수아야, 그냥 네가 다 해. 넌 다 잘하잖아.」": "\"Sua, just do it all yourself. You're good at everything.\"", "그냥 네가 다 해. 넌 다 잘하잖아.": "Just do it all yourself. You're good at everything.", "나 {@picture} 못 그리는 거 방금 봤잖아.": "You just saw me fail at drawing {@picture}s.", "……그래도.": "...Still.", "그래도는 무슨. 빨래판 {@stairs} 붙일 거야?": "Still what? You want to put up washboard {@stairs}?", "수아가 {@colored_pencil} 통을 내 쪽으로 밀었다.": "Sua pushed the box of {@colored_pencil}s over to me.", "네가 그려. 모르는 거 있으면 물어보고.": "You draw. If there's something you don't know, ask.", "{m}, 수아랑 규칙표 만들었어. 수아가 글 쓰고 내가 {@picture} 그렸어.": "{m}, Sua and I made a rules chart. Sua wrote and I drew the {@picture}s.", "오, {@picture}은 네가?": "Oh, you did the {@picture}s?", "응. 수아 {@picture} 진짜 못 그려. {@stairs}을 그렸는데 빨래판 같았어.": "Yeah. Sua is really bad at {@picture}s. She drew {@stairs} and it looked like a washboard.", "수아도 못하는 게 있구나.": "So there are things even Sua can't do.", "근데 나 모르는 말이 있어서 그 칸은 비워 뒀어. 수아가 제일 중요한 거라고, 처음부터 말하지 그랬냐고 하더라.": "But there was a word I didn't know, so I left that box blank. Sua said it was the most important one and asked why I didn't say so from the start.", "그럼 그 칸은 어떻게 했어?": "So what did you do with that box?", "결국 물어보고 그렸어.": "In the end, I asked and drew it.", "처음부터 물었으면 더 빨랐겠다.": "It would've been faster if you'd asked from the start.", "‘짚으며’를 몰라서 동그라미 치고 물어봤어. 수아가 {@hand}을 책장에 대고 보여 줬어.": "I didn't know 'feeling along,' so I circled it and asked. Sua put her {@hand} on the bookshelf to show me.", "그래서 {@picture}이 맞게 됐어?": "So did the {@picture} come out right?", "응. 수아가 고개 끄덕였어.": "Yeah. Sua nodded.", "내가 이해한 대로 그렸는데, 사람이 바닥을 기어가고 있었어.": "I drew it the way I understood it, and the person was crawling on the floor.", "기어가?": "Crawling?", "수아가 기어가라는 게 아니고! 하면서 웃었어. 근데 수아가 {@picture} 보더니 자기 문장이 너무 길대. 줄였어.": "Sua laughed and said, \"Not crawling!\" But then she looked at the {@picture} and said her sentence was too long. She made it shorter.", "{@picture} 덕분에 글도 바뀌었네.": "Thanks to the {@picture}, the writing changed too.", "수아한테 그냥 네가 다 하라고 했어. 넌 다 잘하니까.": "I told Sua to just do it all herself. Because she's good at everything.", "수아가 뭐래?": "What did Sua say?", "빨래판 {@stairs} 붙일 거냐고. 그래서 내가 그렸어.": "She asked if I wanted to put up washboard {@stairs}. So I drew them.", "수아 말이 맞네. {@picture}은 네가 더 잘하잖아.": "Sua's right. You're better at {@picture}s.", "방금 학급회의가 끝났다. 안건은 ‘금요일 학급 놀이 시간에 뭐 할까’였다.": "The class meeting had just ended. The topic was \"What should we do at Friday's class game time?\"", "나는 처음으로 {@hand}을 들고 우리 나라 놀이를 말했다. 떨려서 말이 엉켰다.": "For the first time, I raised my {@hand} and talked about a game from my country. I was nervous, and my words got all tangled.", "(아까 수아가 한 말) 「음…… 규칙이 복잡해 보여서 어려울 것 같아요. 다음 의견!」": "(What Sua said earlier) \"Um... the rules look complicated, so I think it'd be hard. Next idea!\"", "결국 피구로 정해졌다. 아이들이 {@chair}를 정리하며 흩어졌다. 나는 수아에게 갔다.": "In the end, we picked dodgeball. The kids put away their {@chair}s and scattered. I went over to Sua.", "「{x}」 넣기": "Put in 「{x}」", "수아야, 아까 내 놀이…….": "Sua, about my game earlier...", "아, 그거! 나도 얘기하려고 했어.": "Oh, that! I was going to talk to you about it too.", "수아가 주위를 한 번 둘러보더니 목소리를 낮췄다.": "Sua looked around once and lowered her voice.", "……사실 나, 하나도 못 알아들었어.": "...Actually, I didn't understand any of it.", "어?": "Huh?", "네가 말할 때 ‘수건’이랑 ‘같은 편’은 들렸는데, 나머지는 몰랐어. 근데 반장이 못 알아들었다고 하면 이상하잖아.": "When you were talking, I heard 'handkerchief' and 'same team,' but I didn't get the rest. But it'd be weird if the class president said she didn't understand.", "그래서 그냥 어렵다고 넘긴 거야.": "So I just said it looked hard and moved on.", "(수아도…… 나를 못 알아들었구나.)": "(Sua... didn't understand me either.)", "(대피 훈련 때 내가 수아 말을 못 알아들은 거랑 똑같네.)": "(It's just like when I didn't understand Sua at the fire drill.)", "다시 설명해 줄래? 이번엔 진짜 들을게.": "Can you explain it again? This time I'll really listen.", "수아가 형광펜을 꺼내 학급회의 {w}에 적었다.": "Sua took out her highlighter and wrote in the class meeting {w}.", "수아의 {w}: 「다음 학급회의 안건: 같은 편 {@handkerchief} 놀이」": "Sua's {w}: \"Next class meeting topic: Same-Team {@handkerchief} game\"", "다음 회의에 다시 올리자. 이번엔 제대로.": "Let's bring it up again at the next meeting. Properly this time.", "어떻게 설명할까?": "How should I explain it?", "「말보다 해 보는 게 빨라.」 하고 직접 보여 준다.": "\"It's faster to try it than to talk about it.\" Show her.", "말보다 해 보는 게 빨라. 앉아 봐.": "It's faster to try it than to talk about it. Sit down.", "나는 수아를 {@chair}에 앉히고 등 뒤로 돌아가 {@handkerchief}을 살짝 놓았다.": "I sat Sua down on a {@chair}, went around behind her, and quietly dropped the {@handkerchief}.", "이제 뒤에 뭐 있는지 봐.": "Now look what's behind you.", "어? {@handkerchief}?": "Huh? A {@handkerchief}?", "그럼 날 잡아야 해. 잡히면 나는 술래 아니고, 네 편이 돼.": "Then you have to catch me. If I get caught, I'm not \"it.\" I join your team.", "……잡히면 같은 편? 그게 다야?": "...If you get caught, you're on the same team? That's it?", "응. 마지막엔 다 같은 편이야.": "Yeah. At the end, everyone's on the same team.", "아, 이거 재밌겠다!": "Oh, this sounds fun!", "「됐어. 어차피 안 된다며.」 하고 돌아선다.": "\"Forget it. You said it won't work anyway.\" Turn away.", "됐어. 어차피 안 된다며.": "Forget it. You said it won't work anyway.", "아니, 그래서 지금 다시…….": "No, that's why I'm asking again now...", "피구로 정해졌잖아.": "We already picked dodgeball.", "나는 {@bag}을 챙겼다. 수아는 형광펜을 만지작거리며 서 있었다.": "I packed my {@bag}. Sua stood there fiddling with her highlighter.", "……다음 학급회의 때 다시 올리면 돼. 마음 바뀌면 말해 줘.": "...We can bring it up again at the next class meeting. Tell me if you change your mind.", "(속상한 건 맞아. 근데 수아는 진짜 듣고 싶어 했는데.)": "(I am upset. But Sua really wanted to listen.)", "아까 못 한 말까지 한꺼번에 몰아서 설명한다.": "Explain everything at once, including what you couldn't say earlier.", "그러니까 동그랗게 앉아서 술래가 돌다가 {@handkerchief}을 뒤에 놓으면 그걸 알아채서 쫓아가는데 잡히면 술래가 안 되고 잡은 사람 편이 되고 그다음엔 그 편이 같이 술래를…….": "So you sit in a circle and \"it\" goes around and drops the {@handkerchief} behind someone and they notice and chase and if they get caught they don't become \"it\" they join the catcher's team and then that team together is \"it\" and...", "잠깐, 잠깐! 너도 빨라!": "Wait, wait! You're fast too!", "수아가 두 {@hand}을 들었다. 우리 둘 다 웃음이 터졌다.": "Sua held up both {@hand}s. We both burst out laughing.", "……대피 훈련 때 너 같았어?": "...Was I like that at the fire drill?", "응. 딱 나 같았어.": "Yeah. Exactly like me.", "나는 처음부터 다시, 한 문장씩 천천히 말했다.": "I started over from the beginning, saying it slowly, one sentence at a time.", "아까 속상했던 것부터 말하고, 그다음 설명한다.": "First say you were upset earlier, then explain.", "설명할게. 근데 먼저 말할 거 있어.": "I'll explain. But there's something I want to say first.", "아까 바로 다음 의견, 해서 좀 속상했어. 처음으로 {@hand} 들었거든.": "When you said \"Next idea\" right away, I was kind of upset. It was my first time raising my {@hand}.", "……그랬구나. 미안. 못 알아들은 거 들킬까 봐 빨리 넘긴 거야.": "...I see. Sorry. I moved on fast because I was afraid you'd find out I didn't understand.", "이제 천천히 할게. 동그랗게 앉아. 술래가 {@handkerchief}을 뒤에 놓아. 잡히면 같은 편이 돼.": "I'll go slowly now. Sit in a circle. \"It\" drops the {@handkerchief} behind someone. If you get caught, you join the same team.", "세 문장이네. 정리 잘한다.": "Three sentences. You're good at summing up.", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. 우리 나라 놀이 하자고.": "{m}, at the class meeting today I raised my {@hand} for the first time. I said we should play a game from my country.", "정말? 어떻게 됐어?": "Really? How did it go?", "수아가 어려울 것 같다고 바로 다음 의견 했어. 근데 끝나고 수아가 사실 하나도 못 알아들었대.": "Sua said it looked hard and went right to the next idea. But afterward Sua said she actually didn't understand any of it.", "어머, 수아가 그렇게 말했어?": "Oh my, Sua said that?", "그래서 말 말고 직접 보여 줬어. 수아를 앉히고 {@handkerchief} 놓았지.": "So I didn't explain with words, I showed her. I sat Sua down and dropped the {@handkerchief}.", "수아는?": "And Sua?", "이거 재밌겠다! 그랬어.": "She said, \"Oh, this sounds fun!\"", "해 보니까 금방 알았구나.": "Once she tried it, she got it right away.", "근데 나 너무 속상해서 됐다고 하고 그냥 왔어.": "But I was so upset that I said forget it and just left.", "속상했겠다. 처음 {@hand} 든 거였잖아.": "You must have been upset. It was your first time raising your {@hand}.", "응. 수아가 다음 회의 때 다시 올리면 된대.": "Yeah. Sua said we can bring it up again at the next meeting.", "그럼 다음엔 어떻게 할래?": "So what will you do next time?", "아까 못 한 말 한꺼번에 막 했더니, 수아가 너도 빨라! 그랬어.": "I said everything I couldn't say earlier all at once, and Sua said, \"You're fast too!\"", "대피 훈련 때랑 반대네?": "The opposite of the fire drill?", "응. 둘이 웃었어. 그다음엔 천천히 했어.": "Yeah. We both laughed. After that I went slowly.", "속상했다고 먼저 말했어. 수아가 미안하대. 못 알아들은 거 들킬까 봐 그랬대.": "I said first that I was upset. Sua said sorry. She said she was afraid I'd find out she didn't understand.", "수아도 솔직하게 말했네.": "Sua was honest too.", "그러고 세 문장으로 설명했더니 정리 잘한대.": "Then I explained in three sentences, and she said I'm good at summing up.", "반장도 못 알아들을 때가 있구나.": "So even the class president doesn't understand sometimes.", "응. 나만 그런 줄 알았어.": "Yeah. I thought it was just me.", "점심시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "Lunchtime. Sua had the class meeting {w} open. I sat down next to her.", "다음 학급회의 내일이야. 놀이 발표 준비하자.": "The next class meeting is tomorrow. Let's get ready to present the game.", "「{x}」 보기": "Look at 「{x}」", "학급회의는 한 사람이 2분 안에 말해야 해. 규칙 12번.": "At class meetings, each person has to finish talking in 2 minutes. Rule 12.", "그래서 생각해 봤는데, 발표는 내가 할게.": "So I was thinking, I'll do the presentation.", "……네가?": "...You?", "응. 나는 2분 안에 정리할 수 있어. 넌 아직 한국말이 느리잖아. 떨어지면 아깝잖아.": "Yeah. I can sum it up in 2 minutes. Your Korean is still slow. It'd be a shame if it got voted down.", "수아 말은 틀린 데가 없었다. 그래서 더 할 말이 없었다.": "Nothing Sua said was wrong. That's why I had nothing more to say.", "(맞는 말이야. 수아가 하면 통과될 거야.)": "(She's right. If Sua does it, it'll pass.)", "(근데…… 내 놀이인데.)": "(But... it's my game.)", "종이 울렸다. 수아가 형광펜 뚜껑을 딸깍 닫았다.": "The bell rang. Sua clicked the cap back onto her highlighter.", "내일 떨지 마.": "Don't be nervous tomorrow.", "너도.": "You too.", "나는 안 떨어.": "I don't get nervous.", "「그럼…… 네가 해.」": "\"Then... you do it.\"", "그럼…… 네가 해.": "Then... you do it.", "좋아. 내가 깔끔하게 정리할게.": "Good. I'll sum it up neatly.", "수아가 형광펜으로 줄을 그었다. 나는 옆에서 고개만 끄덕였다.": "Sua drew lines with her highlighter. I just nodded beside her.", "(이게 맞는 건가.)": "(Is this right?)", "「내가 할게. 대신 2분 맞추는 연습 같이 해 줘.」": "\"I'll do it. But practice keeping it to 2 minutes with me.\"", "내가 할게. 내 놀이니까.": "I'll do it. Because it's my game.", "2분 넘으면?": "What if it goes over 2 minutes?", "그러니까 연습 같이 해 줘. 네가 {@clock} 봐 줘.": "That's why you should practice with me. You watch the {@clock}.", "수아가 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "Sua watched the {@clock}. I explained from the beginning. It went over 3 minutes.", "정리하면, 세 문장만 해. 앉는다. 놓는다. 잡히면 같은 편.": "So, to sum up, just say three sentences. Sit down. Drop it. If you get caught, same team.", "다시 했다. 1분 50초.": "I did it again. 1 minute 50 seconds.", "……됐네.": "...That works.", "「넌 그냥 반장이라서 다 하고 싶은 거잖아.」": "\"You just want to do everything because you're class president.\"", "넌 그냥 반장이라서 다 하고 싶은 거잖아.": "You just want to do everything because you're class president.", "뭐? 나는 통과되라고 그런 건데!": "What? I did it so it would pass!", "내 놀이인데 왜 네가 해?": "It's my game, so why are you doing it?", "둘 다 목소리가 커졌다. 옆에서 밥 먹던 아이들이 쳐다봤다.": "We both got loud. The kids eating nearby looked over at us.", "……그럼 네가 해 봐. 2분 넘으면 내가 {@hand} 들 거야.": "...Then you try it. If it goes over 2 minutes, I'll raise my {@hand}.", "「나눠서 하자. 시범은 내가, 규칙 설명은 네가.」": "\"Let's split it. I'll do the demo, you explain the rules.\"", "나눠서 하자. 시범은 내가 보여 줄게. 규칙 설명은 네가 해.": "Let's split it. I'll show the demo. You explain the rules.", "시범?": "A demo?", "말로 하면 애들이 못 알아들어. 너도 못 알아들었잖아.": "If we just use words, the kids won't get it. You didn't get it either.", "……그건 맞아.": "...That's true.", "수아가 {w}에 두 칸을 그었다. 한쪽에 ‘시범’, 한쪽에 ‘규칙’.": "Sua drew two boxes in the {w}. One said \"Demo,\" the other said \"Rules.\"", "그럼 넌 몸으로, 난 말로.": "So you use your body, and I use words.", "{m}, 내일 학급회의에서 우리 나라 놀이 다시 발표해.": "{m}, I'm presenting the game from my country again at the class meeting tomorrow.", "오, 누가 발표해?": "Oh, who's presenting?", "수아가 자기가 하겠대. 나는 한국말이 느려서 2분 안에 못 할 거래.": "Sua said she'll do it. She said my Korean is slow, so I can't do it in 2 minutes.", "음…… 그래서?": "Hmm... so?", "그럼 네가 하라고 했어.": "I told her to do it.", "수아가 하는 게 더 나을 것 같았어?": "Did you think it'd be better if Sua did it?", "응. 근데 좀 이상해. 내 놀이인데.": "Yeah. But it feels kind of weird. It's my game.", "그 마음이 드는 게 당연하지.": "Of course you'd feel that way.", "내가 한다고 했어. 대신 수아한테 {@clock} 봐 달라고 했어.": "I said I'd do it. But I asked Sua to watch the {@clock}.", "몇 분 걸렸어?": "How long did it take?", "처음엔 3분. 수아가 세 문장만 하라고 해서 1분 50초 됐어.": "3 minutes at first. Sua told me to just say three sentences, and it became 1 minute 50 seconds.", "수아는 시간 재 주고, 너는 발표하고. 둘이 잘 나눴네.": "Sua kept time and you presented. You two split it up well.", "너는 반장이라서 다 하고 싶은 거라고 했어. 수아도 화냈어.": "I said she just wants to do everything because she's class president. Sua got mad too.", "수아는 무슨 마음이었을까?": "What do you think Sua was feeling?", "통과되라고 그랬대.": "She said she did it so it would pass.", "그 말을 듣고 나니까 어때?": "How do you feel now that you heard that?", "……좀 미안해. 그래도 내가 할 거야.": "...A little sorry. But I'm still doing it.", "나눠서 하자고 했어. 시범은 내가, 규칙 설명은 수아가.": "I said let's split it. I do the demo, Sua explains the rules.", "수아도 말로는 못 알아들었잖아. 해 보니까 알았어.": "Sua didn't get it with just words either. She got it once she tried it.", "네가 잘하는 걸로 맡았구나.": "You took the part you're good at.", "학급회의 시간. 두 번째 안건은 내 놀이였다. 나는 앞으로 나가기 전에 수아 자리로 갔다.": "Class meeting time. The second topic was my game. Before going up front, I went to Sua's seat.", "준비됐어?": "Ready?", "수아가 먼저 앞에 나가 규칙을 설명했다. 그런데 아이들이 웅성거렸다.": "Sua went up front first and explained the rules. But the kids started murmuring.", "아이들: 「잘 모르겠어.」 「만든 사람이 보여 줘!」": "Kids: \"I don't really get it.\" \"Let the person who made it show us!\"", "수아가 나를 봤다.": "Sua looked at me.", "……네가 나와.": "...You come up.", "내가 앞에 나갔다. 수아는 맨 앞자리에서 {@clock}를 보고 있었다.": "I went up front. Sua was in the front row, watching the {@clock}.", "수아가 규칙을 말하고, 나는 시범을 보이려고 앞에 섰다.": "Sua said the rules, and I stood up front to show the demo.", "나는 {@blackboard} 앞에 섰다. 아이들 얼굴이 한꺼번에 보였다.": "I stood in front of the {@blackboard}. I could see all the kids' faces at once.", "동그랗게 앉아요. 술래가 {@handkerchief}을 뒤에 놓아요.": "Sit in a circle. \"It\" drops the {@handkerchief} behind someone.", "{@hand}을 든 아이가 있었다.": "There was a kid with a {@hand} up.", "「{x}」 든 친구 가리키기": "Point to the kid raising a 「{x}」", "아이: 「근데 잡히면 어떻게 돼? 술래 되는 거야?」": "A kid: \"But what happens if you get caught? Do you become 'it'?\"", "아니요. 잡히면…… 잡히면…….": "No. If you get caught... if you get caught...", "머릿속이 하얘졌다. 우리 말로는 바로 떠오르는데, 한국말이 생각나지 않았다.": "My mind went blank. It came to me right away in my language, but I couldn't think of the Korean.", "(같은…… 뭐였지? 어제 수아가 말했는데.)": "(Same... what was it? Sua said it yesterday.)", "몇몇이 고개를 갸웃했다. 누군가 작게 킥 웃었다. 수아가 맨 앞에서 나를 보고 있었다.": "A few kids tilted their heads. Someone giggled quietly. Sua was watching me from the front row.", "선생님: 「재미있겠네요. 다음 체육 시간에 한번 해 봅시다.」": "Teacher: \"That sounds fun. Let's try it in the next P.E. class.\"", "아이들이 손뼉을 쳤다. 나는 자리로 돌아오면서 다리에 힘이 풀렸다.": "The kids clapped. As I went back to my seat, my legs felt weak.", "학급회의가 끝나고 수아가 내 자리로 왔다.": "After the class meeting, Sua came to my desk.", "통과됐네.": "It passed.", "이상하다. 나는 떨어질까 봐 내가 하겠다고 한 건데.": "That's strange. I said I'd do it because I was afraid it'd get voted down.", "……너 이제 진짜 경쟁자 같다.": "...You really feel like a rival now.", "원래 경쟁자였잖아.": "We were rivals from the start.", "아니. 오늘부터 진짜.": "No. From today, for real.", "수아에게 눈짓해서 대신 말해 달라고 한다.": "Give Sua a look to ask her to say it for you.", "나는 수아를 봤다. 수아가 바로 알아듣고 일어났다.": "I looked at Sua. She understood right away and stood up.", "잡히면 잡은 사람 같은 편이 돼요.": "If you get caught, you join the catcher's team. Same team.", "아이: 「아, 그렇구나.」": "A kid: \"Oh, I see.\"", "아이들이 고개를 끄덕였다. 나는 그다음 말을 이어 갔다.": "The kids nodded. I went on with the rest.", "(넘어갔어. 근데…… 내 발표였는데.)": "(I got through it. But... it was my presentation.)", "말 대신 몸으로 보여 준다.": "Show it with your body instead of words.", "잠깐만요. 보여 줄게요.": "Wait. I'll show you.", "나는 질문한 아이에게 다가가 {@hand}을 잡았다. 그리고 그 아이를 데리고 내 옆으로 와서 나란히 섰다.": "I went up to the kid who asked and took their {@hand}. Then I brought them next to me and we stood side by side.", "잡히면, 이렇게. 나랑 같이.": "If you get caught, like this. With me.", "아이: 「아! 같은 편!」": "A kid: \"Oh! Same team!\"", "네! 같은 편!": "Yes! Same team!", "몇 명이 신이 나서 「같은 편!」 하고 따라 했다. 교실이 웃음으로 시끌시끌해졌다. 이번 웃음은 나를 향한 게 아니었다.": "A few kids got excited and copied, \"Same team!\" The classroom filled with noisy laughter. This time the laughter wasn't at me.", "솔직하게 말하고 반 친구들에게 묻는다.": "Say honestly that you don't know and ask the class.", "그 말이 한국말로 생각이 안 나요.": "I can't think of that word in Korean.", "우리 말로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "It comes to me right away in my language. If you get caught, you're on one team with the person who caught you. What do you call that in Korean?", "아이들: 「같은 편!」": "Kids: \"Same team!\"", "맞아요! 같은 편이 돼요.": "That's right! You become the same team.", "아이: 「너네 나라 말로는 뭔데? 다시 해 봐!」": "A kid: \"What is it in your language? Say it again!\"", "아이들이 내 나라 말을 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "The kids copied my language. Their pronunciation was all wrong. The whole class burst out laughing. I laughed with them.", "그 부분은 건너뛰고 「아무튼 재밌어요!」 하고 끝낸다.": "Skip that part and finish with \"Anyway, it's fun!\"", "그건…… 해 보면 알아요. 아무튼 재밌어요!": "That's... you'll see when you play it. Anyway, it's fun!", "아이들이 서로 얼굴을 봤다.": "The kids looked at each other.", "아이: 「잡히면 어떻게 되는지 모르는데?」": "A kid: \"But we don't know what happens when you get caught?\"", "수아가 {@hand}을 들고 일어나 대신 설명했다. 아이들이 그제야 고개를 끄덕였다.": "Sua raised her {@hand}, stood up, and explained for me. Only then did the kids nod.", "(빨리 끝내고 싶었는데, 오히려 더 길어졌어.)": "(I wanted to finish fast, but it took even longer.)", "{m}! 우리 나라 놀이 통과됐어!": "{m}! The game from my country passed!", "정말? 잘됐다!": "Really? That's great!", "근데 발표하다가 ‘같은 편’이 한국말로 생각이 안 났어. 머리가 하얘졌어.": "But while I was presenting, I couldn't think of 'same team' in Korean. My mind went blank.", "수아한테 눈짓했더니 수아가 대신 말해 줬어.": "I gave Sua a look and she said it for me.", "수아가 바로 알아챘구나.": "Sua noticed right away.", "응. 근데 좀 아쉬워. 내 발표였는데.": "Yeah. But I'm a little disappointed. It was my presentation.", "그래도 끝까지 서 있었잖아. 다음엔 네 방법도 하나 준비해 가 볼까?": "Still, you stayed up there till the end. Next time, how about getting your own way ready too?", "말 대신 보여 줬어. 질문한 애 {@hand} 잡고 내 옆에 세웠더니, 걔가 같은 편! 그랬어.": "I showed it instead of saying it. I took the {@hand} of the kid who asked and stood them next to me, and they said, \"Same team!\"", "말이 막혔는데 몸으로 했구나.": "The words got stuck, so you used your body.", "애들이 다 같은 편! 하고 따라 했어. 웃었는데 기분 나쁘지 않았어.": "All the kids copied, \"Same team!\" They laughed, but it didn't feel bad.", "같이 웃은 거니까.": "Because you laughed together.", "한국말이 생각 안 난다고 솔직하게 말했어. 우리 말로 하고, 한국말로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "I said honestly that I couldn't think of it in Korean. I said it in my language and asked what it was in Korean, and all the kids told me together.", "반 친구들 앞에서 그걸 물었어?": "You asked that in front of the whole class?", "응. 애들이 우리 말도 따라 했어. 발음이 엉망이었어.": "Yeah. The kids copied my language too. Their pronunciation was all wrong.", "너한테 한국말 배우고, 너한테 우리 말 배우고.": "You learned Korean from them, and they learned your language from you.", "그냥 해 보면 안다고 하고 넘어가려고 했어. 근데 애들이 모르겠다고 해서 수아가 설명했어.": "I tried to skip it and said you'll see when you play. But the kids said they didn't get it, so Sua explained.", "빨리 끝내고 싶었구나.": "You wanted to finish fast.", "응. 근데 더 길어졌어.": "Yeah. But it took even longer.", "다음엔 모르는 말 하나쯤은 물어봐도 괜찮아.": "Next time, it's okay to ask about one word you don't know.", "그리고 수아가 나보고 오늘부터 진짜 경쟁자래.": "And Sua said that from today, I'm a real rival.", "와. 반장한테 그런 말 들었어?": "Wow. The class president said that to you?", "응. 좀 좋았어.": "Yeah. It felt kind of nice.", "체육 시간. 드디어 같은 편 {@handkerchief} 놀이를 하는 날이었다. 반 전체가 운동장에 동그랗게 앉았다.": "P.E. class. Finally, the day we played the Same-Team {@handkerchief} game. The whole class sat in a circle on the playground.", "처음 5분은 좋았다. 그런데 곧 이상해졌다.": "The first 5 minutes were great. But soon things got weird.", "아이: 「나 잡혔는데 그냥 계속 도망갈래!」": "A kid: \"I got caught, but I'm just going to keep running!\"", "아이: 「반칙이야! 잡히면 같은 편이랬잖아!」": "A kid: \"That's cheating! You said if you get caught, you're on the same team!\"", "아이: 「같은 편 되면 뭐 해? 그다음엔?」": "A kid: \"What do you do once you're on the same team? Then what?\"", "잡힌 아이들이 어디로 가야 할지 몰라 우왕좌왕했다. 원이 흐트러지고, 여기저기서 말다툼이 났다. {@handkerchief}이 바닥에 떨어져 있었다.": "The kids who got caught didn't know where to go and ran around confused. The circle broke apart, and arguments started here and there. The {@handkerchief} was lying on the ground.", "나는 수아에게 갔다. 수아는 팔짱을 끼고 서 있었다.": "I went over to Sua. She was standing with her arms crossed.", "이거 안 되겠다. 그냥 피구 하자.": "This isn't working. Let's just play dodgeball.", "잠깐만…….": "Wait...", "솔직히 말할게. 네 놀이 지금 엉망이야.": "I'll be honest. Your game is a mess right now.", "(수아 말이 맞아. 엉망이야.)": "(Sua's right. It's a mess.)", "(근데 이건 내가 하자고 한 놀이야.)": "(But this is the game I asked to play.)", "체육 시간이 끝났다. 수아가 내 옆으로 왔다.": "P.E. class was over. Sua came over to me.", "정리하면, 반은 성공.": "So, to sum up, half a success.", "반이나?": "Half?", "처음엔 영이었잖아.": "It was zero at first.", "다음에 고쳐서 다시 해 보든가.": "Fix it and try again next time or something.", "「1분만. 규칙 하나만 바꿔 볼게.」": "\"Just 1 minute. Let me change one rule.\"", "1분만 줘. 규칙 하나만 바꿔 볼게.": "Give me just 1 minute. Let me change one rule.", "……1분.": "...1 minute.", "나는 {@handkerchief}을 들고 원 가운데 섰다.": "I held the {@handkerchief} and stood in the middle of the circle.", "잡히면, 잡은 사람 {@hand}을 잡아요. {@hand} 잡고 같이 다녀요!": "If you get caught, hold the catcher's {@hand}. Hold {@hand}s and go together!", "아이: 「{@hand} 잡고?」": "A kid: \"Hold {@hand}s?\"", "응. 그럼 누가 같은 편인지 보여요.": "Yeah. Then you can see who's on the same team.", "다시 시작했다. 잡힌 아이들이 {@hand}을 잡고 줄줄이 달렸다. 기차처럼 길어졌다. 아이들이 깔깔 웃었다.": "We started again. The caught kids held {@hand}s and ran in a line. It got long like a train. The kids giggled.", "「애들이 규칙을 안 지켜서 그래.」": "\"It's because the kids aren't following the rules.\"", "애들이 규칙을 안 지켜서 그래. 내 놀이가 문제가 아니야.": "It's because the kids aren't following the rules. My game isn't the problem.", "규칙이 헷갈리면 안 지키게 되는 거야.": "When rules are confusing, people end up not following them.", "…….": "...", "그사이 아이들은 하나둘 피구공을 가지러 갔다.": "Meanwhile, the kids went one by one to get the dodgeball.", "(남 탓을 했는데, 놀이는 그대로 끝났어.)": "(I blamed others, and the game just ended like that.)", "「……그래. 그만하자.」": "\"...Okay. Let's stop.\"", "……그래. 그만하자.": "...Okay. Let's stop.", "피구 할 사람!": "Who wants to play dodgeball!", "아이들이 우르르 수아 쪽으로 갔다. 나는 {@handkerchief}을 주머니에 넣었다.": "The kids rushed over to Sua. I put the {@handkerchief} in my pocket.", "(그냥 끝나 버렸어.)": "(It just ended.)", "아이들에게 직접 묻는다. 「어디가 헷갈렸어?」": "Ask the kids yourself. \"What part was confusing?\"", "얘들아, 잠깐! 어디가 헷갈렸어?": "Guys, wait! What part was confusing?", "아이: 「잡히고 나서 뭘 해야 할지 모르겠어.」": "A kid: \"I don't know what to do after I get caught.\"", "아이: 「누가 같은 편인지도 모르겠고.」": "A kid: \"And I can't tell who's on the same team.\"", "그럼 잡힌 사람은 모자를 벗자! 모자 벗은 사람끼리 같은 편.": "Then the people who get caught take off their hats! Everyone with no hat is on the same team.", "아이: 「오, 그거 알겠다.」": "A kid: \"Oh, I get that.\"", "다시 시작했다. 모자 벗은 아이들이 한 무리가 되어 함께 술래를 쫓았다. 이번엔 다툼이 줄었다.": "We started again. The kids without hats became one group and chased \"it\" together. This time there were fewer fights.", "{m}, 오늘 체육 시간에 우리 나라 놀이 했어.": "{m}, we played the game from my country in P.E. class today.", "드디어! 재밌었어?": "Finally! Was it fun?", "처음엔. 근데 애들이 잡히고 나서 뭘 해야 할지 몰라서 엉망이 됐어. 수아가 솔직히 엉망이래.": "At first. But the kids didn't know what to do after they got caught, so it turned into a mess. Sua said honestly it was a mess.", "아이고.": "Oh dear.", "1분만 달라고 하고, 잡히면 {@hand} 잡고 다니자고 바꿨어. 기차처럼 길어졌어!": "I asked for just 1 minute and changed it so that when you get caught, you hold {@hand}s and go together. It got long like a train!", "{@hand} 잡고 줄줄이?": "Holding {@hand}s in a line?", "응. 애들이 엄청 웃었어. 수아가 반은 성공이래.": "Yeah. The kids laughed so much. Sua said it was half a success.", "애들이 규칙을 안 지켜서 그렇다고 했는데, 수아가 헷갈리면 안 지키게 된대.": "I said it was because the kids weren't following the rules, but Sua said when it's confusing, people don't follow them.", "수아 말도 일리가 있네.": "Sua has a point.", "응. 그러는 사이에 다들 피구 하러 갔어.": "Yeah. While we were talking, everyone went to play dodgeball.", "그냥 그만하자고 했어. 다들 피구 하러 갔어.": "I just said let's stop. Everyone went to play dodgeball.", "많이 실망했겠다.": "You must have been really disappointed.", "응. {@handkerchief}만 주머니에 있어.": "Yeah. Only the {@handkerchief} is in my pocket.", "고쳐서 다시 해 볼 수도 있잖아. 어디가 문제였는지는 알 것 같아?": "You could fix it and try again. Do you think you know what the problem was?", "애들한테 어디가 헷갈렸냐고 물어봤어. 그래서 잡히면 모자 벗기로 했어.": "I asked the kids what part was confusing. So we decided that when you get caught, you take off your hat.", "애들 말 듣고 바로 고쳤구나.": "You listened to the kids and fixed it right away.", "응. 다툼이 줄었어.": "Yeah. There were fewer fights.", "방과 후. 수아가 교실에 남아 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "After school. Sua stayed in the classroom writing her campaign promises. I picked up the {@pencil} I'd been writing my promises with and went over to her.", "「{x}」 내려놓기": "Put down 「{x}」", "수아의 공약 {@paper}: 「공약 1. 전학 온 친구를 위한 {@picture} 규칙표를 모든 반에 붙이겠습니다.」": "Sua's campaign {@paper}: \"Promise 1. I will put up a {@picture} rules chart for transfer students in every class.\"", "나는 그대로 굳었다. 내 {w} 첫 줄에도 거의 같은 말이 쓰여 있었다.": "I froze. Almost the same words were written on the first line of my {w}.", "이거 좋지? 우리가 만든 규칙표, 반응 좋았잖아.": "This is good, right? The rules chart we made got a great reaction.", "……나도 이거 1번으로 썼는데.": "...I wrote that as my number 1 too.", "어? 진짜?": "Huh? Really?", "같이 만든 거니까 나도 써도 되는 줄 알았지.": "We made it together, so I thought I could use it too.", "({@picture}은 내가 그렸어. 근데 처음 하자고 한 건 수아야.)": "(I drew the {@picture}s. But Sua was the one who first said we should make it.)", "(둘 다 쓰면…… 애들은 누가 만든 걸로 생각할까?)": "(If we both use it... who will the kids think made it?)", "집에 가는 길. 나는 내 {w}을 다시 펴 봤다.": "On the way home. I opened my {w} again.", "(내 공약은…… 뭐가 나다운 걸까?)": "(What promise is... really me?)", "서운한 걸 직접 말하고, 같이 정하자고 한다.": "Say that you feel hurt, and suggest deciding together.", "솔직히 좀 서운해. {@picture}은 내가 그렸는데, 네 공약에만 있으면 네가 다 한 것 같잖아.": "Honestly, I feel a little hurt. I drew the {@picture}s, but if it's only in your promises, it looks like you did it all.", "……그렇게 보일 수도 있겠다.": "...It could look that way.", "그러니까 정하자. 둘 다 쓰든지, 하나만 쓰든지.": "So let's decide. Either we both use it, or only one of us does.", "둘 다 쓰자. 대신 ‘같이 만든’이라고 넣어.": "Let's both use it. But add \"made together.\"", "그다음엔 누가 더 잘 지킬지 애들이 정하겠지.": "After that, the kids will decide who keeps it better.", "수아가 공약 {@paper}에 내 이름을 넣어 ‘같이 만든’이라고 고쳐 썼다.": "Sua added my name to her campaign {@paper} and rewrote it to say \"made together.\"", "다른 애들한테 「수아가 내 아이디어 가져갔어.」라고 말한다.": "Tell the other kids, \"Sua took my idea.\"", "다음 날, 나는 친한 친구에게 작게 말했다.": "The next day, I quietly told a close friend.", "수아가 내 아이디어 가져갔어.": "Sua took my idea.", "그 말은 점심시간 전에 반 전체로 퍼졌다. 수아가 굳은 얼굴로 나를 찾아왔다.": "Before lunch, it had spread to the whole class. Sua came to find me with a stiff face.", "나한테 먼저 말하지 그랬어.": "You should have told me first.", "나는 같이 만든 거라서 쓴 거야.": "I used it because we made it together.", "그건 수아에게 두고, 나만 할 수 있는 다른 공약을 쓴다.": "Let Sua have it, and write a different promise only you can make.", "그거 너 써. 나는 다른 거 쓸래.": "You use that. I'll write something else.", "진짜? 너도 같이 만든 건데.": "Really? You made it too.", "응. 나한테는 다른 게 있어.": "Yeah. I have something else.", "나는 {w} 첫 줄을 지우고 새로 썼다.": "I erased the first line of my {w} and wrote a new one.", "내 {w}: 「공약 1. 모르는 말을 물어봐도 괜찮은 반을 만들겠습니다. ‘천천히 말해 줘’ 카드를 만들겠습니다.」": "My {w}: \"Promise 1. I will make our class a place where it's okay to ask about words you don't know. I will make 'Please talk slowly' cards.\"", "……그거 나보다 네가 잘하는 거네.": "...You're better at that than me.", "응. 대피 훈련 때 그거 필요했거든.": "Yeah. I needed that at the fire drill.", "아무 말 안 하고 혼자 서운해한다.": "Say nothing and feel hurt on your own.", "……아니야. 써.": "...No, it's fine. Use it.", "그래? 고마워!": "Really? Thanks!", "수아는 신나서 공약 {@paper}를 다시 정리했다. 나는 {w}을 덮었다.": "Sua happily reorganized her campaign {@paper}. I closed my {w}.", "(괜찮다고 했는데, 하나도 안 괜찮아.)": "(I said it's fine, but it's not fine at all.)", "{m}, 수아 공약 1번이 내 공약 1번이랑 똑같았어. 우리 둘이 만든 {@picture} 규칙표.": "{m}, Sua's promise number 1 was the same as mine. The {@picture} rules chart we made together.", "어머. 둘이 같이 만든 거?": "Oh my. The one you two made together?", "응. 수아는 같이 만든 거니까 써도 되는 줄 알았대.": "Yeah. Sua said she thought she could use it because we made it together.", "서운하다고 말했어. 그래서 둘 다 쓰고 ‘같이 만든’이라고 넣기로 했어.": "I said I felt hurt. So we decided we'd both use it and add \"made together.\"", "좋은 방법이네. 수아는 어땠어?": "That's a good way. How was Sua?", "누가 더 잘 지킬지는 애들이 정할 거래.": "She said the kids will decide who keeps it better.", "역시 경쟁자다.": "She really is a rival.", "친구한테 수아가 내 거 가져갔다고 했는데, 반 전체에 퍼졌어.": "I told a friend Sua took my idea, and it spread to the whole class.", "아이고. 수아는?": "Oh dear. And Sua?", "나한테 먼저 말하지 그랬냐고 했어.": "She said I should have told her first.", "수아 말이 맞네. 다음엔 수아한테 먼저 말해 보자.": "Sua's right. Next time, let's try telling Sua first.", "그건 수아 쓰라고 하고, 나는 다른 공약 썼어. 모르는 말 물어봐도 괜찮은 반.": "I told Sua to use it and wrote a different promise. A class where it's okay to ask about words you don't know.", "그거 너한테 딱이다.": "That's perfect for you.", "수아도 그거 나보다 네가 잘하는 거래.": "Sua said I'm better at that than her.", "괜찮다고 했어. 근데 안 괜찮아.": "I said it's fine. But it's not fine.", "속으로만 서운했구나.": "You only felt hurt inside.", "응. 말하면 싸울 것 같아서.": "Yeah. I thought if I said it, we'd fight.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 내일 말해 봐도 늦지 않아.": "Saying you feel hurt and fighting are different things. It's not too late to say it tomorrow.", "쉬는 시간. 수아가 교실을 뛰어다니고 있었다. 오늘 종례까지 체험학습 신청서를 다 걷어야 한다고 했다.": "Break time. Sua was running around the classroom. She said she had to collect all the field trip sign-up forms by end-of-day homeroom.", "나는 수아 {@desk}으로 갔다. {@desk} 위에 신청서 {@box}가 있었다.": "I went to Sua's {@desk}. There was a sign-up form {@box} on the {@desk}.", "{@box} 안에 신청서가 보였다. 아직 반도 안 찼다.": "I could see sign-up forms in the {@box}. It wasn't even half full.", "여덟 명 남았어. 종례까지.": "Eight people left. Before homeroom ends.", "도와줄까?": "Want some help?", "아니, 괜찮아. 반장 일이야.": "No, it's okay. It's the class president's job.", "수아가 다시 뛰어갔다. 그때 같은 모둠 친구가 내 옆으로 와서 작게 말했다.": "Sua ran off again. Then a kid from my group came over and said quietly,", "친구: 「야, 그냥 내버려 둬. 수아가 실수하면 너한테 좋은 거잖아. 선거 나간다며.」": "A friend: \"Hey, just leave her alone. If Sua messes up, that's good for you. You're running for president, right?\"", "(……그런가?)": "(...Is that true?)", "그때 뒷자리 친구가 신청서를 들고 멍하니 앉아 있는 게 보였다. 신청서를 뒤집었다 폈다 하고 있었다.": "Then I saw the kid behind me sitting there blankly, holding a sign-up form, flipping it over and back again.", "(저거…… 대피 훈련 때 나 같은 얼굴이다.)": "(That's... the same face I had at the fire drill.)", "종례가 끝났다. 수아가 {@box}를 정리하며 나를 봤다.": "End-of-day homeroom was over. Sua looked at me as she tidied up the {@box}.", "……‘회신’을 모르는 애가 있을 줄은 몰랐어.": "...I didn't think there'd be a kid who didn't know 'reply slip.'", "나도 몰랐었어.": "I didn't know it either.", "그러니까 네가 알았겠지.": "That's why you could tell.", "한 장 내일 받으면 돼. 괜찮아.": "I can get the last one tomorrow. It's okay.", "수아는 괜찮다고 했지만, 형광펜을 꽉 쥐고 있었다.": "Sua said it was okay, but she was gripping her highlighter tight.", "친구 말대로 모른 척한다.": "Do what your friend said and pretend not to notice.", "나는 내 자리로 돌아갔다. 수아는 종례 직전까지 뛰어다녔다.": "I went back to my seat. Sua kept running around until right before homeroom.", "종례 시간. 수아가 선생님께 {@box}를 내밀었다.": "End-of-day homeroom. Sua handed the {@box} to the teacher.", "……한 장 빠졌어요.": "...One is missing.", "(내가 이긴 것 같지가 않아.)": "(It doesn't feel like I won.)", "「내가 뒤쪽 줄만 걷을게. 싫으면 말해.」": "\"I'll collect just the back rows. Tell me if you don't want me to.\"", "수아야. 내가 뒤쪽 줄만 걷을게. 싫으면 말해.": "Sua. I'll collect just the back rows. Tell me if you don't want me to.", "괜찮다니까, 내가…….": "I said it's okay, I'll...", "뒤쪽 줄만이야.": "Just the back rows.", "수아가 잠깐 멈췄다. 숨을 한 번 크게 쉬었다.": "Sua stopped for a moment. She took one big breath.", "……그럼 뒤쪽만.": "...Then just the back.", "나는 뒤쪽 줄을 돌았다. 뒷자리 친구는 ‘회신’이라는 말을 몰라서 못 낸 거였다. 나는 {@picture}으로 설명해 줬다.": "I went around the back rows. The kid behind me hadn't turned it in because they didn't know the words 'reply slip.' I explained it with a {@picture}.", "뒷자리 친구: 「아, 이름 쓰고 다시 내는 거구나!」": "The kid behind me: \"Oh, you write your name and hand it back in!\"", "도와준다고 했다가 거절당하자 「그래, 혼자 해.」 하고 돌아선다.": "When your offer to help is turned down, say \"Fine, do it yourself\" and turn away.", "진짜 도와줄게.": "I'll really help.", "괜찮다고 했잖아!": "I said it's okay!", "……그래, 혼자 해.": "...Fine, do it yourself.", "나는 자리로 돌아갔다. 수아도 나도 기분이 상했다.": "I went back to my seat. Sua and I were both upset.", "종례 시간. 한 장이 빠졌다.": "End-of-day homeroom. One form was missing.", "뒷자리 친구에게 가서 신청서를 같이 본다.": "Go to the kid behind you and look at the sign-up form together.", "나는 수아를 쫓아가는 대신 뒷자리 친구에게 갔다.": "Instead of going after Sua, I went to the kid behind me.", "이거 모르는 말 있어?": "Is there a word in this you don't know?", "뒷자리 친구: 「……‘회신’이 뭐야?」": "The kid behind me: \"...What's a 'reply slip'?\"", "나도 처음에 몰랐어. 이름 쓰고, 부모님 사인 받고, 다시 내는 거야.": "I didn't know at first either. You write your name, get your parent's signature, and hand it back in.", "나는 {w} 귀퉁이에 순서를 {@picture}으로 그려 줬다. 친구가 이름을 쓰고 신청서를 {@box}에 넣었다.": "I drew the steps as a {@picture} in the corner of my {w}. The kid wrote their name and put the sign-up form in the {@box}.", "수아가 돌아와 {@box}를 보고 눈을 크게 떴다.": "Sua came back, looked at the {@box}, and her eyes went wide.", "어? 이거 언제 냈어?": "Huh? When did this get turned in?", "뒷자리 친구: 「방금. 쟤가 알려 줬어.」": "The kid behind me: \"Just now. They showed me.\"", "{m}, 수아가 오늘 종례까지 신청서 다 걷어야 해서 엄청 바빴어.": "{m}, Sua was super busy today because she had to collect all the sign-up forms by end-of-day homeroom.", "반장 일이 많구나.": "The class president has a lot of work.", "응. 근데 친구가 수아 내버려 두래. 수아가 실수하면 나한테 좋다고.": "Yeah. But a friend told me to leave Sua alone. That if Sua messes up, it's good for me.", "그냥 내 자리에 있었어. 결국 한 장 빠졌어.": "I just stayed at my seat. In the end, one form was missing.", "그러고 나서 기분이 어땠어?": "How did you feel after that?", "이긴 것 같지 않았어.": "It didn't feel like I won.", "그렇구나.": "I see.", "뒤쪽 줄만 걷겠다고 했어. 수아가 처음엔 괜찮다고 했는데 결국 그러라고 했어.": "I said I'd collect just the back rows. Sua said it was okay at first, but in the end she said okay.", "수아가 도움을 받았네.": "Sua accepted help.", "응. 그리고 뒷자리 애가 ‘회신’을 몰라서 못 낸 거였어. {@picture}으로 알려 줬어.": "Yeah. And the kid behind me hadn't turned it in because they didn't know 'reply slip.' I explained it with a {@picture}.", "네가 아니었으면 몰랐겠다.": "If it weren't for you, nobody would have known.", "도와준다고 했는데 수아가 괜찮다고 화내서, 그럼 혼자 하라고 했어.": "I offered to help, but Sua got mad and said it was okay, so I told her to do it herself.", "둘 다 기분 상했겠다.": "You must have both been upset.", "응. 그리고 한 장 빠졌어.": "Yeah. And one form was missing.", "수아는 왜 계속 괜찮다고 했을까?": "Why do you think Sua kept saying it was okay?", "……반장 일이라서?": "...Because it's the class president's job?", "뒷자리 애가 신청서를 뒤집었다 폈다 하고 있었어. 대피 훈련 때 나 같아서 가 봤어.": "The kid behind me was flipping the sign-up form over and back. They looked like me at the fire drill, so I went over.", "무슨 일이었어?": "What was going on?", "‘회신’을 몰랐대. 나도 처음엔 몰랐잖아. {@picture}으로 알려 줬어.": "They didn't know 'reply slip.' I didn't know it at first either, remember? I explained it with a {@picture}.", "네가 겪어 봐서 알아본 거네.": "You noticed because you'd been through it yourself.", "근데 경쟁자를 도와주는 거, 이상하진 않았어?": "But helping your rival, didn't that feel strange?", "……모르겠어. 그냥 반 일이잖아.": "...I don't know. It's just class stuff.", "오늘은 내 생일이었다. {m}가 새벽부터 우리 나라 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "Today was my birthday. {m} got up before dawn to make snacks from my country and put them in a {@bowl}. To share with my classmates.", "나는 {@bowl}을 안고 수아에게 갔다.": "I held the {@bowl} and went to Sua.", "수아야! 오늘 내 생일이야. 이거 언제 나눠 주면 돼?": "Sua! It's my birthday today. When can I hand these out?", "「{x}」 뚜껑 열기": "Open the lid of 「{x}」", "{@bowl} 안에 우리 나라 간식이 가득했다.": "The {@bowl} was full of snacks from my country.", "와, 생일 축하해! 근데…….": "Wow, happy birthday! But...", "수아가 {@bowl}을 보더니 표정이 바뀌었다.": "Sua looked at the {@bowl}, and her face changed.", "그거 나눠 주면 안 돼. 규칙 9번. 집에서 만든 음식은 학교에서 나눠 먹지 않기.": "You can't hand those out. Rule 9. No sharing homemade food at school.", "……안 돼?": "...I can't?", "응. 안 돼.": "Nope. You can't.", "수아는 또 빠르고 짧게 말했다. {@bowl}이 갑자기 무거워졌다.": "Sua talked fast and short again. The {@bowl} suddenly felt heavy.", "({m}가 새벽부터 만든 건데.)": "({m} made these before dawn.)", "(우리 나라에서는 생일에 이걸 나눠 먹는데…….)": "(In my country, we share these on birthdays...)", "종례 시간. 선생님이 내 생일이라고 말씀하셨다. 반 아이들이 생일 노래를 불러 줬다.": "End-of-day homeroom. The teacher told everyone it was my birthday. The class sang happy birthday to me.", "수아가 제일 크게 불렀다. 음이 조금 틀렸다.": "Sua sang the loudest. She was a little off-key.", "「우리 나라 음식이라서 싫은 거지?」": "\"You don't like it because it's food from my country, right?\"", "우리 나라 음식이라서 안 된다는 거지?": "You're saying no because it's food from my country, right?", "아니야! 그런 거 아니야!": "No! That's not it!", "수아 얼굴이 빨개졌다.": "Sua's face turned red.", "누가 가져와도 안 되는 거야. 나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "Nobody can bring it, no matter who. I brought rice cakes on my birthday last year and had to take them back home too.", "……아.": "...Oh.", "우리 둘 다 한동안 말이 없었다.": "Neither of us said anything for a while.", "「왜 안 돼?」 하고 이유를 묻는다.": "Ask why: \"Why not?\"", "왜 안 돼?": "Why not?", "음식에 알레르기 있는 애들이 있어. 뭐가 들어갔는지 모르면 위험할 수 있대.": "Some kids have food allergies. If they don't know what's in it, it can be dangerous.", "나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "I brought rice cakes on my birthday last year and had to take them back home too.", "너도?": "You too?", "응. 엄청 속상했어.": "Yeah. I was really upset.", "(나만 안 되는 게 아니구나.)": "(So it's not just me.)", "아무 말 없이 {@bowl}을 다시 {@bag}에 넣는다.": "Put the {@bowl} back in your {@bag} without a word.", "나는 아무 말도 하지 않았다. 뚜껑을 닫고 {@bowl}을 {@bag} 깊숙이 넣었다.": "I didn't say anything. I closed the lid and pushed the {@bowl} deep into my {@bag}.", "……저기.": "...Um.", "나는 대답하지 않고 자리로 갔다. 하루 종일 {@bag}이 무거웠다.": "I didn't answer and went back to my seat. My {@bag} felt heavy all day.", "「그럼 먹는 거 말고, 다른 방법은 돼?」 하고 묻는다.": "Ask, \"Then is there another way, not eating?\"", "그럼 먹는 거 말고 다른 방법은 돼?": "Then is there another way? Not eating?", "다른 방법?": "Another way?", "사진 보여 주면서 우리 나라에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "I show a photo and tell everyone we eat this on birthdays in my country. I can draw how to make it as a {@picture} too.", "그건 돼! 음식만 안 되는 거니까.": "That's okay! It's only the food that's not allowed.", "수아가 형광펜을 꺼냈다.": "Sua took out her highlighter.", "종례 때 1분 줄게. 반장 권한.": "I'll give you one minute at end-of-day homeroom. Class president power.", "{m}…… 학교에서 그거 못 나눠 줬어.": "{m}... I couldn't hand them out at school.", "응? 왜?": "Huh? Why?", "집에서 만든 음식은 학교에서 나눠 먹으면 안 된대. 규칙 9번. 수아가 알려 줬어.": "We're not allowed to share homemade food at school. Rule 9. Sua told me.", "어머…… {m}가 몰랐네. 새벽부터 만들었는데. 미안해.": "Oh dear... {m} didn't know. I made them before dawn, too. I'm sorry.", "{m}가 왜 미안해.": "Why are you sorry, {m}?", "나 수아한테 우리 나라 음식이라서 싫은 거냐고 했어.": "I asked Sua if she didn't like it because it's food from my country.", "아니래. 수아도 작년에 떡 가져왔다가 못 나눠 줬대.": "She said no. Sua brought rice cakes last year and couldn't hand them out either.", "그랬구나. 수아도 놀랐겠다.": "I see. Sua must have been surprised too.", "……응. 내가 좀 심했어.": "...Yeah. I was kind of mean.", "왜 안 되냐고 물었더니, 알레르기 있는 애들 때문이래. 수아도 작년에 떡 가져갔다가 다시 가져갔대.": "I asked why not, and she said it's because of kids with allergies. Sua brought rice cakes last year and had to take them back too.", "다 같이 지키는 규칙이었구나.": "So it was a rule everyone follows.", "응. 나만 안 되는 줄 알았어.": "Yeah. I thought it was just me.", "그냥 아무 말 안 하고 {@bag}에 넣었어. 하루 종일 {@bag}이 무거웠어.": "I just put it in my {@bag} without saying anything. My {@bag} felt heavy all day.", "많이 속상했구나.": "You must have been really upset.", "수아가 뭐라고 하려고 했는데 그냥 갔어.": "Sua was about to say something, but I just walked away.", "수아가 무슨 말 하려고 했을까? 내일 물어봐도 되겠다.": "I wonder what Sua wanted to say. Maybe you can ask her tomorrow.", "그럼 사진 보여 주고 만드는 법 {@picture}으로 그려 와도 되냐고 했어. 수아가 종례 때 1분 준대.": "So I asked if I could show a photo and draw how to make it as a {@picture}. Sua said she'll give me one minute at end-of-day homeroom.", "어머, 그거 좋다! 그럼 {m}가 사진 찍어 줄게.": "Oh, that's a great idea! Then {m} will take a photo for you.", "만드는 법도 알려 줘. {@picture}으로 그릴게.": "Tell me how to make it too. I'll draw it as a {@picture}.", "이건 우리 둘이 먹자. 생일 축하해.": "Let's eat these together, just us two. Happy birthday.", "응. 그리고 오늘 애들이 생일 노래 불러 줬어. 수아가 제일 크게 불렀어. 음 틀리게.": "Yeah. And the kids sang happy birthday to me today. Sua sang the loudest. Off-key.", "반장은 노래도 크게 하는구나.": "So the class president sings loud too.", "점심시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "Lunchtime. Sua was hurrying to pack her {@bag}. I went over to her.", "마침 잘 왔다.": "Perfect timing.", "옆 반 선생님이 우리 {@picture} 규칙표 보시고, 애들한테 설명해 달래. 근데 나 지금 학생회 회의 가야 해.": "The teacher from the next class saw our {@picture} rule chart and wants us to explain it to her kids. But I have to go to a student council meeting right now.", "너 혼자 가 볼래? {@picture}은 네가 그렸잖아.": "Want to go by yourself? You drew the {@picture}, after all.", "(혼자? 옆 반은 아는 애가 하나도 없는데.)": "(By myself? I don't know a single kid in that class.)", "옆 반 앞.": "In front of the next class.", "「{x}」 두드리기": "Knock on 「{x}」", "똑똑. 옆 반 {@door}이 열렸다.": "Knock, knock. The {@door} of the next class opened.", "낯선 얼굴 스무 개가 나를 봤다. 다리가 떨렸다. 그래도 {@picture}을 가리켰다.": "Twenty strange faces looked at me. My legs were shaking. But I still pointed at the {@picture}.", "이건 규칙 7번이에요. 연기가 나면 몸을 낮추고, 벽을 짚어요.": "This is Rule 7. If there's smoke, stay low and keep your hand on the wall.", "옆 반 아이: 「벽은 왜 짚어요?」": "A kid from the next class: \"Why do we touch the wall?\"", "연기 때문에 앞이 안 보여요. 벽을 따라가면 길을 안 잃어요.": "The smoke makes it hard to see. If you follow the wall, you won't get lost.", "옆 반 선생님: 「설명 잘하는구나. {@picture}도 네가 그렸니?」": "Teacher from the next class: \"You explain it really well. Did you draw the {@picture} too?\"", "네!": "Yes!", "회의가 끝나고 둘이 갔을 때는 벌써 수업이 시작되어 있었다.": "When the meeting ended and we went together, class had already started.", "옆 반 선생님: 「아, 지금은 좀 그렇고…… 내일 다시 와 줄래?」": "Teacher from the next class: \"Oh, now's not a good time... Could you come back tomorrow?\"", "수아가 나를 힐끗 봤다. 나는 시선을 피했다.": "Sua glanced at me. I looked away.", "나는 규칙표를 {@blackboard} 옆에 붙이고 나가려 했다.": "I was going to stick the rule chart next to the {@blackboard} and leave.", "옆 반 선생님: 「설명도 조금 해 줄 수 있니?」": "Teacher from the next class: \"Could you explain it a little, too?\"", "……이건, 규칙…… 7번…… 이에요.": "...This is, Rule... 7...", "옆 반 아이들이 고개를 갸웃했다. 나는 꾸벅 인사하고 나왔다.": "The kids in the next class tilted their heads. I bowed quickly and left.", "안녕하세요! 옆 반 반장 양수아예요. 이 규칙표는 얘가 그렸어요. 설명도 얘가 할게요.": "Hello! I'm Yang Sua, class president of the class next door. My friend here drew this rule chart. My friend will explain it too.", "수아가 1분을 딱 채우고 나갔다. 이제 나 혼자였다. 그래도 수아가 열어 준 {@door}이라 덜 떨렸다.": "Sua stayed exactly one minute and left. Now I was on my own. But since Sua had opened the {@door} for me, I was less nervous.", "교실로 돌아오니 수아도 막 회의에서 돌아와 있었다.": "When I got back to our classroom, Sua had just come back from her meeting too.", "어땠어?": "How was it?", "벽 왜 짚냐고 물어봐서 대답했어.": "They asked why we touch the wall, and I answered.", "……나보다 잘했겠다. 나는 ‘규칙이니까’라고 했을 거야.": "...You probably did better than me. I would have just said, 'Because it's the rule.'", "……잘 못 했어.": "...I didn't do well.", "다음에 또 기회 있어.": "You'll get another chance.", "「알았어. 내가 갈게.」": "\"Okay. I'll go.\"", "알았어. 내가 갈게.": "Okay. I'll go.", "진짜? 고마워. {@picture} 보여 주면서 하면 돼.": "Really? Thanks. Just show them the {@picture} while you talk.", "수아가 둘둘 만 규칙표를 내 {@hand}에 쥐여 주고 뛰어갔다.": "Sua pressed the rolled-up rule chart into my {@hand} and ran off.", "「반장이니까 네가 해야지.」": "\"You're class president, so you should do it.\"", "반장이니까 네가 해야지.": "You're class president, so you should do it.", "그건 그런데…… 회의가 있다니까.": "That's true, but... I told you, I have a meeting.", "회의 끝나고 가.": "Go after the meeting.", "……그럼 늦어. 알았어, 끝나고 같이 가자. 대신 말은 네가 해.": "...Then it'll be too late. Fine, let's go together after. But you do the talking.", "「규칙표만 붙이고 올게.」": "\"I'll just put up the rule chart and come back.\"", "설명은 못 하고, 규칙표만 붙이고 올게.": "I can't explain it, but I'll just put up the rule chart and come back.", "음…… 그래도 가 주면 고맙지.": "Hmm... Still, thanks for going.", "수아가 규칙표를 건네고 뛰어갔다.": "Sua handed me the rule chart and ran off.", "「처음 1분만 같이 가 줘. 나머지는 내가 할게.」": "\"Just come with me for the first minute. I'll do the rest.\"", "처음 1분만 같이 가 줘. 인사만. 나머지는 내가 할게.": "Just come with me for the first minute. Just to say hi. I'll do the rest.", "1분?": "One minute?", "……좋아. 1분이면 회의 안 늦어.": "...Okay. One minute won't make me late for the meeting.", "수아가 {@clock}를 보더니 앞장섰다.": "Sua looked at the {@clock} and led the way.", "{m}, 오늘 수아가 옆 반에 가서 우리 규칙표 설명해 달래. 혼자서.": "{m}, today Sua asked me to go to the next class and explain our rule chart. By myself.", "혼자? 아는 애도 없는 반에?": "By yourself? To a class where you don't know anyone?", "응. 수아가 회의 가야 한대서.": "Yeah. Sua said she had to go to a meeting.", "그래서 혼자 갔어. 다리 떨렸는데 {@picture} 가리키면서 했어. 벽 왜 짚냐고 물어봐서 대답도 했어.": "So I went by myself. My legs were shaking, but I pointed at the {@picture} while I talked. They asked why we touch the wall, and I even answered.", "와, 혼자서 질문까지?": "Wow, by yourself, and you even answered a question?", "응. 수아가 자기보다 잘했겠대.": "Yeah. Sua said I probably did better than her.", "수아가 너를 믿고 맡긴 거네.": "Sua trusted you with it.", "반장이니까 수아가 하라고 했어. 근데 회의 끝나고 갔더니 벌써 수업 시작했어.": "I told Sua to do it because she's class president. But when we went after the meeting, class had already started.", "아이고, 못 했구나.": "Oh no, so you couldn't do it.", "응. 내일 다시 오래. 수아가 나를 쳐다봤어.": "Yeah. They told us to come back tomorrow. Sua looked at me.", "내일은 어떻게 할래?": "What will you do tomorrow?", "……내가 할래.": "...I'll do it.", "규칙표만 붙이고 오려고 했는데, 선생님이 설명도 해 달래서 버벅거렸어.": "I was going to just put up the rule chart and leave, but the teacher asked me to explain it, so I stumbled.", "갑자기 하려니까 어려웠겠다.": "It must have been hard to do it out of nowhere.", "응. 준비할 걸 그랬어.": "Yeah. I should have practiced.", "처음 1분만 같이 가 달라고 했어. 수아가 인사하고, 얘가 그렸다고 말해 주고 나갔어. 그다음엔 내가 했어.": "I asked her to come with me for just the first minute. Sua said hi, told them I drew it, and left. After that, I did it.", "필요한 만큼만 도움을 받았구나.": "You got just as much help as you needed.", "응. 수아가 {@door} 열어 주니까 덜 떨렸어.": "Yeah. Sua opened the {@door} for me, so I was less nervous.", "쉬는 시간. 옆 반 아이들이 우리 규칙표를 따라 만들기로 했다는 소식을 들었다. 나는 신이 나서 수아 자리로 갔다.": "Break time. I heard the next class decided to copy our rule chart. I was so excited that I went to Sua's seat.", "수아는 학급 게시물을 붙이고 있었다. {@desk} 위에 뚜껑 열린 {@glue}이 굴러다녔다.": "Sua was putting up class notices. An open {@glue} was rolling around on the {@desk}.", "「{x}」 뚜껑 닫기": "Close the lid of 「{x}」", "수아야! 옆 반이 우리 규칙표 따라 만든대!": "Sua! The next class is making a rule chart like ours!", "옆 반 선생님이 {@picture} 좋다고…….": "The teacher next door said the {@picture} was great...", "지금 그 얘기 할 때 아니야!": "This isn't the time for that!", "수아가 게시물을 탁 내려놓았다.": "Sua put the notice down hard.", "이거 종례 전까지 다 붙여야 하고, 학생회 회의 내용도 정리해야 하고. 너는 반장 안 해 봐서 몰라.": "I have to put all these up before end-of-day homeroom, and I have to sort out the student council meeting notes too. You don't know because you've never been class president.", "교실이 잠깐 조용해졌다. 몇몇이 우리를 봤다.": "The classroom went quiet for a moment. A few kids looked at us.", "(……뭐야. 나는 좋은 소식 말하러 온 건데.)": "(...What? I just came to tell her good news.)", "(‘반장 안 해 봐서 몰라’. 그 말이 콕 찔렸어.)": "('You've never been class president.' That really stung.)", "종례가 끝나고 {@bag}을 메는데, {@pcase} 위에 쪽지 하나가 있었다. 형광펜 글씨였다.": "After end-of-day homeroom, as I put on my {@bag}, there was a note on my {@pcase}. It was in highlighter.", "쪽지: 「아까 말 심하게 했어. 학생회 회의에서 내 안건이 다 떨어져서 그랬어. 그건 너랑 상관없는데. — 수아」": "Note: \"I was mean earlier. All my ideas got voted down at the student council meeting. That has nothing to do with you, though. — Sua\"", "(아팠던 건 아팠던 거야. 근데 수아도 오늘 힘들었구나.)": "(It hurt, and that's still true. But Sua had a hard day too.)", "「그래, 넌 반장이라 잘났다.」 하고 맞받아친다.": "Snap back: \"Yeah, you're so great because you're class president.\"", "그래, 넌 반장이라 잘났다.": "Yeah, you're so great because you're class president.", "그런 뜻 아니잖아!": "That's not what I meant!", "그런 뜻이었잖아.": "Yes, it was.", "수아가 입을 꾹 다물고 다시 게시물을 붙였다. 나도 자리로 돌아갔다. 둘 다 하루 종일 말을 안 했다.": "Sua pressed her lips together and went back to putting up notices. I went back to my seat too. We didn't talk all day.", "「지금 그 말 좀 아팠어. 근데 무슨 일 있어?」": "\"That kind of hurt just now. But is something wrong?\"", "지금 그 말 좀 아팠어.": "That kind of hurt just now.", "근데 너 오늘 좀 이상해. 무슨 일 있어?": "But you're acting kind of strange today. Is something wrong?", "수아가 {@glue}을 내려놓았다. 한참 있다가 작게 말했다.": "Sua put down the {@glue}. After a long time, she said quietly,", "학생회 회의에서 내 안건이 다 떨어졌어. 세 개 다.": "All my ideas got voted down at the student council meeting. All three.", "그거랑 너는 상관없는데. ……미안. 말 심하게 했어.": "That has nothing to do with you. ...Sorry. I was mean.", "나는 남은 게시물 한 장을 집어 수아에게 내밀었다.": "I picked up one of the leftover notices and held it out to Sua.", "「알았어. 이따 다시 올게.」 하고 자리를 비켜 준다.": "Say, \"Okay. I'll come back later,\" and give her some space.", "알았어. 이따 다시 올게.": "Okay. I'll come back later.", "나는 내 자리로 돌아갔다. 마음이 쿡쿡 쑤셨다. 그래도 지금은 더 말하지 않았다.": "I went back to my seat. My heart ached. But I didn't say anything more for now.", "점심시간. 수아가 먼저 내 자리로 왔다.": "Lunchtime. Sua came to my seat first.", "……아까 무슨 얘기 하려고 했어?": "...What were you going to tell me earlier?", "옆 반이 우리 규칙표 따라 만든대.": "The next class is making a rule chart like ours.", "진짜? ……아까 그거 기쁜 소식이었네.": "Really? ...So that was good news earlier.", "「하하, 그렇지.」 하고 웃어넘긴다.": "Laugh it off: \"Haha, right.\"", "하하, 그렇지. 나는 모르지.": "Haha, right. What would I know?", "나는 웃으면서 자리로 돌아왔다.": "I laughed and went back to my seat.", "(웃었는데…… 하나도 안 웃겨.)": "(I laughed... but it wasn't funny at all.)", "수아는 내가 웃는 걸 보고 그냥 괜찮은 줄 알았다.": "Sua saw me laughing and just thought I was okay.", "{m}, 옆 반이 우리 규칙표 따라 만든대서 수아한테 말하러 갔거든.": "{m}, I went to tell Sua that the next class is making a rule chart like ours.", "좋은 소식이네!": "That's good news!", "근데 수아가 지금 그 얘기 할 때 아니래. 너는 반장 안 해 봐서 모른대.": "But Sua said it wasn't the time for that. She said I don't know because I've never been class president.", "어머, 그 말 듣고 속상했겠다.": "Oh, that must have hurt.", "그래, 넌 반장이라 잘났다, 그랬어.": "I said, \"Yeah, you're so great because you're class president.\"", "하루 종일 말 안 했어. 근데 수아가 쪽지 줬어. 학생회에서 안건이 다 떨어졌대.": "We didn't talk all day. But Sua gave me a note. All her ideas got voted down at student council.", "둘 다 안 좋은 날이었구나.": "So you both had a bad day.", "그 말 아팠다고 했어. 그리고 무슨 일 있냐고 물었어.": "I told her it hurt. And I asked if something was wrong.", "아픈 말을 듣고 그걸 물어보기 쉽지 않은데.": "It's not easy to ask that after someone says something that hurts you.", "수아가 학생회에서 안건 세 개가 다 떨어졌대. 그리고 미안하다고 했어.": "Sua said all three of her ideas got voted down at student council. And she said sorry.", "이따 다시 오겠다고 하고 갔어. 근데 수아가 점심때 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "I said I'd come back later and left. But Sua came to me first at lunch and asked what I wanted to say earlier.", "기다렸더니 수아가 왔구나.": "You waited, and Sua came to you.", "응. 그리고 쪽지도 줬어.": "Yeah. And she gave me a note too.", "그냥 웃어넘겼어. 근데 하나도 안 웃겼어.": "I just laughed it off. But it wasn't funny at all.", "웃었으니까 수아는 괜찮은 줄 알았겠다.": "Since you laughed, Sua probably thought you were okay.", "응. 쪽지는 받았는데…… 나 아팠다는 건 수아가 몰라.": "Yeah. I got a note, but... Sua doesn't know I was hurt.", "내일이라도 말해 볼래? 그 말 좀 아팠다고.": "Want to tell her, even tomorrow? That it kind of hurt.", "도서관. 선거 연설문을 쓰다가 막혔다. 마침 수아가 맞은편에 앉아 있었다. 나는 {w}을 들고 수아에게 갔다.": "The library. I got stuck writing my election speech. Sua happened to be sitting across from me. I took my {w} and went over to her.", "수아야, 내 연설문 처음 부분만 봐 줄래?": "Sua, can you look at just the beginning of my speech?", "경쟁자 연설문을?": "Your rival's speech?", "처음 부분만.": "Just the beginning.", "내 {w}: 「안녕하세요. 저는 규칙을 잘 지키는 반장이 되겠습니다. 규칙 3번, 교실에서 뛰지 않기. 규칙 5번, 친구 밀지 않기. 규칙은 누구나 지키는 것입니다. 예외는 없습니다.」": "My {w}: \"Hello. I will be a class president who follows the rules well. Rule 3, no running in the classroom. Rule 5, no pushing friends. Everyone follows the rules. There are no exceptions.\"", "수아가 읽다가 고개를 들었다.": "Sua was reading, then looked up.", "……이거 나잖아.": "...This is me.", "규칙 번호까지. ‘예외는 없습니다’는 내가 첫날 최민호한테 한 말이고.": "Even the rule numbers. And 'There are no exceptions' is what I said to Choi Minho on the first day.", "얼굴이 화끈거렸다. 첫날 밤 {w}에 썼던 말이 생각났다.": "My face got hot. I remembered what I wrote in my {w} on the first night.", "이거면 애들이 왜 너를 뽑아? 나 뽑지.": "With this, why would the kids pick you? They'd pick me.", "너는 뭐가 하고 싶은데?": "What do you want to do?", "고친 거 선거 때 들으면 되겠네. 지금은 안 볼래.": "I'll hear the new version at the election. I won't look now.", "경쟁자 연설문 너무 많이 보면 반칙 같아.": "Looking at your rival's speech too much feels like cheating.", "「네가 잘하니까 너처럼 하면 될 것 같았어. 그냥 둘래.」": "\"You're good at it, so I thought I could just do it like you. I'll leave it.\"", "너 잘하잖아. 너처럼 하면 될 것 같았어. 그냥 둘래.": "You're good at it. I thought I could just do it like you. I'll leave it.", "……그럼 나랑 너랑 뭐가 달라?": "...Then what's the difference between you and me?", "난 경쟁자가 나랑 똑같은 건 재미없어.": "It's no fun if my rival is exactly like me.", "수아가 {w}을 돌려줬다. {w}이 이상하게 무거웠다.": "Sua gave my {w} back. The {w} felt strangely heavy.", "「그럼 너랑 반대로 할래. 규칙 없는 반!」": "\"Then I'll do the opposite of you. A class with no rules!\"", "그럼 너랑 반대로 할래. 규칙 없는 자유로운 반!": "Then I'll do the opposite of you. A free class with no rules!", "애들이 좋아하긴 하겠다.": "The kids would like that.", "근데 너 대피 훈련 때 규칙 7번 덕분에 길 찾았잖아.": "But you found your way during the fire drill thanks to Rule 7.", "……그건 그렇지.": "...That's true.", "(반대로 하는 것도 결국 수아를 보고 정한 거네.)": "(Doing the opposite is still deciding by looking at Sua.)", "「그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 거 말해 줄게.」": "\"Then what do you think I'm good at? I'll tell you yours too.\"", "그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 장점 말해 줄게.": "Then what do you think I'm good at? I'll tell you your good points too.", "음…… 너는 못 알아듣는 애를 알아봐. 신청서 때도, 옆 반 때도.": "Hmm... You notice the kids who don't understand. With the sign-up form, and with the next class too.", "그리고 막히면 몸으로 해. 학급회의 때처럼.": "And when you get stuck, you use your body. Like at the class meeting.", "너는 빨라. 정리 잘하고. 다들 네 말 들어.": "You're fast. You're good at organizing. Everyone listens to you.", "그럼 됐네. 나는 빠른 반장, 너는…….": "Then that's it. I'm the fast class president, and you're...", "……천천히 물어보는 반장?": "...The class president who asks slowly?", "나는 {w}을 새 쪽으로 넘겼다.": "I turned to a new page in my {w}.", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다.」": "My {w}: \"I will be a class president who asks 'Are you okay?' first.\"", "지우고, 내가 겪은 일로 다시 쓴다.": "Erase it and rewrite it with what happened to you.", "……다시 쓸게. 잠깐만.": "...I'll rewrite it. Hold on.", "나는 처음 문장을 지웠다. 첫날이 생각났다. 깨진 관찰 통. 민호를 막은 수아. 그리고 아무도 묻지 않았던 시우.": "I erased the first sentence. I remembered the first day. The broken bug box. Sua stopping Minho. And Siwoo, who nobody asked.", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다. 저는 전학 온 첫날, 아무것도 못 알아들었습니다. 누가 먼저 물어봐 주면 좋겠다고 생각했습니다.」": "My {w}: \"I will be a class president who asks 'Are you okay?' first. On my first day after I transferred, I couldn't understand anything. I wished someone would ask me first.\"", "수아가 그걸 읽었다. 한참 말이 없었다.": "Sua read it. She didn't say anything for a long time.", "……이건 내가 못 쓰는 거다.": "...This is something I can't write.", "{m}, 수아한테 내 연설문 보여 줬는데, 수아가 이거 나잖아, 그랬어.": "{m}, I showed Sua my speech, and she said, \"This is me.\"", "응? 무슨 말이야?": "Huh? What does that mean?", "규칙 번호도 수아처럼 쓰고, 수아가 첫날 한 말도 썼거든. 나도 모르게.": "I wrote rule numbers like Sua, and I even wrote what Sua said on the first day. Without realizing it.", "아…… 수아처럼 되고 싶다고 했었지.": "Ah... You said you wanted to be like Sua.", "수아가 잘하니까 그냥 두겠다고 했어. 근데 수아가 그럼 너랑 나랑 뭐가 다르냐고 했어.": "I said I'd leave it since Sua is good at it. But Sua asked, then what's the difference between you and me?", "뭐라고 대답했어?": "What did you say?", "……대답 못 했어.": "...I couldn't answer.", "그 질문은 오늘 밤에 천천히 생각해 봐도 돼.": "You can think about that question slowly tonight.", "그럼 반대로 규칙 없는 반 하겠다고 했어. 근데 수아가 나 대피 훈련 때 규칙 덕분에 길 찾았잖아, 그러더라.": "So I said I'd do the opposite, a class with no rules. But Sua said I found my way in the fire drill thanks to the rules.", "수아한테 한 방 맞았네.": "Sua got you there.", "응. 반대로 하는 것도 결국 수아 따라 한 거래.": "Yeah. She said doing the opposite is still copying her.", "수아한테 내 장점 말해 달라고 했어. 나도 수아 장점 말해 주고.": "I asked Sua to tell me my good points. And I told her hers.", "나는 못 알아듣는 애를 알아본대. 막히면 몸으로 하고. 그래서 ‘괜찮아?’라고 먼저 묻는 반장이라고 썼어.": "She said I notice kids who don't understand. And when I'm stuck, I use my body. So I wrote that I'll be the class president who asks 'Are you okay?' first.", "와, 그거 너다.": "Wow, that's you.", "지우고 다시 썼어. 첫날 시우 생각이 났거든. 아무도 시우한테 괜찮냐고 안 물어봤잖아.": "I erased it and rewrote it. I thought of Siwoo on the first day. Nobody asked Siwoo if he was okay.", "그날 {w}에 썼던 거?": "What you wrote in your {w} that day?", "응. 수아가 그건 자기가 못 쓰는 거래.": "Yeah. Sua said that's something she can't write.", "네가 겪은 일이니까 너만 쓸 수 있지.": "It's what happened to you, so only you can write it.", "방과 후. 수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "After school. Sua and I agreed to listen to each other's speeches. When I walked into the empty classroom, Sua was already there.", "나 먼저 할게. 시간 재 줘.": "I'll go first. Time me.", "「{x}」로 시간 재기": "Time it with 「{x}」", "수아의 연설은 1분 40초. 막힘이 없었다.": "Sua's speech was 1 minute 40 seconds. She didn't get stuck once.", "좋아. 근데 중간에 너무 빨라. 공약 2번에서 숨 한 번 쉬어.": "Good. But you go too fast in the middle. Take a breath at campaign promise 2.", "……알았어. 숨 쉬기.": "...Okay. Breathe.", "이번엔 내 차례였다. 나는 {w}을 들고 섰다. 고친 연설문이었다. 2분 30초가 걸렸다.": "Now it was my turn. I stood up with my {w}. It was my rewritten speech. It took 2 minutes 30 seconds.", "수아가 팔짱을 꼈다.": "Sua folded her arms.", "솔직히 말해도 돼?": "Can I be honest?", "무슨 말인지 모르겠어. 너무 길고, 끝에 그래서 뭘 하겠다는 건지 안 나와.": "I don't get what you're saying. It's too long, and at the end it doesn't say what you're going to do.", "그리고 ‘괜찮아?’ 부분, 좋은데 너무 빨리 지나가.": "And the 'Are you okay?' part is good, but it goes by too fast.", "(밤새 고친 건데.)": "(I rewrote it all night.)", "「{x}」 한 모금 마시기": "Take a sip of 「{x}」", "교실 창밖이 붉어졌다. 수아가 손바닥을 내밀었다.": "The sky outside the classroom window turned red. Sua held up her palm.", "이기려고 최선을 다하자.": "Let's both do our best to win.", "나는 그 손바닥을 바로 마주치지 못했다. 수아가 {@hand}을 거두고 먼저 나갔다.": "I couldn't high-five her right away. Sua dropped her {@hand} and left first.", "나도 손바닥을 마주쳤다. 짝!": "I high-fived her too. Smack!", "「너 이기려고 일부러 그러는 거지?」": "\"You're doing this on purpose to beat me, aren't you?\"", "너 이기려고 일부러 그러는 거지?": "You're doing this on purpose to beat me, aren't you?", "아니거든. 너도 나한테 숨 쉬라고 했잖아. 나 그거 고칠 거야.": "No, I'm not. You told me to breathe too. I'm going to fix that.", "그럼 다른 사람한테 들어 봐. 그게 낫겠다.": "Then have someone else listen. That would be better.", "수아가 {@bag}을 챙겼다. 연습은 거기서 끝났다.": "Sua packed her {@bag}. Practice ended there.", "「어디가 제일 모르겠어?」 하고 구체적으로 묻는다.": "Ask exactly: \"Which part is the most confusing?\"", "어디가 제일 모르겠어?": "Which part is the most confusing?", "중간에 전학 온 날 얘기. 길어. 그 얘기만 1분이야.": "The part in the middle about the day you transferred. It's long. That part alone is a minute.", "그럼 그거 반으로 줄이면?": "Then what if I cut it in half?", "그리고 끝에 한 줄만 넣어. 반장 되면 뭘 할 건지.": "And add just one line at the end. What you'll do if you become class president.", "‘천천히 말해 줘’ 카드 만들기. 그거 넣을게.": "Making 'Please speak slowly' cards. I'll add that.", "다시 했다. 1분 55초.": "I tried again. 1 minute 55 seconds.", "……이제 알겠다.": "...Now I get it.", "「길다는 건 고칠게. 근데 ‘괜찮아?’ 부분은 내 방식대로 할래.」": "\"I'll fix the long part. But I'll do the 'Are you okay?' part my way.\"", "길다는 건 맞아. 줄일게.": "You're right that it's long. I'll cut it.", "근데 ‘괜찮아?’ 부분은 빨리 지나가는 게 아니라 천천히 말할 거야. 그게 나니까.": "But I won't rush the 'Are you okay?' part. I'll say it slowly. Because that's me.", "……천천히?": "...Slowly?", "응. 거기서 멈췄다가 말할 거야.": "Yeah. I'll stop there, then say it.", "다시 했다. 이번엔 ‘괜찮아?’에서 숨을 한 번 멈췄다. 교실이 조용해졌다.": "I tried again. This time I paused for a breath at 'Are you okay?' The classroom went quiet.", "……그거 좋다. 그건 너 맞네.": "...That's good. That's really you.", "수아가 말한 대로 전부 고친다.": "Fix everything the way Sua said.", "알았어. 네 말대로 다 고칠게.": "Okay. I'll fix everything like you said.", "나는 수아가 지적한 걸 다 고쳤다. 전학 온 날 얘기도 빼고, ‘괜찮아?’도 뺐다.": "I fixed everything Sua pointed out. I took out the part about the day I transferred, and I took out 'Are you okay?' too.", "다시 했다. 1분 30초. 짧고 깔끔했다.": "I tried again. 1 minute 30 seconds. Short and neat.", "……근데 이제 누구 연설인지 모르겠다.": "...But now I can't tell whose speech it is.", "(시키는 대로 했는데.)": "(I did what she told me.)", "{m}, 수아랑 서로 연설 들어 줬어.": "{m}, Sua and I listened to each other's speeches.", "수아는 1분 40초. 진짜 잘해. 근데 수아가 내 거는 무슨 말인지 모르겠대. 너무 길대.": "Sua's was 1 minute 40 seconds. She's really good. But Sua said she didn't get what mine was saying. She said it's too long.", "아이고, 밤새 고친 거잖아.": "Oh no, and you rewrote it all night.", "나 이기려고 일부러 그러는 거냐고 했어. 수아가 그럼 다른 사람한테 들어 보래.": "I asked if she was doing it on purpose to beat me. Sua said then I should have someone else listen.", "속상한 마음에 그렇게 말했구나.": "You said that because you were upset.", "근데 나도 수아한테 숨 쉬라고 했잖아. 수아는 그거 고친대.": "But I told Sua to breathe too. Sua said she's going to fix that.", "……내일 다시 들어 달라고 해 볼래?": "...Want to ask her to listen again tomorrow?", "어디가 제일 모르겠냐고 물었어. 전학 온 날 얘기가 너무 길대. 반으로 줄였어.": "I asked her which part was the most confusing. She said the part about the day I transferred is too long. I cut it in half.", "몇 분 됐어?": "How long was it?", "1분 55초! 수아가 이제 알겠대.": "1 minute 55 seconds! Sua said now she gets it.", "길다는 건 고치겠다고 했어. 근데 ‘괜찮아?’는 내 방식대로 천천히 하겠다고 했어.": "I said I'd fix the long part. But I said I'd do 'Are you okay?' my way, slowly.", "그거 좋대. 그건 나 맞대.": "She said it's good. She said that's really me.", "들을 건 듣고, 지킬 건 지켰네.": "You listened to what you should, and kept what you should.", "수아 말대로 다 고쳤어. 짧아졌어. 근데 수아가 이제 누구 연설인지 모르겠대.": "I fixed everything like Sua said. It got shorter. But Sua said now she can't tell whose speech it is.", "다 빼 버렸구나.": "So you took everything out.", "응. ‘괜찮아?’도 뺐어.": "Yeah. I even took out 'Are you okay?'", "그건 다시 넣고 싶지 않아?": "Don't you want to put that back in?", "……넣을래.": "...I'll put it back.", "창체 시간. 선생님이 수아와 나를 앞으로 부르셨다.": "Activity period. The teacher called Sua and me to the front.", "선생님: 「오늘 자리 바꾸기는 반장 후보 둘이 같이 진행해 볼래요? 연습이라고 생각하고.」": "Teacher: \"Why don't our two class president candidates run the seat change together today? Think of it as practice.\"", "나는 수아 옆에 섰다. 수아가 작게 말했다.": "I stood next to Sua. Sua said quietly,", "번호 뽑기로 하자. 빠르고 공평해.": "Let's draw numbers. It's fast and fair.", "「{x}」 줄 맞추기": "Line up 「{x}」", "그런데 맨 뒤에 앉은 친구가 {@blackboard}을 보느라 눈을 찡그리고 있었다. 지난번 자리 바꿀 때 뒤로 갔던 친구였다.": "But a kid sitting in the very back was squinting to see the {@blackboard}. It was the kid who got moved to the back last time we changed seats.", "(번호 뽑기면…… 또 뒤로 갈 수도 있잖아.)": "(If we draw numbers... that kid might end up in the back again.)", "수아야, 근데 눈 나쁜 애들은 앞에 앉아야 하지 않을까? 먼저 물어보면…….": "Sua, but shouldn't kids with bad eyes sit in front? If we ask first...", "그럼 다들 앞에 앉고 싶다고 하면? 시간 없어. 번호 뽑기가 공평해.": "Then what if everyone says they want to sit in front? We don't have time. Drawing numbers is fair.", "반 아이들이 우리 둘을 보고 있었다. 누군가 「빨리 해!」 하고 외쳤다.": "The class was watching the two of us. Someone shouted, \"Hurry up!\"", "자리 바꾸기가 끝났다. 선생님이 둘을 보고 웃으셨다.": "The seat change was done. The teacher looked at us and smiled.", "선생님: 「둘이 이끄는 방식이 다르네요.」": "Teacher: \"You two lead in different ways.\"", "수아가 나를 힐끗 봤다.": "Sua glanced at me.", "다르다는 게 칭찬이야, 아니야?": "Is 'different' a compliment or not?", "……칭찬이겠지?": "...It's a compliment, I think?", "「둘 다 하자. 꼭 앞이어야 하는 사람만 먼저, 나머지는 뽑기.」": "\"Let's do both. Only the people who really need the front go first, and the rest draw.\"", "둘 다 하자. 눈 때문에 꼭 앞이어야 하는 사람만 먼저 {@hand} 들고, 나머지는 번호 뽑기.": "Let's do both. Only the people who really need to sit in front because of their eyes raise their {@hand} first, and the rest draw numbers.", "……‘꼭’인 사람만?": "...Only the people who 'really' need it?", "응. 그냥 앞이 좋은 건 안 되고.": "Yeah. Just liking the front doesn't count.", "좋아. 정리하면, 꼭인 사람 먼저, 나머지 뽑기.": "Okay. So, to sum up, people who really need it first, everyone else draws.", "세 명이 {@hand}을 들었다. 나머지는 수아가 번호를 뽑았다. 5분 만에 끝났다.": "Three kids raised their {@hand}. Sua drew numbers for the rest. It was done in five minutes.", "반 친구들에게 어떤 방식이 좋은지 묻는다.": "Ask the class which way they like.", "얘들아, 두 가지 방법이 있어. 번호 뽑기, 아니면 먼저 사정 있는 사람 물어보고 정하기. {@hand} 들어 줘.": "Everyone, there are two ways. Draw numbers, or first ask who has a reason and then decide. Raise your {@hand}.", "아이들이 {@hand}을 들었다. 거의 반반이었다.": "The kids raised their {@hand}. It was almost half and half.", "반반이네.": "It's half and half.", "아이: 「그럼 섞어!」": "A kid: \"Then mix them!\"", "결국 사정 있는 사람 먼저, 나머지는 뽑기가 됐다.": "In the end, people with a reason went first, and the rest drew numbers.", "……애들이 정하니까 아무도 불만이 없네.": "...Since the kids decided, nobody's complaining.", "「알았어. 네 방식대로 하자.」": "\"Okay. Let's do it your way.\"", "……알았어. 네 방식대로 하자.": "...Okay. Let's do it your way.", "번호 뽑기로 정했다. 빨랐다. 눈을 찡그리던 친구는 이번에도 맨 뒤가 됐다.": "We decided to draw numbers. It was fast. The kid who was squinting ended up in the very back again.", "(아까 말할 걸.)": "(I should have said something.)", "「내 방식이 더 좋아. 다 물어보고 정하자.」": "\"My way is better. Let's ask everyone and then decide.\"", "내 방식이 더 좋아. 한 명씩 다 물어보고 정하자.": "My way is better. Let's ask everyone one by one and then decide.", "스물네 명을 다?": "All twenty-four kids?", "한 명씩 물어보니 다들 앞이나 창가에 앉고 싶다고 했다. 시간이 다 갔다. 결국 종이 울려서 선생님이 정하셨다.": "When we asked one by one, everyone wanted to sit in front or by the window. We ran out of time. In the end the bell rang and the teacher decided.", "{m}, 오늘 수아랑 둘이 자리 바꾸기 진행했어. 반장 후보 연습이래.": "{m}, today Sua and I ran the seat change together. It was practice for the class president candidates.", "와, 둘이서? 어떻게 했어?": "Wow, just you two? How did it go?", "수아는 번호 뽑기가 공평하대. 근데 맨 뒤 애가 {@blackboard} 보느라 눈을 찡그리고 있었어.": "Sua said drawing numbers is fair. But the kid in the very back was squinting to see the {@blackboard}.", "꼭 앞이어야 하는 사람만 먼저 하고, 나머지는 뽑기로 하자고 했어.": "I said only the people who really need the front go first, and the rest draw numbers.", "수아 방식이랑 네 방식을 섞었구나.": "So you mixed Sua's way and your way.", "응. 5분 만에 끝났어. 수아가 정리하면, 이러면서 정리했어.": "Yeah. It was done in five minutes. Sua summed it up, going \"So, to sum up.\"", "애들한테 어떤 방법이 좋냐고 물어봤어. 반반이었는데 누가 섞자고 해서 섞었어.": "I asked the kids which way they liked. It was half and half, but someone said to mix them, so we did.", "반 아이들이 정했네.": "So the class decided.", "응. 수아가 애들이 정하니까 불만이 없대.": "Yeah. Sua said nobody complains when the kids decide.", "그냥 수아 방식대로 했어. 근데 그 애가 또 맨 뒤 됐어.": "I just did it Sua's way. But that kid ended up in the very back again.", "아쉬웠겠다.": "That's too bad.", "응. 아까 말할 걸.": "Yeah. I should have said something.", "다음엔 말해 봐. 너 그 애 눈 찡그리는 거 봤잖아.": "Say something next time. You saw that kid squinting.", "내 방식대로 다 물어보자고 했는데, 다들 앞이나 창가래. 결국 시간 다 가서 선생님이 정하셨어.": "I said let's ask everyone, my way, but everyone wanted the front or the window. We ran out of time and the teacher decided.", "스물네 명한테 다 물어봤어?": "You asked all twenty-four kids?", "응…… 수아 말도 맞았어. 시간이 없었어.": "Yeah... Sua was right too. There wasn't enough time.", "방과 후. 복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "After school. Sua was standing by the hallway window. I went over next to her.", "{@window}이 열리고 운동장 소리가 들어왔다.": "The {@window} was open, and sounds from the playground came in.", "이거 기억나?": "Remember this?", "수아가 {@bag}에서 접힌 {@paper}를 꺼냈다.": "Sua took a folded {@paper} out of her {@bag}.", "처음 도서관에서 만든 규칙표였다. 귀퉁이에 수아가 그린 빨래판 {@stairs}도 그대로 있었다.": "It was the rule chart we made at the library the first time. Sua's washboard {@stairs} was still there in the corner.", "이거 아직 갖고 있었어?": "You still have this?", "응. 버리기 아까워서.": "Yeah. It felt like a waste to throw it away.", "수아가 창밖 운동장을 봤다.": "Sua looked out at the playground.", "있잖아. 만약에 네가 반장 되면, 나한테 뭘 맡길 거야?": "Hey. If you become class president, what will you give me to do?", "……갑자기?": "...All of a sudden?", "궁금해서. 진짜로.": "I'm curious. Really.", "수아가 규칙표를 다시 접어 내 {@hand}에 쥐여 줬다.": "Sua folded the rule chart again and pressed it into my {@hand}.", "그럼 너는? 네가 반장 되면 나한테 뭘 맡길 거야?": "What about you? If you become class president, what will you give me to do?", "너한테는 ‘새 친구 도우미’. 넌 뭐가 어려운지 아니까.": "For you, 'new-friend helper.' You know what's hard.", "……아, 근데 그 전에 물어볼게. 하고 싶은지.": "...Oh, but before that, I'll ask you. If you want to.", "(처음엔 수아처럼 되고 싶었어.)": "(At first, I wanted to be like Sua.)", "(지금은…… 수아랑 같이 하고 싶어.)": "(Now... I want to do it together with Sua.)", "「네가 잘하는 거. 대신 혼자 다 안 하게 나눠서.」": "\"What you're good at. But split up, so you don't do it all alone.\"", "네가 잘하는 거. 정리하는 거, 시간 재는 거.": "What you're good at. Organizing things, keeping time.", "대신 혼자 다 안 하게 나눠서. 신청서 때처럼 혼자 뛰어다니면 안 돼.": "But split up, so you don't do it all alone. You can't run around by yourself like with the sign-up form.", "……그거 기억하네.": "...You remember that.", "알았어. 나눠서.": "Okay. Split up.", "「아무것도. 내가 다 할 거야.」": "\"Nothing. I'll do it all.\"", "아무것도 안 맡길 거야. 내가 다 할 거야.": "I won't give you anything. I'll do it all.", "……그거 나잖아.": "...That's me.", "응. 너 따라 해 봤어.": "Yeah. I tried copying you.", "그러다 쓰러져. 나 해 봐서 알아.": "You'll collapse doing that. I know because I've done it.", "수아가 웃었다. 농담이었지만, 수아는 진짜 대답을 기다리는 얼굴이었다.": "Sua laughed. It was a joke, but Sua's face was waiting for a real answer.", "「부반장 해 줘.」": "\"Be my vice president.\"", "부반장 해 줘.": "Be my vice president.", "벌써 정했어? 나한테 물어보지도 않고?": "You already decided? Without even asking me?", "부반장이 싫다는 게 아니라, 먼저 물어보라고.": "It's not that I don't want to be vice president. Just ask me first.", "「네가 하고 싶은 걸 먼저 물어볼래.」": "\"I'll ask what you want to do first.\"", "네가 하고 싶은 걸 먼저 물어볼래.": "I'll ask what you want to do first.", "내가 하고 싶은 거?": "What I want to do?", "응. 넌 늘 해야 하는 걸 하잖아. 하고 싶은 건 뭔데?": "Yeah. You always do what you have to do. What do you want to do?", "수아가 한참 생각했다.": "Sua thought for a long time.", "……{@picture} 규칙표. 그거 계속 만들고 싶어. {@picture}은 네가 그리고.": "...{@picture} rule charts. I want to keep making those. And you draw the {@picture}.", "{m}, 수아가 처음 만든 규칙표 아직 갖고 있었어. 빨래판 {@stairs} 그대로.": "{m}, Sua still has the first rule chart she made. With the washboard {@stairs} and everything.", "그 {@stairs}?": "That {@stairs}?", "응. 그리고 수아가 나 반장 되면 자기한테 뭘 맡길 거냐고 물었어.": "Yeah. And Sua asked what I'd give her to do if I become class president.", "네가 잘하는 거, 대신 혼자 다 하지 말고 나눠서 하라고 했어.": "I said what she's good at, but split up so she doesn't do it all alone.", "신청서 때 일 기억하냐고. 알았대.": "I asked if she remembers what happened with the sign-up form. She said okay.", "아무것도 안 맡기고 내가 다 한다고 했어. 수아 따라 한 거야.": "I said I wouldn't give her anything and I'd do it all. I was copying Sua.", "그러다 쓰러진대. 자기가 해 봐서 안대.": "She said I'll collapse doing that. She knows because she's done it.", "부반장 해 달라고 했어. 근데 수아가 물어보지도 않고 정하냐고.": "I asked her to be my vice president. But Sua asked if I was deciding without even asking her.", "싫다고 한 거야?": "Did she say no?", "아니. 먼저 물어보래.": "No. She said ask her first.", "하고 싶은 거 먼저 물어보겠다고 했어. 수아가 한참 생각하더니, {@picture} 규칙표 계속 만들고 싶대.": "I said I'd ask what she wants to do first. Sua thought for a long time, then said she wants to keep making {@picture} rule charts.", "수아가 하고 싶은 걸 처음 들었네.": "That's the first time you've heard what Sua wants to do.", "수아는 반장 되면 나한테 새 친구 도우미 맡긴대. 내가 뭐가 어려운지 아니까. 근데 먼저 물어보겠대.": "Sua said if she becomes class president, she'll make me the new-friend helper. Because I know what's hard. But she'll ask me first.", "둘 다 서로한테 물어보네.": "You're both asking each other.", "응. {m}, 나 처음엔 수아처럼 되고 싶었거든.": "Yeah. {m}, at first I wanted to be like Sua.", "지금은?": "And now?", "지금은 수아랑 같이 하고 싶어.": "Now I want to do it together with Sua.", "결과 발표가 끝났다. 교실은 시끄러웠다. 나는 수아를 찾아 복도 창가로 갔다. 수아가 먼저 와 있었다.": "The results were announced. The classroom was noisy. I went to the hallway window to find Sua. Sua was already there.", "축하해.": "Congratulations.", "솔직히 속상해. 많이.": "Honestly, I'm upset. Really upset.", "수아는 울지 않았다. 대신 형광펜을 꽉 쥐고 있었다.": "Sua didn't cry. Instead, she was squeezing her highlighter tight.", "근데 너 ‘괜찮아?’ 할 때. 나도 거기서 조용해졌어.": "But when you said 'Are you okay?' I went quiet there too.", "……규칙 정리하는 거 필요하면 말해. 아, 물어보는 거 맞지? 물어볼게. 필요해?": "...If you need help organizing rules, tell me. Oh, I'm supposed to ask, right? I'll ask. Do you need it?", "응. 필요해.": "Yeah. I need it.", "그럼 다음 선거 때 보자. 그땐 진짜 안 질 거야.": "Then see you at the next election. I'm really not losing next time.", "수아가 {@blackboard} 쪽을 돌아봤다. {@blackboard}에는 두 이름이 나란히 적혀 있었다. 내 이름, 그리고 수아 이름.": "Sua turned toward the {@blackboard}. Two names were written side by side on the {@blackboard}. My name, and Sua's name.", "……같이래.": "...Together, it says.", "응. 같이.": "Yeah. Together.", "나 혼자 되고 싶었어. 조금.": "I wanted to win by myself. A little.", "나도. 조금.": "Me too. A little.", "둘이 동시에 웃음이 터졌다.": "We both burst out laughing at the same time.", "정리하면, 반장이 둘이야. 그럼 뭐부터 나눠?": "So, to sum up, there are two class presidents. Then what do we split first?", "……그거 먼저 물어보는 거 맞지?": "...We're supposed to ask about that first, right?", "응. 이번엔 내가 먼저 물을게. 너는 뭐 하고 싶어?": "Yeah. This time I'll ask first. What do you want to do?", "새로 온 친구 챙기기. 그리고 바뀌는 거 미리 알려 주기.": "Looking after new kids. And telling everyone about changes ahead of time.", "그럼 나는 회의 정리랑 시간 재기. 규칙표는 같이.": "Then I'll do meeting notes and keeping time. Rule charts, we do together.", "{@picture}은 내가.": "I'll do the {@picture}.", "{@stairs}도 너.": "The {@stairs} too.", "첫날 너 나 보고 멋있다고 생각했지? 민호 막을 때.": "On the first day, you thought I was cool, right? When I stopped Minho.", "……어떻게 알았어?": "...How did you know?", "얼굴에 다 쓰여 있었어. 근데 지금은 내가 너 보고 그래.": "It was all over your face. But now that's how I feel about you.", "목이 따끔했다. 나는 창밖만 봤다.": "My throat stung. I just looked out the window.", "너 ‘괜찮아?’ 할 때, 애들 다 조용해졌어. 나 그거 무서웠어. 질 줄 알았어.": "When you said 'Are you okay?' all the kids went quiet. That scared me. I thought I was going to lose.", "……진짜?": "...Really?", "응. 그래서 말인데, 새 친구 도우미. 해 볼래? 하고 싶은지 먼저 묻는 거야.": "Yeah. So, about the new-friend helper. Want to try it? I'm asking first if you want to.", "(속상해. 근데 수아가 진짜로 물어봤어.)": "(I'm upset. But Sua really asked me.)", "……생각해 볼게. 근데 아마 할 것 같아.": "...I'll think about it. But I think I'll do it.", "정리하면, 할 거라는 거지?": "So, to sum up, you'll do it, right?", "……우리 둘 다 떨어졌네.": "...We both lost.", "정리하면, 둘이 표를 나눠 가졌다는 거지.": "So, to sum up, we split the votes.", "둘 다 잠깐 말이 없었다. 교실 안에서 새 반장이 친구들한테 둘러싸여 있었다.": "Neither of us said anything for a moment. Inside the classroom, the new class president was surrounded by friends.", "……우리 가서 축하해 줄까?": "...Should we go congratulate them?", "응. 같이 가자.": "Yeah. Let's go together.", "그리고 규칙표는 반장 아니어도 만들 수 있잖아.": "And you don't have to be class president to make rule charts.", "수아가 먼저 말했다.": "Sua spoke first.", "떨어졌다.": "I lost.", "……내가 돼서 미안. 아니, 미안한 건 아닌데. 그냥.": "...Sorry I won. No, I'm not sorry. Just...", "……우리 둘 다.": "...Both of us.", "수아가 창틀에 팔을 걸쳤다. 나도 옆에 섰다. 어깨가 거의 닿을 만큼.": "Sua rested her arms on the window frame. I stood next to her. Our shoulders almost touched.", "있잖아. 선거 끝나면 경쟁자 아니잖아.": "Hey. When the election's over, we're not rivals anymore.", "그럼 이제 뭐야, 우리?": "Then what are we now?", "……그냥 친구?": "...Just friends?", "그냥은 별로야. 정리해 봐.": "'Just' isn't good enough. Sum it up.", "음…… 제일 친한 친구.": "Hmm... Best friends.", "수아가 형광펜을 꺼내더니 자기 손등에 작게 별을 그렸다. 그리고 내 손등에도 그렸다.": "Sua took out her highlighter and drew a small star on the back of her hand. Then she drew one on the back of my hand too.", "정리 완료. 지워지면 다시 그려 줄게.": "All summed up. If it wears off, I'll draw it again.", "……떨어졌네.": "...You lost.", "근데 너 아까 발표 끝나자마자 {bff}한테 먼저 갔지?": "But right after the results, you went to {bff} first, didn't you?", "……봤어?": "...You saw?", "응. {bff}도 너 찾고 있었어. 둘이 똑같은 얼굴이던데.": "Yeah. {bff} was looking for you too. You two had the same face.", "수아가 웃었다.": "Sua smiled.", "반장보다 그게 더 어려울걸. 한 사람이랑 진짜 친해지는 거.": "That's probably harder than being class president. Becoming real friends with one person.", "……나는 아직 그런 친구 없어. 다들 반장한테 말 거는 거라서.": "...I don't have a friend like that yet. Everyone talks to me because I'm class president.", "너도 생길 거야.": "You'll have one too.", "정리하면, 나도 좀 덜 바빠야 한다는 거지.": "So, to sum up, I need to be a little less busy too.", "복도 창가에 나 혼자가 아니었다. 그룹 친구들이 우르르 따라 나왔다. 그 안에 수아도 있었다.": "I wasn't alone by the hallway window. My group of friends came pouring out after me. Sua was with them too.", "……떨어졌다.": "...I lost.", "아, 나는 됐지. 근데 우리 중에선 나 혼자네.": "Oh, I won. But I'm the only one out of us.", "친구들이 웃었다.": "My friends laughed.", "친구들이 서로 어깨를 툭툭 쳤다. 누가 「괜찮아, 괜찮아」 했다. 내가 맨날 하던 말이었다.": "My friends patted each other on the shoulder. Someone said, \"It's okay, it's okay.\" That was what I always said.", "우리 반장 아니어도 할 거 많잖아. 정리해 볼까?": "We have lots to do even if we're not class president. Should I sum it up?", "또 정리해?": "Summing up again?", "응. 1번, 점심에 같이 앉기. 2번, 규칙표 만들기. 3번……": "Yep. Number 1, sit together at lunch. Number 2, make rule charts. Number 3...", "친구들: 「3번은 놀기!」": "Friends: \"Number 3 is play!\"", "……3번 놀기. 통과.": "...Number 3, play. Approved.", "떨어졌네.": "You lost.", "그때 교실 {@door}이 열리고, 내 그룹 친구들이 나를 찾아 나왔다. 「야, 어디 갔었어!」": "Just then, the classroom {@door} opened, and my group of friends came out looking for me. \"Hey, where did you go!\"", "……너 찾으러 왔네.": "...They came to find you.", "부럽다. 반장 되면 다들 일 얘기만 하러 오거든. 너는 그냥 너라서 오는 거잖아.": "I'm jealous. When you're class president, everyone only comes to talk about work. They come to you just because you're you.", "……너도 같이 갈래? 점심 같이 먹자.": "...Want to come with us? Let's eat lunch together.", "수아가 잠깐 망설였다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "Sua hesitated for a moment. Then she clicked her highlighter cap shut.", "……한 번만.": "...Just this once.", "……나는 됐고.": "...Well, I won.", "응. 괜찮아.": "Yeah. It's okay.", "그때 교실 안에서 누가 외쳤다.": "Just then, someone shouted from inside the classroom.", "야! 이거 너네 나라 말로 뭐라고 해? 빨리 와 봐!": "Hey! How do you say this in your language? Come here, quick!", "교실 뒤 게시판에는 두 나라 말로 된 낱말 카드가 붙어 있었다. {@desk}, {w}, {@cat}, 나비. 아이들이 하나씩 붙인 거였다.": "On the board at the back of the classroom were word cards in two languages. {@desk}, {w}, {@cat}, butterfly. The kids had put them up one by one.", "저거 언제 저렇게 됐어?": "When did that happen?", "……나도 몰라. 애들이 하나씩 물어보더니.": "...I don't know either. The kids kept asking me, one at a time.", "{U@notebook}.": "{U@notebook}.", "수아가 우리 말로 말했다. 발음이 좀 틀렸다.": "Sua said it in my language. Her pronunciation was a little off.", "응. 맞아.": "Yeah. That's right.", "……반장보다 그게 더 멋있다. 반 애들이 너한테 배우잖아.": "...That's cooler than being class president. The class is learning from you.", "정리하면, 너는 선생님이고 나는 학생이야. 오늘만.": "So, to sum up, you're the teacher and I'm the student. Just for today.", "……나는 됐어.": "...Well, I won.", "수아가 내 {@hand}에 들린 {w}을 봤다.": "Sua looked at the {w} in my {@hand}.", "첫날 쓴 거. 반 친구 이름.": "The one you wrote on the first day. Your classmates' names.", "{w}을 펼쳤다. 첫날 적은 이름 몇 개 밑에, 새 이름이 몇 개 더 있었다. 수아 이름도 있었다.": "I opened the {w}. Under the few names I wrote on the first day, there were some new names. Sua's name was there too.", "다음 학기에 또 나가?": "Are you running again next semester?", "……응. 나갈래.": "...Yeah. I'll run.", "그럼 그때는 이름 더 많이 적어 와. 다 적으면 나 진짜 질 수도 있겠다.": "Then write down more names by then. If you write them all, I might really lose.", "다음 학기에 보자. 경쟁자.": "See you next semester. Rival.", "{m}, 선거 결과 나왔어.": "{m}, the election results are out.", "나 됐어! 수아가 축하한다고 했어. 근데 많이 속상하대.": "I won! Sua said congratulations. But she said she's really upset.", "축하해. 그리고 그걸 솔직하게 말해 준 수아도 대단하다.": "Congratulations. And Sua is amazing for saying that honestly.", "수아가 필요하면 도와준대. 먼저 물어보고.": "Sua said she'll help if I need it. She'll ask first.", "나랑 수아랑 둘 다 반장 됐어! 같이!": "Sua and I both became class president! Together!", "둘 다? 와, 축하해!": "Both of you? Wow, congratulations!", "수아가 혼자 되고 싶었대, 조금. 나도 조금 그랬다고 했어. 둘이 웃었어.": "Sua said she wanted to win by herself, a little. I said me too, a little. We both laughed.", "솔직한 반장 둘이네.": "Two honest class presidents.", "수아가 먼저 뭐 하고 싶냐고 물어봤어. 나는 새 친구 챙기기, 수아는 회의 정리.": "Sua asked me first what I wanted to do. I'm looking after new kids, and Sua's doing meeting notes.", "수아가 됐어.": "Sua won.", "……속상하지?": "...You're upset, right?", "응. 근데 수아가 새 친구 도우미 하고 싶은지 물어봤어. 할 것 같아.": "Yeah. But Sua asked if I want to be the new-friend helper. I think I'll do it.", "반장 아니어도 할 수 있는 일이 생겼네.": "So you found something you can do even without being class president.", "나도 수아도 떨어졌어. 둘이 같이 가서 새 반장 축하해 줬어.": "Sua and I both lost. We went together and congratulated the new class president.", "그거 쉽지 않은데.": "That's not easy.", "수아가 규칙표는 반장 아니어도 만들 수 있대.": "Sua said we can make rule charts even if we're not class president.", "떨어졌어. 근데 {m}, 이거 봐.": "I lost. But {m}, look at this.", "나는 손등의 별을 보여 줬다.": "I showed her the star on the back of my hand.", "이게 뭐야?": "What's this?", "수아가 그렸어. 제일 친한 친구 표시. 지워지면 다시 그려 준대.": "Sua drew it. It means best friends. She said she'll draw it again if it wears off.", "……반장보다 귀한 거 받았네.": "...You got something more precious than being class president.", "떨어졌어. 근데 발표 끝나자마자 {bff}한테 먼저 갔어. 수아가 봤대. 둘이 똑같은 얼굴이었대.": "I lost. But right after the results, I went to {bff} first. Sua saw. She said we had the same face.", "그런 친구가 생겼구나.": "So you have a friend like that now.", "수아가 한 사람이랑 진짜 친해지는 게 반장보다 어렵대.": "Sua said becoming real friends with one person is harder than being class president.", "떨어졌어. 근데 우리 그룹이 다 같이 나와서 괜찮다고 해 줬어. 수아도 있었어. 수아가 할 일 정리했어. 3번은 놀기래.": "I lost. But my whole group came out and told me it's okay. Sua was there too. Sua summed up what we'll do. She said number 3 is play.", "제일 중요한 게 3번이네.": "Number 3 is the most important one.", "떨어졌어. 근데 우리 그룹 애들이 나 찾으러 왔어. 수아가 부럽대. 나는 그냥 나라서 다들 온다고. 그래서 수아한테 점심 같이 먹자고 했어.": "I lost. But my group came looking for me. Sua said she's jealous. She said everyone comes to me just because I'm me. So I asked Sua to eat lunch with us.", "한 번만, 이래.": "She said, \"Just this once.\"", "떨어졌어. 근데 {m}, 교실 뒤에 우리 말 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "I lost. But {m}, there are word cards in our language at the back of the classroom! The kids kept asking one at a time, and now it's like that. Sua even repeated {U@notebook}.", "……우리 말을?": "...In our language?", "응. 내가 선생님이래. 오늘만.": "Yeah. She said I'm the teacher. Just for today.", "{m}는 오늘이 제일 기쁘다.": "Today is {m}'s happiest day.", "떨어졌어. 근데 첫날 {w} 봤는데, 이름이 좀 늘었어. 수아 이름도 있어.": "I lost. But I looked at my {w} from the first day, and there are more names now. Sua's name is there too.", "다음 학기엔?": "And next semester?", "또 나갈 거야. 수아가 그땐 이름 더 많이 적어 오래.": "I'm running again. Sua said to write down more names by then.", "그럼 내일부터 또 한 명씩.": "Then starting tomorrow, one person at a time again."});
T.id=T.id||{};Object.assign(T.id,{"아침. 수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "Pagi. Sua sedang mencentang sesuatu dengan stabilo di depan kelas. Aku menghampiri Sua.", "수아야. 규칙…… 외워 왔어.": "Sua. Aturannya... sudah aku hafalkan.", "진짜? 그럼 확인해 볼까.": "Serius? Kalau begitu, kita cek, ya.", "수아가 형광펜 뚜껑을 딸깍 닫았다.": "Sua menutup stabilonya, klik.", "규칙 3번.": "Aturan nomor 3.", "교실에서 뛰지 않기.": "Tidak berlari di dalam kelas.", "5번.": "Nomor 5.", "친구 밀지 않기.": "Tidak mendorong teman.", "오, 좀 하는데? 그럼 7번.": "Wah, lumayan juga? Kalau begitu, nomor 7.", "비상시에는 {@handkerchief}으로 입을 막고, 자세를 낮춰 이동한다.": "Saat darurat, tutup mulut dengan {@handkerchief}, rendahkan badan, lalu bergerak.", "완벽해.": "Sempurna.", "(……근데 ‘자세를 낮춰’가 무슨 뜻이지? 소리만 외웠어.)": "(...Tapi ‘rendahkan badan’ itu artinya apa? Aku cuma menghafal bunyinya.)", "삐— 삐— 삐—!": "Biiip— biiip— biiip—!", "방송: 「지금부터 화재 대피 훈련을 시작합니다. 담임 선생님의 안내에 따라…….」": "Pengumuman: \"Latihan evakuasi kebakaran dimulai sekarang. Ikuti arahan wali kelas masing-masing...\"", "아이들이 한꺼번에 일어났다. 선생님은 교실 뒤에서 남은 아이가 없는지 확인하고 계셨다.": "Anak-anak berdiri bersamaan. Bu Guru sedang memeriksa di belakang kelas apakah masih ada anak yang tertinggal.", "규칙 7번! {@handkerchief} 꺼내! 입 막고, 자세 낮추고, 오른쪽 {@stairs}!": "Aturan nomor 7! Keluarkan {@handkerchief}! Tutup mulut, rendahkan badan, {@stairs} sebelah kanan!", "수아 말이 너무 빨랐다. 아이들이 줄줄이 복도로 나갔다.": "Sua bicara terlalu cepat. Anak-anak keluar ke lorong satu per satu.", "({@handkerchief}…… {@handkerchief}이 뭐였지?)": "({@handkerchief}... {@handkerchief} itu apa, ya?)", "{@handkerchief}으로 입을 막았다. 그런데 ‘자세를 낮춰’는 아직도 모르겠다. 앞 친구들은 벌써 복도 끝에 있었다.": "Aku menutup mulut dengan {@handkerchief}. Tapi aku masih belum tahu arti ‘rendahkan badan’. Teman-teman di depan sudah sampai di ujung lorong.", "왜 안 와? 내가 7번 말했잖아!": "Kenapa kamu tidak ikut? Aku kan sudah bilang nomor 7!", "(외운 건 맞는데…… 뜻을 몰라.)": "(Aku memang hafal... tapi aku tidak tahu artinya.)", "「{x}」으로 내려가기": "Turun lewat 「{x}」", "운동장. 훈련이 끝났다. 수아가 출석부를 들고 내 옆으로 왔다.": "Lapangan. Latihan sudah selesai. Sua datang ke sebelahku sambil membawa buku absen.", "아까 ‘낮춰’ 몰랐던 거지? 이렇게, 몸을 낮게.": "Tadi kamu tidak tahu ‘rendahkan’, kan? Begini, badannya dibuat rendah.", "……응. 이제 알아.": "...Iya. Sekarang aku tahu.", "규칙은 외우면 끝인 줄 알았어. 뜻을 모를 수도 있구나.": "Aku kira aturan itu cukup dihafal saja. Ternyata bisa saja orang tidak tahu artinya.", "반장은 이런 것까지 다 챙겨야 해. 생각보다 어려워.": "Ketua kelas harus memperhatikan sampai hal begini juga. Ternyata lebih susah dari yang aku kira.", "알아. 그래서 나도 하고 싶어.": "Aku tahu. Makanya aku juga mau jadi ketua kelas.", "……뭐?": "...Apa?", "나도 반장 선거 나갈 거야.": "Aku juga mau ikut pemilihan ketua kelas.", "수아가 나를 빤히 봤다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "Sua menatapku lekat-lekat. Lalu dia menutup stabilonya, klik.", "좋아. 그럼 경쟁이네.": "Oke. Berarti kita bersaing.", "근데 너, 아까 뭐가 어려웠는지는 나보다 잘 알겠다.": "Tapi kamu pasti lebih tahu dariku bagian mana yang tadi susah.", "그 자리에서 수아에게 묻는다. 「천천히! ‘낮춰’가 뭐야?」": "Langsung bertanya kepada Sua. \"Pelan-pelan! ‘Rendahkan’ itu apa?\"", "수아야, 천천히! ‘자세를 낮춰’가 뭐야?": "Sua, pelan-pelan! ‘Rendahkan badan’ itu apa?", "수아가 멈칫했다. 그러더니 바로 허리를 숙여 보였다.": "Sua tertegun sebentar. Lalu dia langsung membungkukkan badan untuk menunjukkannya.", "이렇게! 몸을 낮게. 연기는 위로 올라가니까.": "Begini! Badannya dibuat rendah. Soalnya asap naik ke atas.", "아! 낮춰!": "Oh! Rendahkan!", "나는 허리를 숙이고 수아 옆에서 오른쪽 {@stairs}으로 걸었다.": "Aku membungkuk dan berjalan di sebelah Sua menuju {@stairs} sebelah kanan.", "뛰지 마. 걸어.": "Jangan lari. Jalan.", "알아. 3번.": "Aku tahu. Nomor 3.", "아는 척 고개를 끄덕이고 앞 친구를 따라 한다.": "Mengangguk pura-pura tahu, lalu meniru teman di depan.", "나는 고개를 끄덕이고 바로 앞 친구를 따라 했다. 그런데 그 친구는 쪼그려 앉아서 뒤뚱뒤뚱 걷고 있었다.": "Aku mengangguk dan langsung meniru teman di depanku. Tapi teman itu berjongkok dan berjalan megal-megol.", "그건 오리걸음이잖아!": "Itu kan jalan bebek!", "앞 친구는 장난을 치던 거였다. 나는 얼굴이 빨개졌다.": "Ternyata teman di depan itu sedang bercanda. Mukaku jadi merah.", "허리만 숙여. 이렇게.": "Bungkukkan badan saja. Begini.", "(모르는데 아는 척하니까 더 이상해졌어.)": "(Aku tidak tahu tapi pura-pura tahu, jadinya malah makin aneh.)", "내 나라에서 했던 훈련을 떠올려 판단한다.": "Mengingat latihan di negaraku untuk memutuskan.", "(우리 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "(Di sekolahku juga ada latihan ini. Kalau ada kebakaran, asap naik ke atas, jadi kami membungkuk.)", "(‘낮춰’는 그거구나!)": "(Jadi itu arti ‘rendahkan’!)", "나는 허리를 숙이고, 벽에 붙은 초록색 비상구 {@picture}을 따라 {@stairs} 쪽으로 걸었다.": "Aku membungkuk dan berjalan ke arah {@stairs}, mengikuti {@picture} pintu darurat hijau yang tertempel di dinding.", "수아가 뒤돌아보다가 눈을 동그랗게 떴다.": "Sua menoleh ke belakang, lalu matanya membulat.", "어? 맞게 하네?": "Eh? Kamu benar caranya?", "우리 학교에서도 했어.": "Di sekolahku juga ada latihan ini.", "「너 말 너무 빨라!」 하고 화부터 낸다.": "Langsung marah, \"Kamu bicaranya terlalu cepat!\"", "너 말 너무 빨라! 하나도 몰라!": "Kamu bicaranya terlalu cepat! Aku tidak mengerti sama sekali!", "지금 훈련 중이야! 그냥 따라와!": "Kita lagi latihan! Ikut saja!", "수아가 내 팔을 잡아끌었다. 둘 다 얼굴이 빨개진 채로 {@stairs}까지 갔다.": "Sua menarik lenganku. Kami berdua sampai di {@stairs} dengan muka merah.", "(화는 났는데, ‘낮춰’는 아직도 몰라.)": "(Aku sudah marah, tapi tetap saja belum tahu arti ‘rendahkan’.)", "{m}, 오늘 대피 훈련 했어. 어제 외운 규칙 7번이 나왔어.": "{m}, hari ini ada latihan evakuasi. Aturan nomor 7 yang aku hafalkan kemarin keluar.", "어머, 바로 써먹었네?": "Wah, langsung terpakai, ya?", "근데 나 ‘자세를 낮춰’가 무슨 뜻인지 몰랐어. 소리만 외웠거든.": "Tapi aku tidak tahu arti ‘rendahkan badan’. Aku cuma menghafal bunyinya.", "그래서 수아한테 천천히 말해 달라고, 낮춰가 뭐냐고 물었어. 수아가 허리 숙여서 보여 줬어.": "Jadi aku minta Sua bicara pelan-pelan dan tanya ‘rendahkan’ itu apa. Sua menunjukkannya sambil membungkuk.", "모르는 거 그 자리에서 물어봤구나. {m}가 첫날 말한 거 기억했네.": "Kamu langsung bertanya waktu tidak tahu, ya. Kamu ingat yang {m} bilang di hari pertama.", "응. 물어보니까 금방이었어.": "Iya. Begitu bertanya, langsung beres.", "아는 척하고 앞에 애를 따라 했는데, 걔가 오리걸음으로 장난치는 거였어.": "Aku pura-pura tahu dan meniru anak di depanku, ternyata dia bercanda jalan bebek.", "너도 오리걸음 했어?": "Kamu juga jalan bebek?", "{m}! 웃지 마. 수아가 그건 오리걸음이라고 소리쳤어.": "{m}! Jangan ketawa. Sua sampai teriak kalau itu jalan bebek.", "미안, 미안. 모를 땐 그냥 물어봐도 돼.": "Maaf, maaf. Kalau tidak tahu, tanya saja tidak apa-apa.", "우리 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "Aku ingat latihan di sekolahku. Waktu itu kami membungkuk karena asap. Jadi aku melakukannya dengan benar.", "아, 거기서도 했었지! 기억하고 있었구나.": "Oh, di sana juga pernah, ya! Kamu masih ingat.", "수아가 어? 맞게 하네? 그러더라.": "Sua bilang, \"Eh? Kamu benar caranya?\"", "모르는 말도 아는 걸로 알아낼 수 있구나.": "Ternyata kata yang tidak kita tahu bisa ditebak dari hal yang sudah kita tahu.", "수아한테 너무 빠르다고 화냈어. 수아도 지금 훈련 중이라고 화냈고.": "Aku marah ke Sua karena dia terlalu cepat. Sua juga marah karena kami sedang latihan.", "둘 다 급했구나.": "Kalian berdua sama-sama terburu-buru, ya.", "응. 나중에 수아가 낮춰가 뭔지 알려 줬어.": "Iya. Nanti Sua kasih tahu arti ‘rendahkan’.", "다음엔 화내기 전에 ‘천천히’부터 말해 볼까?": "Lain kali, sebelum marah, coba bilang ‘pelan-pelan’ dulu, ya?", "그리고 {m}. 나 수아한테 반장 선거 나간다고 말했어.": "Terus, {m}. Aku bilang ke Sua kalau aku mau ikut pemilihan ketua kelas.", "정말? 수아가 뭐래?": "Benarkah? Sua bilang apa?", "좋아, 그럼 경쟁이네, 그랬어.": "Dia bilang, \"Oke, berarti kita bersaing.\"", "멋있는 경쟁자네.": "Saingan yang keren.", "도서관 구석 {@desk}. 수아가 큰 {@paper}를 펼쳐 놓고 있었다. 나는 수아 맞은편에 앉았다.": "{@desk} di pojok perpustakaan. Sua sedang membentangkan {@paper} besar. Aku duduk di depan Sua.", "수아야, 뭐 해?": "Sua, lagi apa?", "규칙표 다시 만들어. {@picture}으로.": "Bikin ulang tabel aturan. Pakai {@picture}.", "어제 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "Siapa tahu masih ada anak lain yang cuma menghafal bunyinya, seperti kamu waktu latihan kemarin.", "……그거 좋다.": "...Itu bagus.", "같이 할래? 내가 글 쓰고, 넌 {@picture}.": "Mau bikin bareng? Aku yang menulis, kamu yang {@picture}.", "좋아.": "Oke.", "「{x}」 고르기": "Pilih 「{x}」", "수아는 정말 빨랐다. 순식간에 문장 다섯 개를 써 내려갔다.": "Sua benar-benar cepat. Dalam sekejap dia menulis lima kalimat.", "1번, 3번, 5번은 읽을 수 있었다. 그런데 7번 아래 새로 쓴 문장 하나가 걸렸다.": "Nomor 1, 3, dan 5 bisa aku baca. Tapi ada satu kalimat baru di bawah nomor 7 yang bikin aku bingung.", "{@paper}에 쓰인 글: 「연기가 나면 몸을 낮추고 벽을 짚으며 이동한다.」": "Tulisan di {@paper}: \"Kalau ada asap, rendahkan badan dan bergerak sambil berpegangan ke dinding.\"", "(낮추고는 알아. 근데 ‘벽을 짚으며’는 뭐지?)": "(‘Rendahkan’ aku tahu. Tapi ‘berpegangan ke dinding’ itu apa?)", "자, {@picture} 그리면 돼. 쉬는 시간 10분 남았어.": "Nah, tinggal gambar {@picture}. Istirahat tinggal 10 menit.", "수아는 벌써 다음 줄을 쓰고 있었다.": "Sua sudah menulis baris berikutnya.", "그러다 수아가 {@stairs} {@picture}을 직접 그려 보겠다며 펜을 들었다. {@paper}에 꼬불꼬불한 선이 생겼다.": "Lalu Sua mengambil pena, katanya mau menggambar {@picture} {@stairs} sendiri. Garis berkelok-kelok muncul di {@paper}.", "……그건 뭐야?": "...Itu apa?", "{@stairs}.": "{@stairs}.", "빨래판인 줄 알았어.": "Aku kira papan cuci.", "……그러니까 네가 그려.": "...Makanya kamu yang gambar.", "({@picture}은 내가 잘할 수 있어. 근데 ‘짚으며’를 모르면 뭘 그려야 하지?)": "({@picture} itu aku bisa. Tapi kalau aku tidak tahu ‘berpegangan’, aku harus gambar apa?)", "쉬는 시간이 끝나기 전에 규칙표가 완성됐다. 수아는 맨 아래에 두 사람 이름을 나란히 적었다.": "Sebelum istirahat selesai, tabel aturannya sudah jadi. Sua menulis nama kami berdua berdampingan di bagian paling bawah.", "정리하면, 글은 나, {@picture}은 너.": "Jadi, ringkasnya, tulisan aku, {@picture} kamu.", "{@stairs}도 나.": "{@stairs} juga aku.", "……{@stairs}도 너.": "...{@stairs} juga kamu.", "아는 문장만 그리고, 모르는 문장 칸은 비워 둔다.": "Menggambar kalimat yang dimengerti saja, kotak kalimat yang tidak dimengerti dibiarkan kosong.", "나는 1번, 3번, 5번만 그렸다. 7번 칸은 비워 뒀다.": "Aku cuma menggambar nomor 1, 3, dan 5. Kotak nomor 7 aku biarkan kosong.", "7번은?": "Nomor 7?", "……그건 나중에.": "...Itu nanti saja.", "제일 중요한 건데?": "Itu kan yang paling penting?", "‘짚으며’를 몰라서.": "Soalnya aku tidak tahu ‘berpegangan’.", "아, 그래? 그럼 처음부터 말하지.": "Oh, begitu? Kenapa tidak bilang dari awal?", "모르는 말에 동그라미를 치고 묻는다. 「이거 무슨 뜻이야?」": "Melingkari kata yang tidak dimengerti lalu bertanya. \"Ini artinya apa?\"", "나는 ‘짚으며’에 {@pencil}로 동그라미를 쳤다.": "Aku melingkari ‘berpegangan’ dengan {@pencil}.", "이거 무슨 뜻이야?": "Ini artinya apa?", "벽을 짚으며? {@hand}을 벽에 대고 가는 거.": "Berpegangan ke dinding? Jalan sambil menempelkan {@hand} ke dinding.", "수아가 손바닥을 책장에 붙여 보였다.": "Sua menempelkan telapak tangannya ke rak buku untuk menunjukkannya.", "아! 그럼 {@hand}을 벽에 대고, 허리 숙이고, 걷는 사람.": "Oh! Jadi orang yang menempelkan {@hand} ke dinding, membungkuk, lalu berjalan.", "응. 그거.": "Iya. Itu.", "나는 그 모습을 그렸다. 수아가 {@picture}을 보더니 고개를 끄덕였다.": "Aku menggambar seperti itu. Sua melihat {@picture} itu, lalu mengangguk.", "내가 이해한 대로 먼저 그려서 보여 준다. 「이거 맞아?」": "Menggambar dulu sesuai yang dipahami, lalu menunjukkannya. \"Ini benar?\"", "나는 내가 이해한 대로 그렸다. 연기 아래에서 바닥을 짚고 엉금엉금 기어가는 사람.": "Aku menggambar sesuai yang aku pahami. Orang yang merangkak pelan-pelan di bawah asap sambil bertumpu ke lantai.", "이거 맞아?": "Ini benar?", "……기어가라는 게 아니고!": "...Bukan disuruh merangkak!", "수아가 웃음을 터뜨렸다. 도서관이라 둘 다 입을 막았다.": "Sua tertawa terbahak. Karena di perpustakaan, kami berdua menutup mulut.", "바닥 말고 벽. {@hand}을 벽에 대고 걷는 거야.": "Bukan lantai, tapi dinding. Jalan sambil menempelkan {@hand} ke dinding.", "아, 벽! 그럼 이렇게?": "Oh, dinding! Kalau begini?", "나는 {@picture}을 고쳤다. 수아가 {@picture}을 보더니 자기 문장을 다시 봤다.": "Aku memperbaiki {@picture} itu. Sua melihat {@picture} itu, lalu membaca lagi kalimatnya sendiri.", "{@picture} 보니까 내 문장이 너무 기네. 줄일게.": "Setelah lihat {@picture}, kalimatku kepanjangan. Aku pendekkan.", "「수아야, 그냥 네가 다 해. 넌 다 잘하잖아.」": "\"Sua, kamu saja yang mengerjakan semuanya. Kamu kan jago semuanya.\"", "그냥 네가 다 해. 넌 다 잘하잖아.": "Kamu saja yang mengerjakan semuanya. Kamu kan jago semuanya.", "나 {@picture} 못 그리는 거 방금 봤잖아.": "Barusan kamu lihat sendiri aku tidak bisa menggambar {@picture}.", "……그래도.": "...Tapi tetap saja.", "그래도는 무슨. 빨래판 {@stairs} 붙일 거야?": "Tetap saja apanya. Mau tempel {@stairs} papan cuci?", "수아가 {@colored_pencil} 통을 내 쪽으로 밀었다.": "Sua mendorong kotak {@colored_pencil} ke arahku.", "네가 그려. 모르는 거 있으면 물어보고.": "Kamu yang gambar. Kalau ada yang tidak tahu, tanya saja.", "{m}, 수아랑 규칙표 만들었어. 수아가 글 쓰고 내가 {@picture} 그렸어.": "{m}, aku bikin tabel aturan bareng Sua. Sua yang menulis, aku yang menggambar {@picture}.", "오, {@picture}은 네가?": "Oh, {@picture} itu kamu yang gambar?", "응. 수아 {@picture} 진짜 못 그려. {@stairs}을 그렸는데 빨래판 같았어.": "Iya. Sua benar-benar tidak bisa menggambar {@picture}. Dia menggambar {@stairs}, tapi kelihatan seperti papan cuci.", "수아도 못하는 게 있구나.": "Ternyata Sua juga punya hal yang tidak bisa dia lakukan.", "근데 나 모르는 말이 있어서 그 칸은 비워 뒀어. 수아가 제일 중요한 거라고, 처음부터 말하지 그랬냐고 하더라.": "Tapi ada kata yang aku tidak tahu, jadi kotak itu aku biarkan kosong. Sua bilang itu yang paling penting, kenapa tidak bilang dari awal.", "그럼 그 칸은 어떻게 했어?": "Terus kotak itu bagaimana?", "결국 물어보고 그렸어.": "Akhirnya aku tanya, lalu aku gambar.", "처음부터 물었으면 더 빨랐겠다.": "Kalau tanya dari awal pasti lebih cepat.", "‘짚으며’를 몰라서 동그라미 치고 물어봤어. 수아가 {@hand}을 책장에 대고 보여 줬어.": "Aku tidak tahu ‘berpegangan’, jadi aku lingkari lalu tanya. Sua menunjukkannya dengan menempelkan {@hand} ke rak buku.", "그래서 {@picture}이 맞게 됐어?": "Jadi {@picture} itu jadi benar?", "응. 수아가 고개 끄덕였어.": "Iya. Sua mengangguk.", "내가 이해한 대로 그렸는데, 사람이 바닥을 기어가고 있었어.": "Aku menggambar sesuai yang aku pahami, tapi orangnya malah merangkak di lantai.", "기어가?": "Merangkak?", "수아가 기어가라는 게 아니고! 하면서 웃었어. 근데 수아가 {@picture} 보더니 자기 문장이 너무 길대. 줄였어.": "Sua bilang, \"Bukan disuruh merangkak!\" sambil tertawa. Tapi setelah lihat {@picture}, Sua bilang kalimatnya kepanjangan. Jadi dia pendekkan.", "{@picture} 덕분에 글도 바뀌었네.": "Berkat {@picture}, tulisannya juga berubah, ya.", "수아한테 그냥 네가 다 하라고 했어. 넌 다 잘하니까.": "Aku bilang ke Sua, dia saja yang mengerjakan semuanya. Soalnya dia jago semuanya.", "수아가 뭐래?": "Sua bilang apa?", "빨래판 {@stairs} 붙일 거냐고. 그래서 내가 그렸어.": "Dia tanya, mau tempel {@stairs} papan cuci? Jadi aku yang gambar.", "수아 말이 맞네. {@picture}은 네가 더 잘하잖아.": "Sua benar. {@picture} itu kamu lebih jago.", "방금 학급회의가 끝났다. 안건은 ‘금요일 학급 놀이 시간에 뭐 할까’였다.": "Rapat kelas baru saja selesai. Topiknya ‘Mau main apa di jam bermain kelas hari Jumat’.", "나는 처음으로 {@hand}을 들고 우리 나라 놀이를 말했다. 떨려서 말이 엉켰다.": "Untuk pertama kalinya aku mengangkat {@hand} dan menceritakan permainan dari negaraku. Aku gugup, jadi bicaraku berantakan.", "(아까 수아가 한 말) 「음…… 규칙이 복잡해 보여서 어려울 것 같아요. 다음 의견!」": "(Kata Sua tadi) \"Hmm... aturannya kelihatan rumit, jadi sepertinya susah. Pendapat berikutnya!\"", "결국 피구로 정해졌다. 아이들이 {@chair}를 정리하며 흩어졌다. 나는 수아에게 갔다.": "Akhirnya diputuskan main bola beracun. Anak-anak membereskan {@chair} lalu bubar. Aku menghampiri Sua.", "「{x}」 넣기": "Masukkan 「{x}」", "수아야, 아까 내 놀이…….": "Sua, permainanku tadi...", "아, 그거! 나도 얘기하려고 했어.": "Oh, itu! Aku juga mau membahasnya.", "수아가 주위를 한 번 둘러보더니 목소리를 낮췄다.": "Sua melihat ke sekeliling sekali, lalu memelankan suaranya.", "……사실 나, 하나도 못 알아들었어.": "...Sebenarnya, aku sama sekali tidak mengerti.", "어?": "Hah?", "네가 말할 때 ‘수건’이랑 ‘같은 편’은 들렸는데, 나머지는 몰랐어. 근데 반장이 못 알아들었다고 하면 이상하잖아.": "Waktu kamu bicara, aku dengar ‘sapu tangan’ dan ‘satu tim’, tapi sisanya aku tidak tahu. Tapi kalau ketua kelas bilang tidak mengerti, kan aneh.", "그래서 그냥 어렵다고 넘긴 거야.": "Makanya aku bilang susah saja, lalu lanjut.", "(수아도…… 나를 못 알아들었구나.)": "(Sua juga... tidak mengerti aku.)", "(대피 훈련 때 내가 수아 말을 못 알아들은 거랑 똑같네.)": "(Sama seperti aku tidak mengerti Sua waktu latihan evakuasi.)", "다시 설명해 줄래? 이번엔 진짜 들을게.": "Mau jelaskan lagi? Kali ini aku benar-benar dengar.", "수아가 형광펜을 꺼내 학급회의 {w}에 적었다.": "Sua mengeluarkan stabilo dan menulis di {w} rapat kelas.", "수아의 {w}: 「다음 학급회의 안건: 같은 편 {@handkerchief} 놀이」": "{w} Sua: \"Topik rapat kelas berikutnya: permainan {@handkerchief} Satu Tim\"", "다음 회의에 다시 올리자. 이번엔 제대로.": "Kita ajukan lagi di rapat berikutnya. Kali ini dengan benar.", "어떻게 설명할까?": "Bagaimana cara menjelaskannya?", "「말보다 해 보는 게 빨라.」 하고 직접 보여 준다.": "\"Lebih cepat dicoba daripada dijelaskan.\" Langsung menunjukkannya.", "말보다 해 보는 게 빨라. 앉아 봐.": "Lebih cepat dicoba daripada dijelaskan. Coba duduk.", "나는 수아를 {@chair}에 앉히고 등 뒤로 돌아가 {@handkerchief}을 살짝 놓았다.": "Aku menyuruh Sua duduk di {@chair}, lalu berjalan ke belakangnya dan diam-diam meletakkan {@handkerchief}.", "이제 뒤에 뭐 있는지 봐.": "Sekarang lihat ada apa di belakangmu.", "어? {@handkerchief}?": "Eh? {@handkerchief}?", "그럼 날 잡아야 해. 잡히면 나는 술래 아니고, 네 편이 돼.": "Berarti kamu harus menangkapku. Kalau aku tertangkap, aku tidak jadi penjaga, tapi jadi satu tim denganmu.", "……잡히면 같은 편? 그게 다야?": "...Tertangkap jadi satu tim? Cuma itu?", "응. 마지막엔 다 같은 편이야.": "Iya. Di akhir, semuanya jadi satu tim.", "아, 이거 재밌겠다!": "Wah, ini pasti seru!", "「됐어. 어차피 안 된다며.」 하고 돌아선다.": "\"Sudahlah. Katanya tidak bisa.\" Lalu berbalik pergi.", "됐어. 어차피 안 된다며.": "Sudahlah. Katanya tidak bisa.", "아니, 그래서 지금 다시…….": "Bukan, makanya sekarang aku mau...", "피구로 정해졌잖아.": "Kan sudah diputuskan main bola beracun.", "나는 {@bag}을 챙겼다. 수아는 형광펜을 만지작거리며 서 있었다.": "Aku membereskan {@bag}. Sua berdiri sambil memainkan stabilonya.", "……다음 학급회의 때 다시 올리면 돼. 마음 바뀌면 말해 줘.": "...Kita bisa ajukan lagi di rapat kelas berikutnya. Kalau kamu berubah pikiran, bilang, ya.", "(속상한 건 맞아. 근데 수아는 진짜 듣고 싶어 했는데.)": "(Aku memang kesal. Tapi Sua benar-benar ingin mendengarnya.)", "아까 못 한 말까지 한꺼번에 몰아서 설명한다.": "Menjelaskan semua yang tadi tidak sempat dikatakan sekaligus.", "그러니까 동그랗게 앉아서 술래가 돌다가 {@handkerchief}을 뒤에 놓으면 그걸 알아채서 쫓아가는데 잡히면 술래가 안 되고 잡은 사람 편이 되고 그다음엔 그 편이 같이 술래를…….": "Jadi duduk melingkar lalu penjaga berkeliling terus kalau dia meletakkan {@handkerchief} di belakang kita harus sadar lalu mengejar tapi kalau tertangkap tidak jadi penjaga malah jadi satu tim dengan yang menangkap lalu setelah itu tim itu sama-sama jadi penjaga...", "잠깐, 잠깐! 너도 빨라!": "Tunggu, tunggu! Kamu juga cepat!", "수아가 두 {@hand}을 들었다. 우리 둘 다 웃음이 터졌다.": "Sua mengangkat kedua {@hand}. Kami berdua tertawa terbahak.", "……대피 훈련 때 너 같았어?": "...Waktu latihan evakuasi aku seperti kamu, ya?", "응. 딱 나 같았어.": "Iya. Persis seperti aku.", "나는 처음부터 다시, 한 문장씩 천천히 말했다.": "Aku menjelaskan lagi dari awal, pelan-pelan, satu kalimat demi satu kalimat.", "아까 속상했던 것부터 말하고, 그다음 설명한다.": "Menceritakan rasa kesal tadi dulu, baru menjelaskan.", "설명할게. 근데 먼저 말할 거 있어.": "Aku jelaskan. Tapi ada yang mau aku bilang dulu.", "아까 바로 다음 의견, 해서 좀 속상했어. 처음으로 {@hand} 들었거든.": "Tadi kamu langsung bilang ‘pendapat berikutnya’, aku agak kesal. Itu pertama kalinya aku mengangkat {@hand}.", "……그랬구나. 미안. 못 알아들은 거 들킬까 봐 빨리 넘긴 거야.": "...Begitu, ya. Maaf. Aku cepat-cepat lanjut karena takut ketahuan tidak mengerti.", "이제 천천히 할게. 동그랗게 앉아. 술래가 {@handkerchief}을 뒤에 놓아. 잡히면 같은 편이 돼.": "Sekarang aku pelan-pelan. Duduk melingkar. Penjaga meletakkan {@handkerchief} di belakang. Kalau tertangkap, jadi satu tim.", "세 문장이네. 정리 잘한다.": "Tiga kalimat. Kamu pintar meringkas.", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. 우리 나라 놀이 하자고.": "{m}, hari ini di rapat kelas aku mengangkat {@hand} untuk pertama kalinya. Aku usul main permainan dari negaraku.", "정말? 어떻게 됐어?": "Benarkah? Terus bagaimana?", "수아가 어려울 것 같다고 바로 다음 의견 했어. 근데 끝나고 수아가 사실 하나도 못 알아들었대.": "Sua bilang sepertinya susah, lalu langsung ke pendapat berikutnya. Tapi setelah selesai, Sua bilang sebenarnya dia sama sekali tidak mengerti.", "어머, 수아가 그렇게 말했어?": "Wah, Sua bilang begitu?", "그래서 말 말고 직접 보여 줬어. 수아를 앉히고 {@handkerchief} 놓았지.": "Jadi aku tidak menjelaskan, tapi langsung menunjukkannya. Aku suruh Sua duduk, lalu aku letakkan {@handkerchief}.", "수아는?": "Sua bagaimana?", "이거 재밌겠다! 그랬어.": "Dia bilang, \"Wah, ini pasti seru!\"", "해 보니까 금방 알았구나.": "Begitu dicoba, langsung mengerti, ya.", "근데 나 너무 속상해서 됐다고 하고 그냥 왔어.": "Tapi aku kesal sekali, jadi aku bilang sudahlah, lalu pergi saja.", "속상했겠다. 처음 {@hand} 든 거였잖아.": "Pasti kesal, ya. Itu pertama kalinya kamu mengangkat {@hand}.", "응. 수아가 다음 회의 때 다시 올리면 된대.": "Iya. Sua bilang bisa diajukan lagi di rapat berikutnya.", "그럼 다음엔 어떻게 할래?": "Terus lain kali kamu mau bagaimana?", "아까 못 한 말 한꺼번에 막 했더니, 수아가 너도 빨라! 그랬어.": "Aku bicara semua yang tadi tidak sempat sekaligus, terus Sua bilang, \"Kamu juga cepat!\"", "대피 훈련 때랑 반대네?": "Kebalikan dari waktu latihan evakuasi, ya?", "응. 둘이 웃었어. 그다음엔 천천히 했어.": "Iya. Kami berdua tertawa. Setelah itu aku bicara pelan-pelan.", "속상했다고 먼저 말했어. 수아가 미안하대. 못 알아들은 거 들킬까 봐 그랬대.": "Aku bilang dulu kalau aku kesal. Sua minta maaf. Katanya dia takut ketahuan tidak mengerti.", "수아도 솔직하게 말했네.": "Sua juga jujur, ya.", "그러고 세 문장으로 설명했더니 정리 잘한대.": "Terus aku jelaskan dalam tiga kalimat, dan dia bilang aku pintar meringkas.", "반장도 못 알아들을 때가 있구나.": "Ternyata ketua kelas juga kadang tidak mengerti, ya.", "응. 나만 그런 줄 알았어.": "Iya. Aku kira cuma aku yang begitu.", "점심시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "Jam makan siang. Sua sedang membuka {w} rapat kelas. Aku duduk di sebelah Sua.", "다음 학급회의 내일이야. 놀이 발표 준비하자.": "Rapat kelas berikutnya besok. Ayo siapkan presentasi permainannya.", "「{x}」 보기": "Lihat 「{x}」", "학급회의는 한 사람이 2분 안에 말해야 해. 규칙 12번.": "Di rapat kelas, setiap orang harus bicara dalam 2 menit. Aturan nomor 12.", "그래서 생각해 봤는데, 발표는 내가 할게.": "Jadi aku sudah pikirkan, biar aku yang presentasi.", "……네가?": "...Kamu?", "응. 나는 2분 안에 정리할 수 있어. 넌 아직 한국말이 느리잖아. 떨어지면 아깝잖아.": "Iya. Aku bisa meringkas dalam 2 menit. Bahasa Koreamu kan masih lambat. Sayang kalau sampai ditolak.", "수아 말은 틀린 데가 없었다. 그래서 더 할 말이 없었다.": "Kata-kata Sua tidak ada yang salah. Makanya aku tidak bisa bilang apa-apa lagi.", "(맞는 말이야. 수아가 하면 통과될 거야.)": "(Dia benar. Kalau Sua yang presentasi, pasti diterima.)", "(근데…… 내 놀이인데.)": "(Tapi... itu kan permainanku.)", "종이 울렸다. 수아가 형광펜 뚜껑을 딸깍 닫았다.": "Bel berbunyi. Sua menutup stabilonya, klik.", "내일 떨지 마.": "Besok jangan gugup.", "너도.": "Kamu juga.", "나는 안 떨어.": "Aku tidak gugup.", "「그럼…… 네가 해.」": "\"Kalau begitu... kamu saja.\"", "그럼…… 네가 해.": "Kalau begitu... kamu saja.", "좋아. 내가 깔끔하게 정리할게.": "Oke. Aku akan meringkasnya dengan rapi.", "수아가 형광펜으로 줄을 그었다. 나는 옆에서 고개만 끄덕였다.": "Sua menarik garis dengan stabilo. Aku cuma mengangguk di sebelahnya.", "(이게 맞는 건가.)": "(Apa ini sudah benar?)", "「내가 할게. 대신 2분 맞추는 연습 같이 해 줘.」": "\"Aku saja. Tapi bantu aku latihan supaya pas 2 menit.\"", "내가 할게. 내 놀이니까.": "Aku saja. Kan permainanku.", "2분 넘으면?": "Kalau lebih dari 2 menit?", "그러니까 연습 같이 해 줘. 네가 {@clock} 봐 줘.": "Makanya bantu aku latihan. Kamu lihat {@clock}, ya.", "수아가 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "Sua melihat {@clock}. Aku menjelaskan dari awal. Lebih dari 3 menit.", "정리하면, 세 문장만 해. 앉는다. 놓는다. 잡히면 같은 편.": "Jadi, ringkasnya, tiga kalimat saja. Duduk. Letakkan. Tertangkap jadi satu tim.", "다시 했다. 1분 50초.": "Aku coba lagi. 1 menit 50 detik.", "……됐네.": "...Bisa, kan.", "「넌 그냥 반장이라서 다 하고 싶은 거잖아.」": "\"Kamu cuma mau mengerjakan semuanya karena kamu ketua kelas.\"", "넌 그냥 반장이라서 다 하고 싶은 거잖아.": "Kamu cuma mau mengerjakan semuanya karena kamu ketua kelas.", "뭐? 나는 통과되라고 그런 건데!": "Apa? Aku begitu supaya usulnya diterima!", "내 놀이인데 왜 네가 해?": "Itu permainanku, kenapa kamu yang presentasi?", "둘 다 목소리가 커졌다. 옆에서 밥 먹던 아이들이 쳐다봤다.": "Suara kami berdua makin keras. Anak-anak yang sedang makan di sebelah menoleh.", "……그럼 네가 해 봐. 2분 넘으면 내가 {@hand} 들 거야.": "...Kalau begitu, coba kamu saja. Kalau lebih dari 2 menit, aku angkat {@hand}.", "「나눠서 하자. 시범은 내가, 규칙 설명은 네가.」": "\"Kita bagi saja. Peragaan aku, penjelasan aturan kamu.\"", "나눠서 하자. 시범은 내가 보여 줄게. 규칙 설명은 네가 해.": "Kita bagi saja. Aku yang memperagakan. Kamu yang menjelaskan aturannya.", "시범?": "Peragaan?", "말로 하면 애들이 못 알아들어. 너도 못 알아들었잖아.": "Kalau cuma dijelaskan, anak-anak tidak akan mengerti. Kamu juga tidak mengerti, kan.", "……그건 맞아.": "...Itu benar.", "수아가 {w}에 두 칸을 그었다. 한쪽에 ‘시범’, 한쪽에 ‘규칙’.": "Sua menggambar dua kotak di {w}. Satu ‘peragaan’, satu ‘aturan’.", "그럼 넌 몸으로, 난 말로.": "Jadi kamu pakai badan, aku pakai kata-kata.", "{m}, 내일 학급회의에서 우리 나라 놀이 다시 발표해.": "{m}, besok di rapat kelas aku presentasi permainan dari negaraku lagi.", "오, 누가 발표해?": "Oh, siapa yang presentasi?", "수아가 자기가 하겠대. 나는 한국말이 느려서 2분 안에 못 할 거래.": "Sua bilang biar dia saja. Katanya bahasa Koreaku masih lambat, jadi tidak bisa selesai dalam 2 menit.", "음…… 그래서?": "Hmm... terus?", "그럼 네가 하라고 했어.": "Aku bilang, ya sudah, kamu saja.", "수아가 하는 게 더 나을 것 같았어?": "Kamu pikir lebih baik Sua yang presentasi?", "응. 근데 좀 이상해. 내 놀이인데.": "Iya. Tapi rasanya agak aneh. Itu kan permainanku.", "그 마음이 드는 게 당연하지.": "Wajar kalau kamu merasa begitu.", "내가 한다고 했어. 대신 수아한테 {@clock} 봐 달라고 했어.": "Aku bilang aku saja. Tapi aku minta Sua lihat {@clock}.", "몇 분 걸렸어?": "Berapa menit?", "처음엔 3분. 수아가 세 문장만 하라고 해서 1분 50초 됐어.": "Awalnya 3 menit. Sua suruh aku pakai tiga kalimat saja, jadi 1 menit 50 detik.", "수아는 시간 재 주고, 너는 발표하고. 둘이 잘 나눴네.": "Sua mengukur waktu, kamu presentasi. Kalian berbagi tugas dengan baik.", "너는 반장이라서 다 하고 싶은 거라고 했어. 수아도 화냈어.": "Aku bilang dia mau mengerjakan semuanya karena dia ketua kelas. Sua juga marah.", "수아는 무슨 마음이었을까?": "Kira-kira Sua merasa apa, ya?", "통과되라고 그랬대.": "Katanya dia begitu supaya usulnya diterima.", "그 말을 듣고 나니까 어때?": "Setelah dengar itu, kamu merasa bagaimana?", "……좀 미안해. 그래도 내가 할 거야.": "...Agak menyesal. Tapi tetap aku yang presentasi.", "나눠서 하자고 했어. 시범은 내가, 규칙 설명은 수아가.": "Aku usul kita bagi saja. Peragaan aku, penjelasan aturan Sua.", "수아도 말로는 못 알아들었잖아. 해 보니까 알았어.": "Sua juga tidak mengerti kalau cuma dijelaskan. Begitu dicoba, baru dia mengerti.", "네가 잘하는 걸로 맡았구나.": "Kamu ambil bagian yang kamu jago, ya.", "학급회의 시간. 두 번째 안건은 내 놀이였다. 나는 앞으로 나가기 전에 수아 자리로 갔다.": "Rapat kelas. Topik kedua adalah permainanku. Sebelum maju ke depan, aku pergi ke tempat duduk Sua.", "준비됐어?": "Sudah siap?", "수아가 먼저 앞에 나가 규칙을 설명했다. 그런데 아이들이 웅성거렸다.": "Sua maju duluan dan menjelaskan aturannya. Tapi anak-anak jadi ribut.", "아이들: 「잘 모르겠어.」 「만든 사람이 보여 줘!」": "Anak-anak: \"Tidak terlalu mengerti.\" \"Yang bikin, tunjukkan dong!\"", "수아가 나를 봤다.": "Sua melihat ke arahku.", "……네가 나와.": "...Kamu yang maju.", "내가 앞에 나갔다. 수아는 맨 앞자리에서 {@clock}를 보고 있었다.": "Aku maju ke depan. Sua duduk di bangku paling depan sambil melihat {@clock}.", "수아가 규칙을 말하고, 나는 시범을 보이려고 앞에 섰다.": "Sua menjelaskan aturan, dan aku berdiri di depan untuk memperagakan.", "나는 {@blackboard} 앞에 섰다. 아이들 얼굴이 한꺼번에 보였다.": "Aku berdiri di depan {@blackboard}. Wajah anak-anak terlihat semua sekaligus.", "동그랗게 앉아요. 술래가 {@handkerchief}을 뒤에 놓아요.": "Duduk melingkar. Penjaga meletakkan {@handkerchief} di belakang.", "{@hand}을 든 아이가 있었다.": "Ada anak yang mengangkat {@hand}.", "「{x}」 든 친구 가리키기": "Tunjuk teman yang mengangkat 「{x}」", "아이: 「근데 잡히면 어떻게 돼? 술래 되는 거야?」": "Seorang anak: \"Terus kalau tertangkap bagaimana? Jadi penjaga?\"", "아니요. 잡히면…… 잡히면…….": "Bukan. Kalau tertangkap... kalau tertangkap...", "머릿속이 하얘졌다. 우리 말로는 바로 떠오르는데, 한국말이 생각나지 않았다.": "Kepalaku jadi kosong. Dalam bahasaku langsung terpikir, tapi bahasa Koreanya tidak teringat.", "(같은…… 뭐였지? 어제 수아가 말했는데.)": "(Satu... apa, ya? Kemarin Sua bilang.)", "몇몇이 고개를 갸웃했다. 누군가 작게 킥 웃었다. 수아가 맨 앞에서 나를 보고 있었다.": "Beberapa anak memiringkan kepala. Ada yang tertawa kecil. Sua menatapku dari depan.", "선생님: 「재미있겠네요. 다음 체육 시간에 한번 해 봅시다.」": "Bu Guru: \"Kedengarannya seru. Ayo kita coba di jam olahraga berikutnya.\"", "아이들이 손뼉을 쳤다. 나는 자리로 돌아오면서 다리에 힘이 풀렸다.": "Anak-anak bertepuk tangan. Waktu kembali ke tempat duduk, kakiku lemas.", "학급회의가 끝나고 수아가 내 자리로 왔다.": "Setelah rapat kelas selesai, Sua datang ke tempat dudukku.", "통과됐네.": "Diterima, ya.", "이상하다. 나는 떨어질까 봐 내가 하겠다고 한 건데.": "Aneh. Padahal aku mau presentasi sendiri karena takut ditolak.", "……너 이제 진짜 경쟁자 같다.": "...Sekarang kamu benar-benar seperti saingan.", "원래 경쟁자였잖아.": "Dari awal kan memang saingan.", "아니. 오늘부터 진짜.": "Bukan. Mulai hari ini benar-benar saingan.", "수아에게 눈짓해서 대신 말해 달라고 한다.": "Memberi kode ke Sua supaya dia yang menjawab.", "나는 수아를 봤다. 수아가 바로 알아듣고 일어났다.": "Aku melihat ke arah Sua. Sua langsung mengerti dan berdiri.", "잡히면 잡은 사람 같은 편이 돼요.": "Kalau tertangkap, jadi satu tim dengan yang menangkap.", "아이: 「아, 그렇구나.」": "Seorang anak: \"Oh, begitu.\"", "아이들이 고개를 끄덕였다. 나는 그다음 말을 이어 갔다.": "Anak-anak mengangguk. Aku melanjutkan penjelasan berikutnya.", "(넘어갔어. 근데…… 내 발표였는데.)": "(Lewat juga. Tapi... ini kan presentasiku.)", "말 대신 몸으로 보여 준다.": "Menunjukkan dengan gerakan, bukan dengan kata-kata.", "잠깐만요. 보여 줄게요.": "Sebentar. Aku tunjukkan.", "나는 질문한 아이에게 다가가 {@hand}을 잡았다. 그리고 그 아이를 데리고 내 옆으로 와서 나란히 섰다.": "Aku mendekati anak yang bertanya dan memegang {@hand}-nya. Lalu aku membawanya ke sebelahku dan kami berdiri berdampingan.", "잡히면, 이렇게. 나랑 같이.": "Kalau tertangkap, begini. Bersama aku.", "아이: 「아! 같은 편!」": "Seorang anak: \"Oh! Satu tim!\"", "네! 같은 편!": "Iya! Satu tim!", "몇 명이 신이 나서 「같은 편!」 하고 따라 했다. 교실이 웃음으로 시끌시끌해졌다. 이번 웃음은 나를 향한 게 아니었다.": "Beberapa anak ikut bersemangat berseru, \"Satu tim!\" Kelas jadi ramai dengan tawa. Kali ini tawanya bukan untuk menertawakan aku.", "솔직하게 말하고 반 친구들에게 묻는다.": "Bicara jujur dan bertanya kepada teman-teman sekelas.", "그 말이 한국말로 생각이 안 나요.": "Kata itu tidak teringat dalam bahasa Korea.", "우리 말로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "Dalam bahasaku langsung terpikir. Kalau tertangkap, jadi satu kelompok dengan yang menangkap. Ini bahasa Koreanya apa?", "아이들: 「같은 편!」": "Anak-anak: \"Satu tim!\"", "맞아요! 같은 편이 돼요.": "Betul! Jadi satu tim.", "아이: 「너네 나라 말로는 뭔데? 다시 해 봐!」": "Seorang anak: \"Kalau di bahasa negaramu apa? Coba ucapkan lagi!\"", "아이들이 내 나라 말을 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "Anak-anak menirukan bahasa negaraku. Pengucapannya kacau semua. Kelas tertawa riuh. Aku juga ikut tertawa.", "그 부분은 건너뛰고 「아무튼 재밌어요!」 하고 끝낸다.": "Melewati bagian itu dan menutup dengan \"Pokoknya seru!\"", "그건…… 해 보면 알아요. 아무튼 재밌어요!": "Itu... nanti tahu sendiri kalau dicoba. Pokoknya seru!", "아이들이 서로 얼굴을 봤다.": "Anak-anak saling pandang.", "아이: 「잡히면 어떻게 되는지 모르는데?」": "Seorang anak: \"Kami tidak tahu apa yang terjadi kalau tertangkap?\"", "수아가 {@hand}을 들고 일어나 대신 설명했다. 아이들이 그제야 고개를 끄덕였다.": "Sua mengangkat {@hand}, berdiri, lalu menjelaskan menggantikanku. Barulah anak-anak mengangguk.", "(빨리 끝내고 싶었는데, 오히려 더 길어졌어.)": "(Aku mau cepat selesai, tapi malah jadi makin lama.)", "{m}! 우리 나라 놀이 통과됐어!": "{m}! Permainan dari negaraku diterima!", "정말? 잘됐다!": "Benarkah? Hebat!", "근데 발표하다가 ‘같은 편’이 한국말로 생각이 안 났어. 머리가 하얘졌어.": "Tapi waktu presentasi, aku tidak ingat bahasa Korea untuk ‘satu tim’. Kepalaku jadi kosong.", "수아한테 눈짓했더니 수아가 대신 말해 줬어.": "Aku memberi kode ke Sua, lalu Sua yang menjawab menggantikan aku.", "수아가 바로 알아챘구나.": "Sua langsung paham, ya.", "응. 근데 좀 아쉬워. 내 발표였는데.": "Iya. Tapi agak sayang. Itu kan presentasiku.", "그래도 끝까지 서 있었잖아. 다음엔 네 방법도 하나 준비해 가 볼까?": "Tapi kamu tetap berdiri sampai selesai. Lain kali, mau coba siapkan satu caramu sendiri?", "말 대신 보여 줬어. 질문한 애 {@hand} 잡고 내 옆에 세웠더니, 걔가 같은 편! 그랬어.": "Aku menunjukkan, bukan menjelaskan. Aku pegang {@hand} anak yang bertanya, lalu aku suruh dia berdiri di sebelahku, terus dia bilang, \"Satu tim!\"", "말이 막혔는데 몸으로 했구나.": "Kata-katamu tersendat, tapi kamu pakai gerakan, ya.", "애들이 다 같은 편! 하고 따라 했어. 웃었는데 기분 나쁘지 않았어.": "Anak-anak semua ikut bilang, \"Satu tim!\" Mereka tertawa, tapi aku tidak merasa sakit hati.", "같이 웃은 거니까.": "Soalnya kalian tertawa bersama.", "한국말이 생각 안 난다고 솔직하게 말했어. 우리 말로 하고, 한국말로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "Aku jujur bilang tidak ingat bahasa Koreanya. Aku bilang dalam bahasaku, lalu tanya bahasa Koreanya apa, terus anak-anak sama-sama memberi tahu.", "반 친구들 앞에서 그걸 물었어?": "Kamu tanya itu di depan teman-teman sekelas?", "응. 애들이 우리 말도 따라 했어. 발음이 엉망이었어.": "Iya. Anak-anak juga menirukan bahasaku. Pengucapannya kacau.", "너한테 한국말 배우고, 너한테 우리 말 배우고.": "Kamu belajar bahasa Korea dari mereka, mereka belajar bahasamu darimu.", "그냥 해 보면 안다고 하고 넘어가려고 했어. 근데 애들이 모르겠다고 해서 수아가 설명했어.": "Aku mau lewati saja dengan bilang nanti tahu sendiri kalau dicoba. Tapi anak-anak bilang tidak mengerti, jadi Sua yang menjelaskan.", "빨리 끝내고 싶었구나.": "Kamu ingin cepat selesai, ya.", "응. 근데 더 길어졌어.": "Iya. Tapi malah jadi lebih lama.", "다음엔 모르는 말 하나쯤은 물어봐도 괜찮아.": "Lain kali, bertanya satu kata yang tidak kamu tahu juga tidak apa-apa.", "그리고 수아가 나보고 오늘부터 진짜 경쟁자래.": "Terus, Sua bilang mulai hari ini aku benar-benar saingannya.", "와. 반장한테 그런 말 들었어?": "Wah. Ketua kelas bilang begitu?", "응. 좀 좋았어.": "Iya. Aku agak senang.", "체육 시간. 드디어 같은 편 {@handkerchief} 놀이를 하는 날이었다. 반 전체가 운동장에 동그랗게 앉았다.": "Jam olahraga. Akhirnya hari ini kami main permainan {@handkerchief} Satu Tim. Seluruh kelas duduk melingkar di lapangan.", "처음 5분은 좋았다. 그런데 곧 이상해졌다.": "Lima menit pertama asyik. Tapi tidak lama kemudian jadi aneh.", "아이: 「나 잡혔는데 그냥 계속 도망갈래!」": "Seorang anak: \"Aku sudah tertangkap, tapi aku mau terus kabur saja!\"", "아이: 「반칙이야! 잡히면 같은 편이랬잖아!」": "Seorang anak: \"Curang! Katanya kalau tertangkap jadi satu tim!\"", "아이: 「같은 편 되면 뭐 해? 그다음엔?」": "Seorang anak: \"Kalau sudah satu tim, terus ngapain? Habis itu apa?\"", "잡힌 아이들이 어디로 가야 할지 몰라 우왕좌왕했다. 원이 흐트러지고, 여기저기서 말다툼이 났다. {@handkerchief}이 바닥에 떨어져 있었다.": "Anak-anak yang tertangkap bingung harus ke mana, jadi mondar-mandir. Lingkarannya berantakan, di sana-sini ada yang bertengkar. {@handkerchief} tergeletak di tanah.", "나는 수아에게 갔다. 수아는 팔짱을 끼고 서 있었다.": "Aku menghampiri Sua. Sua berdiri sambil melipat tangan.", "이거 안 되겠다. 그냥 피구 하자.": "Ini tidak bisa. Main bola beracun saja.", "잠깐만…….": "Tunggu sebentar...", "솔직히 말할게. 네 놀이 지금 엉망이야.": "Aku jujur saja, ya. Permainanmu sekarang berantakan.", "(수아 말이 맞아. 엉망이야.)": "(Sua benar. Berantakan.)", "(근데 이건 내가 하자고 한 놀이야.)": "(Tapi ini permainan yang aku usulkan.)", "체육 시간이 끝났다. 수아가 내 옆으로 왔다.": "Jam olahraga selesai. Sua datang ke sebelahku.", "정리하면, 반은 성공.": "Jadi, ringkasnya, setengah berhasil.", "반이나?": "Setengah?", "처음엔 영이었잖아.": "Awalnya kan nol.", "다음에 고쳐서 다시 해 보든가.": "Lain kali diperbaiki, terus dicoba lagi.", "「1분만. 규칙 하나만 바꿔 볼게.」": "\"Satu menit saja. Aku coba ganti satu aturan.\"", "1분만 줘. 규칙 하나만 바꿔 볼게.": "Kasih aku satu menit. Aku coba ganti satu aturan.", "……1분.": "...Satu menit.", "나는 {@handkerchief}을 들고 원 가운데 섰다.": "Aku memegang {@handkerchief} dan berdiri di tengah lingkaran.", "잡히면, 잡은 사람 {@hand}을 잡아요. {@hand} 잡고 같이 다녀요!": "Kalau tertangkap, pegang {@hand} orang yang menangkap. Pegangan {@hand} dan jalan bersama!", "아이: 「{@hand} 잡고?」": "Seorang anak: \"Pegangan {@hand}?\"", "응. 그럼 누가 같은 편인지 보여요.": "Iya. Jadi kelihatan siapa yang satu tim.", "다시 시작했다. 잡힌 아이들이 {@hand}을 잡고 줄줄이 달렸다. 기차처럼 길어졌다. 아이들이 깔깔 웃었다.": "Permainan dimulai lagi. Anak-anak yang tertangkap berlari berbaris sambil berpegangan {@hand}. Barisannya makin panjang seperti kereta. Anak-anak tertawa cekikikan.", "「애들이 규칙을 안 지켜서 그래.」": "\"Itu karena anak-anak tidak menaati aturan.\"", "애들이 규칙을 안 지켜서 그래. 내 놀이가 문제가 아니야.": "Itu karena anak-anak tidak menaati aturan. Bukan permainanku yang salah.", "규칙이 헷갈리면 안 지키게 되는 거야.": "Kalau aturannya membingungkan, orang jadi tidak menaatinya.", "…….": "...", "그사이 아이들은 하나둘 피구공을 가지러 갔다.": "Sementara itu, anak-anak satu per satu pergi mengambil bola beracun.", "(남 탓을 했는데, 놀이는 그대로 끝났어.)": "(Aku menyalahkan orang lain, tapi permainannya tetap selesai begitu saja.)", "「……그래. 그만하자.」": "\"...Ya sudah. Berhenti saja.\"", "……그래. 그만하자.": "...Ya sudah. Berhenti saja.", "피구 할 사람!": "Siapa mau main bola beracun!", "아이들이 우르르 수아 쪽으로 갔다. 나는 {@handkerchief}을 주머니에 넣었다.": "Anak-anak berbondong-bondong ke arah Sua. Aku memasukkan {@handkerchief} ke saku.", "(그냥 끝나 버렸어.)": "(Selesai begitu saja.)", "아이들에게 직접 묻는다. 「어디가 헷갈렸어?」": "Bertanya langsung kepada anak-anak. \"Bagian mana yang membingungkan?\"", "얘들아, 잠깐! 어디가 헷갈렸어?": "Teman-teman, tunggu sebentar! Bagian mana yang membingungkan?", "아이: 「잡히고 나서 뭘 해야 할지 모르겠어.」": "Seorang anak: \"Aku tidak tahu harus ngapain setelah tertangkap.\"", "아이: 「누가 같은 편인지도 모르겠고.」": "Seorang anak: \"Aku juga tidak tahu siapa yang satu tim.\"", "그럼 잡힌 사람은 모자를 벗자! 모자 벗은 사람끼리 같은 편.": "Kalau begitu, yang tertangkap lepas topi! Yang lepas topi, satu tim.", "아이: 「오, 그거 알겠다.」": "Seorang anak: \"Oh, kalau itu aku mengerti.\"", "다시 시작했다. 모자 벗은 아이들이 한 무리가 되어 함께 술래를 쫓았다. 이번엔 다툼이 줄었다.": "Permainan dimulai lagi. Anak-anak yang lepas topi jadi satu kelompok dan sama-sama mengejar penjaga. Kali ini pertengkarannya berkurang.", "{m}, 오늘 체육 시간에 우리 나라 놀이 했어.": "{m}, hari ini di jam olahraga kami main permainan dari negaraku.", "드디어! 재밌었어?": "Akhirnya! Seru?", "처음엔. 근데 애들이 잡히고 나서 뭘 해야 할지 몰라서 엉망이 됐어. 수아가 솔직히 엉망이래.": "Awalnya. Tapi anak-anak tidak tahu harus ngapain setelah tertangkap, jadi berantakan. Sua bilang terus terang kalau itu berantakan.", "아이고.": "Aduh.", "1분만 달라고 하고, 잡히면 {@hand} 잡고 다니자고 바꿨어. 기차처럼 길어졌어!": "Aku minta satu menit, lalu aku ganti aturannya: kalau tertangkap, pegangan {@hand} dan jalan bersama. Barisannya jadi panjang seperti kereta!", "{@hand} 잡고 줄줄이?": "Pegangan {@hand} berbaris?", "응. 애들이 엄청 웃었어. 수아가 반은 성공이래.": "Iya. Anak-anak tertawa terus. Sua bilang setengah berhasil.", "애들이 규칙을 안 지켜서 그렇다고 했는데, 수아가 헷갈리면 안 지키게 된대.": "Aku bilang itu karena anak-anak tidak menaati aturan, tapi Sua bilang kalau membingungkan, orang jadi tidak menaatinya.", "수아 말도 일리가 있네.": "Kata Sua juga ada benarnya.", "응. 그러는 사이에 다들 피구 하러 갔어.": "Iya. Sementara itu, semuanya pergi main bola beracun.", "그냥 그만하자고 했어. 다들 피구 하러 갔어.": "Aku bilang berhenti saja. Semuanya pergi main bola beracun.", "많이 실망했겠다.": "Pasti kamu kecewa sekali.", "응. {@handkerchief}만 주머니에 있어.": "Iya. Cuma {@handkerchief} yang ada di sakuku.", "고쳐서 다시 해 볼 수도 있잖아. 어디가 문제였는지는 알 것 같아?": "Kan bisa diperbaiki lalu dicoba lagi. Kamu kira-kira tahu di mana masalahnya?", "애들한테 어디가 헷갈렸냐고 물어봤어. 그래서 잡히면 모자 벗기로 했어.": "Aku tanya anak-anak bagian mana yang membingungkan. Jadi kami sepakat kalau tertangkap, lepas topi.", "애들 말 듣고 바로 고쳤구나.": "Kamu dengar kata anak-anak, lalu langsung memperbaikinya, ya.", "응. 다툼이 줄었어.": "Iya. Pertengkarannya berkurang.", "방과 후. 수아가 교실에 남아 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "Pulang sekolah. Sua masih di kelas, sedang menulis janji kampanye. Aku juga membawa {@pencil} yang aku pakai menulis janji kampanye dan menghampiri Sua.", "「{x}」 내려놓기": "Letakkan 「{x}」", "수아의 공약 {@paper}: 「공약 1. 전학 온 친구를 위한 {@picture} 규칙표를 모든 반에 붙이겠습니다.」": "{@paper} janji kampanye Sua: \"Janji 1. Saya akan menempel tabel aturan {@picture} untuk teman pindahan di semua kelas.\"", "나는 그대로 굳었다. 내 {w} 첫 줄에도 거의 같은 말이 쓰여 있었다.": "Aku membeku. Di baris pertama {w}-ku juga tertulis hampir sama persis.", "이거 좋지? 우리가 만든 규칙표, 반응 좋았잖아.": "Bagus, kan? Tabel aturan yang kita bikin, tanggapannya bagus.", "……나도 이거 1번으로 썼는데.": "...Aku juga menulis itu sebagai nomor 1.", "어? 진짜?": "Eh? Serius?", "같이 만든 거니까 나도 써도 되는 줄 알았지.": "Kita bikin bareng, jadi aku kira aku juga boleh menulisnya.", "({@picture}은 내가 그렸어. 근데 처음 하자고 한 건 수아야.)": "({@picture} itu aku yang gambar. Tapi yang pertama mengusulkan Sua.)", "(둘 다 쓰면…… 애들은 누가 만든 걸로 생각할까?)": "(Kalau kami berdua menulisnya... anak-anak akan mengira siapa yang membuatnya?)", "집에 가는 길. 나는 내 {w}을 다시 펴 봤다.": "Di jalan pulang. Aku membuka {w}-ku lagi.", "(내 공약은…… 뭐가 나다운 걸까?)": "(Janji kampanyeku... yang benar-benar aku itu apa, ya?)", "서운한 걸 직접 말하고, 같이 정하자고 한다.": "Mengatakan langsung rasa kecewanya, lalu mengajak memutuskan bersama.", "솔직히 좀 서운해. {@picture}은 내가 그렸는데, 네 공약에만 있으면 네가 다 한 것 같잖아.": "Jujur, aku agak kecewa. {@picture} itu aku yang gambar, tapi kalau cuma ada di janji kampanyemu, kelihatannya kamu yang mengerjakan semuanya.", "……그렇게 보일 수도 있겠다.": "...Bisa saja kelihatan begitu, ya.", "그러니까 정하자. 둘 다 쓰든지, 하나만 쓰든지.": "Makanya ayo kita putuskan. Kita berdua menulisnya, atau cuma satu orang.", "둘 다 쓰자. 대신 ‘같이 만든’이라고 넣어.": "Kita berdua tulis saja. Tapi tambahkan ‘dibuat bersama’.", "그다음엔 누가 더 잘 지킬지 애들이 정하겠지.": "Setelah itu, anak-anak yang akan menentukan siapa yang lebih bisa menepatinya.", "수아가 공약 {@paper}에 내 이름을 넣어 ‘같이 만든’이라고 고쳐 썼다.": "Sua menambahkan namaku di {@paper} janji kampanyenya dan mengubahnya jadi ‘dibuat bersama’.", "다른 애들한테 「수아가 내 아이디어 가져갔어.」라고 말한다.": "Bilang ke anak-anak lain, \"Sua mengambil ideku.\"", "다음 날, 나는 친한 친구에게 작게 말했다.": "Keesokan harinya, aku bilang pelan-pelan ke teman dekatku.", "수아가 내 아이디어 가져갔어.": "Sua mengambil ideku.", "그 말은 점심시간 전에 반 전체로 퍼졌다. 수아가 굳은 얼굴로 나를 찾아왔다.": "Sebelum jam makan siang, kata-kata itu sudah menyebar ke seluruh kelas. Sua datang mencariku dengan wajah kaku.", "나한테 먼저 말하지 그랬어.": "Kenapa tidak bilang ke aku dulu?", "나는 같이 만든 거라서 쓴 거야.": "Aku menulisnya karena kita bikin bareng.", "그건 수아에게 두고, 나만 할 수 있는 다른 공약을 쓴다.": "Membiarkan itu untuk Sua, lalu menulis janji kampanye lain yang cuma bisa aku lakukan.", "그거 너 써. 나는 다른 거 쓸래.": "Itu kamu saja yang pakai. Aku tulis yang lain.", "진짜? 너도 같이 만든 건데.": "Serius? Kan kamu juga ikut bikin.", "응. 나한테는 다른 게 있어.": "Iya. Aku punya yang lain.", "나는 {w} 첫 줄을 지우고 새로 썼다.": "Aku menghapus baris pertama {w} dan menulis yang baru.", "내 {w}: 「공약 1. 모르는 말을 물어봐도 괜찮은 반을 만들겠습니다. ‘천천히 말해 줘’ 카드를 만들겠습니다.」": "{w}-ku: \"Janji 1. Saya akan membuat kelas yang membolehkan kita bertanya kata yang tidak kita tahu. Saya akan membuat kartu ‘Tolong bicara pelan-pelan’.\"", "……그거 나보다 네가 잘하는 거네.": "...Itu memang kamu lebih jago dariku.", "응. 대피 훈련 때 그거 필요했거든.": "Iya. Waktu latihan evakuasi, aku butuh itu.", "아무 말 안 하고 혼자 서운해한다.": "Tidak bilang apa-apa dan kecewa sendirian.", "……아니야. 써.": "...Tidak apa-apa. Tulis saja.", "그래? 고마워!": "Benarkah? Terima kasih!", "수아는 신나서 공약 {@paper}를 다시 정리했다. 나는 {w}을 덮었다.": "Sua dengan senang merapikan lagi {@paper} janji kampanyenya. Aku menutup {w}.", "(괜찮다고 했는데, 하나도 안 괜찮아.)": "(Aku bilang tidak apa-apa, tapi sebenarnya sama sekali tidak.)", "{m}, 수아 공약 1번이 내 공약 1번이랑 똑같았어. 우리 둘이 만든 {@picture} 규칙표.": "{m}, janji nomor 1 Sua sama persis dengan janji nomor 1-ku. Tabel aturan {@picture} yang kami bikin berdua.", "어머. 둘이 같이 만든 거?": "Wah. Yang kalian bikin bersama?", "응. 수아는 같이 만든 거니까 써도 되는 줄 알았대.": "Iya. Kata Sua, karena dibikin bareng, dia kira boleh menulisnya.", "서운하다고 말했어. 그래서 둘 다 쓰고 ‘같이 만든’이라고 넣기로 했어.": "Aku bilang aku kecewa. Jadi kami sepakat kami berdua menulisnya dan menambahkan ‘dibuat bersama’.", "좋은 방법이네. 수아는 어땠어?": "Cara yang bagus. Sua bagaimana?", "누가 더 잘 지킬지는 애들이 정할 거래.": "Katanya anak-anak yang akan menentukan siapa yang lebih bisa menepatinya.", "역시 경쟁자다.": "Memang saingan.", "친구한테 수아가 내 거 가져갔다고 했는데, 반 전체에 퍼졌어.": "Aku bilang ke temanku kalau Sua mengambil punyaku, terus menyebar ke seluruh kelas.", "아이고. 수아는?": "Aduh. Sua bagaimana?", "나한테 먼저 말하지 그랬냐고 했어.": "Dia bilang, kenapa tidak bilang ke dia dulu.", "수아 말이 맞네. 다음엔 수아한테 먼저 말해 보자.": "Sua benar. Lain kali coba bilang ke Sua dulu, ya.", "그건 수아 쓰라고 하고, 나는 다른 공약 썼어. 모르는 말 물어봐도 괜찮은 반.": "Aku suruh Sua yang pakai itu, dan aku menulis janji lain. Kelas yang membolehkan kita bertanya kata yang tidak kita tahu.", "그거 너한테 딱이다.": "Itu cocok sekali untukmu.", "수아도 그거 나보다 네가 잘하는 거래.": "Sua juga bilang itu aku lebih jago dari dia.", "괜찮다고 했어. 근데 안 괜찮아.": "Aku bilang tidak apa-apa. Tapi sebenarnya tidak.", "속으로만 서운했구나.": "Kamu cuma kecewa di dalam hati, ya.", "응. 말하면 싸울 것 같아서.": "Iya. Soalnya kalau aku bilang, rasanya kami bakal bertengkar.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 내일 말해 봐도 늦지 않아.": "Bilang kecewa dan bertengkar itu beda. Bilang besok juga belum terlambat.", "쉬는 시간. 수아가 교실을 뛰어다니고 있었다. 오늘 종례까지 체험학습 신청서를 다 걷어야 한다고 했다.": "Jam istirahat. Sua berlari ke sana kemari di kelas. Katanya formulir pendaftaran karyawisata harus terkumpul semua sebelum jam pulang hari ini.", "나는 수아 {@desk}으로 갔다. {@desk} 위에 신청서 {@box}가 있었다.": "Aku pergi ke {@desk} Sua. Di atas {@desk} ada {@box} formulir pendaftaran.", "{@box} 안에 신청서가 보였다. 아직 반도 안 찼다.": "Di dalam {@box} kelihatan formulir pendaftaran. Belum terisi setengahnya.", "여덟 명 남았어. 종례까지.": "Tinggal delapan orang. Sampai jam pulang.", "도와줄까?": "Mau aku bantu?", "아니, 괜찮아. 반장 일이야.": "Tidak, tidak apa-apa. Ini tugas ketua kelas.", "수아가 다시 뛰어갔다. 그때 같은 모둠 친구가 내 옆으로 와서 작게 말했다.": "Sua berlari lagi. Saat itu teman satu kelompokku datang ke sebelahku dan berbisik.", "친구: 「야, 그냥 내버려 둬. 수아가 실수하면 너한테 좋은 거잖아. 선거 나간다며.」": "Teman: \"Hei, biarkan saja. Kalau Sua salah, kan bagus buat kamu. Katanya kamu ikut pemilihan.\"", "(……그런가?)": "(...Benar juga?)", "그때 뒷자리 친구가 신청서를 들고 멍하니 앉아 있는 게 보였다. 신청서를 뒤집었다 폈다 하고 있었다.": "Saat itu aku melihat teman yang duduk di belakang sedang memegang formulir sambil bengong. Dia membolak-balik formulirnya.", "(저거…… 대피 훈련 때 나 같은 얼굴이다.)": "(Itu... wajahnya sama seperti aku waktu latihan evakuasi.)", "종례가 끝났다. 수아가 {@box}를 정리하며 나를 봤다.": "Jam pulang selesai. Sua merapikan {@box} sambil melihat ke arahku.", "……‘회신’을 모르는 애가 있을 줄은 몰랐어.": "...Aku tidak menyangka ada anak yang tidak tahu arti ‘lembar balasan’.", "나도 몰랐었어.": "Dulu aku juga tidak tahu.", "그러니까 네가 알았겠지.": "Makanya kamu yang sadar.", "한 장 내일 받으면 돼. 괜찮아.": "Satu lembar bisa dikumpulkan besok. Tidak apa-apa.", "수아는 괜찮다고 했지만, 형광펜을 꽉 쥐고 있었다.": "Sua bilang tidak apa-apa, tapi dia menggenggam stabilonya erat-erat.", "친구 말대로 모른 척한다.": "Pura-pura tidak tahu, seperti kata teman.", "나는 내 자리로 돌아갔다. 수아는 종례 직전까지 뛰어다녔다.": "Aku kembali ke tempat dudukku. Sua terus berlari ke sana kemari sampai tepat sebelum jam pulang.", "종례 시간. 수아가 선생님께 {@box}를 내밀었다.": "Jam pulang. Sua menyerahkan {@box} kepada Bu Guru.", "……한 장 빠졌어요.": "...Kurang satu lembar, Bu.", "(내가 이긴 것 같지가 않아.)": "(Rasanya aku tidak menang.)", "「내가 뒤쪽 줄만 걷을게. 싫으면 말해.」": "\"Aku kumpulkan baris belakang saja. Kalau tidak mau, bilang.\"", "수아야. 내가 뒤쪽 줄만 걷을게. 싫으면 말해.": "Sua. Aku kumpulkan baris belakang saja. Kalau tidak mau, bilang.", "괜찮다니까, 내가…….": "Sudah aku bilang tidak apa-apa, aku saja...", "뒤쪽 줄만이야.": "Baris belakang saja.", "수아가 잠깐 멈췄다. 숨을 한 번 크게 쉬었다.": "Sua berhenti sebentar. Dia menarik napas panjang.", "……그럼 뒤쪽만.": "...Kalau begitu, baris belakang saja.", "나는 뒤쪽 줄을 돌았다. 뒷자리 친구는 ‘회신’이라는 말을 몰라서 못 낸 거였다. 나는 {@picture}으로 설명해 줬다.": "Aku berkeliling baris belakang. Ternyata teman di belakang tidak mengumpulkan karena tidak tahu arti kata ‘lembar balasan’. Aku menjelaskannya dengan {@picture}.", "뒷자리 친구: 「아, 이름 쓰고 다시 내는 거구나!」": "Teman di belakang: \"Oh, jadi tulis nama lalu dikumpulkan lagi!\"", "도와준다고 했다가 거절당하자 「그래, 혼자 해.」 하고 돌아선다.": "Ditolak waktu menawarkan bantuan, lalu berbalik, \"Ya sudah, kerjakan sendiri.\"", "진짜 도와줄게.": "Aku benar-benar mau bantu.", "괜찮다고 했잖아!": "Kan sudah aku bilang tidak apa-apa!", "……그래, 혼자 해.": "...Ya sudah, kerjakan sendiri.", "나는 자리로 돌아갔다. 수아도 나도 기분이 상했다.": "Aku kembali ke tempat dudukku. Sua dan aku sama-sama kesal.", "종례 시간. 한 장이 빠졌다.": "Jam pulang. Kurang satu lembar.", "뒷자리 친구에게 가서 신청서를 같이 본다.": "Menghampiri teman di belakang dan melihat formulirnya bersama.", "나는 수아를 쫓아가는 대신 뒷자리 친구에게 갔다.": "Daripada mengejar Sua, aku menghampiri teman yang duduk di belakang.", "이거 모르는 말 있어?": "Ada kata yang tidak kamu tahu di sini?", "뒷자리 친구: 「……‘회신’이 뭐야?」": "Teman di belakang: \"...‘Lembar balasan’ itu apa?\"", "나도 처음에 몰랐어. 이름 쓰고, 부모님 사인 받고, 다시 내는 거야.": "Awalnya aku juga tidak tahu. Tulis nama, minta tanda tangan orang tua, lalu kumpulkan lagi.", "나는 {w} 귀퉁이에 순서를 {@picture}으로 그려 줬다. 친구가 이름을 쓰고 신청서를 {@box}에 넣었다.": "Aku menggambar urutannya dengan {@picture} di pojok {w}. Temanku menulis nama dan memasukkan formulirnya ke {@box}.", "수아가 돌아와 {@box}를 보고 눈을 크게 떴다.": "Sua kembali, melihat {@box}, lalu membelalakkan mata.", "어? 이거 언제 냈어?": "Eh? Ini kapan dikumpulkan?", "뒷자리 친구: 「방금. 쟤가 알려 줬어.」": "Teman di belakang: \"Barusan. Dia yang kasih tahu aku.\"", "{m}, 수아가 오늘 종례까지 신청서 다 걷어야 해서 엄청 바빴어.": "{m}, hari ini Sua sibuk sekali karena harus mengumpulkan semua formulir pendaftaran sebelum jam pulang.", "반장 일이 많구나.": "Tugas ketua kelas banyak, ya.", "응. 근데 친구가 수아 내버려 두래. 수아가 실수하면 나한테 좋다고.": "Iya. Tapi temanku bilang biarkan saja Sua. Katanya kalau Sua salah, bagus buat aku.", "그냥 내 자리에 있었어. 결국 한 장 빠졌어.": "Aku diam saja di tempat dudukku. Akhirnya kurang satu lembar.", "그러고 나서 기분이 어땠어?": "Setelah itu, kamu merasa bagaimana?", "이긴 것 같지 않았어.": "Rasanya aku tidak menang.", "그렇구나.": "Begitu, ya.", "뒤쪽 줄만 걷겠다고 했어. 수아가 처음엔 괜찮다고 했는데 결국 그러라고 했어.": "Aku bilang aku kumpulkan baris belakang saja. Awalnya Sua bilang tidak apa-apa, tapi akhirnya dia setuju.", "수아가 도움을 받았네.": "Sua mau menerima bantuan, ya.", "응. 그리고 뒷자리 애가 ‘회신’을 몰라서 못 낸 거였어. {@picture}으로 알려 줬어.": "Iya. Terus ternyata anak di belakang tidak mengumpulkan karena tidak tahu ‘lembar balasan’. Aku kasih tahu dengan {@picture}.", "네가 아니었으면 몰랐겠다.": "Kalau bukan kamu, tidak akan ada yang tahu.", "도와준다고 했는데 수아가 괜찮다고 화내서, 그럼 혼자 하라고 했어.": "Aku bilang mau bantu, tapi Sua marah bilang tidak apa-apa, jadi aku bilang ya sudah, kerjakan sendiri.", "둘 다 기분 상했겠다.": "Kalian berdua pasti sama-sama kesal.", "응. 그리고 한 장 빠졌어.": "Iya. Terus kurang satu lembar.", "수아는 왜 계속 괜찮다고 했을까?": "Kenapa Sua terus bilang tidak apa-apa, ya?", "……반장 일이라서?": "...Karena itu tugas ketua kelas?", "뒷자리 애가 신청서를 뒤집었다 폈다 하고 있었어. 대피 훈련 때 나 같아서 가 봤어.": "Anak di belakang membolak-balik formulirnya. Mirip aku waktu latihan evakuasi, jadi aku datangi.", "무슨 일이었어?": "Ada apa?", "‘회신’을 몰랐대. 나도 처음엔 몰랐잖아. {@picture}으로 알려 줬어.": "Katanya dia tidak tahu arti ‘lembar balasan’. Aku juga awalnya tidak tahu, kan. Aku kasih tahu dengan {@picture}.", "네가 겪어 봐서 알아본 거네.": "Karena kamu pernah mengalaminya, kamu bisa melihatnya, ya.", "근데 경쟁자를 도와주는 거, 이상하진 않았어?": "Tapi membantu saingan, tidak terasa aneh?", "……모르겠어. 그냥 반 일이잖아.": "...Tidak tahu. Kan itu urusan kelas.", "오늘은 내 생일이었다. {m}가 새벽부터 우리 나라 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "Hari ini ulang tahunku. Sejak subuh {m} membuat camilan dari negaraku dan menaruhnya di {@bowl}. Supaya kubagi dengan teman-teman sekelas.", "나는 {@bowl}을 안고 수아에게 갔다.": "Aku memeluk {@bowl} itu dan pergi ke Sua.", "수아야! 오늘 내 생일이야. 이거 언제 나눠 주면 돼?": "Sua! Hari ini ulang tahunku. Kapan aku boleh membagikan ini?", "「{x}」 뚜껑 열기": "Buka tutup 「{x}」", "{@bowl} 안에 우리 나라 간식이 가득했다.": "{@bowl} itu penuh camilan dari negaraku.", "와, 생일 축하해! 근데…….": "Wah, selamat ulang tahun! Tapi...", "수아가 {@bowl}을 보더니 표정이 바뀌었다.": "Begitu melihat {@bowl}, wajah Sua berubah.", "그거 나눠 주면 안 돼. 규칙 9번. 집에서 만든 음식은 학교에서 나눠 먹지 않기.": "Itu nggak boleh dibagikan. Aturan 9. Makanan buatan rumah tidak dibagikan di sekolah.", "……안 돼?": "...Nggak boleh?", "응. 안 돼.": "Iya. Nggak boleh.", "수아는 또 빠르고 짧게 말했다. {@bowl}이 갑자기 무거워졌다.": "Sua lagi-lagi bicara cepat dan singkat. {@bowl} itu tiba-tiba terasa berat.", "({m}가 새벽부터 만든 건데.)": "({m} membuatnya sejak subuh.)", "(우리 나라에서는 생일에 이걸 나눠 먹는데…….)": "(Di negaraku, makanan ini dibagi-bagi waktu ulang tahun...)", "종례 시간. 선생님이 내 생일이라고 말씀하셨다. 반 아이들이 생일 노래를 불러 줬다.": "Waktu homeroom pulang sekolah. Bu Guru bilang hari ini ulang tahunku. Anak-anak sekelas menyanyikan lagu ulang tahun untukku.", "수아가 제일 크게 불렀다. 음이 조금 틀렸다.": "Sua yang menyanyi paling keras. Nadanya agak meleset.", "「우리 나라 음식이라서 싫은 거지?」": "\"Kamu nggak suka karena ini makanan dari negaraku, kan?\"", "우리 나라 음식이라서 안 된다는 거지?": "Nggak boleh karena ini makanan dari negaraku, kan?", "아니야! 그런 거 아니야!": "Bukan! Bukan begitu!", "수아 얼굴이 빨개졌다.": "Wajah Sua jadi merah.", "누가 가져와도 안 되는 거야. 나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "Siapa pun yang bawa tetap nggak boleh. Ulang tahun tahun lalu aku juga bawa kue beras, terus kubawa pulang lagi.", "……아.": "...Oh.", "우리 둘 다 한동안 말이 없었다.": "Kami berdua diam cukup lama.", "「왜 안 돼?」 하고 이유를 묻는다.": "Tanya alasannya: \"Kenapa nggak boleh?\"", "왜 안 돼?": "Kenapa nggak boleh?", "음식에 알레르기 있는 애들이 있어. 뭐가 들어갔는지 모르면 위험할 수 있대.": "Ada anak yang alergi makanan. Katanya bisa bahaya kalau nggak tahu isinya apa.", "나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "Ulang tahun tahun lalu aku juga bawa kue beras, terus kubawa pulang lagi.", "너도?": "Kamu juga?", "응. 엄청 속상했어.": "Iya. Sedih banget.", "(나만 안 되는 게 아니구나.)": "(Ternyata bukan cuma aku yang nggak boleh.)", "아무 말 없이 {@bowl}을 다시 {@bag}에 넣는다.": "Masukkan lagi {@bowl} ke {@bag} tanpa bicara.", "나는 아무 말도 하지 않았다. 뚜껑을 닫고 {@bowl}을 {@bag} 깊숙이 넣었다.": "Aku tidak bicara apa-apa. Aku menutup tutupnya dan memasukkan {@bowl} dalam-dalam ke {@bag}.", "……저기.": "...Eh.", "나는 대답하지 않고 자리로 갔다. 하루 종일 {@bag}이 무거웠다.": "Aku tidak menjawab dan kembali ke tempat dudukku. Seharian {@bag} terasa berat.", "「그럼 먹는 거 말고, 다른 방법은 돼?」 하고 묻는다.": "Tanya: \"Kalau bukan dimakan, cara lain boleh?\"", "그럼 먹는 거 말고 다른 방법은 돼?": "Kalau bukan dimakan, cara lain boleh?", "다른 방법?": "Cara lain?", "사진 보여 주면서 우리 나라에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "Aku tunjukkan foto, terus bilang di negaraku ini dimakan waktu ulang tahun. Cara membuatnya juga bisa kugambar jadi {@picture}.", "그건 돼! 음식만 안 되는 거니까.": "Itu boleh! Yang nggak boleh cuma makanannya.", "수아가 형광펜을 꺼냈다.": "Sua mengeluarkan stabilo.", "종례 때 1분 줄게. 반장 권한.": "Waktu homeroom pulang nanti aku kasih satu menit. Hak ketua kelas.", "{m}…… 학교에서 그거 못 나눠 줬어.": "{m}... aku nggak bisa membagikannya di sekolah.", "응? 왜?": "Hm? Kenapa?", "집에서 만든 음식은 학교에서 나눠 먹으면 안 된대. 규칙 9번. 수아가 알려 줬어.": "Makanan buatan rumah nggak boleh dibagi di sekolah. Aturan 9. Sua yang kasih tahu.", "어머…… {m}가 몰랐네. 새벽부터 만들었는데. 미안해.": "Aduh... {m} nggak tahu. Padahal dibuat sejak subuh. Maaf ya.", "{m}가 왜 미안해.": "Kenapa {m} yang minta maaf.", "나 수아한테 우리 나라 음식이라서 싫은 거냐고 했어.": "Aku tanya ke Sua, dia nggak suka karena ini makanan dari negaraku, ya.", "아니래. 수아도 작년에 떡 가져왔다가 못 나눠 줬대.": "Katanya bukan. Tahun lalu Sua juga bawa kue beras dan nggak bisa membagikannya.", "그랬구나. 수아도 놀랐겠다.": "Oh, begitu. Sua pasti kaget juga.", "……응. 내가 좀 심했어.": "...Iya. Aku agak keterlaluan.", "왜 안 되냐고 물었더니, 알레르기 있는 애들 때문이래. 수아도 작년에 떡 가져갔다가 다시 가져갔대.": "Aku tanya kenapa nggak boleh, katanya karena ada anak yang alergi. Tahun lalu Sua juga bawa kue beras, terus dibawa pulang lagi.", "다 같이 지키는 규칙이었구나.": "Ternyata itu aturan yang dijaga semua orang, ya.", "응. 나만 안 되는 줄 알았어.": "Iya. Kukira cuma aku yang nggak boleh.", "그냥 아무 말 안 하고 {@bag}에 넣었어. 하루 종일 {@bag}이 무거웠어.": "Aku diam saja dan memasukkannya ke {@bag}. Seharian {@bag} terasa berat.", "많이 속상했구나.": "Kamu pasti sedih sekali.", "수아가 뭐라고 하려고 했는데 그냥 갔어.": "Sua mau bilang sesuatu, tapi aku pergi saja.", "수아가 무슨 말 하려고 했을까? 내일 물어봐도 되겠다.": "Sua mau bilang apa, ya? Besok kamu bisa tanya dia.", "그럼 사진 보여 주고 만드는 법 {@picture}으로 그려 와도 되냐고 했어. 수아가 종례 때 1분 준대.": "Aku tanya, boleh nggak aku tunjukkan foto dan gambar cara membuatnya jadi {@picture}. Sua bilang dia kasih satu menit waktu homeroom pulang.", "어머, 그거 좋다! 그럼 {m}가 사진 찍어 줄게.": "Wah, bagus itu! Nanti {m} fotokan.", "만드는 법도 알려 줘. {@picture}으로 그릴게.": "Ajari cara membuatnya juga. Aku gambar jadi {@picture}.", "이건 우리 둘이 먹자. 생일 축하해.": "Yang ini kita makan berdua saja. Selamat ulang tahun.", "응. 그리고 오늘 애들이 생일 노래 불러 줬어. 수아가 제일 크게 불렀어. 음 틀리게.": "Iya. Terus hari ini anak-anak menyanyikan lagu ulang tahun untukku. Sua yang paling keras. Nadanya meleset.", "반장은 노래도 크게 하는구나.": "Ternyata ketua kelas menyanyi juga paling keras.", "점심시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "Jam istirahat makan siang. Sua sedang buru-buru membereskan {@bag}. Aku pergi ke Sua.", "마침 잘 왔다.": "Pas banget kamu datang.", "옆 반 선생님이 우리 {@picture} 규칙표 보시고, 애들한테 설명해 달래. 근데 나 지금 학생회 회의 가야 해.": "Guru kelas sebelah lihat daftar aturan {@picture} kita, terus minta dijelaskan ke anak-anaknya. Tapi aku harus ke rapat OSIS sekarang.", "너 혼자 가 볼래? {@picture}은 네가 그렸잖아.": "Kamu mau coba pergi sendiri? {@picture}-nya kan kamu yang gambar.", "(혼자? 옆 반은 아는 애가 하나도 없는데.)": "(Sendiri? Di kelas sebelah aku nggak kenal siapa pun.)", "옆 반 앞.": "Di depan kelas sebelah.", "「{x}」 두드리기": "Ketuk 「{x}」", "똑똑. 옆 반 {@door}이 열렸다.": "Tok tok. {@door} kelas sebelah terbuka.", "낯선 얼굴 스무 개가 나를 봤다. 다리가 떨렸다. 그래도 {@picture}을 가리켰다.": "Dua puluh wajah asing menatapku. Kakiku gemetar. Tapi aku tetap menunjuk {@picture}.", "이건 규칙 7번이에요. 연기가 나면 몸을 낮추고, 벽을 짚어요.": "Ini aturan 7. Kalau ada asap, rendahkan badan dan pegang dinding.", "옆 반 아이: 「벽은 왜 짚어요?」": "Anak kelas sebelah: \"Kenapa harus pegang dinding?\"", "연기 때문에 앞이 안 보여요. 벽을 따라가면 길을 안 잃어요.": "Karena asap, kita nggak bisa lihat ke depan. Kalau mengikuti dinding, kita nggak tersesat.", "옆 반 선생님: 「설명 잘하는구나. {@picture}도 네가 그렸니?」": "Guru kelas sebelah: \"Kamu pintar menjelaskan. {@picture}-nya juga kamu yang gambar?\"", "네!": "Iya!", "회의가 끝나고 둘이 갔을 때는 벌써 수업이 시작되어 있었다.": "Waktu kami berdua pergi setelah rapat selesai, pelajaran sudah dimulai.", "옆 반 선생님: 「아, 지금은 좀 그렇고…… 내일 다시 와 줄래?」": "Guru kelas sebelah: \"Aduh, sekarang kurang pas... Besok bisa datang lagi?\"", "수아가 나를 힐끗 봤다. 나는 시선을 피했다.": "Sua melirikku. Aku membuang muka.", "나는 규칙표를 {@blackboard} 옆에 붙이고 나가려 했다.": "Aku menempelkan daftar aturan di samping {@blackboard} dan mau langsung keluar.", "옆 반 선생님: 「설명도 조금 해 줄 수 있니?」": "Guru kelas sebelah: \"Bisa jelaskan sedikit juga?\"", "……이건, 규칙…… 7번…… 이에요.": "...Ini, aturan... nomor... 7.", "옆 반 아이들이 고개를 갸웃했다. 나는 꾸벅 인사하고 나왔다.": "Anak-anak kelas sebelah memiringkan kepala. Aku membungkuk memberi salam lalu keluar.", "안녕하세요! 옆 반 반장 양수아예요. 이 규칙표는 얘가 그렸어요. 설명도 얘가 할게요.": "Halo! Aku Yang Sua, ketua kelas sebelah. Daftar aturan ini dia yang gambar. Dia juga yang akan menjelaskan.", "수아가 1분을 딱 채우고 나갔다. 이제 나 혼자였다. 그래도 수아가 열어 준 {@door}이라 덜 떨렸다.": "Pas satu menit, Sua keluar. Sekarang aku sendirian. Tapi karena Sua yang membukakan {@door}, aku tidak terlalu gemetar.", "교실로 돌아오니 수아도 막 회의에서 돌아와 있었다.": "Waktu aku kembali ke kelas, Sua juga baru kembali dari rapat.", "어땠어?": "Gimana?", "벽 왜 짚냐고 물어봐서 대답했어.": "Mereka tanya kenapa pegang dinding, terus aku jawab.", "……나보다 잘했겠다. 나는 ‘규칙이니까’라고 했을 거야.": "...Pasti lebih bagus dari aku. Aku pasti cuma bilang 'karena itu aturan'.", "……잘 못 했어.": "...Aku nggak bisa melakukannya dengan baik.", "다음에 또 기회 있어.": "Nanti masih ada kesempatan lagi.", "「알았어. 내가 갈게.」": "\"Oke. Aku yang pergi.\"", "알았어. 내가 갈게.": "Oke. Aku yang pergi.", "진짜? 고마워. {@picture} 보여 주면서 하면 돼.": "Serius? Makasih. Tinggal tunjukkan {@picture} sambil menjelaskan.", "수아가 둘둘 만 규칙표를 내 {@hand}에 쥐여 주고 뛰어갔다.": "Sua menyelipkan daftar aturan yang digulung ke {@hand}-ku lalu lari.", "「반장이니까 네가 해야지.」": "\"Kamu kan ketua kelas, kamu yang harus pergi.\"", "반장이니까 네가 해야지.": "Kamu kan ketua kelas, kamu yang harus pergi.", "그건 그런데…… 회의가 있다니까.": "Iya sih... tapi aku ada rapat.", "회의 끝나고 가.": "Pergi saja setelah rapat.", "……그럼 늦어. 알았어, 끝나고 같이 가자. 대신 말은 네가 해.": "...Nanti terlambat. Oke, habis rapat kita pergi bareng. Tapi kamu yang bicara.", "「규칙표만 붙이고 올게.」": "\"Aku tempel daftar aturannya saja.\"", "설명은 못 하고, 규칙표만 붙이고 올게.": "Aku nggak bisa menjelaskan, jadi aku tempel daftar aturannya saja.", "음…… 그래도 가 주면 고맙지.": "Hmm... tapi kalau kamu mau pergi, aku berterima kasih.", "수아가 규칙표를 건네고 뛰어갔다.": "Sua memberikan daftar aturan lalu lari.", "「처음 1분만 같이 가 줘. 나머지는 내가 할게.」": "\"Temani aku satu menit pertama saja. Sisanya aku yang urus.\"", "처음 1분만 같이 가 줘. 인사만. 나머지는 내가 할게.": "Temani aku satu menit pertama saja. Cuma salam. Sisanya aku yang urus.", "1분?": "Satu menit?", "……좋아. 1분이면 회의 안 늦어.": "...Oke. Kalau satu menit, aku nggak terlambat rapat.", "수아가 {@clock}를 보더니 앞장섰다.": "Sua melihat {@clock} lalu berjalan duluan.", "{m}, 오늘 수아가 옆 반에 가서 우리 규칙표 설명해 달래. 혼자서.": "{m}, hari ini Sua minta aku ke kelas sebelah buat menjelaskan daftar aturan kami. Sendirian.", "혼자? 아는 애도 없는 반에?": "Sendiri? Ke kelas yang nggak ada anak yang kamu kenal?", "응. 수아가 회의 가야 한대서.": "Iya. Soalnya Sua harus ke rapat.", "그래서 혼자 갔어. 다리 떨렸는데 {@picture} 가리키면서 했어. 벽 왜 짚냐고 물어봐서 대답도 했어.": "Jadi aku pergi sendiri. Kakiku gemetar, tapi aku menjelaskan sambil menunjuk {@picture}. Mereka tanya kenapa pegang dinding, aku juga jawab.", "와, 혼자서 질문까지?": "Wah, sendirian sampai menjawab pertanyaan?", "응. 수아가 자기보다 잘했겠대.": "Iya. Kata Sua, aku pasti lebih bagus dari dia.", "수아가 너를 믿고 맡긴 거네.": "Sua percaya padamu, makanya dia serahkan ke kamu.", "반장이니까 수아가 하라고 했어. 근데 회의 끝나고 갔더니 벌써 수업 시작했어.": "Aku bilang Sua harus pergi karena dia ketua kelas. Tapi waktu kami pergi habis rapat, pelajaran sudah mulai.", "아이고, 못 했구나.": "Aduh, jadi nggak sempat, ya.", "응. 내일 다시 오래. 수아가 나를 쳐다봤어.": "Iya. Disuruh datang lagi besok. Sua menatapku.", "내일은 어떻게 할래?": "Besok mau gimana?", "……내가 할래.": "...Aku yang pergi.", "규칙표만 붙이고 오려고 했는데, 선생님이 설명도 해 달래서 버벅거렸어.": "Aku mau tempel daftar aturannya saja, tapi gurunya minta aku menjelaskan juga, jadi aku tergagap-gagap.", "갑자기 하려니까 어려웠겠다.": "Pasti susah kalau mendadak, ya.", "응. 준비할 걸 그랬어.": "Iya. Harusnya aku siap-siap.", "처음 1분만 같이 가 달라고 했어. 수아가 인사하고, 얘가 그렸다고 말해 주고 나갔어. 그다음엔 내가 했어.": "Aku minta Sua menemani satu menit pertama saja. Sua memberi salam, bilang aku yang gambar, lalu keluar. Sesudah itu aku yang menjelaskan.", "필요한 만큼만 도움을 받았구나.": "Kamu minta bantuan secukupnya saja, ya.", "응. 수아가 {@door} 열어 주니까 덜 떨렸어.": "Iya. Karena Sua yang membukakan {@door}, aku nggak terlalu gemetar.", "쉬는 시간. 옆 반 아이들이 우리 규칙표를 따라 만들기로 했다는 소식을 들었다. 나는 신이 나서 수아 자리로 갔다.": "Jam istirahat. Aku dengar kabar anak-anak kelas sebelah mau membuat daftar aturan seperti punya kami. Dengan senang aku pergi ke tempat duduk Sua.", "수아는 학급 게시물을 붙이고 있었다. {@desk} 위에 뚜껑 열린 {@glue}이 굴러다녔다.": "Sua sedang menempel pengumuman kelas. Di atas {@desk} ada {@glue} yang tutupnya terbuka dan menggelinding.", "「{x}」 뚜껑 닫기": "Tutup 「{x}」", "수아야! 옆 반이 우리 규칙표 따라 만든대!": "Sua! Kelas sebelah mau bikin daftar aturan kayak punya kita!", "옆 반 선생님이 {@picture} 좋다고…….": "Kata guru kelas sebelah, {@picture}-nya bagus...", "지금 그 얘기 할 때 아니야!": "Sekarang bukan waktunya ngomongin itu!", "수아가 게시물을 탁 내려놓았다.": "Sua meletakkan pengumuman dengan keras.", "이거 종례 전까지 다 붙여야 하고, 학생회 회의 내용도 정리해야 하고. 너는 반장 안 해 봐서 몰라.": "Ini harus ditempel semua sebelum homeroom pulang, terus hasil rapat OSIS juga harus kurangkum. Kamu nggak tahu karena belum pernah jadi ketua kelas.", "교실이 잠깐 조용해졌다. 몇몇이 우리를 봤다.": "Kelas mendadak sunyi. Beberapa anak melihat ke arah kami.", "(……뭐야. 나는 좋은 소식 말하러 온 건데.)": "(...Apa sih. Aku kan datang buat kasih kabar baik.)", "(‘반장 안 해 봐서 몰라’. 그 말이 콕 찔렸어.)": "('Kamu nggak tahu karena belum pernah jadi ketua kelas.' Kata-kata itu menusuk.)", "종례가 끝나고 {@bag}을 메는데, {@pcase} 위에 쪽지 하나가 있었다. 형광펜 글씨였다.": "Waktu homeroom selesai dan aku memakai {@bag}, ada secarik catatan di atas {@pcase}. Tulisannya pakai stabilo.", "쪽지: 「아까 말 심하게 했어. 학생회 회의에서 내 안건이 다 떨어져서 그랬어. 그건 너랑 상관없는데. — 수아」": "Catatan: \"Tadi aku ngomong keterlaluan. Semua usulku ditolak di rapat OSIS, makanya begitu. Padahal itu nggak ada hubungannya sama kamu. — Sua\"", "(아팠던 건 아팠던 거야. 근데 수아도 오늘 힘들었구나.)": "(Yang sakit tetap sakit. Tapi ternyata hari ini Sua juga berat.)", "「그래, 넌 반장이라 잘났다.」 하고 맞받아친다.": "Balas: \"Iya, kamu hebat karena ketua kelas.\"", "그래, 넌 반장이라 잘났다.": "Iya, kamu hebat karena ketua kelas.", "그런 뜻 아니잖아!": "Bukan itu maksudku!", "그런 뜻이었잖아.": "Itu maksudmu, kan.", "수아가 입을 꾹 다물고 다시 게시물을 붙였다. 나도 자리로 돌아갔다. 둘 다 하루 종일 말을 안 했다.": "Sua mengatupkan bibirnya dan menempel pengumuman lagi. Aku juga kembali ke tempat dudukku. Seharian kami berdua tidak bicara.", "「지금 그 말 좀 아팠어. 근데 무슨 일 있어?」": "\"Kata-kata tadi agak menyakitkan. Tapi ada apa?\"", "지금 그 말 좀 아팠어.": "Kata-kata tadi agak menyakitkan.", "근데 너 오늘 좀 이상해. 무슨 일 있어?": "Tapi hari ini kamu agak aneh. Ada apa?", "수아가 {@glue}을 내려놓았다. 한참 있다가 작게 말했다.": "Sua meletakkan {@glue}. Setelah lama, dia bicara pelan.", "학생회 회의에서 내 안건이 다 떨어졌어. 세 개 다.": "Semua usulku ditolak di rapat OSIS. Tiga-tiganya.", "그거랑 너는 상관없는데. ……미안. 말 심하게 했어.": "Itu nggak ada hubungannya sama kamu. ...Maaf. Aku ngomong keterlaluan.", "나는 남은 게시물 한 장을 집어 수아에게 내밀었다.": "Aku mengambil satu lembar pengumuman yang tersisa dan menyodorkannya ke Sua.", "「알았어. 이따 다시 올게.」 하고 자리를 비켜 준다.": "Bilang \"Oke. Nanti aku datang lagi.\" lalu beri dia ruang.", "알았어. 이따 다시 올게.": "Oke. Nanti aku datang lagi.", "나는 내 자리로 돌아갔다. 마음이 쿡쿡 쑤셨다. 그래도 지금은 더 말하지 않았다.": "Aku kembali ke tempat dudukku. Hatiku terasa nyeri. Tapi untuk sekarang aku tidak bicara lagi.", "점심시간. 수아가 먼저 내 자리로 왔다.": "Jam istirahat makan siang. Sua yang datang duluan ke tempat dudukku.", "……아까 무슨 얘기 하려고 했어?": "...Tadi kamu mau ngomong apa?", "옆 반이 우리 규칙표 따라 만든대.": "Kelas sebelah mau bikin daftar aturan kayak punya kita.", "진짜? ……아까 그거 기쁜 소식이었네.": "Serius? ...Ternyata tadi itu kabar baik.", "「하하, 그렇지.」 하고 웃어넘긴다.": "Tertawa saja: \"Haha, iya juga.\"", "하하, 그렇지. 나는 모르지.": "Haha, iya juga. Aku kan nggak tahu.", "나는 웃으면서 자리로 돌아왔다.": "Aku kembali ke tempat dudukku sambil tertawa.", "(웃었는데…… 하나도 안 웃겨.)": "(Aku tertawa... tapi sama sekali nggak lucu.)", "수아는 내가 웃는 걸 보고 그냥 괜찮은 줄 알았다.": "Melihat aku tertawa, Sua mengira aku baik-baik saja.", "{m}, 옆 반이 우리 규칙표 따라 만든대서 수아한테 말하러 갔거든.": "{m}, aku dengar kelas sebelah mau bikin daftar aturan kayak punya kami, jadi aku pergi kasih tahu Sua.", "좋은 소식이네!": "Itu kabar baik!", "근데 수아가 지금 그 얘기 할 때 아니래. 너는 반장 안 해 봐서 모른대.": "Tapi kata Sua sekarang bukan waktunya ngomongin itu. Katanya aku nggak tahu karena belum pernah jadi ketua kelas.", "어머, 그 말 듣고 속상했겠다.": "Aduh, kamu pasti sedih dengar itu.", "그래, 넌 반장이라 잘났다, 그랬어.": "Aku bilang, iya, kamu hebat karena ketua kelas.", "하루 종일 말 안 했어. 근데 수아가 쪽지 줬어. 학생회에서 안건이 다 떨어졌대.": "Seharian kami nggak bicara. Tapi Sua kasih aku catatan. Katanya semua usulnya ditolak di OSIS.", "둘 다 안 좋은 날이었구나.": "Ternyata hari yang buruk buat kalian berdua, ya.", "그 말 아팠다고 했어. 그리고 무슨 일 있냐고 물었어.": "Aku bilang kata-katanya menyakitkan. Terus aku tanya ada apa.", "아픈 말을 듣고 그걸 물어보기 쉽지 않은데.": "Nggak gampang bertanya begitu setelah dengar kata-kata yang menyakitkan.", "수아가 학생회에서 안건 세 개가 다 떨어졌대. 그리고 미안하다고 했어.": "Kata Sua, tiga usulnya ditolak semua di OSIS. Terus dia minta maaf.", "이따 다시 오겠다고 하고 갔어. 근데 수아가 점심때 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "Aku bilang nanti datang lagi, terus pergi. Tapi waktu makan siang Sua datang duluan dan tanya tadi aku mau ngomong apa.", "기다렸더니 수아가 왔구나.": "Kamu menunggu, terus Sua datang, ya.", "응. 그리고 쪽지도 줬어.": "Iya. Terus dia juga kasih catatan.", "그냥 웃어넘겼어. 근데 하나도 안 웃겼어.": "Aku tertawa saja. Tapi sama sekali nggak lucu.", "웃었으니까 수아는 괜찮은 줄 알았겠다.": "Karena kamu tertawa, Sua pasti mengira kamu baik-baik saja.", "응. 쪽지는 받았는데…… 나 아팠다는 건 수아가 몰라.": "Iya. Aku dapat catatannya... tapi Sua nggak tahu kalau aku sakit hati.", "내일이라도 말해 볼래? 그 말 좀 아팠다고.": "Mau coba bilang besok? Bahwa kata-kata itu agak menyakitkan.", "도서관. 선거 연설문을 쓰다가 막혔다. 마침 수아가 맞은편에 앉아 있었다. 나는 {w}을 들고 수아에게 갔다.": "Perpustakaan. Aku buntu waktu menulis pidato pemilihan. Kebetulan Sua duduk di seberangku. Aku membawa {w} dan pergi ke Sua.", "수아야, 내 연설문 처음 부분만 봐 줄래?": "Sua, bisa lihat bagian awal pidatoku?", "경쟁자 연설문을?": "Pidato sainganmu?", "처음 부분만.": "Bagian awalnya saja.", "내 {w}: 「안녕하세요. 저는 규칙을 잘 지키는 반장이 되겠습니다. 규칙 3번, 교실에서 뛰지 않기. 규칙 5번, 친구 밀지 않기. 규칙은 누구나 지키는 것입니다. 예외는 없습니다.」": "{w}-ku: \"Halo. Saya akan menjadi ketua kelas yang menaati aturan. Aturan 3, tidak berlari di kelas. Aturan 5, tidak mendorong teman. Aturan ditaati oleh semua orang. Tidak ada pengecualian.\"", "수아가 읽다가 고개를 들었다.": "Sua membaca, lalu mengangkat kepala.", "……이거 나잖아.": "...Ini kan aku.", "규칙 번호까지. ‘예외는 없습니다’는 내가 첫날 최민호한테 한 말이고.": "Sampai nomor aturannya. 'Tidak ada pengecualian' itu kata-kataku ke Choi Minho di hari pertama.", "얼굴이 화끈거렸다. 첫날 밤 {w}에 썼던 말이 생각났다.": "Wajahku terasa panas. Aku teringat kata-kata yang kutulis di {w} pada malam pertama.", "이거면 애들이 왜 너를 뽑아? 나 뽑지.": "Kalau begini, kenapa anak-anak pilih kamu? Mereka pilih aku saja.", "너는 뭐가 하고 싶은데?": "Kamu sendiri mau melakukan apa?", "고친 거 선거 때 들으면 되겠네. 지금은 안 볼래.": "Yang sudah kamu perbaiki, aku dengar waktu pemilihan saja. Sekarang aku nggak mau lihat.", "경쟁자 연설문 너무 많이 보면 반칙 같아.": "Kalau terlalu banyak lihat pidato saingan, rasanya kayak curang.", "「네가 잘하니까 너처럼 하면 될 것 같았어. 그냥 둘래.」": "\"Kamu kan hebat, jadi kupikir cukup meniru kamu. Biar begini saja.\"", "너 잘하잖아. 너처럼 하면 될 것 같았어. 그냥 둘래.": "Kamu kan hebat. Kupikir cukup meniru kamu. Biar begini saja.", "……그럼 나랑 너랑 뭐가 달라?": "...Kalau begitu, apa bedanya aku sama kamu?", "난 경쟁자가 나랑 똑같은 건 재미없어.": "Aku nggak suka kalau sainganku sama persis kayak aku.", "수아가 {w}을 돌려줬다. {w}이 이상하게 무거웠다.": "Sua mengembalikan {w}. Entah kenapa {w} itu terasa berat.", "「그럼 너랑 반대로 할래. 규칙 없는 반!」": "\"Kalau begitu aku buat kebalikanmu. Kelas tanpa aturan!\"", "그럼 너랑 반대로 할래. 규칙 없는 자유로운 반!": "Kalau begitu aku buat kebalikanmu. Kelas bebas tanpa aturan!", "애들이 좋아하긴 하겠다.": "Anak-anak sih pasti suka.", "근데 너 대피 훈련 때 규칙 7번 덕분에 길 찾았잖아.": "Tapi waktu latihan evakuasi kamu menemukan jalan berkat aturan 7, kan.", "……그건 그렇지.": "...Iya juga sih.", "(반대로 하는 것도 결국 수아를 보고 정한 거네.)": "(Membuat kebalikannya pun ternyata kuputuskan sambil melihat Sua.)", "「그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 거 말해 줄게.」": "\"Kalau begitu, menurutmu aku pintar apa? Aku juga kasih tahu kelebihanmu.\"", "그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 장점 말해 줄게.": "Kalau begitu, menurutmu aku pintar apa? Aku juga kasih tahu kelebihanmu.", "음…… 너는 못 알아듣는 애를 알아봐. 신청서 때도, 옆 반 때도.": "Hmm... kamu bisa tahu siapa yang nggak paham. Waktu formulir pendaftaran, waktu di kelas sebelah juga.", "그리고 막히면 몸으로 해. 학급회의 때처럼.": "Terus kalau buntu, kamu pakai badan. Kayak waktu rapat kelas.", "너는 빨라. 정리 잘하고. 다들 네 말 들어.": "Kamu cepat. Pintar merangkum. Semua orang dengar kata-katamu.", "그럼 됐네. 나는 빠른 반장, 너는…….": "Berarti beres. Aku ketua kelas yang cepat, kamu...", "……천천히 물어보는 반장?": "...Ketua kelas yang bertanya pelan-pelan?", "나는 {w}을 새 쪽으로 넘겼다.": "Aku membalik {w} ke halaman baru.", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다.」": "{w}-ku: \"Saya akan menjadi ketua kelas yang lebih dulu bertanya, 'Kamu nggak apa-apa?'\"", "지우고, 내가 겪은 일로 다시 쓴다.": "Hapus, lalu tulis ulang dari pengalamanku sendiri.", "……다시 쓸게. 잠깐만.": "...Aku tulis ulang. Sebentar.", "나는 처음 문장을 지웠다. 첫날이 생각났다. 깨진 관찰 통. 민호를 막은 수아. 그리고 아무도 묻지 않았던 시우.": "Aku menghapus kalimat pertama. Aku teringat hari pertama. Kotak pengamatan yang pecah. Sua yang menghentikan Minho. Dan Siwoo, yang tidak ditanya siapa pun.", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다. 저는 전학 온 첫날, 아무것도 못 알아들었습니다. 누가 먼저 물어봐 주면 좋겠다고 생각했습니다.」": "{w}-ku: \"Saya akan menjadi ketua kelas yang lebih dulu bertanya, 'Kamu nggak apa-apa?' Di hari pertama saya pindah, saya tidak mengerti apa pun. Saya berpikir, alangkah baiknya kalau ada yang bertanya lebih dulu.\"", "수아가 그걸 읽었다. 한참 말이 없었다.": "Sua membacanya. Lama dia tidak bicara.", "……이건 내가 못 쓰는 거다.": "...Ini yang nggak bisa aku tulis.", "{m}, 수아한테 내 연설문 보여 줬는데, 수아가 이거 나잖아, 그랬어.": "{m}, aku tunjukkan pidatoku ke Sua, terus Sua bilang, ini kan aku.", "응? 무슨 말이야?": "Hm? Maksudnya apa?", "규칙 번호도 수아처럼 쓰고, 수아가 첫날 한 말도 썼거든. 나도 모르게.": "Aku tulis nomor aturan kayak Sua, terus kata-kata Sua di hari pertama juga kutulis. Tanpa sadar.", "아…… 수아처럼 되고 싶다고 했었지.": "Oh... kamu pernah bilang mau jadi seperti Sua, ya.", "수아가 잘하니까 그냥 두겠다고 했어. 근데 수아가 그럼 너랑 나랑 뭐가 다르냐고 했어.": "Aku bilang biar begitu saja karena Sua hebat. Tapi Sua tanya, kalau begitu apa bedanya aku sama dia.", "뭐라고 대답했어?": "Kamu jawab apa?", "……대답 못 했어.": "...Aku nggak bisa jawab.", "그 질문은 오늘 밤에 천천히 생각해 봐도 돼.": "Pertanyaan itu boleh kamu pikirkan pelan-pelan malam ini.", "그럼 반대로 규칙 없는 반 하겠다고 했어. 근데 수아가 나 대피 훈련 때 규칙 덕분에 길 찾았잖아, 그러더라.": "Terus aku bilang mau buat kebalikannya, kelas tanpa aturan. Tapi Sua bilang, waktu latihan evakuasi aku menemukan jalan berkat aturan.", "수아한테 한 방 맞았네.": "Kamu kena skakmat sama Sua, ya.", "응. 반대로 하는 것도 결국 수아 따라 한 거래.": "Iya. Katanya membuat kebalikannya juga ujung-ujungnya meniru Sua.", "수아한테 내 장점 말해 달라고 했어. 나도 수아 장점 말해 주고.": "Aku minta Sua kasih tahu kelebihanku. Aku juga kasih tahu kelebihan Sua.", "나는 못 알아듣는 애를 알아본대. 막히면 몸으로 하고. 그래서 ‘괜찮아?’라고 먼저 묻는 반장이라고 썼어.": "Katanya aku bisa tahu siapa yang nggak paham. Kalau buntu, aku pakai badan. Jadi aku tulis ketua kelas yang lebih dulu bertanya 'Kamu nggak apa-apa?'.", "와, 그거 너다.": "Wah, itu kamu banget.", "지우고 다시 썼어. 첫날 시우 생각이 났거든. 아무도 시우한테 괜찮냐고 안 물어봤잖아.": "Aku hapus dan tulis ulang. Soalnya aku teringat Siwoo di hari pertama. Nggak ada yang tanya ke Siwoo dia nggak apa-apa atau nggak.", "그날 {w}에 썼던 거?": "Yang kamu tulis di {w} hari itu?", "응. 수아가 그건 자기가 못 쓰는 거래.": "Iya. Kata Sua, itu yang nggak bisa dia tulis.", "네가 겪은 일이니까 너만 쓸 수 있지.": "Itu pengalamanmu, jadi cuma kamu yang bisa menulisnya.", "방과 후. 수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "Sepulang sekolah. Aku dan Sua sepakat saling mendengarkan pidato. Waktu aku masuk ke kelas yang kosong, Sua sudah datang duluan.", "나 먼저 할게. 시간 재 줘.": "Aku duluan. Hitung waktunya, ya.", "「{x}」로 시간 재기": "Hitung waktu dengan 「{x}」", "수아의 연설은 1분 40초. 막힘이 없었다.": "Pidato Sua 1 menit 40 detik. Lancar tanpa tersendat.", "좋아. 근데 중간에 너무 빨라. 공약 2번에서 숨 한 번 쉬어.": "Bagus. Tapi di tengah terlalu cepat. Di janji kampanye nomor 2, tarik napas sekali.", "……알았어. 숨 쉬기.": "...Oke. Tarik napas.", "이번엔 내 차례였다. 나는 {w}을 들고 섰다. 고친 연설문이었다. 2분 30초가 걸렸다.": "Sekarang giliranku. Aku berdiri sambil memegang {w}. Ini pidato yang sudah kuperbaiki. Waktunya 2 menit 30 detik.", "수아가 팔짱을 꼈다.": "Sua melipat tangan.", "솔직히 말해도 돼?": "Boleh aku jujur?", "무슨 말인지 모르겠어. 너무 길고, 끝에 그래서 뭘 하겠다는 건지 안 나와.": "Aku nggak ngerti maksudnya. Terlalu panjang, dan di akhir nggak jelas sebenarnya kamu mau melakukan apa.", "그리고 ‘괜찮아?’ 부분, 좋은데 너무 빨리 지나가.": "Terus bagian 'Kamu nggak apa-apa?' bagus, tapi lewatnya terlalu cepat.", "(밤새 고친 건데.)": "(Padahal aku memperbaikinya semalaman.)", "「{x}」 한 모금 마시기": "Minum seteguk 「{x}」", "교실 창밖이 붉어졌다. 수아가 손바닥을 내밀었다.": "Langit di luar jendela kelas jadi merah. Sua menyodorkan telapak tangannya.", "이기려고 최선을 다하자.": "Ayo berusaha sebaik mungkin untuk menang.", "나는 그 손바닥을 바로 마주치지 못했다. 수아가 {@hand}을 거두고 먼저 나갔다.": "Aku tidak langsung bisa menepuk telapak tangan itu. Sua menarik {@hand}-nya dan keluar duluan.", "나도 손바닥을 마주쳤다. 짝!": "Aku juga menepuk telapak tangannya. Plak!", "「너 이기려고 일부러 그러는 거지?」": "\"Kamu sengaja begitu biar menang, kan?\"", "너 이기려고 일부러 그러는 거지?": "Kamu sengaja begitu biar menang, kan?", "아니거든. 너도 나한테 숨 쉬라고 했잖아. 나 그거 고칠 거야.": "Nggak, ya. Kamu juga suruh aku tarik napas, kan. Aku mau perbaiki itu.", "그럼 다른 사람한테 들어 봐. 그게 낫겠다.": "Kalau begitu minta orang lain dengar saja. Itu lebih baik.", "수아가 {@bag}을 챙겼다. 연습은 거기서 끝났다.": "Sua membereskan {@bag}. Latihan berakhir di situ.", "「어디가 제일 모르겠어?」 하고 구체적으로 묻는다.": "Tanya dengan jelas: \"Bagian mana yang paling nggak jelas?\"", "어디가 제일 모르겠어?": "Bagian mana yang paling nggak jelas?", "중간에 전학 온 날 얘기. 길어. 그 얘기만 1분이야.": "Cerita hari pertama kamu pindah di tengah. Panjang. Cerita itu saja satu menit.", "그럼 그거 반으로 줄이면?": "Kalau dipotong setengah?", "그리고 끝에 한 줄만 넣어. 반장 되면 뭘 할 건지.": "Terus di akhir tambahkan satu baris saja. Kalau jadi ketua kelas, kamu mau melakukan apa.", "‘천천히 말해 줘’ 카드 만들기. 그거 넣을게.": "Membuat kartu 'Tolong bicara pelan-pelan'. Itu yang aku masukkan.", "다시 했다. 1분 55초.": "Aku coba lagi. 1 menit 55 detik.", "……이제 알겠다.": "...Sekarang aku ngerti.", "「길다는 건 고칠게. 근데 ‘괜찮아?’ 부분은 내 방식대로 할래.」": "\"Yang terlalu panjang akan kuperbaiki. Tapi bagian 'Kamu nggak apa-apa?' aku pakai caraku sendiri.\"", "길다는 건 맞아. 줄일게.": "Memang terlalu panjang. Aku pendekkan.", "근데 ‘괜찮아?’ 부분은 빨리 지나가는 게 아니라 천천히 말할 거야. 그게 나니까.": "Tapi bagian 'Kamu nggak apa-apa?' bukan dilewati cepat, aku mau mengucapkannya pelan-pelan. Karena itulah aku.", "……천천히?": "...Pelan-pelan?", "응. 거기서 멈췄다가 말할 거야.": "Iya. Aku berhenti sebentar di situ, baru bicara.", "다시 했다. 이번엔 ‘괜찮아?’에서 숨을 한 번 멈췄다. 교실이 조용해졌다.": "Aku coba lagi. Kali ini aku berhenti sejenak di 'Kamu nggak apa-apa?'. Kelas jadi hening.", "……그거 좋다. 그건 너 맞네.": "...Itu bagus. Itu memang kamu.", "수아가 말한 대로 전부 고친다.": "Perbaiki semuanya persis seperti kata Sua.", "알았어. 네 말대로 다 고칠게.": "Oke. Aku perbaiki semua sesuai katamu.", "나는 수아가 지적한 걸 다 고쳤다. 전학 온 날 얘기도 빼고, ‘괜찮아?’도 뺐다.": "Aku memperbaiki semua yang Sua tunjukkan. Cerita hari pertama pindah kubuang, 'Kamu nggak apa-apa?' juga kubuang.", "다시 했다. 1분 30초. 짧고 깔끔했다.": "Aku coba lagi. 1 menit 30 detik. Singkat dan rapi.", "……근데 이제 누구 연설인지 모르겠다.": "...Tapi sekarang aku nggak tahu ini pidato siapa.", "(시키는 대로 했는데.)": "(Padahal aku sudah melakukan seperti yang disuruh.)", "{m}, 수아랑 서로 연설 들어 줬어.": "{m}, aku sama Sua saling mendengarkan pidato.", "수아는 1분 40초. 진짜 잘해. 근데 수아가 내 거는 무슨 말인지 모르겠대. 너무 길대.": "Sua 1 menit 40 detik. Hebat banget. Tapi kata Sua, pidatoku nggak jelas maksudnya. Terlalu panjang.", "아이고, 밤새 고친 거잖아.": "Aduh, padahal kamu memperbaikinya semalaman.", "나 이기려고 일부러 그러는 거냐고 했어. 수아가 그럼 다른 사람한테 들어 보래.": "Aku tanya, dia sengaja begitu biar menang, ya. Sua bilang kalau begitu minta orang lain dengar saja.", "속상한 마음에 그렇게 말했구나.": "Kamu bilang begitu karena sedih, ya.", "근데 나도 수아한테 숨 쉬라고 했잖아. 수아는 그거 고친대.": "Tapi aku juga suruh Sua tarik napas, kan. Sua bilang dia mau perbaiki itu.", "……내일 다시 들어 달라고 해 볼래?": "...Mau coba minta dia dengar lagi besok?", "어디가 제일 모르겠냐고 물었어. 전학 온 날 얘기가 너무 길대. 반으로 줄였어.": "Aku tanya bagian mana yang paling nggak jelas. Katanya cerita hari pertama pindah terlalu panjang. Aku potong setengah.", "몇 분 됐어?": "Jadi berapa menit?", "1분 55초! 수아가 이제 알겠대.": "1 menit 55 detik! Kata Sua, sekarang dia ngerti.", "길다는 건 고치겠다고 했어. 근데 ‘괜찮아?’는 내 방식대로 천천히 하겠다고 했어.": "Aku bilang yang terlalu panjang akan kuperbaiki. Tapi 'Kamu nggak apa-apa?' mau kuucapkan pelan-pelan dengan caraku sendiri.", "그거 좋대. 그건 나 맞대.": "Katanya bagus. Katanya itu memang aku.", "들을 건 듣고, 지킬 건 지켰네.": "Yang perlu didengar, kamu dengar. Yang perlu dijaga, kamu jaga.", "수아 말대로 다 고쳤어. 짧아졌어. 근데 수아가 이제 누구 연설인지 모르겠대.": "Aku perbaiki semua sesuai kata Sua. Jadi lebih pendek. Tapi kata Sua sekarang dia nggak tahu ini pidato siapa.", "다 빼 버렸구나.": "Semuanya kamu buang, ya.", "응. ‘괜찮아?’도 뺐어.": "Iya. 'Kamu nggak apa-apa?' juga kubuang.", "그건 다시 넣고 싶지 않아?": "Kamu nggak mau memasukkannya lagi?", "……넣을래.": "...Mau.", "창체 시간. 선생님이 수아와 나를 앞으로 부르셨다.": "Jam kegiatan kelas. Bu Guru memanggil Sua dan aku ke depan.", "선생님: 「오늘 자리 바꾸기는 반장 후보 둘이 같이 진행해 볼래요? 연습이라고 생각하고.」": "Bu Guru: \"Hari ini pindah tempat duduk dipimpin berdua oleh dua calon ketua kelas, ya? Anggap saja latihan.\"", "나는 수아 옆에 섰다. 수아가 작게 말했다.": "Aku berdiri di samping Sua. Sua berbisik.", "번호 뽑기로 하자. 빠르고 공평해.": "Kita pakai undian nomor saja. Cepat dan adil.", "「{x}」 줄 맞추기": "Rapikan barisan 「{x}」", "그런데 맨 뒤에 앉은 친구가 {@blackboard}을 보느라 눈을 찡그리고 있었다. 지난번 자리 바꿀 때 뒤로 갔던 친구였다.": "Tapi teman yang duduk paling belakang menyipitkan mata untuk melihat {@blackboard}. Dia teman yang dipindah ke belakang waktu pindah tempat duduk sebelumnya.", "(번호 뽑기면…… 또 뒤로 갈 수도 있잖아.)": "(Kalau pakai undian... bisa-bisa dia ke belakang lagi.)", "수아야, 근데 눈 나쁜 애들은 앞에 앉아야 하지 않을까? 먼저 물어보면…….": "Sua, tapi bukannya anak yang matanya kurang bagus harus duduk di depan? Kalau ditanya dulu...", "그럼 다들 앞에 앉고 싶다고 하면? 시간 없어. 번호 뽑기가 공평해.": "Kalau semua bilang mau duduk di depan, gimana? Nggak ada waktu. Undian nomor itu adil.", "반 아이들이 우리 둘을 보고 있었다. 누군가 「빨리 해!」 하고 외쳤다.": "Anak-anak sekelas memperhatikan kami berdua. Ada yang berteriak, \"Cepetan!\"", "자리 바꾸기가 끝났다. 선생님이 둘을 보고 웃으셨다.": "Pindah tempat duduk selesai. Bu Guru melihat kami berdua dan tersenyum.", "선생님: 「둘이 이끄는 방식이 다르네요.」": "Bu Guru: \"Cara kalian memimpin berbeda, ya.\"", "수아가 나를 힐끗 봤다.": "Sua melirikku.", "다르다는 게 칭찬이야, 아니야?": "Berbeda itu pujian atau bukan?", "……칭찬이겠지?": "...Pujian, kan?", "「둘 다 하자. 꼭 앞이어야 하는 사람만 먼저, 나머지는 뽑기.」": "\"Pakai dua-duanya. Yang benar-benar harus di depan duluan, sisanya undian.\"", "둘 다 하자. 눈 때문에 꼭 앞이어야 하는 사람만 먼저 {@hand} 들고, 나머지는 번호 뽑기.": "Pakai dua-duanya. Yang karena matanya benar-benar harus di depan angkat {@hand} duluan, sisanya undian nomor.", "……‘꼭’인 사람만?": "...Cuma yang 'benar-benar'?", "응. 그냥 앞이 좋은 건 안 되고.": "Iya. Kalau cuma suka di depan, nggak boleh.", "좋아. 정리하면, 꼭인 사람 먼저, 나머지 뽑기.": "Oke. Jadi, ringkasnya, yang benar-benar perlu duluan, sisanya undian.", "세 명이 {@hand}을 들었다. 나머지는 수아가 번호를 뽑았다. 5분 만에 끝났다.": "Tiga anak mengangkat {@hand}. Sisanya, Sua yang mengundi nomor. Selesai dalam lima menit.", "반 친구들에게 어떤 방식이 좋은지 묻는다.": "Tanya teman-teman sekelas cara mana yang mereka suka.", "얘들아, 두 가지 방법이 있어. 번호 뽑기, 아니면 먼저 사정 있는 사람 물어보고 정하기. {@hand} 들어 줘.": "Teman-teman, ada dua cara. Undian nomor, atau tanya dulu siapa yang punya alasan khusus baru ditentukan. Angkat {@hand}, ya.", "아이들이 {@hand}을 들었다. 거의 반반이었다.": "Anak-anak mengangkat {@hand}. Hampir setengah-setengah.", "반반이네.": "Setengah-setengah.", "아이: 「그럼 섞어!」": "Seorang anak: \"Kalau gitu gabung saja!\"", "결국 사정 있는 사람 먼저, 나머지는 뽑기가 됐다.": "Akhirnya, yang punya alasan khusus duluan, sisanya undian.", "……애들이 정하니까 아무도 불만이 없네.": "...Karena anak-anak sendiri yang memutuskan, nggak ada yang protes.", "「알았어. 네 방식대로 하자.」": "\"Oke. Pakai caramu saja.\"", "……알았어. 네 방식대로 하자.": "...Oke. Pakai caramu saja.", "번호 뽑기로 정했다. 빨랐다. 눈을 찡그리던 친구는 이번에도 맨 뒤가 됐다.": "Akhirnya pakai undian nomor. Cepat. Teman yang tadi menyipitkan mata lagi-lagi dapat paling belakang.", "(아까 말할 걸.)": "(Harusnya tadi aku bilang.)", "「내 방식이 더 좋아. 다 물어보고 정하자.」": "\"Caraku lebih bagus. Tanya semua dulu baru putuskan.\"", "내 방식이 더 좋아. 한 명씩 다 물어보고 정하자.": "Caraku lebih bagus. Kita tanya satu per satu dulu baru putuskan.", "스물네 명을 다?": "Dua puluh empat orang semuanya?", "한 명씩 물어보니 다들 앞이나 창가에 앉고 싶다고 했다. 시간이 다 갔다. 결국 종이 울려서 선생님이 정하셨다.": "Waktu ditanya satu per satu, semua bilang mau duduk di depan atau dekat jendela. Waktunya habis. Akhirnya bel berbunyi dan Bu Guru yang menentukan.", "{m}, 오늘 수아랑 둘이 자리 바꾸기 진행했어. 반장 후보 연습이래.": "{m}, hari ini aku sama Sua memimpin pindah tempat duduk berdua. Katanya latihan calon ketua kelas.", "와, 둘이서? 어떻게 했어?": "Wah, berdua? Gimana caranya?", "수아는 번호 뽑기가 공평하대. 근데 맨 뒤 애가 {@blackboard} 보느라 눈을 찡그리고 있었어.": "Kata Sua, undian nomor itu adil. Tapi anak paling belakang menyipitkan mata buat lihat {@blackboard}.", "꼭 앞이어야 하는 사람만 먼저 하고, 나머지는 뽑기로 하자고 했어.": "Aku bilang yang benar-benar harus di depan duluan, sisanya undian.", "수아 방식이랑 네 방식을 섞었구나.": "Kamu menggabungkan cara Sua dan caramu, ya.", "응. 5분 만에 끝났어. 수아가 정리하면, 이러면서 정리했어.": "Iya. Selesai dalam lima menit. Sua bilang \"jadi, ringkasnya\" terus merangkumnya.", "애들한테 어떤 방법이 좋냐고 물어봤어. 반반이었는데 누가 섞자고 해서 섞었어.": "Aku tanya ke anak-anak cara mana yang mereka suka. Setengah-setengah, terus ada yang bilang gabung saja, jadi kami gabung.", "반 아이들이 정했네.": "Jadi anak-anak sekelas yang memutuskan.", "응. 수아가 애들이 정하니까 불만이 없대.": "Iya. Kata Sua, karena anak-anak sendiri yang memutuskan, nggak ada yang protes.", "그냥 수아 방식대로 했어. 근데 그 애가 또 맨 뒤 됐어.": "Aku ikut cara Sua saja. Tapi anak itu dapat paling belakang lagi.", "아쉬웠겠다.": "Pasti kamu menyesal.", "응. 아까 말할 걸.": "Iya. Harusnya tadi aku bilang.", "다음엔 말해 봐. 너 그 애 눈 찡그리는 거 봤잖아.": "Lain kali bilang, ya. Kamu kan lihat anak itu menyipitkan mata.", "내 방식대로 다 물어보자고 했는데, 다들 앞이나 창가래. 결국 시간 다 가서 선생님이 정하셨어.": "Aku bilang pakai caraku, tanya semuanya, tapi semua mau di depan atau dekat jendela. Akhirnya waktunya habis dan Bu Guru yang menentukan.", "스물네 명한테 다 물어봤어?": "Kamu tanya ke dua puluh empat orang semuanya?", "응…… 수아 말도 맞았어. 시간이 없었어.": "Iya... kata Sua juga benar. Nggak ada waktu.", "방과 후. 복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "Sepulang sekolah. Sua berdiri di dekat jendela lorong. Aku menghampiri Sua.", "{@window}이 열리고 운동장 소리가 들어왔다.": "{@window} terbuka dan suara dari lapangan terdengar masuk.", "이거 기억나?": "Kamu ingat ini?", "수아가 {@bag}에서 접힌 {@paper}를 꺼냈다.": "Sua mengeluarkan {@paper} yang terlipat dari {@bag}.", "처음 도서관에서 만든 규칙표였다. 귀퉁이에 수아가 그린 빨래판 {@stairs}도 그대로 있었다.": "Itu daftar aturan pertama yang kami buat di perpustakaan. {@stairs} mirip papan cuci yang Sua gambar di pojoknya juga masih ada.", "이거 아직 갖고 있었어?": "Kamu masih menyimpan ini?", "응. 버리기 아까워서.": "Iya. Sayang kalau dibuang.", "수아가 창밖 운동장을 봤다.": "Sua memandang lapangan di luar jendela.", "있잖아. 만약에 네가 반장 되면, 나한테 뭘 맡길 거야?": "Eh. Kalau misalnya kamu jadi ketua kelas, kamu mau kasih aku tugas apa?", "……갑자기?": "...Kok tiba-tiba?", "궁금해서. 진짜로.": "Penasaran. Serius.", "수아가 규칙표를 다시 접어 내 {@hand}에 쥐여 줬다.": "Sua melipat lagi daftar aturan itu dan menyelipkannya ke {@hand}-ku.", "그럼 너는? 네가 반장 되면 나한테 뭘 맡길 거야?": "Kalau kamu? Kalau kamu jadi ketua kelas, kamu mau kasih aku tugas apa?", "너한테는 ‘새 친구 도우미’. 넌 뭐가 어려운지 아니까.": "Buat kamu, 'pembantu teman baru'. Kamu kan tahu apa yang susah.", "……아, 근데 그 전에 물어볼게. 하고 싶은지.": "...Oh, tapi sebelum itu aku tanya dulu. Kamu mau atau nggak.", "(처음엔 수아처럼 되고 싶었어.)": "(Awalnya aku ingin jadi seperti Sua.)", "(지금은…… 수아랑 같이 하고 싶어.)": "(Sekarang... aku ingin melakukannya bersama Sua.)", "「네가 잘하는 거. 대신 혼자 다 안 하게 나눠서.」": "\"Yang kamu kuasai. Tapi dibagi, supaya kamu nggak mengerjakan semuanya sendiri.\"", "네가 잘하는 거. 정리하는 거, 시간 재는 거.": "Yang kamu kuasai. Merangkum, menghitung waktu.", "대신 혼자 다 안 하게 나눠서. 신청서 때처럼 혼자 뛰어다니면 안 돼.": "Tapi dibagi, supaya kamu nggak mengerjakan semuanya sendiri. Jangan lari ke sana kemari sendirian kayak waktu formulir pendaftaran.", "……그거 기억하네.": "...Kamu ingat itu.", "알았어. 나눠서.": "Oke. Dibagi.", "「아무것도. 내가 다 할 거야.」": "\"Nggak ada. Aku kerjakan semuanya sendiri.\"", "아무것도 안 맡길 거야. 내가 다 할 거야.": "Aku nggak akan kasih tugas apa pun. Aku kerjakan semuanya sendiri.", "……그거 나잖아.": "...Itu kan aku.", "응. 너 따라 해 봤어.": "Iya. Aku coba meniru kamu.", "그러다 쓰러져. 나 해 봐서 알아.": "Nanti kamu tumbang. Aku tahu, aku sudah pernah.", "수아가 웃었다. 농담이었지만, 수아는 진짜 대답을 기다리는 얼굴이었다.": "Sua tertawa. Itu cuma bercanda, tapi wajah Sua seperti menunggu jawaban yang sungguhan.", "「부반장 해 줘.」": "\"Jadi wakil ketua kelas, ya.\"", "부반장 해 줘.": "Jadi wakil ketua kelas, ya.", "벌써 정했어? 나한테 물어보지도 않고?": "Sudah kamu putuskan? Tanpa tanya aku dulu?", "부반장이 싫다는 게 아니라, 먼저 물어보라고.": "Bukan karena aku nggak mau jadi wakil ketua, tapi tanya dulu.", "「네가 하고 싶은 걸 먼저 물어볼래.」": "\"Aku mau tanya dulu apa yang ingin kamu lakukan.\"", "네가 하고 싶은 걸 먼저 물어볼래.": "Aku mau tanya dulu apa yang ingin kamu lakukan.", "내가 하고 싶은 거?": "Yang ingin aku lakukan?", "응. 넌 늘 해야 하는 걸 하잖아. 하고 싶은 건 뭔데?": "Iya. Kamu selalu mengerjakan yang harus dikerjakan. Yang ingin kamu lakukan apa?", "수아가 한참 생각했다.": "Sua berpikir lama.", "……{@picture} 규칙표. 그거 계속 만들고 싶어. {@picture}은 네가 그리고.": "...Daftar aturan {@picture}. Aku ingin terus membuatnya. {@picture}-nya kamu yang gambar.", "{m}, 수아가 처음 만든 규칙표 아직 갖고 있었어. 빨래판 {@stairs} 그대로.": "{m}, Sua masih menyimpan daftar aturan pertama yang dia buat. {@stairs} yang mirip papan cuci itu masih ada.", "그 {@stairs}?": "{@stairs} yang itu?", "응. 그리고 수아가 나 반장 되면 자기한테 뭘 맡길 거냐고 물었어.": "Iya. Terus Sua tanya, kalau aku jadi ketua kelas, aku mau kasih dia tugas apa.", "네가 잘하는 거, 대신 혼자 다 하지 말고 나눠서 하라고 했어.": "Aku bilang yang dia kuasai, tapi dibagi, jangan dikerjakan sendirian semuanya.", "신청서 때 일 기억하냐고. 알았대.": "Aku tanya dia ingat kejadian formulir pendaftaran. Katanya oke.", "아무것도 안 맡기고 내가 다 한다고 했어. 수아 따라 한 거야.": "Aku bilang nggak akan kasih tugas apa pun, aku kerjakan semuanya sendiri. Aku meniru Sua.", "그러다 쓰러진대. 자기가 해 봐서 안대.": "Katanya nanti aku tumbang. Dia tahu karena sudah pernah.", "부반장 해 달라고 했어. 근데 수아가 물어보지도 않고 정하냐고.": "Aku minta dia jadi wakil ketua kelas. Tapi Sua tanya, kok aku memutuskan tanpa tanya dia dulu.", "싫다고 한 거야?": "Dia bilang nggak mau?", "아니. 먼저 물어보래.": "Nggak. Katanya tanya dulu.", "하고 싶은 거 먼저 물어보겠다고 했어. 수아가 한참 생각하더니, {@picture} 규칙표 계속 만들고 싶대.": "Aku bilang mau tanya dulu apa yang ingin dia lakukan. Sua berpikir lama, terus bilang dia ingin terus membuat daftar aturan {@picture}.", "수아가 하고 싶은 걸 처음 들었네.": "Pertama kali kamu dengar apa yang ingin Sua lakukan, ya.", "수아는 반장 되면 나한테 새 친구 도우미 맡긴대. 내가 뭐가 어려운지 아니까. 근데 먼저 물어보겠대.": "Kata Sua, kalau dia jadi ketua kelas, dia mau kasih aku tugas pembantu teman baru. Karena aku tahu apa yang susah. Tapi dia mau tanya aku dulu.", "둘 다 서로한테 물어보네.": "Kalian berdua saling bertanya, ya.", "응. {m}, 나 처음엔 수아처럼 되고 싶었거든.": "Iya. {m}, awalnya aku ingin jadi seperti Sua.", "지금은?": "Sekarang?", "지금은 수아랑 같이 하고 싶어.": "Sekarang aku ingin melakukannya bersama Sua.", "결과 발표가 끝났다. 교실은 시끄러웠다. 나는 수아를 찾아 복도 창가로 갔다. 수아가 먼저 와 있었다.": "Pengumuman hasil selesai. Kelas ramai. Aku mencari Sua dan pergi ke dekat jendela lorong. Sua sudah ada di sana duluan.", "축하해.": "Selamat, ya.", "솔직히 속상해. 많이.": "Jujur, aku sedih. Banget.", "수아는 울지 않았다. 대신 형광펜을 꽉 쥐고 있었다.": "Sua tidak menangis. Tapi dia menggenggam erat stabilonya.", "근데 너 ‘괜찮아?’ 할 때. 나도 거기서 조용해졌어.": "Tapi waktu kamu bilang 'Kamu nggak apa-apa?'. Aku juga jadi diam di situ.", "……규칙 정리하는 거 필요하면 말해. 아, 물어보는 거 맞지? 물어볼게. 필요해?": "...Kalau perlu bantuan merangkum aturan, bilang saja. Oh, harusnya tanya dulu, kan? Aku tanya, ya. Perlu?", "응. 필요해.": "Iya. Perlu.", "그럼 다음 선거 때 보자. 그땐 진짜 안 질 거야.": "Kalau begitu, sampai jumpa di pemilihan berikutnya. Waktu itu aku benar-benar nggak akan kalah.", "수아가 {@blackboard} 쪽을 돌아봤다. {@blackboard}에는 두 이름이 나란히 적혀 있었다. 내 이름, 그리고 수아 이름.": "Sua menoleh ke arah {@blackboard}. Di {@blackboard} tertulis dua nama berdampingan. Namaku, dan nama Sua.", "……같이래.": "...Katanya bareng.", "응. 같이.": "Iya. Bareng.", "나 혼자 되고 싶었어. 조금.": "Aku ingin jadi sendirian. Sedikit.", "나도. 조금.": "Aku juga. Sedikit.", "둘이 동시에 웃음이 터졌다.": "Kami berdua tertawa bersamaan.", "정리하면, 반장이 둘이야. 그럼 뭐부터 나눠?": "Jadi, ringkasnya, ketua kelasnya ada dua. Terus, apa yang kita bagi duluan?", "……그거 먼저 물어보는 거 맞지?": "...Itu harus ditanya dulu, kan?", "응. 이번엔 내가 먼저 물을게. 너는 뭐 하고 싶어?": "Iya. Kali ini aku yang tanya duluan. Kamu ingin melakukan apa?", "새로 온 친구 챙기기. 그리고 바뀌는 거 미리 알려 주기.": "Memperhatikan teman yang baru datang. Terus memberi tahu lebih dulu kalau ada yang berubah.", "그럼 나는 회의 정리랑 시간 재기. 규칙표는 같이.": "Kalau begitu aku merangkum rapat dan menghitung waktu. Daftar aturan kita buat bareng.", "{@picture}은 내가.": "{@picture}-nya aku.", "{@stairs}도 너.": "{@stairs}-nya juga kamu.", "첫날 너 나 보고 멋있다고 생각했지? 민호 막을 때.": "Di hari pertama kamu lihat aku dan pikir aku keren, kan? Waktu aku menghentikan Minho.", "……어떻게 알았어?": "...Kok kamu tahu?", "얼굴에 다 쓰여 있었어. 근데 지금은 내가 너 보고 그래.": "Kelihatan jelas di wajahmu. Tapi sekarang aku yang begitu waktu lihat kamu.", "목이 따끔했다. 나는 창밖만 봤다.": "Tenggorokanku terasa perih. Aku hanya memandang ke luar jendela.", "너 ‘괜찮아?’ 할 때, 애들 다 조용해졌어. 나 그거 무서웠어. 질 줄 알았어.": "Waktu kamu bilang 'Kamu nggak apa-apa?', anak-anak semua jadi diam. Aku takut. Kukira aku bakal kalah.", "……진짜?": "...Serius?", "응. 그래서 말인데, 새 친구 도우미. 해 볼래? 하고 싶은지 먼저 묻는 거야.": "Iya. Makanya, pembantu teman baru. Kamu mau coba? Aku tanya dulu kamu mau atau nggak.", "(속상해. 근데 수아가 진짜로 물어봤어.)": "(Sedih. Tapi Sua benar-benar bertanya.)", "……생각해 볼게. 근데 아마 할 것 같아.": "...Aku pikir-pikir dulu. Tapi kayaknya aku mau.", "정리하면, 할 거라는 거지?": "Jadi, ringkasnya, kamu mau, kan?", "……우리 둘 다 떨어졌네.": "...Kita berdua kalah, ya.", "정리하면, 둘이 표를 나눠 가졌다는 거지.": "Jadi, ringkasnya, suara kita terbagi berdua.", "둘 다 잠깐 말이 없었다. 교실 안에서 새 반장이 친구들한테 둘러싸여 있었다.": "Kami berdua diam sebentar. Di dalam kelas, ketua kelas yang baru dikerumuni teman-teman.", "……우리 가서 축하해 줄까?": "...Kita ke sana kasih selamat, yuk?", "응. 같이 가자.": "Iya. Ayo bareng.", "그리고 규칙표는 반장 아니어도 만들 수 있잖아.": "Terus, daftar aturan kan bisa dibuat walau bukan ketua kelas.", "수아가 먼저 말했다.": "Sua yang bicara duluan.", "떨어졌다.": "Aku kalah.", "……내가 돼서 미안. 아니, 미안한 건 아닌데. 그냥.": "...Maaf aku yang terpilih. Eh, bukan minta maaf sih. Cuma, ya.", "……우리 둘 다.": "...Kita berdua.", "수아가 창틀에 팔을 걸쳤다. 나도 옆에 섰다. 어깨가 거의 닿을 만큼.": "Sua menyandarkan lengannya di bingkai jendela. Aku berdiri di sampingnya. Bahu kami hampir bersentuhan.", "있잖아. 선거 끝나면 경쟁자 아니잖아.": "Eh. Kalau pemilihan selesai, kita bukan saingan lagi, kan.", "그럼 이제 뭐야, 우리?": "Terus sekarang kita apa?", "……그냥 친구?": "...Teman biasa?", "그냥은 별로야. 정리해 봐.": "'Biasa' itu kurang. Coba rangkum.", "음…… 제일 친한 친구.": "Hmm... sahabat.", "수아가 형광펜을 꺼내더니 자기 손등에 작게 별을 그렸다. 그리고 내 손등에도 그렸다.": "Sua mengeluarkan stabilo dan menggambar bintang kecil di punggung tangannya. Lalu di punggung tanganku juga.", "정리 완료. 지워지면 다시 그려 줄게.": "Rangkuman selesai. Kalau terhapus, nanti kugambar lagi.", "……떨어졌네.": "...Kalah, ya.", "근데 너 아까 발표 끝나자마자 {bff}한테 먼저 갔지?": "Tapi tadi begitu pengumuman selesai, kamu langsung ke {bff} duluan, kan?", "……봤어?": "...Kamu lihat?", "응. {bff}도 너 찾고 있었어. 둘이 똑같은 얼굴이던데.": "Iya. {bff} juga lagi cari kamu. Wajah kalian berdua sama persis.", "수아가 웃었다.": "Sua tertawa.", "반장보다 그게 더 어려울걸. 한 사람이랑 진짜 친해지는 거.": "Itu mungkin lebih susah daripada jadi ketua kelas. Benar-benar akrab dengan satu orang.", "……나는 아직 그런 친구 없어. 다들 반장한테 말 거는 거라서.": "...Aku belum punya teman kayak gitu. Semua orang ngajak ngobrol aku karena aku ketua kelas.", "너도 생길 거야.": "Kamu juga nanti punya.", "정리하면, 나도 좀 덜 바빠야 한다는 거지.": "Jadi, ringkasnya, aku juga harus sedikit kurang sibuk.", "복도 창가에 나 혼자가 아니었다. 그룹 친구들이 우르르 따라 나왔다. 그 안에 수아도 있었다.": "Di dekat jendela lorong, aku tidak sendirian. Teman-teman kelompokku berbondong-bondong ikut keluar. Sua juga ada di antara mereka.", "……떨어졌다.": "...Kalah.", "아, 나는 됐지. 근데 우리 중에선 나 혼자네.": "Ah, aku sih terpilih. Tapi di antara kita cuma aku sendiri.", "친구들이 웃었다.": "Teman-teman tertawa.", "친구들이 서로 어깨를 툭툭 쳤다. 누가 「괜찮아, 괜찮아」 했다. 내가 맨날 하던 말이었다.": "Teman-teman saling menepuk bahu. Ada yang bilang, \"Nggak apa-apa, nggak apa-apa.\" Itu kata-kata yang selalu kuucapkan.", "우리 반장 아니어도 할 거 많잖아. 정리해 볼까?": "Walau bukan ketua kelas, banyak yang bisa kita lakukan, kan. Mau kita rangkum?", "또 정리해?": "Merangkum lagi?", "응. 1번, 점심에 같이 앉기. 2번, 규칙표 만들기. 3번……": "Iya. Nomor 1, duduk bareng waktu makan siang. Nomor 2, membuat daftar aturan. Nomor 3...", "친구들: 「3번은 놀기!」": "Teman-teman: \"Nomor 3 main!\"", "……3번 놀기. 통과.": "...Nomor 3, main. Disetujui.", "떨어졌네.": "Kalah, ya.", "그때 교실 {@door}이 열리고, 내 그룹 친구들이 나를 찾아 나왔다. 「야, 어디 갔었어!」": "Saat itu {@door} kelas terbuka, dan teman-teman kelompokku keluar mencariku. \"Hei, kamu ke mana saja!\"", "……너 찾으러 왔네.": "...Mereka datang mencarimu.", "부럽다. 반장 되면 다들 일 얘기만 하러 오거든. 너는 그냥 너라서 오는 거잖아.": "Iri, deh. Kalau jadi ketua kelas, semua datang cuma buat ngomongin tugas. Kamu didatangi karena kamu ya kamu.", "……너도 같이 갈래? 점심 같이 먹자.": "...Kamu mau ikut juga? Kita makan siang bareng.", "수아가 잠깐 망설였다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "Sua ragu sebentar. Lalu dia menutup stabilonya, klik.", "……한 번만.": "...Sekali ini saja.", "……나는 됐고.": "...Aku sih terpilih.", "응. 괜찮아.": "Iya. Nggak apa-apa.", "그때 교실 안에서 누가 외쳤다.": "Saat itu ada yang berteriak dari dalam kelas.", "야! 이거 너네 나라 말로 뭐라고 해? 빨리 와 봐!": "Hei! Ini dalam bahasa negaramu apa? Cepat ke sini!", "교실 뒤 게시판에는 두 나라 말로 된 낱말 카드가 붙어 있었다. {@desk}, {w}, {@cat}, 나비. 아이들이 하나씩 붙인 거였다.": "Di papan pengumuman belakang kelas tertempel kartu kata dalam dua bahasa. {@desk}, {w}, {@cat}, kupu-kupu. Anak-anak menempelkannya satu per satu.", "저거 언제 저렇게 됐어?": "Kapan itu jadi begitu?", "……나도 몰라. 애들이 하나씩 물어보더니.": "...Aku juga nggak tahu. Anak-anak tanya satu per satu, terus begitu.", "{U@notebook}.": "{U@notebook}.", "수아가 우리 말로 말했다. 발음이 좀 틀렸다.": "Sua mengucapkannya dalam bahasaku. Pengucapannya agak salah.", "응. 맞아.": "Iya. Betul.", "……반장보다 그게 더 멋있다. 반 애들이 너한테 배우잖아.": "...Itu lebih keren daripada ketua kelas. Anak-anak sekelas belajar darimu.", "정리하면, 너는 선생님이고 나는 학생이야. 오늘만.": "Jadi, ringkasnya, kamu gurunya dan aku muridnya. Hari ini saja.", "……나는 됐어.": "...Aku sih terpilih.", "수아가 내 {@hand}에 들린 {w}을 봤다.": "Sua melihat {w} yang ada di {@hand}-ku.", "첫날 쓴 거. 반 친구 이름.": "Yang kamu tulis di hari pertama. Nama-nama teman sekelas.", "{w}을 펼쳤다. 첫날 적은 이름 몇 개 밑에, 새 이름이 몇 개 더 있었다. 수아 이름도 있었다.": "Aku membuka {w}. Di bawah beberapa nama yang kutulis di hari pertama, ada beberapa nama baru. Nama Sua juga ada.", "다음 학기에 또 나가?": "Semester depan kamu ikut lagi?", "……응. 나갈래.": "...Iya. Aku ikut.", "그럼 그때는 이름 더 많이 적어 와. 다 적으면 나 진짜 질 수도 있겠다.": "Kalau begitu, nanti tulis lebih banyak nama. Kalau semua kamu tulis, aku beneran bisa kalah.", "다음 학기에 보자. 경쟁자.": "Sampai jumpa semester depan. Saingan.", "{m}, 선거 결과 나왔어.": "{m}, hasil pemilihan sudah keluar.", "나 됐어! 수아가 축하한다고 했어. 근데 많이 속상하대.": "Aku terpilih! Sua bilang selamat. Tapi katanya dia sedih banget.", "축하해. 그리고 그걸 솔직하게 말해 준 수아도 대단하다.": "Selamat, ya. Dan Sua juga hebat, mau mengatakannya dengan jujur.", "수아가 필요하면 도와준대. 먼저 물어보고.": "Kata Sua, kalau aku perlu, dia mau bantu. Tapi tanya dulu.", "나랑 수아랑 둘 다 반장 됐어! 같이!": "Aku dan Sua dua-duanya jadi ketua kelas! Bareng!", "둘 다? 와, 축하해!": "Dua-duanya? Wah, selamat!", "수아가 혼자 되고 싶었대, 조금. 나도 조금 그랬다고 했어. 둘이 웃었어.": "Kata Sua, dia ingin jadi sendirian, sedikit. Aku bilang aku juga sedikit begitu. Kami berdua tertawa.", "솔직한 반장 둘이네.": "Dua ketua kelas yang jujur, ya.", "수아가 먼저 뭐 하고 싶냐고 물어봤어. 나는 새 친구 챙기기, 수아는 회의 정리.": "Sua tanya duluan aku ingin melakukan apa. Aku memperhatikan teman baru, Sua merangkum rapat.", "수아가 됐어.": "Sua yang terpilih.", "……속상하지?": "...Sedih, ya?", "응. 근데 수아가 새 친구 도우미 하고 싶은지 물어봤어. 할 것 같아.": "Iya. Tapi Sua tanya aku mau jadi pembantu teman baru atau nggak. Kayaknya aku mau.", "반장 아니어도 할 수 있는 일이 생겼네.": "Ada yang bisa kamu lakukan walau bukan ketua kelas, ya.", "나도 수아도 떨어졌어. 둘이 같이 가서 새 반장 축하해 줬어.": "Aku dan Sua dua-duanya kalah. Kami berdua pergi bareng kasih selamat ke ketua kelas yang baru.", "그거 쉽지 않은데.": "Itu nggak gampang, lho.", "수아가 규칙표는 반장 아니어도 만들 수 있대.": "Kata Sua, daftar aturan bisa dibuat walau bukan ketua kelas.", "떨어졌어. 근데 {m}, 이거 봐.": "Aku kalah. Tapi {m}, lihat ini.", "나는 손등의 별을 보여 줬다.": "Aku menunjukkan bintang di punggung tanganku.", "이게 뭐야?": "Ini apa?", "수아가 그렸어. 제일 친한 친구 표시. 지워지면 다시 그려 준대.": "Sua yang gambar. Tanda sahabat. Kalau terhapus, katanya mau digambar lagi.", "……반장보다 귀한 거 받았네.": "...Kamu dapat sesuatu yang lebih berharga daripada jadi ketua kelas.", "떨어졌어. 근데 발표 끝나자마자 {bff}한테 먼저 갔어. 수아가 봤대. 둘이 똑같은 얼굴이었대.": "Aku kalah. Tapi begitu pengumuman selesai, aku langsung ke {bff} duluan. Sua lihat. Katanya wajah kami berdua sama persis.", "그런 친구가 생겼구나.": "Kamu sudah punya teman seperti itu, ya.", "수아가 한 사람이랑 진짜 친해지는 게 반장보다 어렵대.": "Kata Sua, benar-benar akrab dengan satu orang itu lebih susah daripada jadi ketua kelas.", "떨어졌어. 근데 우리 그룹이 다 같이 나와서 괜찮다고 해 줬어. 수아도 있었어. 수아가 할 일 정리했어. 3번은 놀기래.": "Aku kalah. Tapi kelompokku keluar semua dan bilang nggak apa-apa. Sua juga ada. Sua merangkum apa saja yang mau kami lakukan. Nomor 3 katanya main.", "제일 중요한 게 3번이네.": "Yang paling penting nomor 3, ya.", "떨어졌어. 근데 우리 그룹 애들이 나 찾으러 왔어. 수아가 부럽대. 나는 그냥 나라서 다들 온다고. 그래서 수아한테 점심 같이 먹자고 했어.": "Aku kalah. Tapi teman-teman kelompokku datang mencariku. Kata Sua, dia iri. Katanya semua datang karena aku ya aku. Jadi aku ajak Sua makan siang bareng.", "한 번만, 이래.": "Katanya, sekali ini saja.", "떨어졌어. 근데 {m}, 교실 뒤에 우리 말 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "Aku kalah. Tapi {m}, di belakang kelas ada kartu kata bahasa kita! Anak-anak tanya satu per satu, terus jadi begitu. Sua juga ikut bilang {U@notebook}.", "……우리 말을?": "...Bahasa kita?", "응. 내가 선생님이래. 오늘만.": "Iya. Katanya aku gurunya. Hari ini saja.", "{m}는 오늘이 제일 기쁘다.": "Hari ini hari yang paling membahagiakan buat {m}.", "떨어졌어. 근데 첫날 {w} 봤는데, 이름이 좀 늘었어. 수아 이름도 있어.": "Aku kalah. Tapi waktu aku lihat {w} dari hari pertama, namanya sudah bertambah. Nama Sua juga ada.", "다음 학기엔?": "Semester depan?", "또 나갈 거야. 수아가 그땐 이름 더 많이 적어 오래.": "Aku ikut lagi. Kata Sua, nanti aku harus tulis lebih banyak nama.", "그럼 내일부터 또 한 명씩.": "Kalau begitu, mulai besok satu orang lagi, satu per satu."});
T.vi=T.vi||{};Object.assign(T.vi,{"아침. 수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "Buổi sáng. Sua đang dùng bút dạ quang đánh dấu gì đó ở phía trước lớp. Mình đi đến chỗ Sua.", "수아야. 규칙…… 외워 왔어.": "Sua ơi. Quy tắc... tớ học thuộc rồi.", "진짜? 그럼 확인해 볼까.": "Thật á? Vậy kiểm tra thử nhé.", "수아가 형광펜 뚜껑을 딸깍 닫았다.": "Sua đóng nắp bút dạ quang cái tách.", "규칙 3번.": "Quy tắc số 3.", "교실에서 뛰지 않기.": "Không chạy trong lớp.", "5번.": "Số 5.", "친구 밀지 않기.": "Không xô đẩy bạn.", "오, 좀 하는데? 그럼 7번.": "Ồ, cũng giỏi đấy chứ? Vậy số 7.", "비상시에는 {@handkerchief}으로 입을 막고, 자세를 낮춰 이동한다.": "Khi khẩn cấp, dùng {@handkerchief} che miệng, hạ thấp tư thế và di chuyển.", "완벽해.": "Hoàn hảo.", "(……근데 ‘자세를 낮춰’가 무슨 뜻이지? 소리만 외웠어.)": "(...Mà ‘hạ thấp tư thế’ nghĩa là gì nhỉ? Mình chỉ thuộc lòng âm thôi.)", "삐— 삐— 삐—!": "Bíp— bíp— bíp—!", "방송: 「지금부터 화재 대피 훈련을 시작합니다. 담임 선생님의 안내에 따라…….」": "Thông báo: \"Bây giờ bắt đầu buổi diễn tập sơ tán khi có cháy. Các em hãy làm theo hướng dẫn của giáo viên chủ nhiệm...\"", "아이들이 한꺼번에 일어났다. 선생님은 교실 뒤에서 남은 아이가 없는지 확인하고 계셨다.": "Các bạn đồng loạt đứng dậy. Cô giáo đang kiểm tra ở cuối lớp xem còn ai ở lại không.", "규칙 7번! {@handkerchief} 꺼내! 입 막고, 자세 낮추고, 오른쪽 {@stairs}!": "Quy tắc số 7! Lấy {@handkerchief} ra! Che miệng, hạ thấp người, {@stairs} bên phải!", "수아 말이 너무 빨랐다. 아이들이 줄줄이 복도로 나갔다.": "Sua nói nhanh quá. Các bạn lần lượt đi ra hành lang.", "({@handkerchief}…… {@handkerchief}이 뭐였지?)": "({@handkerchief}... {@handkerchief} là gì nhỉ?)", "{@handkerchief}으로 입을 막았다. 그런데 ‘자세를 낮춰’는 아직도 모르겠다. 앞 친구들은 벌써 복도 끝에 있었다.": "Mình lấy {@handkerchief} che miệng. Nhưng ‘hạ thấp tư thế’ thì mình vẫn chưa hiểu. Các bạn phía trước đã ở cuối hành lang rồi.", "왜 안 와? 내가 7번 말했잖아!": "Sao cậu không đi? Tớ nói số 7 rồi mà!", "(외운 건 맞는데…… 뜻을 몰라.)": "(Thuộc thì đúng là thuộc rồi... nhưng mình không biết nghĩa.)", "「{x}」으로 내려가기": "Đi xuống bằng 「{x}」", "운동장. 훈련이 끝났다. 수아가 출석부를 들고 내 옆으로 왔다.": "Sân trường. Buổi diễn tập kết thúc. Sua cầm sổ điểm danh đến bên cạnh mình.", "아까 ‘낮춰’ 몰랐던 거지? 이렇게, 몸을 낮게.": "Lúc nãy cậu không biết ‘hạ thấp’ đúng không? Thế này, hạ người thấp xuống.", "……응. 이제 알아.": "...Ừ. Giờ tớ biết rồi.", "규칙은 외우면 끝인 줄 알았어. 뜻을 모를 수도 있구나.": "Tớ cứ tưởng quy tắc thì học thuộc là xong. Hóa ra cũng có thể không biết nghĩa.", "반장은 이런 것까지 다 챙겨야 해. 생각보다 어려워.": "Lớp trưởng phải lo cả những chuyện như thế này. Khó hơn tớ nghĩ.", "알아. 그래서 나도 하고 싶어.": "Tớ biết. Vì thế tớ cũng muốn làm.", "……뭐?": "...Gì cơ?", "나도 반장 선거 나갈 거야.": "Tớ cũng sẽ ra tranh cử lớp trưởng.", "수아가 나를 빤히 봤다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "Sua nhìn chằm chằm vào mình. Rồi cậu ấy đóng nắp bút dạ quang cái tách.", "좋아. 그럼 경쟁이네.": "Được. Vậy là cạnh tranh nhé.", "근데 너, 아까 뭐가 어려웠는지는 나보다 잘 알겠다.": "Mà chắc cậu biết rõ hơn tớ lúc nãy chỗ nào khó.", "그 자리에서 수아에게 묻는다. 「천천히! ‘낮춰’가 뭐야?」": "Hỏi Sua ngay tại chỗ. \"Chậm thôi! ‘Hạ thấp’ là gì?\"", "수아야, 천천히! ‘자세를 낮춰’가 뭐야?": "Sua ơi, chậm thôi! ‘Hạ thấp tư thế’ là gì?", "수아가 멈칫했다. 그러더니 바로 허리를 숙여 보였다.": "Sua khựng lại. Rồi cậu ấy cúi lưng xuống làm mẫu ngay.", "이렇게! 몸을 낮게. 연기는 위로 올라가니까.": "Thế này! Hạ người thấp xuống. Vì khói bốc lên trên mà.", "아! 낮춰!": "À! Hạ thấp!", "나는 허리를 숙이고 수아 옆에서 오른쪽 {@stairs}으로 걸었다.": "Mình cúi lưng, đi bên cạnh Sua về phía {@stairs} bên phải.", "뛰지 마. 걸어.": "Đừng chạy. Đi bộ thôi.", "알아. 3번.": "Tớ biết. Số 3.", "아는 척 고개를 끄덕이고 앞 친구를 따라 한다.": "Gật đầu như thể đã hiểu và làm theo bạn phía trước.", "나는 고개를 끄덕이고 바로 앞 친구를 따라 했다. 그런데 그 친구는 쪼그려 앉아서 뒤뚱뒤뚱 걷고 있었다.": "Mình gật đầu và làm theo bạn ngay phía trước. Nhưng bạn ấy đang ngồi xổm, đi lạch bạch.", "그건 오리걸음이잖아!": "Đó là đi vịt mà!", "앞 친구는 장난을 치던 거였다. 나는 얼굴이 빨개졌다.": "Bạn phía trước đang đùa. Mặt mình đỏ bừng.", "허리만 숙여. 이렇게.": "Chỉ cúi lưng thôi. Thế này.", "(모르는데 아는 척하니까 더 이상해졌어.)": "(Không biết mà làm như biết nên càng kỳ hơn.)", "내 나라에서 했던 훈련을 떠올려 판단한다.": "Nhớ lại buổi diễn tập ở nước mình để phán đoán.", "(우리 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "(Ở trường mình cũng tập cái này. Khi có cháy, khói bay lên trên nên phải cúi người.)", "(‘낮춰’는 그거구나!)": "(‘Hạ thấp’ là cái đó!)", "나는 허리를 숙이고, 벽에 붙은 초록색 비상구 {@picture}을 따라 {@stairs} 쪽으로 걸었다.": "Mình cúi lưng, đi theo {@picture} lối thoát hiểm màu xanh lá trên tường về phía {@stairs}.", "수아가 뒤돌아보다가 눈을 동그랗게 떴다.": "Sua quay lại nhìn rồi tròn mắt.", "어? 맞게 하네?": "Ơ? Làm đúng nhỉ?", "우리 학교에서도 했어.": "Ở trường tớ cũng tập rồi.", "「너 말 너무 빨라!」 하고 화부터 낸다.": "Nổi giận trước: \"Cậu nói nhanh quá!\"", "너 말 너무 빨라! 하나도 몰라!": "Cậu nói nhanh quá! Tớ chẳng hiểu gì cả!", "지금 훈련 중이야! 그냥 따라와!": "Đang diễn tập mà! Cứ đi theo đi!", "수아가 내 팔을 잡아끌었다. 둘 다 얼굴이 빨개진 채로 {@stairs}까지 갔다.": "Sua kéo tay mình. Cả hai mặt đỏ bừng đi đến tận {@stairs}.", "(화는 났는데, ‘낮춰’는 아직도 몰라.)": "(Giận thì giận, nhưng ‘hạ thấp’ mình vẫn chưa hiểu.)", "{m}, 오늘 대피 훈련 했어. 어제 외운 규칙 7번이 나왔어.": "{m} ơi, hôm nay con diễn tập sơ tán. Quy tắc số 7 con học thuộc hôm qua có xuất hiện đấy.", "어머, 바로 써먹었네?": "Ôi, dùng được ngay luôn à?", "근데 나 ‘자세를 낮춰’가 무슨 뜻인지 몰랐어. 소리만 외웠거든.": "Nhưng con không biết ‘hạ thấp tư thế’ nghĩa là gì. Con chỉ thuộc âm thôi.", "그래서 수아한테 천천히 말해 달라고, 낮춰가 뭐냐고 물었어. 수아가 허리 숙여서 보여 줬어.": "Nên con nhờ Sua nói chậm lại, hỏi ‘hạ thấp’ là gì. Sua cúi lưng làm mẫu cho con xem.", "모르는 거 그 자리에서 물어봤구나. {m}가 첫날 말한 거 기억했네.": "Con hỏi ngay tại chỗ điều mình không biết à. Con nhớ lời {m} nói hôm đầu tiên nhỉ.", "응. 물어보니까 금방이었어.": "Vâng. Hỏi một cái là hiểu ngay.", "아는 척하고 앞에 애를 따라 했는데, 걔가 오리걸음으로 장난치는 거였어.": "Con làm như biết rồi làm theo bạn phía trước, nhưng bạn ấy đang đùa, đi vịt.", "너도 오리걸음 했어?": "Con cũng đi vịt à?", "{m}! 웃지 마. 수아가 그건 오리걸음이라고 소리쳤어.": "{m}! Đừng cười. Sua hét lên đó là đi vịt.", "미안, 미안. 모를 땐 그냥 물어봐도 돼.": "Xin lỗi, xin lỗi. Khi không biết thì cứ hỏi là được.", "우리 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "Con nhớ ra buổi diễn tập ở trường mình. Cúi người vì khói ấy. Nên con làm đúng.", "아, 거기서도 했었지! 기억하고 있었구나.": "À, ở đó cũng tập rồi nhỉ! Con vẫn nhớ đấy.", "수아가 어? 맞게 하네? 그러더라.": "Sua bảo, ơ? Làm đúng nhỉ?", "모르는 말도 아는 걸로 알아낼 수 있구나.": "Từ không biết cũng có thể đoán ra từ điều mình đã biết nhỉ.", "수아한테 너무 빠르다고 화냈어. 수아도 지금 훈련 중이라고 화냈고.": "Con giận Sua vì nói nhanh quá. Sua cũng giận, bảo đang diễn tập.", "둘 다 급했구나.": "Cả hai đều vội nhỉ.", "응. 나중에 수아가 낮춰가 뭔지 알려 줬어.": "Vâng. Sau đó Sua chỉ cho con ‘hạ thấp’ là gì.", "다음엔 화내기 전에 ‘천천히’부터 말해 볼까?": "Lần sau, trước khi giận, thử nói ‘chậm thôi’ trước nhé?", "그리고 {m}. 나 수아한테 반장 선거 나간다고 말했어.": "Còn nữa {m} ơi. Con đã nói với Sua là con sẽ ra tranh cử lớp trưởng.", "정말? 수아가 뭐래?": "Thật à? Sua nói sao?", "좋아, 그럼 경쟁이네, 그랬어.": "Bạn ấy bảo, được, vậy là cạnh tranh nhé.", "멋있는 경쟁자네.": "Đối thủ ngầu ghê.", "도서관 구석 {@desk}. 수아가 큰 {@paper}를 펼쳐 놓고 있었다. 나는 수아 맞은편에 앉았다.": "{@desk} ở góc thư viện. Sua đang trải một tờ {@paper} lớn. Mình ngồi đối diện Sua.", "수아야, 뭐 해?": "Sua ơi, cậu làm gì đấy?", "규칙표 다시 만들어. {@picture}으로.": "Làm lại bảng quy tắc. Bằng {@picture}.", "어제 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "Hôm qua lúc diễn tập, biết đâu cũng có bạn chỉ thuộc âm giống cậu.", "……그거 좋다.": "...Hay đấy.", "같이 할래? 내가 글 쓰고, 넌 {@picture}.": "Làm cùng không? Tớ viết chữ, cậu vẽ {@picture}.", "좋아.": "Được.", "「{x}」 고르기": "Chọn 「{x}」", "수아는 정말 빨랐다. 순식간에 문장 다섯 개를 써 내려갔다.": "Sua nhanh thật. Trong chớp mắt đã viết xong năm câu.", "1번, 3번, 5번은 읽을 수 있었다. 그런데 7번 아래 새로 쓴 문장 하나가 걸렸다.": "Số 1, 3, 5 thì mình đọc được. Nhưng có một câu mới viết dưới số 7 làm mình vướng.", "{@paper}에 쓰인 글: 「연기가 나면 몸을 낮추고 벽을 짚으며 이동한다.」": "Chữ trên {@paper}: \"Khi có khói, hạ thấp người và vịn tường mà di chuyển.\"", "(낮추고는 알아. 근데 ‘벽을 짚으며’는 뭐지?)": "(Hạ thấp thì mình biết. Nhưng ‘vịn tường’ là gì?)", "자, {@picture} 그리면 돼. 쉬는 시간 10분 남았어.": "Đây, cậu vẽ {@picture} là được. Còn 10 phút giải lao.", "수아는 벌써 다음 줄을 쓰고 있었다.": "Sua đã viết đến dòng tiếp theo rồi.", "그러다 수아가 {@stairs} {@picture}을 직접 그려 보겠다며 펜을 들었다. {@paper}에 꼬불꼬불한 선이 생겼다.": "Rồi Sua bảo sẽ tự vẽ {@picture} {@stairs}, cầm bút lên. Trên {@paper} hiện ra những đường ngoằn ngoèo.", "……그건 뭐야?": "...Cái gì đấy?", "{@stairs}.": "{@stairs}.", "빨래판인 줄 알았어.": "Tớ tưởng là cái bàn giặt.", "……그러니까 네가 그려.": "...Thế nên cậu vẽ đi.", "({@picture}은 내가 잘할 수 있어. 근데 ‘짚으며’를 모르면 뭘 그려야 하지?)": "({@picture} thì mình làm tốt được. Nhưng không biết ‘vịn’ thì vẽ cái gì đây?)", "쉬는 시간이 끝나기 전에 규칙표가 완성됐다. 수아는 맨 아래에 두 사람 이름을 나란히 적었다.": "Trước khi hết giờ giải lao, bảng quy tắc đã xong. Sua viết tên hai đứa cạnh nhau ở dưới cùng.", "정리하면, 글은 나, {@picture}은 너.": "Tóm lại là, chữ là tớ, {@picture} là cậu.", "{@stairs}도 나.": "{@stairs} cũng là tớ.", "……{@stairs}도 너.": "...{@stairs} cũng là cậu.", "아는 문장만 그리고, 모르는 문장 칸은 비워 둔다.": "Chỉ vẽ những câu mình hiểu, để trống ô câu không hiểu.", "나는 1번, 3번, 5번만 그렸다. 7번 칸은 비워 뒀다.": "Mình chỉ vẽ số 1, 3, 5. Ô số 7 để trống.", "7번은?": "Số 7 đâu?", "……그건 나중에.": "...Cái đó để sau.", "제일 중요한 건데?": "Cái quan trọng nhất mà?", "‘짚으며’를 몰라서.": "Vì tớ không biết ‘vịn’.", "아, 그래? 그럼 처음부터 말하지.": "À, thế à? Vậy sao không nói ngay từ đầu.", "모르는 말에 동그라미를 치고 묻는다. 「이거 무슨 뜻이야?」": "Khoanh tròn từ không biết rồi hỏi. \"Cái này nghĩa là gì?\"", "나는 ‘짚으며’에 {@pencil}로 동그라미를 쳤다.": "Mình lấy {@pencil} khoanh tròn chữ ‘vịn’.", "이거 무슨 뜻이야?": "Cái này nghĩa là gì?", "벽을 짚으며? {@hand}을 벽에 대고 가는 거.": "Vịn tường à? Là đặt {@hand} lên tường mà đi.", "수아가 손바닥을 책장에 붙여 보였다.": "Sua áp lòng bàn tay vào giá sách làm mẫu.", "아! 그럼 {@hand}을 벽에 대고, 허리 숙이고, 걷는 사람.": "À! Vậy là người đặt {@hand} lên tường, cúi lưng và đi bộ.", "응. 그거.": "Ừ. Đúng rồi.", "나는 그 모습을 그렸다. 수아가 {@picture}을 보더니 고개를 끄덕였다.": "Mình vẽ dáng đó. Sua nhìn {@picture} rồi gật đầu.", "내가 이해한 대로 먼저 그려서 보여 준다. 「이거 맞아?」": "Vẽ trước theo cách mình hiểu rồi cho xem. \"Thế này đúng không?\"", "나는 내가 이해한 대로 그렸다. 연기 아래에서 바닥을 짚고 엉금엉금 기어가는 사람.": "Mình vẽ theo cách mình hiểu. Một người chống tay xuống sàn, bò lổm ngổm dưới làn khói.", "이거 맞아?": "Thế này đúng không?", "……기어가라는 게 아니고!": "...Không phải bảo bò đâu!", "수아가 웃음을 터뜨렸다. 도서관이라 둘 다 입을 막았다.": "Sua bật cười. Vì là thư viện nên cả hai cùng bịt miệng.", "바닥 말고 벽. {@hand}을 벽에 대고 걷는 거야.": "Không phải sàn mà là tường. Đặt {@hand} lên tường mà đi.", "아, 벽! 그럼 이렇게?": "À, tường! Vậy thế này à?", "나는 {@picture}을 고쳤다. 수아가 {@picture}을 보더니 자기 문장을 다시 봤다.": "Mình sửa lại {@picture}. Sua nhìn {@picture} rồi đọc lại câu của mình.", "{@picture} 보니까 내 문장이 너무 기네. 줄일게.": "Nhìn {@picture} mới thấy câu của tớ dài quá. Tớ rút gọn lại.", "「수아야, 그냥 네가 다 해. 넌 다 잘하잖아.」": "\"Sua ơi, cậu làm hết đi. Cậu cái gì cũng giỏi mà.\"", "그냥 네가 다 해. 넌 다 잘하잖아.": "Cậu làm hết đi. Cậu cái gì cũng giỏi mà.", "나 {@picture} 못 그리는 거 방금 봤잖아.": "Cậu vừa thấy tớ vẽ {@picture} dở thế nào mà.", "……그래도.": "...Dù vậy.", "그래도는 무슨. 빨래판 {@stairs} 붙일 거야?": "Dù vậy cái gì. Định dán {@stairs} hình bàn giặt à?", "수아가 {@colored_pencil} 통을 내 쪽으로 밀었다.": "Sua đẩy hộp {@colored_pencil} về phía mình.", "네가 그려. 모르는 거 있으면 물어보고.": "Cậu vẽ đi. Có gì không biết thì hỏi.", "{m}, 수아랑 규칙표 만들었어. 수아가 글 쓰고 내가 {@picture} 그렸어.": "{m} ơi, con làm bảng quy tắc với Sua. Sua viết chữ, con vẽ {@picture}.", "오, {@picture}은 네가?": "Ồ, {@picture} là con vẽ à?", "응. 수아 {@picture} 진짜 못 그려. {@stairs}을 그렸는데 빨래판 같았어.": "Vâng. Sua vẽ {@picture} dở lắm. Bạn ấy vẽ {@stairs} mà trông như cái bàn giặt.", "수아도 못하는 게 있구나.": "Sua cũng có cái không giỏi nhỉ.", "근데 나 모르는 말이 있어서 그 칸은 비워 뒀어. 수아가 제일 중요한 거라고, 처음부터 말하지 그랬냐고 하더라.": "Nhưng có từ con không biết nên con để trống ô đó. Sua bảo cái đó quan trọng nhất, sao không nói ngay từ đầu.", "그럼 그 칸은 어떻게 했어?": "Thế ô đó con làm sao?", "결국 물어보고 그렸어.": "Cuối cùng con hỏi rồi vẽ.", "처음부터 물었으면 더 빨랐겠다.": "Hỏi ngay từ đầu thì đã nhanh hơn rồi.", "‘짚으며’를 몰라서 동그라미 치고 물어봤어. 수아가 {@hand}을 책장에 대고 보여 줬어.": "Con không biết ‘vịn’ nên khoanh tròn rồi hỏi. Sua đặt {@hand} lên giá sách làm mẫu cho con.", "그래서 {@picture}이 맞게 됐어?": "Thế {@picture} có đúng không?", "응. 수아가 고개 끄덕였어.": "Vâng. Sua gật đầu.", "내가 이해한 대로 그렸는데, 사람이 바닥을 기어가고 있었어.": "Con vẽ theo cách con hiểu, nhưng người trong tranh lại đang bò dưới sàn.", "기어가?": "Bò à?", "수아가 기어가라는 게 아니고! 하면서 웃었어. 근데 수아가 {@picture} 보더니 자기 문장이 너무 길대. 줄였어.": "Sua vừa cười vừa bảo, không phải bảo bò đâu! Nhưng Sua nhìn {@picture} rồi bảo câu của bạn ấy dài quá. Bạn ấy rút gọn lại.", "{@picture} 덕분에 글도 바뀌었네.": "Nhờ {@picture} mà chữ cũng thay đổi nhỉ.", "수아한테 그냥 네가 다 하라고 했어. 넌 다 잘하니까.": "Con bảo Sua cứ làm hết đi. Vì bạn ấy cái gì cũng giỏi.", "수아가 뭐래?": "Sua nói sao?", "빨래판 {@stairs} 붙일 거냐고. 그래서 내가 그렸어.": "Bạn ấy hỏi định dán {@stairs} hình bàn giặt à. Nên con vẽ.", "수아 말이 맞네. {@picture}은 네가 더 잘하잖아.": "Sua nói đúng đấy. {@picture} thì con giỏi hơn mà.", "방금 학급회의가 끝났다. 안건은 ‘금요일 학급 놀이 시간에 뭐 할까’였다.": "Buổi sinh hoạt lớp vừa kết thúc. Chủ đề là ‘Giờ chơi của lớp thứ Sáu sẽ chơi gì’.", "나는 처음으로 {@hand}을 들고 우리 나라 놀이를 말했다. 떨려서 말이 엉켰다.": "Lần đầu tiên mình giơ {@hand} lên và kể về trò chơi của nước mình. Vì run nên lời nói bị rối.", "(아까 수아가 한 말) 「음…… 규칙이 복잡해 보여서 어려울 것 같아요. 다음 의견!」": "(Lời Sua nói lúc nãy) \"Ừm... luật có vẻ phức tạp nên chắc sẽ khó. Ý kiến tiếp theo!\"", "결국 피구로 정해졌다. 아이들이 {@chair}를 정리하며 흩어졌다. 나는 수아에게 갔다.": "Cuối cùng lớp chọn chơi bóng né. Các bạn xếp {@chair} rồi tản đi. Mình đi đến chỗ Sua.", "「{x}」 넣기": "Đặt 「{x}」 vào", "수아야, 아까 내 놀이…….": "Sua ơi, trò chơi của tớ lúc nãy...", "아, 그거! 나도 얘기하려고 했어.": "À, cái đó! Tớ cũng định nói.", "수아가 주위를 한 번 둘러보더니 목소리를 낮췄다.": "Sua nhìn quanh một lượt rồi hạ giọng.", "……사실 나, 하나도 못 알아들었어.": "...Thật ra, tớ chẳng hiểu gì cả.", "어?": "Hả?", "네가 말할 때 ‘수건’이랑 ‘같은 편’은 들렸는데, 나머지는 몰랐어. 근데 반장이 못 알아들었다고 하면 이상하잖아.": "Lúc cậu nói, tớ nghe được ‘khăn’ với ‘cùng đội’, còn lại thì không hiểu. Nhưng lớp trưởng mà nói là không hiểu thì kỳ lắm.", "그래서 그냥 어렵다고 넘긴 거야.": "Nên tớ cứ bảo là khó rồi cho qua.", "(수아도…… 나를 못 알아들었구나.)": "(Sua cũng... không hiểu mình.)", "(대피 훈련 때 내가 수아 말을 못 알아들은 거랑 똑같네.)": "(Giống hệt lúc diễn tập sơ tán mình không hiểu lời Sua.)", "다시 설명해 줄래? 이번엔 진짜 들을게.": "Cậu giải thích lại được không? Lần này tớ nghe thật.", "수아가 형광펜을 꺼내 학급회의 {w}에 적었다.": "Sua lấy bút dạ quang ra, ghi vào {w} sinh hoạt lớp.", "수아의 {w}: 「다음 학급회의 안건: 같은 편 {@handkerchief} 놀이」": "{w} của Sua: \"Chủ đề buổi sinh hoạt lớp tới: Trò chơi {@handkerchief} Cùng Đội\"", "다음 회의에 다시 올리자. 이번엔 제대로.": "Buổi sinh hoạt tới mình đưa ra lại. Lần này cho đàng hoàng.", "어떻게 설명할까?": "Giải thích thế nào đây?", "「말보다 해 보는 게 빨라.」 하고 직접 보여 준다.": "\"Làm thử nhanh hơn nói.\" Rồi làm mẫu luôn.", "말보다 해 보는 게 빨라. 앉아 봐.": "Làm thử nhanh hơn nói. Cậu ngồi xuống đi.", "나는 수아를 {@chair}에 앉히고 등 뒤로 돌아가 {@handkerchief}을 살짝 놓았다.": "Mình cho Sua ngồi lên {@chair}, vòng ra sau lưng và khẽ đặt {@handkerchief} xuống.", "이제 뒤에 뭐 있는지 봐.": "Giờ cậu nhìn xem đằng sau có gì.", "어? {@handkerchief}?": "Ơ? {@handkerchief}?", "그럼 날 잡아야 해. 잡히면 나는 술래 아니고, 네 편이 돼.": "Thế thì cậu phải bắt tớ. Bị bắt thì tớ không làm cái nữa, mà thành cùng đội với cậu.", "……잡히면 같은 편? 그게 다야?": "...Bị bắt là cùng đội? Thế thôi à?", "응. 마지막엔 다 같은 편이야.": "Ừ. Cuối cùng ai cũng cùng đội.", "아, 이거 재밌겠다!": "À, cái này chắc vui đây!", "「됐어. 어차피 안 된다며.」 하고 돌아선다.": "\"Thôi. Đằng nào cũng bảo không được mà.\" Rồi quay đi.", "됐어. 어차피 안 된다며.": "Thôi. Đằng nào cậu cũng bảo không được mà.", "아니, 그래서 지금 다시…….": "Không, nên bây giờ tớ mới...", "피구로 정해졌잖아.": "Đã chọn bóng né rồi còn gì.", "나는 {@bag}을 챙겼다. 수아는 형광펜을 만지작거리며 서 있었다.": "Mình thu dọn {@bag}. Sua đứng đó, mân mê cây bút dạ quang.", "……다음 학급회의 때 다시 올리면 돼. 마음 바뀌면 말해 줘.": "...Buổi sinh hoạt lớp tới đưa ra lại là được. Nếu đổi ý thì nói tớ nhé.", "(속상한 건 맞아. 근데 수아는 진짜 듣고 싶어 했는데.)": "(Buồn thì đúng là buồn. Nhưng Sua thật lòng muốn nghe mà.)", "아까 못 한 말까지 한꺼번에 몰아서 설명한다.": "Dồn hết những điều lúc nãy chưa nói ra để giải thích một lèo.", "그러니까 동그랗게 앉아서 술래가 돌다가 {@handkerchief}을 뒤에 놓으면 그걸 알아채서 쫓아가는데 잡히면 술래가 안 되고 잡은 사람 편이 되고 그다음엔 그 편이 같이 술래를…….": "Tức là ngồi thành vòng tròn rồi người làm cái đi vòng quanh và đặt {@handkerchief} sau lưng thì phải phát hiện ra rồi đuổi theo mà nếu bị bắt thì không phải làm cái mà thành cùng đội với người bắt rồi sau đó đội đó cùng nhau làm cái...", "잠깐, 잠깐! 너도 빨라!": "Khoan, khoan! Cậu cũng nhanh quá!", "수아가 두 {@hand}을 들었다. 우리 둘 다 웃음이 터졌다.": "Sua giơ hai {@hand} lên. Cả hai đứa cùng bật cười.", "……대피 훈련 때 너 같았어?": "...Lúc diễn tập sơ tán tớ giống thế này à?", "응. 딱 나 같았어.": "Ừ. Y hệt cậu.", "나는 처음부터 다시, 한 문장씩 천천히 말했다.": "Mình nói lại từ đầu, từng câu một, thật chậm.", "아까 속상했던 것부터 말하고, 그다음 설명한다.": "Nói ra nỗi buồn lúc nãy trước, rồi mới giải thích.", "설명할게. 근데 먼저 말할 거 있어.": "Tớ sẽ giải thích. Nhưng trước tiên tớ có chuyện muốn nói.", "아까 바로 다음 의견, 해서 좀 속상했어. 처음으로 {@hand} 들었거든.": "Lúc nãy cậu nói ngay ‘ý kiến tiếp theo’, tớ hơi buồn. Vì đó là lần đầu tớ giơ {@hand}.", "……그랬구나. 미안. 못 알아들은 거 들킬까 봐 빨리 넘긴 거야.": "...Ra vậy. Xin lỗi. Tớ sợ bị lộ là không hiểu nên cho qua nhanh.", "이제 천천히 할게. 동그랗게 앉아. 술래가 {@handkerchief}을 뒤에 놓아. 잡히면 같은 편이 돼.": "Giờ tớ nói chậm nhé. Ngồi thành vòng tròn. Người làm cái đặt {@handkerchief} sau lưng. Bị bắt thì thành cùng đội.", "세 문장이네. 정리 잘한다.": "Ba câu nhỉ. Cậu tóm tắt giỏi đấy.", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. 우리 나라 놀이 하자고.": "{m} ơi, hôm nay ở buổi sinh hoạt lớp con giơ {@hand} lần đầu tiên. Con đề nghị chơi trò của nước mình.", "정말? 어떻게 됐어?": "Thật à? Thế rồi sao?", "수아가 어려울 것 같다고 바로 다음 의견 했어. 근데 끝나고 수아가 사실 하나도 못 알아들었대.": "Sua bảo chắc sẽ khó rồi chuyển ngay sang ý kiến tiếp theo. Nhưng xong buổi, Sua bảo thật ra bạn ấy chẳng hiểu gì cả.", "어머, 수아가 그렇게 말했어?": "Ôi, Sua nói thế à?", "그래서 말 말고 직접 보여 줬어. 수아를 앉히고 {@handkerchief} 놓았지.": "Nên con không nói nữa mà làm mẫu luôn. Con cho Sua ngồi rồi đặt {@handkerchief}.", "수아는?": "Thế Sua thì sao?", "이거 재밌겠다! 그랬어.": "Bạn ấy bảo, cái này chắc vui đây!", "해 보니까 금방 알았구나.": "Làm thử một cái là hiểu ngay nhỉ.", "근데 나 너무 속상해서 됐다고 하고 그냥 왔어.": "Nhưng con buồn quá nên bảo thôi rồi về luôn.", "속상했겠다. 처음 {@hand} 든 거였잖아.": "Chắc con buồn lắm. Lần đầu con giơ {@hand} mà.", "응. 수아가 다음 회의 때 다시 올리면 된대.": "Vâng. Sua bảo buổi sinh hoạt tới đưa ra lại là được.", "그럼 다음엔 어떻게 할래?": "Vậy lần sau con sẽ làm thế nào?", "아까 못 한 말 한꺼번에 막 했더니, 수아가 너도 빨라! 그랬어.": "Con nói một lèo hết những gì lúc nãy chưa nói, thế là Sua bảo, cậu cũng nhanh quá!", "대피 훈련 때랑 반대네?": "Ngược với lúc diễn tập sơ tán nhỉ?", "응. 둘이 웃었어. 그다음엔 천천히 했어.": "Vâng. Hai đứa cùng cười. Sau đó con nói chậm lại.", "속상했다고 먼저 말했어. 수아가 미안하대. 못 알아들은 거 들킬까 봐 그랬대.": "Con nói trước là con buồn. Sua xin lỗi. Bạn ấy bảo sợ bị lộ là không hiểu.", "수아도 솔직하게 말했네.": "Sua cũng thành thật nhỉ.", "그러고 세 문장으로 설명했더니 정리 잘한대.": "Rồi con giải thích bằng ba câu, bạn ấy khen con tóm tắt giỏi.", "반장도 못 알아들을 때가 있구나.": "Lớp trưởng cũng có lúc không hiểu nhỉ.", "응. 나만 그런 줄 알았어.": "Vâng. Con cứ tưởng chỉ mình con như thế.", "점심시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "Giờ ăn trưa. Sua đang mở {w} sinh hoạt lớp. Mình ngồi cạnh Sua.", "다음 학급회의 내일이야. 놀이 발표 준비하자.": "Buổi sinh hoạt lớp tới là ngày mai. Chuẩn bị phần trình bày trò chơi nào.", "「{x}」 보기": "Xem 「{x}」", "학급회의는 한 사람이 2분 안에 말해야 해. 규칙 12번.": "Ở buổi sinh hoạt lớp, mỗi người phải nói trong vòng 2 phút. Quy tắc số 12.", "그래서 생각해 봤는데, 발표는 내가 할게.": "Nên tớ nghĩ rồi, phần trình bày để tớ làm.", "……네가?": "...Cậu á?", "응. 나는 2분 안에 정리할 수 있어. 넌 아직 한국말이 느리잖아. 떨어지면 아깝잖아.": "Ừ. Tớ tóm tắt được trong 2 phút. Cậu nói tiếng Hàn còn chậm. Bị loại thì tiếc lắm.", "수아 말은 틀린 데가 없었다. 그래서 더 할 말이 없었다.": "Lời Sua chẳng sai chỗ nào. Vì thế mình càng không biết nói gì.", "(맞는 말이야. 수아가 하면 통과될 거야.)": "(Đúng thật. Sua làm thì chắc sẽ được thông qua.)", "(근데…… 내 놀이인데.)": "(Nhưng mà... đây là trò chơi của mình.)", "종이 울렸다. 수아가 형광펜 뚜껑을 딸깍 닫았다.": "Chuông reo. Sua đóng nắp bút dạ quang cái tách.", "내일 떨지 마.": "Mai đừng run nhé.", "너도.": "Cậu cũng thế.", "나는 안 떨어.": "Tớ không run đâu.", "「그럼…… 네가 해.」": "\"Vậy thì... cậu làm đi.\"", "그럼…… 네가 해.": "Vậy thì... cậu làm đi.", "좋아. 내가 깔끔하게 정리할게.": "Được. Tớ sẽ tóm tắt gọn gàng.", "수아가 형광펜으로 줄을 그었다. 나는 옆에서 고개만 끄덕였다.": "Sua kẻ một đường bằng bút dạ quang. Mình ngồi bên cạnh, chỉ gật đầu.", "(이게 맞는 건가.)": "(Thế này có đúng không nhỉ.)", "「내가 할게. 대신 2분 맞추는 연습 같이 해 줘.」": "\"Tớ sẽ làm. Nhưng cậu tập với tớ cho vừa 2 phút nhé.\"", "내가 할게. 내 놀이니까.": "Tớ sẽ làm. Vì đây là trò chơi của tớ.", "2분 넘으면?": "Quá 2 phút thì sao?", "그러니까 연습 같이 해 줘. 네가 {@clock} 봐 줘.": "Thế nên cậu tập cùng tớ nhé. Cậu xem {@clock} giúp tớ.", "수아가 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "Sua nhìn {@clock}. Mình giải thích từ đầu. Hơn 3 phút.", "정리하면, 세 문장만 해. 앉는다. 놓는다. 잡히면 같은 편.": "Tóm lại là, chỉ nói ba câu thôi. Ngồi. Đặt. Bị bắt là cùng đội.", "다시 했다. 1분 50초.": "Làm lại. 1 phút 50 giây.", "……됐네.": "...Được rồi đấy.", "「넌 그냥 반장이라서 다 하고 싶은 거잖아.」": "\"Cậu chỉ muốn làm hết vì cậu là lớp trưởng thôi.\"", "넌 그냥 반장이라서 다 하고 싶은 거잖아.": "Cậu chỉ muốn làm hết vì cậu là lớp trưởng thôi.", "뭐? 나는 통과되라고 그런 건데!": "Gì cơ? Tớ làm thế để được thông qua mà!", "내 놀이인데 왜 네가 해?": "Trò chơi của tớ, sao cậu lại làm?", "둘 다 목소리가 커졌다. 옆에서 밥 먹던 아이들이 쳐다봤다.": "Cả hai đều to tiếng. Các bạn đang ăn cơm bên cạnh quay sang nhìn.", "……그럼 네가 해 봐. 2분 넘으면 내가 {@hand} 들 거야.": "...Vậy cậu làm thử đi. Quá 2 phút là tớ giơ {@hand} đấy.", "「나눠서 하자. 시범은 내가, 규칙 설명은 네가.」": "\"Chia ra làm nhé. Tớ làm mẫu, cậu giải thích luật.\"", "나눠서 하자. 시범은 내가 보여 줄게. 규칙 설명은 네가 해.": "Chia ra làm nhé. Tớ sẽ làm mẫu. Cậu giải thích luật.", "시범?": "Làm mẫu?", "말로 하면 애들이 못 알아들어. 너도 못 알아들었잖아.": "Nói bằng lời thì các bạn không hiểu đâu. Cậu cũng không hiểu còn gì.", "……그건 맞아.": "...Cái đó thì đúng.", "수아가 {w}에 두 칸을 그었다. 한쪽에 ‘시범’, 한쪽에 ‘규칙’.": "Sua kẻ hai ô trong {w}. Một bên ‘Làm mẫu’, một bên ‘Luật’.", "그럼 넌 몸으로, 난 말로.": "Vậy cậu dùng cơ thể, tớ dùng lời.", "{m}, 내일 학급회의에서 우리 나라 놀이 다시 발표해.": "{m} ơi, mai ở buổi sinh hoạt lớp con sẽ trình bày lại trò chơi của nước mình.", "오, 누가 발표해?": "Ồ, ai trình bày?", "수아가 자기가 하겠대. 나는 한국말이 느려서 2분 안에 못 할 거래.": "Sua bảo bạn ấy sẽ làm. Bạn ấy bảo con nói tiếng Hàn chậm nên không nói được trong 2 phút.", "음…… 그래서?": "Ừm... rồi sao?", "그럼 네가 하라고 했어.": "Con bảo thế thì cậu làm đi.", "수아가 하는 게 더 나을 것 같았어?": "Con thấy Sua làm thì tốt hơn à?", "응. 근데 좀 이상해. 내 놀이인데.": "Vâng. Nhưng con thấy hơi lạ. Đây là trò chơi của con mà.", "그 마음이 드는 게 당연하지.": "Con thấy vậy là đương nhiên thôi.", "내가 한다고 했어. 대신 수아한테 {@clock} 봐 달라고 했어.": "Con bảo con sẽ làm. Nhưng con nhờ Sua xem {@clock} giúp.", "몇 분 걸렸어?": "Mất mấy phút?", "처음엔 3분. 수아가 세 문장만 하라고 해서 1분 50초 됐어.": "Lúc đầu là 3 phút. Sua bảo chỉ nói ba câu thôi, thế là còn 1 phút 50 giây.", "수아는 시간 재 주고, 너는 발표하고. 둘이 잘 나눴네.": "Sua bấm giờ, con trình bày. Hai đứa chia việc khéo nhỉ.", "너는 반장이라서 다 하고 싶은 거라고 했어. 수아도 화냈어.": "Con bảo Sua chỉ muốn làm hết vì là lớp trưởng. Sua cũng giận.", "수아는 무슨 마음이었을까?": "Con nghĩ lúc đó Sua cảm thấy thế nào?", "통과되라고 그랬대.": "Bạn ấy bảo làm thế để được thông qua.", "그 말을 듣고 나니까 어때?": "Nghe vậy rồi con thấy sao?", "……좀 미안해. 그래도 내가 할 거야.": "...Con thấy hơi có lỗi. Nhưng con vẫn sẽ làm.", "나눠서 하자고 했어. 시범은 내가, 규칙 설명은 수아가.": "Con bảo chia ra làm. Con làm mẫu, Sua giải thích luật.", "수아도 말로는 못 알아들었잖아. 해 보니까 알았어.": "Sua nghe bằng lời cũng không hiểu mà. Làm thử mới hiểu.", "네가 잘하는 걸로 맡았구나.": "Con nhận phần con giỏi nhỉ.", "학급회의 시간. 두 번째 안건은 내 놀이였다. 나는 앞으로 나가기 전에 수아 자리로 갔다.": "Giờ sinh hoạt lớp. Chủ đề thứ hai là trò chơi của mình. Trước khi lên phía trước, mình đến chỗ Sua.", "준비됐어?": "Sẵn sàng chưa?", "수아가 먼저 앞에 나가 규칙을 설명했다. 그런데 아이들이 웅성거렸다.": "Sua lên trước giải thích luật. Nhưng các bạn xì xào.", "아이들: 「잘 모르겠어.」 「만든 사람이 보여 줘!」": "Các bạn: \"Tớ không hiểu lắm.\" \"Người nghĩ ra làm mẫu đi!\"", "수아가 나를 봤다.": "Sua nhìn mình.", "……네가 나와.": "...Cậu lên đi.", "내가 앞에 나갔다. 수아는 맨 앞자리에서 {@clock}를 보고 있었다.": "Mình lên phía trước. Sua ngồi bàn đầu, nhìn {@clock}.", "수아가 규칙을 말하고, 나는 시범을 보이려고 앞에 섰다.": "Sua nói luật, còn mình đứng lên phía trước để làm mẫu.", "나는 {@blackboard} 앞에 섰다. 아이들 얼굴이 한꺼번에 보였다.": "Mình đứng trước {@blackboard}. Gương mặt các bạn hiện ra cùng lúc.", "동그랗게 앉아요. 술래가 {@handkerchief}을 뒤에 놓아요.": "Mọi người ngồi thành vòng tròn nhé. Người làm cái đặt {@handkerchief} sau lưng.", "{@hand}을 든 아이가 있었다.": "Có một bạn đang giơ {@hand}.", "「{x}」 든 친구 가리키기": "Chỉ vào bạn đang giơ 「{x}」", "아이: 「근데 잡히면 어떻게 돼? 술래 되는 거야?」": "Một bạn: \"Mà bị bắt thì sao? Thành người làm cái à?\"", "아니요. 잡히면…… 잡히면…….": "Không. Bị bắt thì... bị bắt thì...", "머릿속이 하얘졌다. 우리 말로는 바로 떠오르는데, 한국말이 생각나지 않았다.": "Đầu óc mình trống rỗng. Bằng tiếng nước mình thì nghĩ ra ngay, nhưng tiếng Hàn thì không nhớ ra.", "(같은…… 뭐였지? 어제 수아가 말했는데.)": "(Cùng... là gì nhỉ? Hôm qua Sua nói rồi mà.)", "몇몇이 고개를 갸웃했다. 누군가 작게 킥 웃었다. 수아가 맨 앞에서 나를 보고 있었다.": "Vài bạn nghiêng đầu. Ai đó khẽ cười khúc khích. Sua ngồi bàn đầu nhìn mình.", "선생님: 「재미있겠네요. 다음 체육 시간에 한번 해 봅시다.」": "Cô giáo: \"Nghe vui đấy. Giờ thể dục tới mình chơi thử nhé.\"", "아이들이 손뼉을 쳤다. 나는 자리로 돌아오면서 다리에 힘이 풀렸다.": "Các bạn vỗ tay. Mình đi về chỗ, chân bủn rủn.", "학급회의가 끝나고 수아가 내 자리로 왔다.": "Buổi sinh hoạt lớp kết thúc, Sua đến chỗ mình.", "통과됐네.": "Được thông qua rồi nhỉ.", "이상하다. 나는 떨어질까 봐 내가 하겠다고 한 건데.": "Lạ thật. Tớ đã bảo để tớ làm vì sợ bị loại.", "……너 이제 진짜 경쟁자 같다.": "...Giờ cậu trông như đối thủ thật rồi đấy.", "원래 경쟁자였잖아.": "Vốn là đối thủ mà.", "아니. 오늘부터 진짜.": "Không. Từ hôm nay mới là thật.", "수아에게 눈짓해서 대신 말해 달라고 한다.": "Ra hiệu bằng mắt để Sua nói giúp.", "나는 수아를 봤다. 수아가 바로 알아듣고 일어났다.": "Mình nhìn Sua. Sua hiểu ngay và đứng dậy.", "잡히면 잡은 사람 같은 편이 돼요.": "Bị bắt thì thành cùng đội với người bắt.", "아이: 「아, 그렇구나.」": "Một bạn: \"À, ra vậy.\"", "아이들이 고개를 끄덕였다. 나는 그다음 말을 이어 갔다.": "Các bạn gật đầu. Mình nói tiếp phần sau.", "(넘어갔어. 근데…… 내 발표였는데.)": "(Qua được rồi. Nhưng... đây là phần trình bày của mình mà.)", "말 대신 몸으로 보여 준다.": "Làm mẫu bằng cơ thể thay cho lời nói.", "잠깐만요. 보여 줄게요.": "Chờ chút. Tớ làm mẫu nhé.", "나는 질문한 아이에게 다가가 {@hand}을 잡았다. 그리고 그 아이를 데리고 내 옆으로 와서 나란히 섰다.": "Mình đến gần bạn vừa hỏi và nắm {@hand} bạn ấy. Rồi dẫn bạn ấy đến đứng cạnh mình.", "잡히면, 이렇게. 나랑 같이.": "Bị bắt thì thế này. Cùng với tớ.", "아이: 「아! 같은 편!」": "Một bạn: \"À! Cùng đội!\"", "네! 같은 편!": "Đúng! Cùng đội!", "몇 명이 신이 나서 「같은 편!」 하고 따라 했다. 교실이 웃음으로 시끌시끌해졌다. 이번 웃음은 나를 향한 게 아니었다.": "Mấy bạn hào hứng nói theo \"Cùng đội!\". Lớp học rộn tiếng cười. Lần này tiếng cười không phải nhắm vào mình.", "솔직하게 말하고 반 친구들에게 묻는다.": "Nói thật lòng rồi hỏi các bạn trong lớp.", "그 말이 한국말로 생각이 안 나요.": "Từ đó tớ không nhớ ra bằng tiếng Hàn.", "우리 말로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "Bằng tiếng nước tớ thì nghĩ ra ngay. Bị bắt thì thành một đội với người bắt. Cái này tiếng Hàn nói thế nào?", "아이들: 「같은 편!」": "Các bạn: \"Cùng đội!\"", "맞아요! 같은 편이 돼요.": "Đúng rồi! Thành cùng đội.", "아이: 「너네 나라 말로는 뭔데? 다시 해 봐!」": "Một bạn: \"Tiếng nước cậu nói thế nào? Nói lại đi!\"", "아이들이 내 나라 말을 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "Các bạn nói theo tiếng nước mình. Phát âm lung tung hết. Cả lớp cười ồ. Mình cũng cười theo.", "그 부분은 건너뛰고 「아무튼 재밌어요!」 하고 끝낸다.": "Bỏ qua chỗ đó và kết thúc bằng \"Dù sao cũng vui lắm!\"", "그건…… 해 보면 알아요. 아무튼 재밌어요!": "Cái đó thì... chơi thử là biết. Dù sao cũng vui lắm!", "아이들이 서로 얼굴을 봤다.": "Các bạn nhìn nhau.", "아이: 「잡히면 어떻게 되는지 모르는데?」": "Một bạn: \"Không biết bị bắt thì thế nào mà?\"", "수아가 {@hand}을 들고 일어나 대신 설명했다. 아이들이 그제야 고개를 끄덕였다.": "Sua giơ {@hand} đứng dậy giải thích thay. Lúc đó các bạn mới gật đầu.", "(빨리 끝내고 싶었는데, 오히려 더 길어졌어.)": "(Mình muốn kết thúc nhanh, ai ngờ lại càng dài hơn.)", "{m}! 우리 나라 놀이 통과됐어!": "{m} ơi! Trò chơi của nước mình được thông qua rồi!", "정말? 잘됐다!": "Thật à? Hay quá!", "근데 발표하다가 ‘같은 편’이 한국말로 생각이 안 났어. 머리가 하얘졌어.": "Nhưng đang trình bày thì con không nhớ ra ‘cùng đội’ bằng tiếng Hàn. Đầu con trống rỗng.", "수아한테 눈짓했더니 수아가 대신 말해 줬어.": "Con ra hiệu bằng mắt, thế là Sua nói giúp con.", "수아가 바로 알아챘구나.": "Sua nhận ra ngay nhỉ.", "응. 근데 좀 아쉬워. 내 발표였는데.": "Vâng. Nhưng con hơi tiếc. Đó là phần trình bày của con mà.", "그래도 끝까지 서 있었잖아. 다음엔 네 방법도 하나 준비해 가 볼까?": "Nhưng con vẫn đứng đến cuối mà. Lần sau thử chuẩn bị thêm một cách của riêng con nhé?", "말 대신 보여 줬어. 질문한 애 {@hand} 잡고 내 옆에 세웠더니, 걔가 같은 편! 그랬어.": "Con làm mẫu thay cho lời nói. Con nắm {@hand} bạn vừa hỏi, cho đứng cạnh con, thế là bạn ấy nói, cùng đội!", "말이 막혔는데 몸으로 했구나.": "Bí lời thì dùng cơ thể nhỉ.", "애들이 다 같은 편! 하고 따라 했어. 웃었는데 기분 나쁘지 않았어.": "Các bạn đều nói theo, cùng đội! Mọi người cười nhưng con không thấy khó chịu.", "같이 웃은 거니까.": "Vì là cùng cười với nhau mà.", "한국말이 생각 안 난다고 솔직하게 말했어. 우리 말로 하고, 한국말로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "Con nói thật là không nhớ ra tiếng Hàn. Con nói bằng tiếng nước mình rồi hỏi tiếng Hàn là gì, thế là các bạn cùng chỉ cho con.", "반 친구들 앞에서 그걸 물었어?": "Con hỏi điều đó trước cả lớp à?", "응. 애들이 우리 말도 따라 했어. 발음이 엉망이었어.": "Vâng. Các bạn còn nói theo tiếng nước mình. Phát âm lung tung hết.", "너한테 한국말 배우고, 너한테 우리 말 배우고.": "Con học tiếng Hàn từ các bạn, các bạn học tiếng nước mình từ con.", "그냥 해 보면 안다고 하고 넘어가려고 했어. 근데 애들이 모르겠다고 해서 수아가 설명했어.": "Con định bảo cứ chơi thử là biết rồi cho qua. Nhưng các bạn bảo không hiểu nên Sua giải thích.", "빨리 끝내고 싶었구나.": "Con muốn kết thúc nhanh nhỉ.", "응. 근데 더 길어졌어.": "Vâng. Nhưng lại càng dài hơn.", "다음엔 모르는 말 하나쯤은 물어봐도 괜찮아.": "Lần sau hỏi một từ mình không biết cũng không sao đâu.", "그리고 수아가 나보고 오늘부터 진짜 경쟁자래.": "Còn nữa, Sua bảo từ hôm nay con mới là đối thủ thật.", "와. 반장한테 그런 말 들었어?": "Oa. Lớp trưởng nói thế với con à?", "응. 좀 좋았어.": "Vâng. Con thấy hơi vui.", "체육 시간. 드디어 같은 편 {@handkerchief} 놀이를 하는 날이었다. 반 전체가 운동장에 동그랗게 앉았다.": "Giờ thể dục. Cuối cùng cũng đến ngày chơi trò {@handkerchief} Cùng Đội. Cả lớp ngồi thành vòng tròn trên sân.", "처음 5분은 좋았다. 그런데 곧 이상해졌다.": "5 phút đầu thì vui. Nhưng chẳng mấy chốc mọi thứ trở nên kỳ lạ.", "아이: 「나 잡혔는데 그냥 계속 도망갈래!」": "Một bạn: \"Tớ bị bắt rồi nhưng tớ cứ chạy tiếp đây!\"", "아이: 「반칙이야! 잡히면 같은 편이랬잖아!」": "Một bạn: \"Ăn gian! Đã bảo bị bắt là cùng đội mà!\"", "아이: 「같은 편 되면 뭐 해? 그다음엔?」": "Một bạn: \"Cùng đội rồi thì làm gì? Rồi sau đó?\"", "잡힌 아이들이 어디로 가야 할지 몰라 우왕좌왕했다. 원이 흐트러지고, 여기저기서 말다툼이 났다. {@handkerchief}이 바닥에 떨어져 있었다.": "Các bạn bị bắt không biết đi đâu nên chạy lung tung. Vòng tròn rối loạn, chỗ này chỗ kia cãi nhau. {@handkerchief} rơi trên mặt đất.", "나는 수아에게 갔다. 수아는 팔짱을 끼고 서 있었다.": "Mình đi đến chỗ Sua. Sua đang khoanh tay đứng.", "이거 안 되겠다. 그냥 피구 하자.": "Thế này không được rồi. Chơi bóng né đi.", "잠깐만…….": "Chờ chút...", "솔직히 말할게. 네 놀이 지금 엉망이야.": "Tớ nói thật nhé. Trò chơi của cậu bây giờ rối tung rồi.", "(수아 말이 맞아. 엉망이야.)": "(Sua nói đúng. Rối tung thật.)", "(근데 이건 내가 하자고 한 놀이야.)": "(Nhưng đây là trò chơi mình đề nghị.)", "체육 시간이 끝났다. 수아가 내 옆으로 왔다.": "Giờ thể dục kết thúc. Sua đến bên cạnh mình.", "정리하면, 반은 성공.": "Tóm lại là, thành công một nửa.", "반이나?": "Tận một nửa á?", "처음엔 영이었잖아.": "Lúc đầu là không mà.", "다음에 고쳐서 다시 해 보든가.": "Lần sau sửa rồi chơi lại xem sao.", "「1분만. 규칙 하나만 바꿔 볼게.」": "\"Một phút thôi. Tớ đổi thử một luật.\"", "1분만 줘. 규칙 하나만 바꿔 볼게.": "Cho tớ một phút. Tớ đổi thử một luật.", "……1분.": "...Một phút.", "나는 {@handkerchief}을 들고 원 가운데 섰다.": "Mình cầm {@handkerchief} đứng giữa vòng tròn.", "잡히면, 잡은 사람 {@hand}을 잡아요. {@hand} 잡고 같이 다녀요!": "Bị bắt thì nắm {@hand} người bắt. Nắm {@hand} rồi đi cùng nhau!", "아이: 「{@hand} 잡고?」": "Một bạn: \"Nắm {@hand} á?\"", "응. 그럼 누가 같은 편인지 보여요.": "Ừ. Thế thì sẽ thấy ai cùng đội.", "다시 시작했다. 잡힌 아이들이 {@hand}을 잡고 줄줄이 달렸다. 기차처럼 길어졌다. 아이들이 깔깔 웃었다.": "Bắt đầu lại. Các bạn bị bắt nắm {@hand} nhau chạy thành hàng. Dài ra như đoàn tàu. Các bạn cười khanh khách.", "「애들이 규칙을 안 지켜서 그래.」": "\"Tại các bạn không giữ luật đấy.\"", "애들이 규칙을 안 지켜서 그래. 내 놀이가 문제가 아니야.": "Tại các bạn không giữ luật đấy. Trò chơi của tớ không có vấn đề gì.", "규칙이 헷갈리면 안 지키게 되는 거야.": "Luật mà khó hiểu thì người ta sẽ không giữ.", "…….": "...", "그사이 아이들은 하나둘 피구공을 가지러 갔다.": "Trong lúc đó, từng bạn một đi lấy bóng né.", "(남 탓을 했는데, 놀이는 그대로 끝났어.)": "(Mình đổ lỗi cho người khác, còn trò chơi thì cứ thế kết thúc.)", "「……그래. 그만하자.」": "\"...Ừ. Thôi dừng lại.\"", "……그래. 그만하자.": "...Ừ. Thôi dừng lại.", "피구 할 사람!": "Ai chơi bóng né nào!", "아이들이 우르르 수아 쪽으로 갔다. 나는 {@handkerchief}을 주머니에 넣었다.": "Các bạn ùa về phía Sua. Mình cất {@handkerchief} vào túi.", "(그냥 끝나 버렸어.)": "(Thế là kết thúc luôn.)", "아이들에게 직접 묻는다. 「어디가 헷갈렸어?」": "Hỏi thẳng các bạn. \"Chỗ nào khó hiểu?\"", "얘들아, 잠깐! 어디가 헷갈렸어?": "Các bạn ơi, chờ chút! Chỗ nào khó hiểu?", "아이: 「잡히고 나서 뭘 해야 할지 모르겠어.」": "Một bạn: \"Bị bắt rồi tớ không biết phải làm gì.\"", "아이: 「누가 같은 편인지도 모르겠고.」": "Một bạn: \"Cũng không biết ai cùng đội nữa.\"", "그럼 잡힌 사람은 모자를 벗자! 모자 벗은 사람끼리 같은 편.": "Vậy người bị bắt thì cởi mũ ra! Những người cởi mũ là cùng đội.", "아이: 「오, 그거 알겠다.」": "Một bạn: \"Ồ, cái đó thì hiểu.\"", "다시 시작했다. 모자 벗은 아이들이 한 무리가 되어 함께 술래를 쫓았다. 이번엔 다툼이 줄었다.": "Bắt đầu lại. Các bạn cởi mũ thành một nhóm, cùng đuổi người làm cái. Lần này ít cãi nhau hơn.", "{m}, 오늘 체육 시간에 우리 나라 놀이 했어.": "{m} ơi, hôm nay giờ thể dục con chơi trò của nước mình.", "드디어! 재밌었어?": "Cuối cùng cũng chơi! Có vui không?", "처음엔. 근데 애들이 잡히고 나서 뭘 해야 할지 몰라서 엉망이 됐어. 수아가 솔직히 엉망이래.": "Lúc đầu thì vui. Nhưng các bạn bị bắt rồi không biết phải làm gì nên rối tung. Sua bảo thật lòng là rối tung.", "아이고.": "Ôi trời.", "1분만 달라고 하고, 잡히면 {@hand} 잡고 다니자고 바꿨어. 기차처럼 길어졌어!": "Con xin một phút, đổi thành bị bắt thì nắm {@hand} đi cùng nhau. Dài ra như đoàn tàu!", "{@hand} 잡고 줄줄이?": "Nắm {@hand} thành hàng à?", "응. 애들이 엄청 웃었어. 수아가 반은 성공이래.": "Vâng. Các bạn cười nhiều lắm. Sua bảo thành công một nửa.", "애들이 규칙을 안 지켜서 그렇다고 했는데, 수아가 헷갈리면 안 지키게 된대.": "Con bảo tại các bạn không giữ luật, nhưng Sua bảo luật khó hiểu thì người ta sẽ không giữ.", "수아 말도 일리가 있네.": "Sua nói cũng có lý đấy.", "응. 그러는 사이에 다들 피구 하러 갔어.": "Vâng. Trong lúc đó mọi người đi chơi bóng né hết.", "그냥 그만하자고 했어. 다들 피구 하러 갔어.": "Con bảo thôi dừng lại. Mọi người đi chơi bóng né hết.", "많이 실망했겠다.": "Chắc con thất vọng lắm.", "응. {@handkerchief}만 주머니에 있어.": "Vâng. Chỉ còn {@handkerchief} trong túi thôi.", "고쳐서 다시 해 볼 수도 있잖아. 어디가 문제였는지는 알 것 같아?": "Con có thể sửa rồi chơi lại mà. Con có biết chỗ nào có vấn đề không?", "애들한테 어디가 헷갈렸냐고 물어봤어. 그래서 잡히면 모자 벗기로 했어.": "Con hỏi các bạn chỗ nào khó hiểu. Nên quyết định bị bắt thì cởi mũ.", "애들 말 듣고 바로 고쳤구나.": "Con nghe các bạn rồi sửa ngay nhỉ.", "응. 다툼이 줄었어.": "Vâng. Ít cãi nhau hơn.", "방과 후. 수아가 교실에 남아 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "Sau giờ học. Sua ở lại lớp viết lời hứa tranh cử. Mình cũng cầm cây {@pencil} đang viết lời hứa đi về phía Sua.", "「{x}」 내려놓기": "Đặt 「{x}」 xuống", "수아의 공약 {@paper}: 「공약 1. 전학 온 친구를 위한 {@picture} 규칙표를 모든 반에 붙이겠습니다.」": "{@paper} lời hứa của Sua: \"Lời hứa 1. Tôi sẽ dán bảng quy tắc bằng {@picture} dành cho bạn mới chuyển đến ở tất cả các lớp.\"", "나는 그대로 굳었다. 내 {w} 첫 줄에도 거의 같은 말이 쓰여 있었다.": "Mình đứng sững lại. Dòng đầu tiên trong {w} của mình cũng viết gần như y hệt.", "이거 좋지? 우리가 만든 규칙표, 반응 좋았잖아.": "Cái này hay đúng không? Bảng quy tắc bọn mình làm, các bạn thích lắm mà.", "……나도 이거 1번으로 썼는데.": "...Tớ cũng viết cái này là số 1.", "어? 진짜?": "Ơ? Thật à?", "같이 만든 거니까 나도 써도 되는 줄 알았지.": "Vì cùng làm với nhau nên tớ tưởng tớ cũng dùng được.", "({@picture}은 내가 그렸어. 근데 처음 하자고 한 건 수아야.)": "({@picture} là mình vẽ. Nhưng người đề nghị làm trước là Sua.)", "(둘 다 쓰면…… 애들은 누가 만든 걸로 생각할까?)": "(Nếu cả hai cùng viết... các bạn sẽ nghĩ ai làm ra nhỉ?)", "집에 가는 길. 나는 내 {w}을 다시 펴 봤다.": "Trên đường về nhà. Mình mở {w} của mình ra xem lại.", "(내 공약은…… 뭐가 나다운 걸까?)": "(Lời hứa của mình... cái gì mới thật sự là mình nhỉ?)", "서운한 걸 직접 말하고, 같이 정하자고 한다.": "Nói thẳng nỗi buồn và đề nghị cùng quyết định.", "솔직히 좀 서운해. {@picture}은 내가 그렸는데, 네 공약에만 있으면 네가 다 한 것 같잖아.": "Nói thật là tớ hơi buồn. {@picture} là tớ vẽ, mà chỉ có trong lời hứa của cậu thì giống như cậu làm hết vậy.", "……그렇게 보일 수도 있겠다.": "...Có thể trông như thế thật.", "그러니까 정하자. 둘 다 쓰든지, 하나만 쓰든지.": "Vậy mình quyết định đi. Hoặc cả hai cùng viết, hoặc chỉ một người viết.", "둘 다 쓰자. 대신 ‘같이 만든’이라고 넣어.": "Cả hai cùng viết. Nhưng thêm chữ ‘cùng làm’ vào.", "그다음엔 누가 더 잘 지킬지 애들이 정하겠지.": "Sau đó thì các bạn sẽ quyết định ai giữ lời tốt hơn.", "수아가 공약 {@paper}에 내 이름을 넣어 ‘같이 만든’이라고 고쳐 썼다.": "Sua thêm tên mình vào {@paper} lời hứa, sửa lại thành ‘cùng làm’.", "다른 애들한테 「수아가 내 아이디어 가져갔어.」라고 말한다.": "Nói với các bạn khác: \"Sua lấy ý tưởng của tớ.\"", "다음 날, 나는 친한 친구에게 작게 말했다.": "Hôm sau, mình khẽ nói với một bạn thân.", "수아가 내 아이디어 가져갔어.": "Sua lấy ý tưởng của tớ.", "그 말은 점심시간 전에 반 전체로 퍼졌다. 수아가 굳은 얼굴로 나를 찾아왔다.": "Lời đó lan ra cả lớp trước giờ ăn trưa. Sua mặt lạnh tanh đến tìm mình.", "나한테 먼저 말하지 그랬어.": "Sao cậu không nói với tớ trước?", "나는 같이 만든 거라서 쓴 거야.": "Tớ viết vì đó là thứ bọn mình cùng làm.", "그건 수아에게 두고, 나만 할 수 있는 다른 공약을 쓴다.": "Để cái đó cho Sua, rồi viết một lời hứa khác mà chỉ mình làm được.", "그거 너 써. 나는 다른 거 쓸래.": "Cái đó cậu viết đi. Tớ sẽ viết cái khác.", "진짜? 너도 같이 만든 건데.": "Thật á? Cậu cũng cùng làm mà.", "응. 나한테는 다른 게 있어.": "Ừ. Tớ có cái khác.", "나는 {w} 첫 줄을 지우고 새로 썼다.": "Mình xóa dòng đầu trong {w} và viết lại.", "내 {w}: 「공약 1. 모르는 말을 물어봐도 괜찮은 반을 만들겠습니다. ‘천천히 말해 줘’ 카드를 만들겠습니다.」": "{w} của mình: \"Lời hứa 1. Tôi sẽ tạo một lớp học nơi hỏi từ mình không biết cũng không sao. Tôi sẽ làm thẻ ‘Nói chậm giúp tớ nhé’.\"", "……그거 나보다 네가 잘하는 거네.": "...Cái đó cậu giỏi hơn tớ nhỉ.", "응. 대피 훈련 때 그거 필요했거든.": "Ừ. Lúc diễn tập sơ tán tớ đã cần cái đó.", "아무 말 안 하고 혼자 서운해한다.": "Không nói gì, một mình buồn.", "……아니야. 써.": "...Không sao. Cậu viết đi.", "그래? 고마워!": "Thế à? Cảm ơn nhé!", "수아는 신나서 공약 {@paper}를 다시 정리했다. 나는 {w}을 덮었다.": "Sua hào hứng sắp xếp lại {@paper} lời hứa. Mình gấp {w} lại.", "(괜찮다고 했는데, 하나도 안 괜찮아.)": "(Mình bảo không sao, nhưng chẳng ổn chút nào.)", "{m}, 수아 공약 1번이 내 공약 1번이랑 똑같았어. 우리 둘이 만든 {@picture} 규칙표.": "{m} ơi, lời hứa số 1 của Sua giống hệt lời hứa số 1 của con. Bảng quy tắc bằng {@picture} hai đứa con cùng làm.", "어머. 둘이 같이 만든 거?": "Ôi. Cái hai đứa cùng làm à?", "응. 수아는 같이 만든 거니까 써도 되는 줄 알았대.": "Vâng. Sua bảo vì cùng làm nên bạn ấy tưởng dùng được.", "서운하다고 말했어. 그래서 둘 다 쓰고 ‘같이 만든’이라고 넣기로 했어.": "Con nói là con buồn. Nên hai đứa quyết định cùng viết và thêm chữ ‘cùng làm’.", "좋은 방법이네. 수아는 어땠어?": "Cách hay đấy. Sua thì sao?", "누가 더 잘 지킬지는 애들이 정할 거래.": "Bạn ấy bảo các bạn sẽ quyết định ai giữ lời tốt hơn.", "역시 경쟁자다.": "Đúng là đối thủ.", "친구한테 수아가 내 거 가져갔다고 했는데, 반 전체에 퍼졌어.": "Con bảo với một bạn là Sua lấy của con, thế là lan ra cả lớp.", "아이고. 수아는?": "Ôi trời. Sua thì sao?", "나한테 먼저 말하지 그랬냐고 했어.": "Bạn ấy hỏi sao con không nói với bạn ấy trước.", "수아 말이 맞네. 다음엔 수아한테 먼저 말해 보자.": "Sua nói đúng đấy. Lần sau thử nói với Sua trước nhé.", "그건 수아 쓰라고 하고, 나는 다른 공약 썼어. 모르는 말 물어봐도 괜찮은 반.": "Con để cái đó cho Sua viết, còn con viết lời hứa khác. Một lớp học nơi hỏi từ không biết cũng không sao.", "그거 너한테 딱이다.": "Cái đó hợp với con lắm.", "수아도 그거 나보다 네가 잘하는 거래.": "Sua cũng bảo cái đó con giỏi hơn bạn ấy.", "괜찮다고 했어. 근데 안 괜찮아.": "Con bảo không sao. Nhưng không ổn chút nào.", "속으로만 서운했구나.": "Con chỉ buồn trong lòng thôi nhỉ.", "응. 말하면 싸울 것 같아서.": "Vâng. Vì con sợ nói ra sẽ cãi nhau.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 내일 말해 봐도 늦지 않아.": "Nói là mình buồn và cãi nhau là hai chuyện khác nhau. Mai nói cũng chưa muộn đâu.", "쉬는 시간. 수아가 교실을 뛰어다니고 있었다. 오늘 종례까지 체험학습 신청서를 다 걷어야 한다고 했다.": "Giờ giải lao. Sua đang chạy khắp lớp. Cậu ấy nói phải thu hết đơn đăng ký đi trải nghiệm trước giờ sinh hoạt cuối ngày hôm nay.", "나는 수아 {@desk}으로 갔다. {@desk} 위에 신청서 {@box}가 있었다.": "Mình đến {@desk} của Sua. Trên {@desk} có {@box} đựng đơn đăng ký.", "{@box} 안에 신청서가 보였다. 아직 반도 안 찼다.": "Trong {@box} có mấy tờ đơn. Còn chưa được một nửa.", "여덟 명 남았어. 종례까지.": "Còn tám người. Trước giờ sinh hoạt cuối ngày.", "도와줄까?": "Tớ giúp nhé?", "아니, 괜찮아. 반장 일이야.": "Không, không sao. Việc của lớp trưởng mà.", "수아가 다시 뛰어갔다. 그때 같은 모둠 친구가 내 옆으로 와서 작게 말했다.": "Sua lại chạy đi. Lúc đó, một bạn cùng nhóm đến bên cạnh mình nói nhỏ.", "친구: 「야, 그냥 내버려 둬. 수아가 실수하면 너한테 좋은 거잖아. 선거 나간다며.」": "Bạn: \"Này, cứ kệ đi. Sua mà sai thì tốt cho cậu còn gì. Cậu ra tranh cử mà.\"", "(……그런가?)": "(...Vậy sao?)", "그때 뒷자리 친구가 신청서를 들고 멍하니 앉아 있는 게 보였다. 신청서를 뒤집었다 폈다 하고 있었다.": "Lúc đó mình thấy bạn ngồi bàn sau đang cầm đơn ngồi ngẩn ra. Bạn ấy cứ lật đơn qua lại.", "(저거…… 대피 훈련 때 나 같은 얼굴이다.)": "(Kia... là khuôn mặt giống mình lúc diễn tập sơ tán.)", "종례가 끝났다. 수아가 {@box}를 정리하며 나를 봤다.": "Giờ sinh hoạt cuối ngày kết thúc. Sua vừa sắp xếp {@box} vừa nhìn mình.", "……‘회신’을 모르는 애가 있을 줄은 몰랐어.": "...Tớ không ngờ có bạn không biết từ ‘hồi đáp’.", "나도 몰랐었어.": "Tớ cũng từng không biết.", "그러니까 네가 알았겠지.": "Thế nên cậu mới nhận ra.", "한 장 내일 받으면 돼. 괜찮아.": "Một tờ thì mai nhận cũng được. Không sao.", "수아는 괜찮다고 했지만, 형광펜을 꽉 쥐고 있었다.": "Sua bảo không sao, nhưng tay cậu ấy nắm chặt cây bút dạ quang.", "친구 말대로 모른 척한다.": "Làm như không biết, theo lời bạn.", "나는 내 자리로 돌아갔다. 수아는 종례 직전까지 뛰어다녔다.": "Mình quay về chỗ. Sua chạy khắp nơi đến tận trước giờ sinh hoạt cuối ngày.", "종례 시간. 수아가 선생님께 {@box}를 내밀었다.": "Giờ sinh hoạt cuối ngày. Sua đưa {@box} cho cô giáo.", "……한 장 빠졌어요.": "...Thiếu một tờ ạ.", "(내가 이긴 것 같지가 않아.)": "(Mình chẳng thấy như mình thắng.)", "「내가 뒤쪽 줄만 걷을게. 싫으면 말해.」": "\"Tớ thu dãy sau thôi. Không muốn thì cứ nói.\"", "수아야. 내가 뒤쪽 줄만 걷을게. 싫으면 말해.": "Sua ơi. Tớ thu dãy sau thôi. Không muốn thì cứ nói.", "괜찮다니까, 내가…….": "Đã bảo không sao mà, tớ...", "뒤쪽 줄만이야.": "Chỉ dãy sau thôi.", "수아가 잠깐 멈췄다. 숨을 한 번 크게 쉬었다.": "Sua khựng lại một chút. Cậu ấy hít một hơi thật sâu.", "……그럼 뒤쪽만.": "...Vậy chỉ dãy sau thôi.", "나는 뒤쪽 줄을 돌았다. 뒷자리 친구는 ‘회신’이라는 말을 몰라서 못 낸 거였다. 나는 {@picture}으로 설명해 줬다.": "Mình đi quanh dãy sau. Bạn bàn sau không nộp được vì không biết từ ‘hồi đáp’. Mình giải thích bằng {@picture}.", "뒷자리 친구: 「아, 이름 쓰고 다시 내는 거구나!」": "Bạn bàn sau: \"À, là viết tên rồi nộp lại à!\"", "도와준다고 했다가 거절당하자 「그래, 혼자 해.」 하고 돌아선다.": "Bảo giúp mà bị từ chối thì nói \"Ừ, tự làm đi.\" rồi quay đi.", "진짜 도와줄게.": "Tớ giúp thật mà.", "괜찮다고 했잖아!": "Đã bảo không sao rồi mà!", "……그래, 혼자 해.": "...Ừ, tự làm đi.", "나는 자리로 돌아갔다. 수아도 나도 기분이 상했다.": "Mình về chỗ. Cả Sua và mình đều không vui.", "종례 시간. 한 장이 빠졌다.": "Giờ sinh hoạt cuối ngày. Thiếu một tờ.", "뒷자리 친구에게 가서 신청서를 같이 본다.": "Đến chỗ bạn bàn sau và cùng xem đơn.", "나는 수아를 쫓아가는 대신 뒷자리 친구에게 갔다.": "Thay vì đuổi theo Sua, mình đến chỗ bạn bàn sau.", "이거 모르는 말 있어?": "Ở đây có từ nào cậu không biết không?", "뒷자리 친구: 「……‘회신’이 뭐야?」": "Bạn bàn sau: \"...‘Hồi đáp’ là gì?\"", "나도 처음에 몰랐어. 이름 쓰고, 부모님 사인 받고, 다시 내는 거야.": "Lúc đầu tớ cũng không biết. Là viết tên, xin chữ ký bố mẹ, rồi nộp lại.", "나는 {w} 귀퉁이에 순서를 {@picture}으로 그려 줬다. 친구가 이름을 쓰고 신청서를 {@box}에 넣었다.": "Mình vẽ {@picture} các bước ở góc {w}. Bạn ấy viết tên rồi bỏ đơn vào {@box}.", "수아가 돌아와 {@box}를 보고 눈을 크게 떴다.": "Sua quay lại, nhìn {@box} rồi tròn mắt.", "어? 이거 언제 냈어?": "Ơ? Cái này nộp lúc nào thế?", "뒷자리 친구: 「방금. 쟤가 알려 줬어.」": "Bạn bàn sau: \"Vừa xong. Bạn ấy chỉ cho tớ.\"", "{m}, 수아가 오늘 종례까지 신청서 다 걷어야 해서 엄청 바빴어.": "{m} ơi, hôm nay Sua phải thu hết đơn đăng ký trước giờ sinh hoạt cuối ngày nên bận lắm.", "반장 일이 많구나.": "Việc của lớp trưởng nhiều nhỉ.", "응. 근데 친구가 수아 내버려 두래. 수아가 실수하면 나한테 좋다고.": "Vâng. Nhưng có bạn bảo con cứ kệ Sua. Sua mà sai thì tốt cho con.", "그냥 내 자리에 있었어. 결국 한 장 빠졌어.": "Con cứ ngồi ở chỗ mình. Cuối cùng thiếu một tờ.", "그러고 나서 기분이 어땠어?": "Rồi sau đó con thấy thế nào?", "이긴 것 같지 않았어.": "Con không thấy như mình thắng.", "그렇구나.": "Ra vậy.", "뒤쪽 줄만 걷겠다고 했어. 수아가 처음엔 괜찮다고 했는데 결국 그러라고 했어.": "Con bảo con sẽ thu dãy sau. Lúc đầu Sua bảo không sao, nhưng cuối cùng cũng đồng ý.", "수아가 도움을 받았네.": "Sua đã nhận sự giúp đỡ nhỉ.", "응. 그리고 뒷자리 애가 ‘회신’을 몰라서 못 낸 거였어. {@picture}으로 알려 줬어.": "Vâng. Còn bạn bàn sau không nộp được vì không biết từ ‘hồi đáp’. Con chỉ bằng {@picture}.", "네가 아니었으면 몰랐겠다.": "Không có con thì chắc chẳng ai biết.", "도와준다고 했는데 수아가 괜찮다고 화내서, 그럼 혼자 하라고 했어.": "Con bảo sẽ giúp nhưng Sua giận, bảo không sao, nên con bảo vậy thì tự làm đi.", "둘 다 기분 상했겠다.": "Chắc cả hai đều không vui.", "응. 그리고 한 장 빠졌어.": "Vâng. Rồi thiếu một tờ.", "수아는 왜 계속 괜찮다고 했을까?": "Con nghĩ sao Sua cứ nói không sao mãi?", "……반장 일이라서?": "...Vì là việc của lớp trưởng ạ?", "뒷자리 애가 신청서를 뒤집었다 폈다 하고 있었어. 대피 훈련 때 나 같아서 가 봤어.": "Bạn bàn sau cứ lật đơn qua lại. Giống con lúc diễn tập sơ tán nên con đến xem.", "무슨 일이었어?": "Có chuyện gì thế?", "‘회신’을 몰랐대. 나도 처음엔 몰랐잖아. {@picture}으로 알려 줬어.": "Bạn ấy không biết từ ‘hồi đáp’. Lúc đầu con cũng không biết mà. Con chỉ bằng {@picture}.", "네가 겪어 봐서 알아본 거네.": "Vì con từng trải qua nên con nhận ra nhỉ.", "근데 경쟁자를 도와주는 거, 이상하진 않았어?": "Mà giúp đối thủ, con không thấy lạ à?", "……모르겠어. 그냥 반 일이잖아.": "...Con không biết. Đó là việc của lớp mà.", "오늘은 내 생일이었다. {m}가 새벽부터 우리 나라 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "Hôm nay là sinh nhật mình. {m} đã dậy từ sáng sớm làm món ăn vặt của nước mình rồi cho vào {@bowl}. Để mình chia cho các bạn trong lớp cùng ăn.", "나는 {@bowl}을 안고 수아에게 갔다.": "Mình ôm {@bowl} đến chỗ Sua.", "수아야! 오늘 내 생일이야. 이거 언제 나눠 주면 돼?": "Sua ơi! Hôm nay là sinh nhật tớ. Khi nào tớ chia cái này được?", "「{x}」 뚜껑 열기": "Mở nắp 「{x}」", "{@bowl} 안에 우리 나라 간식이 가득했다.": "Trong {@bowl} đầy món ăn vặt của nước mình.", "와, 생일 축하해! 근데…….": "Oa, chúc mừng sinh nhật! Nhưng mà...", "수아가 {@bowl}을 보더니 표정이 바뀌었다.": "Sua nhìn {@bowl} rồi đổi sắc mặt.", "그거 나눠 주면 안 돼. 규칙 9번. 집에서 만든 음식은 학교에서 나눠 먹지 않기.": "Không chia cái đó được đâu. Quy tắc số 9. Không chia nhau ăn đồ ăn làm ở nhà trong trường.", "……안 돼?": "...Không được à?", "응. 안 돼.": "Ừ. Không được.", "수아는 또 빠르고 짧게 말했다. {@bowl}이 갑자기 무거워졌다.": "Sua lại nói nhanh và ngắn. {@bowl} bỗng nặng trĩu.", "({m}가 새벽부터 만든 건데.)": "({m} đã làm từ sáng sớm mà.)", "(우리 나라에서는 생일에 이걸 나눠 먹는데…….)": "(Ở nước mình, sinh nhật là chia nhau ăn món này mà...)", "종례 시간. 선생님이 내 생일이라고 말씀하셨다. 반 아이들이 생일 노래를 불러 줬다.": "Giờ sinh hoạt cuối ngày. Cô giáo nói hôm nay là sinh nhật mình. Cả lớp hát mừng sinh nhật cho mình.", "수아가 제일 크게 불렀다. 음이 조금 틀렸다.": "Sua hát to nhất. Hơi lạc giọng một chút.", "「우리 나라 음식이라서 싫은 거지?」": "\"Vì là món ăn nước tớ nên cậu không thích, đúng không?\"", "우리 나라 음식이라서 안 된다는 거지?": "Vì là món ăn nước tớ nên mới không được, đúng không?", "아니야! 그런 거 아니야!": "Không phải! Không phải thế đâu!", "수아 얼굴이 빨개졌다.": "Mặt Sua đỏ bừng.", "누가 가져와도 안 되는 거야. 나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "Ai mang đến cũng không được. Sinh nhật năm ngoái tớ cũng mang bánh tteok đến rồi lại phải mang về.", "……아.": "...À.", "우리 둘 다 한동안 말이 없었다.": "Cả hai đứa im lặng một lúc lâu.", "「왜 안 돼?」 하고 이유를 묻는다.": "Hỏi lý do: \"Sao lại không được?\"", "왜 안 돼?": "Sao lại không được?", "음식에 알레르기 있는 애들이 있어. 뭐가 들어갔는지 모르면 위험할 수 있대.": "Có bạn bị dị ứng thức ăn. Nếu không biết bên trong có gì thì có thể nguy hiểm.", "나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "Sinh nhật năm ngoái tớ cũng mang bánh tteok đến rồi lại phải mang về.", "너도?": "Cậu cũng thế à?", "응. 엄청 속상했어.": "Ừ. Buồn lắm luôn.", "(나만 안 되는 게 아니구나.)": "(Hóa ra không phải chỉ mình mình bị cấm.)", "아무 말 없이 {@bowl}을 다시 {@bag}에 넣는다.": "Không nói gì, cất {@bowl} lại vào {@bag}.", "나는 아무 말도 하지 않았다. 뚜껑을 닫고 {@bowl}을 {@bag} 깊숙이 넣었다.": "Mình không nói gì cả. Mình đậy nắp lại rồi nhét {@bowl} vào sâu trong {@bag}.", "……저기.": "...Này.", "나는 대답하지 않고 자리로 갔다. 하루 종일 {@bag}이 무거웠다.": "Mình không trả lời mà về chỗ. Cả ngày hôm đó {@bag} nặng trĩu.", "「그럼 먹는 거 말고, 다른 방법은 돼?」 하고 묻는다.": "Hỏi: \"Vậy không ăn mà làm cách khác thì được không?\"", "그럼 먹는 거 말고 다른 방법은 돼?": "Vậy không ăn, mà làm cách khác thì được không?", "다른 방법?": "Cách khác?", "사진 보여 주면서 우리 나라에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "Cho mọi người xem ảnh và kể là ở nước tớ sinh nhật thì ăn món này. Tớ còn có thể vẽ cách làm thành {@picture} mang đến nữa.", "그건 돼! 음식만 안 되는 거니까.": "Cái đó thì được! Vì chỉ cấm đồ ăn thôi mà.", "수아가 형광펜을 꺼냈다.": "Sua lấy bút dạ quang ra.", "종례 때 1분 줄게. 반장 권한.": "Giờ sinh hoạt cuối ngày tớ cho cậu 1 phút. Quyền của lớp trưởng.", "{m}…… 학교에서 그거 못 나눠 줬어.": "{m}... con không chia món đó ở trường được.", "응? 왜?": "Hả? Sao thế?", "집에서 만든 음식은 학교에서 나눠 먹으면 안 된대. 규칙 9번. 수아가 알려 줬어.": "Đồ ăn làm ở nhà thì không được chia nhau ăn trong trường. Quy tắc số 9. Sua bảo con đấy.", "어머…… {m}가 몰랐네. 새벽부터 만들었는데. 미안해.": "Ôi... {m} không biết. Làm từ sáng sớm thế mà. Xin lỗi con nhé.", "{m}가 왜 미안해.": "Sao {m} lại xin lỗi chứ.", "나 수아한테 우리 나라 음식이라서 싫은 거냐고 했어.": "Con hỏi Sua có phải vì là món ăn nước mình nên bạn ấy không thích không.", "아니래. 수아도 작년에 떡 가져왔다가 못 나눠 줬대.": "Bạn ấy bảo không phải. Năm ngoái Sua cũng mang bánh tteok đến mà không được chia.", "그랬구나. 수아도 놀랐겠다.": "Ra vậy. Chắc Sua cũng bất ngờ lắm.", "……응. 내가 좀 심했어.": "...Vâng. Con hơi quá đáng.", "왜 안 되냐고 물었더니, 알레르기 있는 애들 때문이래. 수아도 작년에 떡 가져갔다가 다시 가져갔대.": "Con hỏi sao lại không được, bạn ấy bảo là vì có bạn bị dị ứng. Năm ngoái Sua cũng mang bánh tteok đến rồi lại mang về.", "다 같이 지키는 규칙이었구나.": "Hóa ra là quy tắc mọi người cùng giữ.", "응. 나만 안 되는 줄 알았어.": "Vâng. Con cứ tưởng chỉ mình con bị cấm.", "그냥 아무 말 안 하고 {@bag}에 넣었어. 하루 종일 {@bag}이 무거웠어.": "Con chẳng nói gì, cứ thế cất vào {@bag}. Cả ngày {@bag} nặng trĩu.", "많이 속상했구나.": "Con buồn lắm nhỉ.", "수아가 뭐라고 하려고 했는데 그냥 갔어.": "Sua định nói gì đó mà con cứ thế đi luôn.", "수아가 무슨 말 하려고 했을까? 내일 물어봐도 되겠다.": "Sua định nói gì nhỉ? Mai con hỏi thử cũng được đấy.", "그럼 사진 보여 주고 만드는 법 {@picture}으로 그려 와도 되냐고 했어. 수아가 종례 때 1분 준대.": "Con hỏi là cho xem ảnh rồi vẽ cách làm thành {@picture} mang đến có được không. Sua bảo sẽ cho con 1 phút vào giờ sinh hoạt cuối ngày.", "어머, 그거 좋다! 그럼 {m}가 사진 찍어 줄게.": "Ôi, hay quá! Vậy {m} sẽ chụp ảnh cho con.", "만드는 법도 알려 줘. {@picture}으로 그릴게.": "Mẹ chỉ con cách làm nữa nhé. Con sẽ vẽ thành {@picture}.", "이건 우리 둘이 먹자. 생일 축하해.": "Cái này hai mẹ con mình ăn nhé. Chúc mừng sinh nhật con.", "응. 그리고 오늘 애들이 생일 노래 불러 줬어. 수아가 제일 크게 불렀어. 음 틀리게.": "Vâng. Với lại hôm nay các bạn hát mừng sinh nhật con. Sua hát to nhất. Lạc giọng nữa.", "반장은 노래도 크게 하는구나.": "Lớp trưởng hát cũng to ghê.", "점심시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "Giờ ăn trưa. Sua đang vội vàng xếp {@bag}. Mình đi đến chỗ Sua.", "마침 잘 왔다.": "Cậu đến đúng lúc lắm.", "옆 반 선생님이 우리 {@picture} 규칙표 보시고, 애들한테 설명해 달래. 근데 나 지금 학생회 회의 가야 해.": "Cô giáo lớp bên xem bảng quy tắc {@picture} của bọn mình rồi, nhờ giải thích cho các bạn lớp đó. Nhưng giờ tớ phải đi họp hội học sinh.", "너 혼자 가 볼래? {@picture}은 네가 그렸잖아.": "Cậu đi một mình thử nhé? {@picture} là cậu vẽ mà.", "(혼자? 옆 반은 아는 애가 하나도 없는데.)": "(Một mình á? Lớp bên mình chẳng quen ai cả.)", "옆 반 앞.": "Trước cửa lớp bên.", "「{x}」 두드리기": "Gõ 「{x}」", "똑똑. 옆 반 {@door}이 열렸다.": "Cốc cốc. {@door} lớp bên mở ra.", "낯선 얼굴 스무 개가 나를 봤다. 다리가 떨렸다. 그래도 {@picture}을 가리켰다.": "Hai mươi gương mặt lạ nhìn mình. Chân mình run run. Nhưng mình vẫn chỉ vào {@picture}.", "이건 규칙 7번이에요. 연기가 나면 몸을 낮추고, 벽을 짚어요.": "Đây là quy tắc số 7 ạ. Khi có khói thì cúi thấp người xuống và vịn vào tường.", "옆 반 아이: 「벽은 왜 짚어요?」": "Bạn lớp bên: \"Sao lại phải vịn tường?\"", "연기 때문에 앞이 안 보여요. 벽을 따라가면 길을 안 잃어요.": "Vì có khói nên không nhìn thấy phía trước. Đi men theo tường thì sẽ không bị lạc đường.", "옆 반 선생님: 「설명 잘하는구나. {@picture}도 네가 그렸니?」": "Cô giáo lớp bên: \"Em giải thích giỏi quá. {@picture} cũng là em vẽ à?\"", "네!": "Vâng ạ!", "회의가 끝나고 둘이 갔을 때는 벌써 수업이 시작되어 있었다.": "Lúc họp xong hai đứa đến nơi thì tiết học đã bắt đầu rồi.", "옆 반 선생님: 「아, 지금은 좀 그렇고…… 내일 다시 와 줄래?」": "Cô giáo lớp bên: \"À, bây giờ thì hơi khó... Mai các em quay lại nhé?\"", "수아가 나를 힐끗 봤다. 나는 시선을 피했다.": "Sua liếc nhìn mình. Mình tránh ánh mắt bạn ấy.", "나는 규칙표를 {@blackboard} 옆에 붙이고 나가려 했다.": "Mình dán bảng quy tắc cạnh {@blackboard} rồi định đi ra.", "옆 반 선생님: 「설명도 조금 해 줄 수 있니?」": "Cô giáo lớp bên: \"Em giải thích một chút được không?\"", "……이건, 규칙…… 7번…… 이에요.": "...Đây là, quy tắc... số 7... ạ.", "옆 반 아이들이 고개를 갸웃했다. 나는 꾸벅 인사하고 나왔다.": "Các bạn lớp bên nghiêng đầu khó hiểu. Mình cúi chào rồi đi ra.", "안녕하세요! 옆 반 반장 양수아예요. 이 규칙표는 얘가 그렸어요. 설명도 얘가 할게요.": "Chào các bạn! Mình là Yang Sua, lớp trưởng lớp bên. Bảng quy tắc này là bạn ấy vẽ. Bạn ấy cũng sẽ giải thích luôn.", "수아가 1분을 딱 채우고 나갔다. 이제 나 혼자였다. 그래도 수아가 열어 준 {@door}이라 덜 떨렸다.": "Sua ở lại đúng 1 phút rồi đi ra. Giờ chỉ còn mình mình. Nhưng vì là {@door} Sua mở giúp nên mình bớt run hơn.", "교실로 돌아오니 수아도 막 회의에서 돌아와 있었다.": "Về đến lớp thì Sua cũng vừa họp xong quay về.", "어땠어?": "Thế nào rồi?", "벽 왜 짚냐고 물어봐서 대답했어.": "Các bạn hỏi sao phải vịn tường, tớ trả lời rồi.", "……나보다 잘했겠다. 나는 ‘규칙이니까’라고 했을 거야.": "...Chắc cậu làm tốt hơn tớ. Tớ thì chắc sẽ chỉ bảo 'vì đó là quy tắc'.", "……잘 못 했어.": "...Tớ làm không tốt lắm.", "다음에 또 기회 있어.": "Lần sau vẫn còn cơ hội mà.", "「알았어. 내가 갈게.」": "\"Được rồi. Tớ sẽ đi.\"", "알았어. 내가 갈게.": "Được rồi. Tớ sẽ đi.", "진짜? 고마워. {@picture} 보여 주면서 하면 돼.": "Thật hả? Cảm ơn nhé. Cậu cứ vừa cho xem {@picture} vừa nói là được.", "수아가 둘둘 만 규칙표를 내 {@hand}에 쥐여 주고 뛰어갔다.": "Sua dúi bảng quy tắc cuộn tròn vào {@hand} mình rồi chạy đi.", "「반장이니까 네가 해야지.」": "\"Cậu là lớp trưởng thì cậu phải làm chứ.\"", "반장이니까 네가 해야지.": "Cậu là lớp trưởng thì cậu phải làm chứ.", "그건 그런데…… 회의가 있다니까.": "Thì đúng vậy, nhưng... tớ đã bảo là có họp mà.", "회의 끝나고 가.": "Họp xong rồi đi.", "……그럼 늦어. 알았어, 끝나고 같이 가자. 대신 말은 네가 해.": "...Thế thì muộn mất. Thôi được, họp xong cùng đi. Nhưng cậu nói nhé.", "「규칙표만 붙이고 올게.」": "\"Tớ chỉ đi dán bảng quy tắc thôi.\"", "설명은 못 하고, 규칙표만 붙이고 올게.": "Tớ không giải thích được đâu, tớ chỉ đi dán bảng quy tắc thôi.", "음…… 그래도 가 주면 고맙지.": "Ừm... dù vậy cậu đi giúp thì tớ cũng cảm ơn.", "수아가 규칙표를 건네고 뛰어갔다.": "Sua đưa bảng quy tắc rồi chạy đi.", "「처음 1분만 같이 가 줘. 나머지는 내가 할게.」": "\"Đi cùng tớ 1 phút đầu thôi. Phần còn lại tớ lo.\"", "처음 1분만 같이 가 줘. 인사만. 나머지는 내가 할게.": "Đi cùng tớ 1 phút đầu thôi. Chỉ chào thôi. Phần còn lại tớ lo.", "1분?": "1 phút?", "……좋아. 1분이면 회의 안 늦어.": "...Được. 1 phút thì không bị muộn họp.", "수아가 {@clock}를 보더니 앞장섰다.": "Sua nhìn {@clock} rồi đi trước.", "{m}, 오늘 수아가 옆 반에 가서 우리 규칙표 설명해 달래. 혼자서.": "{m}, hôm nay Sua nhờ con sang lớp bên giải thích bảng quy tắc của lớp con. Một mình.", "혼자? 아는 애도 없는 반에?": "Một mình? Ở lớp chẳng quen ai à?", "응. 수아가 회의 가야 한대서.": "Vâng. Vì Sua bảo phải đi họp.", "그래서 혼자 갔어. 다리 떨렸는데 {@picture} 가리키면서 했어. 벽 왜 짚냐고 물어봐서 대답도 했어.": "Thế là con đi một mình. Chân con run lắm nhưng con vừa chỉ vào {@picture} vừa nói. Các bạn hỏi sao phải vịn tường, con cũng trả lời được.", "와, 혼자서 질문까지?": "Oa, một mình mà trả lời được cả câu hỏi à?", "응. 수아가 자기보다 잘했겠대.": "Vâng. Sua bảo chắc con làm tốt hơn bạn ấy.", "수아가 너를 믿고 맡긴 거네.": "Sua tin con nên mới giao cho con đấy.", "반장이니까 수아가 하라고 했어. 근데 회의 끝나고 갔더니 벌써 수업 시작했어.": "Con bảo Sua là lớp trưởng thì Sua phải làm. Nhưng họp xong mới đi thì tiết học đã bắt đầu rồi.", "아이고, 못 했구나.": "Ôi, thế là không làm được à.", "응. 내일 다시 오래. 수아가 나를 쳐다봤어.": "Vâng. Cô bảo mai quay lại. Sua nhìn con.", "내일은 어떻게 할래?": "Mai con định làm thế nào?", "……내가 할래.": "...Con sẽ làm.", "규칙표만 붙이고 오려고 했는데, 선생님이 설명도 해 달래서 버벅거렸어.": "Con định chỉ dán bảng quy tắc rồi về, nhưng cô bảo giải thích luôn nên con bị lắp bắp.", "갑자기 하려니까 어려웠겠다.": "Đột ngột phải làm nên chắc khó lắm.", "응. 준비할 걸 그랬어.": "Vâng. Biết thế con chuẩn bị trước.", "처음 1분만 같이 가 달라고 했어. 수아가 인사하고, 얘가 그렸다고 말해 주고 나갔어. 그다음엔 내가 했어.": "Con nhờ Sua đi cùng 1 phút đầu thôi. Sua chào rồi nói là con vẽ, rồi đi ra. Sau đó con tự làm.", "필요한 만큼만 도움을 받았구나.": "Con chỉ nhờ giúp vừa đủ thôi nhỉ.", "응. 수아가 {@door} 열어 주니까 덜 떨렸어.": "Vâng. Sua mở {@door} giúp nên con bớt run.", "쉬는 시간. 옆 반 아이들이 우리 규칙표를 따라 만들기로 했다는 소식을 들었다. 나는 신이 나서 수아 자리로 갔다.": "Giờ ra chơi. Mình nghe tin các bạn lớp bên sẽ làm bảng quy tắc theo lớp mình. Mình hớn hở chạy đến chỗ Sua.", "수아는 학급 게시물을 붙이고 있었다. {@desk} 위에 뚜껑 열린 {@glue}이 굴러다녔다.": "Sua đang dán bảng tin của lớp. Trên {@desk}, {@glue} mở nắp lăn lóc.", "「{x}」 뚜껑 닫기": "Đậy nắp 「{x}」", "수아야! 옆 반이 우리 규칙표 따라 만든대!": "Sua ơi! Lớp bên sẽ làm bảng quy tắc theo lớp mình đấy!", "옆 반 선생님이 {@picture} 좋다고…….": "Cô giáo lớp bên khen {@picture} đẹp...", "지금 그 얘기 할 때 아니야!": "Giờ không phải lúc nói chuyện đó!", "수아가 게시물을 탁 내려놓았다.": "Sua đặt mạnh tờ thông báo xuống.", "이거 종례 전까지 다 붙여야 하고, 학생회 회의 내용도 정리해야 하고. 너는 반장 안 해 봐서 몰라.": "Cái này phải dán hết trước giờ sinh hoạt cuối ngày, còn phải tóm tắt nội dung họp hội học sinh nữa. Cậu chưa làm lớp trưởng bao giờ nên không biết đâu.", "교실이 잠깐 조용해졌다. 몇몇이 우리를 봤다.": "Lớp học bỗng im lặng một lúc. Vài bạn nhìn sang bọn mình.", "(……뭐야. 나는 좋은 소식 말하러 온 건데.)": "(...Gì chứ. Mình đến để báo tin vui mà.)", "(‘반장 안 해 봐서 몰라’. 그 말이 콕 찔렸어.)": "('Chưa làm lớp trưởng bao giờ nên không biết'. Câu đó làm mình nhói lòng.)", "종례가 끝나고 {@bag}을 메는데, {@pcase} 위에 쪽지 하나가 있었다. 형광펜 글씨였다.": "Giờ sinh hoạt cuối ngày xong, lúc mình đeo {@bag} lên thì thấy có một mẩu giấy trên {@pcase}. Chữ viết bằng bút dạ quang.", "쪽지: 「아까 말 심하게 했어. 학생회 회의에서 내 안건이 다 떨어져서 그랬어. 그건 너랑 상관없는데. — 수아」": "Mẩu giấy: \"Lúc nãy tớ nói quá lời. Vì ở cuộc họp hội học sinh, ý kiến của tớ bị bác hết nên mới thế. Chuyện đó chẳng liên quan gì đến cậu. — Sua\"", "(아팠던 건 아팠던 거야. 근데 수아도 오늘 힘들었구나.)": "(Đau thì vẫn là đau. Nhưng hôm nay Sua cũng mệt mỏi lắm.)", "「그래, 넌 반장이라 잘났다.」 하고 맞받아친다.": "Đáp trả: \"Ừ, cậu là lớp trưởng nên giỏi lắm.\"", "그래, 넌 반장이라 잘났다.": "Ừ, cậu là lớp trưởng nên giỏi lắm nhỉ.", "그런 뜻 아니잖아!": "Tớ đâu có ý đó!", "그런 뜻이었잖아.": "Thì đúng là ý đó còn gì.", "수아가 입을 꾹 다물고 다시 게시물을 붙였다. 나도 자리로 돌아갔다. 둘 다 하루 종일 말을 안 했다.": "Sua mím chặt môi rồi lại dán tiếp. Mình cũng về chỗ. Cả hai đứa không nói với nhau câu nào suốt cả ngày.", "「지금 그 말 좀 아팠어. 근데 무슨 일 있어?」": "\"Câu vừa rồi làm tớ hơi đau. Mà có chuyện gì à?\"", "지금 그 말 좀 아팠어.": "Câu vừa rồi làm tớ hơi đau đấy.", "근데 너 오늘 좀 이상해. 무슨 일 있어?": "Mà hôm nay cậu hơi lạ. Có chuyện gì à?", "수아가 {@glue}을 내려놓았다. 한참 있다가 작게 말했다.": "Sua đặt {@glue} xuống. Một lúc lâu sau mới nói nhỏ.", "학생회 회의에서 내 안건이 다 떨어졌어. 세 개 다.": "Ở cuộc họp hội học sinh, ý kiến của tớ bị bác hết rồi. Cả ba cái.", "그거랑 너는 상관없는데. ……미안. 말 심하게 했어.": "Chuyện đó chẳng liên quan gì đến cậu. ...Xin lỗi. Tớ nói quá lời.", "나는 남은 게시물 한 장을 집어 수아에게 내밀었다.": "Mình nhặt tờ thông báo còn lại đưa cho Sua.", "「알았어. 이따 다시 올게.」 하고 자리를 비켜 준다.": "Nói \"Được rồi. Lát nữa tớ quay lại.\" rồi để Sua yên.", "알았어. 이따 다시 올게.": "Được rồi. Lát nữa tớ quay lại.", "나는 내 자리로 돌아갔다. 마음이 쿡쿡 쑤셨다. 그래도 지금은 더 말하지 않았다.": "Mình về chỗ của mình. Lòng nhói từng cơn. Nhưng lúc này mình không nói thêm gì.", "점심시간. 수아가 먼저 내 자리로 왔다.": "Giờ ăn trưa. Sua chủ động đến chỗ mình trước.", "……아까 무슨 얘기 하려고 했어?": "...Lúc nãy cậu định nói gì thế?", "옆 반이 우리 규칙표 따라 만든대.": "Lớp bên sẽ làm bảng quy tắc theo lớp mình đấy.", "진짜? ……아까 그거 기쁜 소식이었네.": "Thật á? ...Hóa ra lúc nãy là tin vui.", "「하하, 그렇지.」 하고 웃어넘긴다.": "Cười cho qua: \"Haha, đúng rồi.\"", "하하, 그렇지. 나는 모르지.": "Haha, đúng rồi. Tớ thì biết gì đâu.", "나는 웃으면서 자리로 돌아왔다.": "Mình vừa cười vừa về chỗ.", "(웃었는데…… 하나도 안 웃겨.)": "(Cười đấy... nhưng chẳng buồn cười chút nào.)", "수아는 내가 웃는 걸 보고 그냥 괜찮은 줄 알았다.": "Thấy mình cười, Sua cứ tưởng mình không sao.", "{m}, 옆 반이 우리 규칙표 따라 만든대서 수아한테 말하러 갔거든.": "{m}, lớp bên sẽ làm bảng quy tắc theo lớp con, nên con đến báo cho Sua.", "좋은 소식이네!": "Tin vui đấy chứ!", "근데 수아가 지금 그 얘기 할 때 아니래. 너는 반장 안 해 봐서 모른대.": "Nhưng Sua bảo giờ không phải lúc nói chuyện đó. Bảo con chưa làm lớp trưởng bao giờ nên không biết.", "어머, 그 말 듣고 속상했겠다.": "Ôi, nghe thế chắc con buồn lắm.", "그래, 넌 반장이라 잘났다, 그랬어.": "Con bảo: ừ, cậu là lớp trưởng nên giỏi lắm.", "하루 종일 말 안 했어. 근데 수아가 쪽지 줬어. 학생회에서 안건이 다 떨어졌대.": "Cả ngày bọn con không nói chuyện. Nhưng Sua đưa con mẩu giấy. Ở hội học sinh, ý kiến của bạn ấy bị bác hết.", "둘 다 안 좋은 날이었구나.": "Hôm nay cả hai đứa đều không vui nhỉ.", "그 말 아팠다고 했어. 그리고 무슨 일 있냐고 물었어.": "Con bảo câu đó làm con đau. Rồi con hỏi có chuyện gì không.", "아픈 말을 듣고 그걸 물어보기 쉽지 않은데.": "Nghe câu làm mình đau mà vẫn hỏi được thế thì không dễ đâu.", "수아가 학생회에서 안건 세 개가 다 떨어졌대. 그리고 미안하다고 했어.": "Ở hội học sinh, cả ba ý kiến của Sua bị bác hết. Rồi bạn ấy xin lỗi con.", "이따 다시 오겠다고 하고 갔어. 근데 수아가 점심때 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "Con bảo lát quay lại rồi đi. Nhưng trưa Sua đến trước, hỏi lúc nãy con định nói gì.", "기다렸더니 수아가 왔구나.": "Con đợi thì Sua đến nhỉ.", "응. 그리고 쪽지도 줬어.": "Vâng. Bạn ấy còn đưa con mẩu giấy nữa.", "그냥 웃어넘겼어. 근데 하나도 안 웃겼어.": "Con cười cho qua. Nhưng chẳng buồn cười chút nào.", "웃었으니까 수아는 괜찮은 줄 알았겠다.": "Con cười nên chắc Sua tưởng con không sao.", "응. 쪽지는 받았는데…… 나 아팠다는 건 수아가 몰라.": "Vâng. Con nhận được mẩu giấy rồi... nhưng Sua không biết là con bị đau.", "내일이라도 말해 볼래? 그 말 좀 아팠다고.": "Mai con thử nói xem? Là câu đó làm con hơi đau.", "도서관. 선거 연설문을 쓰다가 막혔다. 마침 수아가 맞은편에 앉아 있었다. 나는 {w}을 들고 수아에게 갔다.": "Thư viện. Mình đang viết bài phát biểu tranh cử thì bị bí. Đúng lúc Sua ngồi đối diện. Mình cầm {w} đến chỗ Sua.", "수아야, 내 연설문 처음 부분만 봐 줄래?": "Sua ơi, cậu xem giúp tớ phần đầu bài phát biểu được không?", "경쟁자 연설문을?": "Bài phát biểu của đối thủ á?", "처음 부분만.": "Chỉ phần đầu thôi.", "내 {w}: 「안녕하세요. 저는 규칙을 잘 지키는 반장이 되겠습니다. 규칙 3번, 교실에서 뛰지 않기. 규칙 5번, 친구 밀지 않기. 규칙은 누구나 지키는 것입니다. 예외는 없습니다.」": "{w} của mình: \"Xin chào các bạn. Mình sẽ là lớp trưởng luôn giữ đúng quy tắc. Quy tắc số 3, không chạy trong lớp. Quy tắc số 5, không xô đẩy bạn. Quy tắc là thứ ai cũng phải giữ. Không có ngoại lệ.\"", "수아가 읽다가 고개를 들었다.": "Sua đang đọc thì ngẩng lên.", "……이거 나잖아.": "...Đây là tớ còn gì.", "규칙 번호까지. ‘예외는 없습니다’는 내가 첫날 최민호한테 한 말이고.": "Cả số quy tắc nữa. 'Không có ngoại lệ' là câu tớ nói với Choi Minho hôm đầu tiên.", "얼굴이 화끈거렸다. 첫날 밤 {w}에 썼던 말이 생각났다.": "Mặt mình nóng bừng. Mình nhớ lại câu đã viết vào {w} tối hôm đầu tiên.", "이거면 애들이 왜 너를 뽑아? 나 뽑지.": "Thế này thì sao các bạn lại bầu cậu? Bầu tớ thôi.", "너는 뭐가 하고 싶은데?": "Cậu muốn làm gì?", "고친 거 선거 때 들으면 되겠네. 지금은 안 볼래.": "Bản sửa thì tớ nghe vào hôm bầu cử là được. Giờ tớ không xem đâu.", "경쟁자 연설문 너무 많이 보면 반칙 같아.": "Xem bài phát biểu của đối thủ nhiều quá thì giống ăn gian.", "「네가 잘하니까 너처럼 하면 될 것 같았어. 그냥 둘래.」": "\"Cậu giỏi nên tớ nghĩ làm giống cậu là được. Tớ để nguyên.\"", "너 잘하잖아. 너처럼 하면 될 것 같았어. 그냥 둘래.": "Cậu giỏi mà. Tớ nghĩ làm giống cậu là được. Tớ để nguyên.", "……그럼 나랑 너랑 뭐가 달라?": "...Thế thì tớ với cậu khác gì nhau?", "난 경쟁자가 나랑 똑같은 건 재미없어.": "Đối thủ mà giống hệt tớ thì chẳng vui gì.", "수아가 {w}을 돌려줬다. {w}이 이상하게 무거웠다.": "Sua trả lại {w}. {w} nặng một cách lạ lùng.", "「그럼 너랑 반대로 할래. 규칙 없는 반!」": "\"Vậy tớ làm ngược lại cậu. Lớp không có quy tắc!\"", "그럼 너랑 반대로 할래. 규칙 없는 자유로운 반!": "Vậy tớ làm ngược lại cậu. Một lớp tự do không có quy tắc!", "애들이 좋아하긴 하겠다.": "Các bạn chắc sẽ thích đấy.", "근데 너 대피 훈련 때 규칙 7번 덕분에 길 찾았잖아.": "Nhưng hôm diễn tập sơ tán, nhờ quy tắc số 7 mà cậu tìm được đường còn gì.", "……그건 그렇지.": "...Cái đó thì đúng.", "(반대로 하는 것도 결국 수아를 보고 정한 거네.)": "(Làm ngược lại thì rốt cuộc cũng là nhìn Sua mà quyết định.)", "「그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 거 말해 줄게.」": "\"Vậy cậu thấy tớ giỏi cái gì? Tớ cũng sẽ nói điểm mạnh của cậu.\"", "그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 장점 말해 줄게.": "Vậy cậu thấy tớ giỏi cái gì? Tớ cũng sẽ nói điểm mạnh của cậu.", "음…… 너는 못 알아듣는 애를 알아봐. 신청서 때도, 옆 반 때도.": "Ừm... cậu nhận ra bạn nào không hiểu. Cả lúc làm đơn đăng ký, cả lúc ở lớp bên.", "그리고 막히면 몸으로 해. 학급회의 때처럼.": "Còn khi bí thì cậu dùng cơ thể để diễn tả. Như lúc họp lớp ấy.", "너는 빨라. 정리 잘하고. 다들 네 말 들어.": "Cậu nhanh. Tóm tắt giỏi. Ai cũng nghe lời cậu.", "그럼 됐네. 나는 빠른 반장, 너는…….": "Vậy là được rồi. Tớ là lớp trưởng nhanh nhẹn, còn cậu là...", "……천천히 물어보는 반장?": "...Lớp trưởng hỏi han từ từ?", "나는 {w}을 새 쪽으로 넘겼다.": "Mình lật {w} sang trang mới.", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다.」": "{w} của mình: \"Mình sẽ là lớp trưởng hỏi 'Cậu ổn không?' trước tiên.\"", "지우고, 내가 겪은 일로 다시 쓴다.": "Xóa đi, viết lại bằng chuyện mình đã trải qua.", "……다시 쓸게. 잠깐만.": "...Tớ viết lại đây. Chờ chút.", "나는 처음 문장을 지웠다. 첫날이 생각났다. 깨진 관찰 통. 민호를 막은 수아. 그리고 아무도 묻지 않았던 시우.": "Mình xóa câu đầu tiên. Mình nhớ lại ngày đầu tiên. Chiếc hộp quan sát bị vỡ. Sua ngăn Minho lại. Và Siwoo, người mà không ai hỏi han.", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다. 저는 전학 온 첫날, 아무것도 못 알아들었습니다. 누가 먼저 물어봐 주면 좋겠다고 생각했습니다.」": "{w} của mình: \"Mình sẽ là lớp trưởng hỏi 'Cậu ổn không?' trước tiên. Ngày đầu tiên chuyển trường đến, mình chẳng hiểu gì cả. Mình đã nghĩ giá mà có ai hỏi mình trước thì tốt biết mấy.\"", "수아가 그걸 읽었다. 한참 말이 없었다.": "Sua đọc xong. Rất lâu không nói gì.", "……이건 내가 못 쓰는 거다.": "...Cái này thì tớ không viết được.", "{m}, 수아한테 내 연설문 보여 줬는데, 수아가 이거 나잖아, 그랬어.": "{m}, con cho Sua xem bài phát biểu, Sua bảo: đây là tớ còn gì.", "응? 무슨 말이야?": "Hả? Nghĩa là sao?", "규칙 번호도 수아처럼 쓰고, 수아가 첫날 한 말도 썼거든. 나도 모르게.": "Con viết cả số quy tắc giống Sua, còn viết cả câu Sua nói hôm đầu tiên. Con không để ý.", "아…… 수아처럼 되고 싶다고 했었지.": "À... con từng bảo muốn được giống Sua mà.", "수아가 잘하니까 그냥 두겠다고 했어. 근데 수아가 그럼 너랑 나랑 뭐가 다르냐고 했어.": "Con bảo Sua giỏi nên con để nguyên. Nhưng Sua hỏi: thế thì cậu với tớ khác gì nhau.", "뭐라고 대답했어?": "Con trả lời thế nào?", "……대답 못 했어.": "...Con không trả lời được.", "그 질문은 오늘 밤에 천천히 생각해 봐도 돼.": "Câu hỏi đó tối nay con cứ từ từ suy nghĩ cũng được.", "그럼 반대로 규칙 없는 반 하겠다고 했어. 근데 수아가 나 대피 훈련 때 규칙 덕분에 길 찾았잖아, 그러더라.": "Thế là con bảo sẽ làm ngược lại, lớp không có quy tắc. Nhưng Sua bảo: hôm diễn tập sơ tán nhờ quy tắc mà cậu tìm được đường còn gì.", "수아한테 한 방 맞았네.": "Bị Sua bắt bài rồi.", "응. 반대로 하는 것도 결국 수아 따라 한 거래.": "Vâng. Bạn ấy bảo làm ngược lại thì rốt cuộc cũng là bắt chước Sua.", "수아한테 내 장점 말해 달라고 했어. 나도 수아 장점 말해 주고.": "Con nhờ Sua nói điểm mạnh của con. Con cũng nói điểm mạnh của Sua.", "나는 못 알아듣는 애를 알아본대. 막히면 몸으로 하고. 그래서 ‘괜찮아?’라고 먼저 묻는 반장이라고 썼어.": "Bạn ấy bảo con nhận ra bạn nào không hiểu. Bí thì dùng cơ thể diễn tả. Nên con viết là lớp trưởng hỏi 'Cậu ổn không?' trước tiên.", "와, 그거 너다.": "Oa, đúng là con rồi.", "지우고 다시 썼어. 첫날 시우 생각이 났거든. 아무도 시우한테 괜찮냐고 안 물어봤잖아.": "Con xóa đi viết lại. Vì con nhớ đến Siwoo hôm đầu tiên. Chẳng ai hỏi Siwoo có ổn không cả.", "그날 {w}에 썼던 거?": "Cái con viết vào {w} hôm đó à?", "응. 수아가 그건 자기가 못 쓰는 거래.": "Vâng. Sua bảo cái đó bạn ấy không viết được.", "네가 겪은 일이니까 너만 쓸 수 있지.": "Vì là chuyện con đã trải qua nên chỉ con viết được thôi.", "방과 후. 수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "Sau giờ học. Mình và Sua hẹn nghe bài phát biểu của nhau. Vào lớp trống thì Sua đã đến trước rồi.", "나 먼저 할게. 시간 재 줘.": "Tớ nói trước nhé. Cậu bấm giờ giúp tớ.", "「{x}」로 시간 재기": "Bấm giờ bằng 「{x}」", "수아의 연설은 1분 40초. 막힘이 없었다.": "Bài phát biểu của Sua dài 1 phút 40 giây. Không vấp chút nào.", "좋아. 근데 중간에 너무 빨라. 공약 2번에서 숨 한 번 쉬어.": "Tốt. Nhưng đoạn giữa nhanh quá. Đến lời hứa số 2 thì hít một hơi.", "……알았어. 숨 쉬기.": "...Biết rồi. Hít thở.", "이번엔 내 차례였다. 나는 {w}을 들고 섰다. 고친 연설문이었다. 2분 30초가 걸렸다.": "Lần này đến lượt mình. Mình cầm {w} đứng lên. Là bài phát biểu đã sửa. Mất 2 phút 30 giây.", "수아가 팔짱을 꼈다.": "Sua khoanh tay.", "솔직히 말해도 돼?": "Tớ nói thật được không?", "무슨 말인지 모르겠어. 너무 길고, 끝에 그래서 뭘 하겠다는 건지 안 나와.": "Tớ không hiểu cậu nói gì. Dài quá, mà đến cuối cũng không rõ là cậu sẽ làm gì.", "그리고 ‘괜찮아?’ 부분, 좋은데 너무 빨리 지나가.": "Còn phần 'Cậu ổn không?' thì hay, nhưng lướt qua nhanh quá.", "(밤새 고친 건데.)": "(Mình sửa cả đêm đấy.)", "「{x}」 한 모금 마시기": "Uống một ngụm 「{x}」", "교실 창밖이 붉어졌다. 수아가 손바닥을 내밀었다.": "Ngoài cửa sổ lớp học ửng đỏ. Sua chìa lòng bàn tay ra.", "이기려고 최선을 다하자.": "Cố hết sức để thắng nhé.", "나는 그 손바닥을 바로 마주치지 못했다. 수아가 {@hand}을 거두고 먼저 나갔다.": "Mình không đập tay ngay được. Sua thu {@hand} lại rồi đi ra trước.", "나도 손바닥을 마주쳤다. 짝!": "Mình cũng đập tay. Bốp!", "「너 이기려고 일부러 그러는 거지?」": "\"Cậu cố tình nói thế để thắng tớ đúng không?\"", "너 이기려고 일부러 그러는 거지?": "Cậu cố tình nói thế để thắng tớ đúng không?", "아니거든. 너도 나한테 숨 쉬라고 했잖아. 나 그거 고칠 거야.": "Không phải nhé. Cậu cũng bảo tớ hít thở còn gì. Tớ sẽ sửa cái đó.", "그럼 다른 사람한테 들어 봐. 그게 낫겠다.": "Thế thì cậu nhờ người khác nghe đi. Thế tốt hơn.", "수아가 {@bag}을 챙겼다. 연습은 거기서 끝났다.": "Sua xếp {@bag}. Buổi tập dừng ở đó.", "「어디가 제일 모르겠어?」 하고 구체적으로 묻는다.": "Hỏi cụ thể: \"Chỗ nào cậu thấy khó hiểu nhất?\"", "어디가 제일 모르겠어?": "Chỗ nào cậu thấy khó hiểu nhất?", "중간에 전학 온 날 얘기. 길어. 그 얘기만 1분이야.": "Đoạn giữa kể về ngày chuyển trường. Dài. Riêng đoạn đó đã 1 phút.", "그럼 그거 반으로 줄이면?": "Vậy rút đoạn đó còn một nửa thì sao?", "그리고 끝에 한 줄만 넣어. 반장 되면 뭘 할 건지.": "Rồi cuối bài thêm đúng một câu. Làm lớp trưởng thì cậu sẽ làm gì.", "‘천천히 말해 줘’ 카드 만들기. 그거 넣을게.": "Làm thẻ 'Nói chậm thôi'. Tớ sẽ thêm cái đó.", "다시 했다. 1분 55초.": "Làm lại. 1 phút 55 giây.", "……이제 알겠다.": "...Giờ thì tớ hiểu rồi.", "「길다는 건 고칠게. 근데 ‘괜찮아?’ 부분은 내 방식대로 할래.」": "\"Dài thì tớ sửa. Nhưng phần 'Cậu ổn không?' tớ sẽ làm theo cách của tớ.\"", "길다는 건 맞아. 줄일게.": "Dài thì đúng. Tớ sẽ rút ngắn.", "근데 ‘괜찮아?’ 부분은 빨리 지나가는 게 아니라 천천히 말할 거야. 그게 나니까.": "Nhưng phần 'Cậu ổn không?' tớ sẽ không lướt nhanh mà nói thật chậm. Vì đó là tớ.", "……천천히?": "...Chậm á?", "응. 거기서 멈췄다가 말할 거야.": "Ừ. Đến đó tớ sẽ dừng lại rồi mới nói.", "다시 했다. 이번엔 ‘괜찮아?’에서 숨을 한 번 멈췄다. 교실이 조용해졌다.": "Làm lại. Lần này đến 'Cậu ổn không?' mình dừng lại một nhịp. Cả lớp im phăng phắc.", "……그거 좋다. 그건 너 맞네.": "...Cái đó hay đấy. Đó đúng là cậu.", "수아가 말한 대로 전부 고친다.": "Sửa hết theo lời Sua.", "알았어. 네 말대로 다 고칠게.": "Được rồi. Tớ sẽ sửa hết theo lời cậu.", "나는 수아가 지적한 걸 다 고쳤다. 전학 온 날 얘기도 빼고, ‘괜찮아?’도 뺐다.": "Mình sửa hết những chỗ Sua chỉ ra. Bỏ cả đoạn kể ngày chuyển trường, bỏ cả 'Cậu ổn không?'.", "다시 했다. 1분 30초. 짧고 깔끔했다.": "Làm lại. 1 phút 30 giây. Ngắn và gọn gàng.", "……근데 이제 누구 연설인지 모르겠다.": "...Nhưng giờ chẳng biết đây là bài phát biểu của ai nữa.", "(시키는 대로 했는데.)": "(Mình làm đúng như được bảo mà.)", "{m}, 수아랑 서로 연설 들어 줬어.": "{m}, con với Sua nghe bài phát biểu của nhau.", "수아는 1분 40초. 진짜 잘해. 근데 수아가 내 거는 무슨 말인지 모르겠대. 너무 길대.": "Sua nói 1 phút 40 giây. Giỏi thật luôn. Nhưng Sua bảo không hiểu bài của con nói gì. Dài quá.", "아이고, 밤새 고친 거잖아.": "Ôi, con sửa cả đêm mà.", "나 이기려고 일부러 그러는 거냐고 했어. 수아가 그럼 다른 사람한테 들어 보래.": "Con hỏi có phải bạn ấy cố tình nói thế để thắng con không. Sua bảo thế thì nhờ người khác nghe đi.", "속상한 마음에 그렇게 말했구나.": "Con buồn quá nên mới nói thế nhỉ.", "근데 나도 수아한테 숨 쉬라고 했잖아. 수아는 그거 고친대.": "Nhưng con cũng bảo Sua hít thở mà. Sua bảo sẽ sửa cái đó.", "……내일 다시 들어 달라고 해 볼래?": "...Mai con thử nhờ bạn ấy nghe lại nhé?", "어디가 제일 모르겠냐고 물었어. 전학 온 날 얘기가 너무 길대. 반으로 줄였어.": "Con hỏi chỗ nào khó hiểu nhất. Bạn ấy bảo đoạn kể ngày chuyển trường dài quá. Con rút còn một nửa.", "몇 분 됐어?": "Thành bao nhiêu phút?", "1분 55초! 수아가 이제 알겠대.": "1 phút 55 giây! Sua bảo giờ thì hiểu rồi.", "길다는 건 고치겠다고 했어. 근데 ‘괜찮아?’는 내 방식대로 천천히 하겠다고 했어.": "Con bảo dài thì con sẽ sửa. Nhưng 'Cậu ổn không?' thì con sẽ nói chậm theo cách của con.", "그거 좋대. 그건 나 맞대.": "Bạn ấy bảo hay. Bảo đó đúng là con.", "들을 건 듣고, 지킬 건 지켰네.": "Cái cần nghe thì con nghe, cái cần giữ thì con giữ.", "수아 말대로 다 고쳤어. 짧아졌어. 근데 수아가 이제 누구 연설인지 모르겠대.": "Con sửa hết theo lời Sua. Ngắn rồi. Nhưng Sua bảo giờ không biết là bài phát biểu của ai nữa.", "다 빼 버렸구나.": "Con bỏ hết đi rồi.", "응. ‘괜찮아?’도 뺐어.": "Vâng. Bỏ cả 'Cậu ổn không?'.", "그건 다시 넣고 싶지 않아?": "Con không muốn thêm lại cái đó à?", "……넣을래.": "...Con sẽ thêm lại.", "창체 시간. 선생님이 수아와 나를 앞으로 부르셨다.": "Giờ hoạt động trải nghiệm. Cô giáo gọi Sua và mình lên trước lớp.", "선생님: 「오늘 자리 바꾸기는 반장 후보 둘이 같이 진행해 볼래요? 연습이라고 생각하고.」": "Cô giáo: \"Hôm nay hai ứng viên lớp trưởng cùng điều hành việc đổi chỗ nhé? Coi như là luyện tập.\"", "나는 수아 옆에 섰다. 수아가 작게 말했다.": "Mình đứng cạnh Sua. Sua nói nhỏ.", "번호 뽑기로 하자. 빠르고 공평해.": "Bốc số đi. Nhanh và công bằng.", "「{x}」 줄 맞추기": "Xếp 「{x}」 cho thẳng hàng", "그런데 맨 뒤에 앉은 친구가 {@blackboard}을 보느라 눈을 찡그리고 있었다. 지난번 자리 바꿀 때 뒤로 갔던 친구였다.": "Nhưng bạn ngồi cuối lớp đang nheo mắt nhìn {@blackboard}. Đó là bạn lần đổi chỗ trước đã bị xuống cuối.", "(번호 뽑기면…… 또 뒤로 갈 수도 있잖아.)": "(Nếu bốc số thì... bạn ấy có thể lại bị xuống cuối mất.)", "수아야, 근데 눈 나쁜 애들은 앞에 앉아야 하지 않을까? 먼저 물어보면…….": "Sua ơi, nhưng các bạn mắt kém có nên ngồi bàn đầu không? Nếu hỏi trước thì...", "그럼 다들 앞에 앉고 싶다고 하면? 시간 없어. 번호 뽑기가 공평해.": "Thế nếu ai cũng muốn ngồi bàn đầu thì sao? Không có thời gian đâu. Bốc số mới công bằng.", "반 아이들이 우리 둘을 보고 있었다. 누군가 「빨리 해!」 하고 외쳤다.": "Cả lớp đang nhìn hai đứa. Có ai đó hét: \"Nhanh lên!\"", "자리 바꾸기가 끝났다. 선생님이 둘을 보고 웃으셨다.": "Đổi chỗ xong. Cô giáo nhìn hai đứa rồi mỉm cười.", "선생님: 「둘이 이끄는 방식이 다르네요.」": "Cô giáo: \"Hai em dẫn dắt theo cách khác nhau nhỉ.\"", "수아가 나를 힐끗 봤다.": "Sua liếc nhìn mình.", "다르다는 게 칭찬이야, 아니야?": "Khác nhau là khen hay không?", "……칭찬이겠지?": "...Chắc là khen?", "「둘 다 하자. 꼭 앞이어야 하는 사람만 먼저, 나머지는 뽑기.」": "\"Làm cả hai đi. Ai thật sự cần ngồi bàn đầu thì trước, còn lại bốc số.\"", "둘 다 하자. 눈 때문에 꼭 앞이어야 하는 사람만 먼저 {@hand} 들고, 나머지는 번호 뽑기.": "Làm cả hai đi. Ai vì mắt mà thật sự cần ngồi bàn đầu thì giơ {@hand} trước, còn lại bốc số.", "……‘꼭’인 사람만?": "...Chỉ người 'thật sự cần' thôi á?", "응. 그냥 앞이 좋은 건 안 되고.": "Ừ. Chỉ thích ngồi bàn đầu thôi thì không được.", "좋아. 정리하면, 꼭인 사람 먼저, 나머지 뽑기.": "Được. Tóm lại là, người thật sự cần thì trước, còn lại bốc số.", "세 명이 {@hand}을 들었다. 나머지는 수아가 번호를 뽑았다. 5분 만에 끝났다.": "Ba bạn giơ {@hand}. Còn lại Sua bốc số. 5 phút là xong.", "반 친구들에게 어떤 방식이 좋은지 묻는다.": "Hỏi các bạn trong lớp thích cách nào hơn.", "얘들아, 두 가지 방법이 있어. 번호 뽑기, 아니면 먼저 사정 있는 사람 물어보고 정하기. {@hand} 들어 줘.": "Các bạn ơi, có hai cách. Bốc số, hoặc hỏi trước ai có lý do riêng rồi mới quyết. Giơ {@hand} lên nhé.", "아이들이 {@hand}을 들었다. 거의 반반이었다.": "Các bạn giơ {@hand}. Gần như chia đôi.", "반반이네.": "Chia đôi luôn.", "아이: 「그럼 섞어!」": "Một bạn: \"Thế thì gộp lại!\"", "결국 사정 있는 사람 먼저, 나머지는 뽑기가 됐다.": "Cuối cùng thành ra ai có lý do riêng thì trước, còn lại bốc số.", "……애들이 정하니까 아무도 불만이 없네.": "...Các bạn tự quyết nên chẳng ai phàn nàn cả.", "「알았어. 네 방식대로 하자.」": "\"Được rồi. Làm theo cách của cậu đi.\"", "……알았어. 네 방식대로 하자.": "...Được rồi. Làm theo cách của cậu đi.", "번호 뽑기로 정했다. 빨랐다. 눈을 찡그리던 친구는 이번에도 맨 뒤가 됐다.": "Quyết định bốc số. Nhanh thật. Bạn nheo mắt lần này lại bị xuống cuối lớp.", "(아까 말할 걸.)": "(Biết thế lúc nãy mình nói.)", "「내 방식이 더 좋아. 다 물어보고 정하자.」": "\"Cách của tớ hay hơn. Hỏi hết mọi người rồi quyết.\"", "내 방식이 더 좋아. 한 명씩 다 물어보고 정하자.": "Cách của tớ hay hơn. Hỏi từng người một rồi quyết.", "스물네 명을 다?": "Cả hai mươi bốn người á?", "한 명씩 물어보니 다들 앞이나 창가에 앉고 싶다고 했다. 시간이 다 갔다. 결국 종이 울려서 선생님이 정하셨다.": "Hỏi từng người thì ai cũng muốn ngồi bàn đầu hoặc cạnh cửa sổ. Hết sạch thời gian. Cuối cùng chuông reo nên cô giáo quyết định.", "{m}, 오늘 수아랑 둘이 자리 바꾸기 진행했어. 반장 후보 연습이래.": "{m}, hôm nay con với Sua cùng điều hành đổi chỗ. Cô bảo là luyện tập cho ứng viên lớp trưởng.", "와, 둘이서? 어떻게 했어?": "Oa, hai đứa tự làm à? Làm thế nào?", "수아는 번호 뽑기가 공평하대. 근데 맨 뒤 애가 {@blackboard} 보느라 눈을 찡그리고 있었어.": "Sua bảo bốc số mới công bằng. Nhưng bạn ngồi cuối cứ nheo mắt nhìn {@blackboard}.", "꼭 앞이어야 하는 사람만 먼저 하고, 나머지는 뽑기로 하자고 했어.": "Con bảo ai thật sự cần ngồi bàn đầu thì trước, còn lại bốc số.", "수아 방식이랑 네 방식을 섞었구나.": "Con gộp cách của Sua với cách của con nhỉ.", "응. 5분 만에 끝났어. 수아가 정리하면, 이러면서 정리했어.": "Vâng. 5 phút là xong. Sua còn nói \"Tóm lại là\" rồi tóm tắt nữa.", "애들한테 어떤 방법이 좋냐고 물어봤어. 반반이었는데 누가 섞자고 해서 섞었어.": "Con hỏi các bạn thích cách nào. Chia đôi, xong có bạn bảo gộp lại nên bọn con gộp.", "반 아이들이 정했네.": "Các bạn trong lớp tự quyết nhỉ.", "응. 수아가 애들이 정하니까 불만이 없대.": "Vâng. Sua bảo các bạn tự quyết nên không ai phàn nàn.", "그냥 수아 방식대로 했어. 근데 그 애가 또 맨 뒤 됐어.": "Con cứ làm theo cách của Sua. Nhưng bạn ấy lại bị xuống cuối.", "아쉬웠겠다.": "Chắc tiếc lắm nhỉ.", "응. 아까 말할 걸.": "Vâng. Biết thế lúc nãy con nói.", "다음엔 말해 봐. 너 그 애 눈 찡그리는 거 봤잖아.": "Lần sau con nói thử nhé. Con thấy bạn ấy nheo mắt mà.", "내 방식대로 다 물어보자고 했는데, 다들 앞이나 창가래. 결국 시간 다 가서 선생님이 정하셨어.": "Con bảo hỏi hết theo cách của con, nhưng ai cũng muốn ngồi bàn đầu hoặc cạnh cửa sổ. Cuối cùng hết giờ nên cô quyết định.", "스물네 명한테 다 물어봤어?": "Con hỏi hết cả hai mươi bốn bạn à?", "응…… 수아 말도 맞았어. 시간이 없었어.": "Vâng... Sua nói cũng đúng. Không có thời gian.", "방과 후. 복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "Sau giờ học. Sua đứng cạnh cửa sổ hành lang. Mình đến bên Sua.", "{@window}이 열리고 운동장 소리가 들어왔다.": "{@window} mở ra, tiếng sân trường vọng vào.", "이거 기억나?": "Cậu nhớ cái này không?", "수아가 {@bag}에서 접힌 {@paper}를 꺼냈다.": "Sua lấy {@paper} gấp lại từ trong {@bag} ra.", "처음 도서관에서 만든 규칙표였다. 귀퉁이에 수아가 그린 빨래판 {@stairs}도 그대로 있었다.": "Đó là bảng quy tắc làm lần đầu ở thư viện. Ở góc vẫn còn nguyên {@stairs} trông như cái bàn giặt mà Sua vẽ.", "이거 아직 갖고 있었어?": "Cậu vẫn còn giữ cái này à?", "응. 버리기 아까워서.": "Ừ. Tiếc nên không vứt.", "수아가 창밖 운동장을 봤다.": "Sua nhìn ra sân trường ngoài cửa sổ.", "있잖아. 만약에 네가 반장 되면, 나한테 뭘 맡길 거야?": "Này. Nếu cậu làm lớp trưởng, cậu sẽ giao cho tớ việc gì?", "……갑자기?": "...Tự nhiên hỏi thế?", "궁금해서. 진짜로.": "Tò mò thôi. Thật đấy.", "수아가 규칙표를 다시 접어 내 {@hand}에 쥐여 줬다.": "Sua gấp bảng quy tắc lại rồi dúi vào {@hand} mình.", "그럼 너는? 네가 반장 되면 나한테 뭘 맡길 거야?": "Thế còn cậu? Nếu cậu làm lớp trưởng, cậu sẽ giao cho tớ việc gì?", "너한테는 ‘새 친구 도우미’. 넌 뭐가 어려운지 아니까.": "Cậu thì làm 'người giúp bạn mới'. Vì cậu biết cái gì khó.", "……아, 근데 그 전에 물어볼게. 하고 싶은지.": "...À, nhưng trước đó tớ sẽ hỏi. Xem cậu có muốn không.", "(처음엔 수아처럼 되고 싶었어.)": "(Lúc đầu mình muốn được giống Sua.)", "(지금은…… 수아랑 같이 하고 싶어.)": "(Còn bây giờ... mình muốn cùng làm với Sua.)", "「네가 잘하는 거. 대신 혼자 다 안 하게 나눠서.」": "\"Việc cậu giỏi. Nhưng chia ra để cậu không phải làm hết một mình.\"", "네가 잘하는 거. 정리하는 거, 시간 재는 거.": "Việc cậu giỏi. Tóm tắt, bấm giờ.", "대신 혼자 다 안 하게 나눠서. 신청서 때처럼 혼자 뛰어다니면 안 돼.": "Nhưng chia ra để cậu không phải làm hết một mình. Không được chạy đôn chạy đáo một mình như lúc làm đơn đăng ký đâu.", "……그거 기억하네.": "...Cậu còn nhớ chuyện đó à.", "알았어. 나눠서.": "Biết rồi. Chia ra.", "「아무것도. 내가 다 할 거야.」": "\"Không giao gì cả. Tớ sẽ làm hết.\"", "아무것도 안 맡길 거야. 내가 다 할 거야.": "Tớ sẽ không giao gì cả. Tớ sẽ làm hết.", "……그거 나잖아.": "...Đó là tớ còn gì.", "응. 너 따라 해 봤어.": "Ừ. Tớ bắt chước cậu đấy.", "그러다 쓰러져. 나 해 봐서 알아.": "Làm thế là kiệt sức đấy. Tớ làm rồi nên tớ biết.", "수아가 웃었다. 농담이었지만, 수아는 진짜 대답을 기다리는 얼굴이었다.": "Sua cười. Là đùa thôi, nhưng gương mặt Sua đang chờ câu trả lời thật.", "「부반장 해 줘.」": "\"Làm lớp phó nhé.\"", "부반장 해 줘.": "Cậu làm lớp phó nhé.", "벌써 정했어? 나한테 물어보지도 않고?": "Quyết luôn rồi á? Còn chẳng hỏi tớ?", "부반장이 싫다는 게 아니라, 먼저 물어보라고.": "Không phải tớ ghét làm lớp phó, mà là cậu phải hỏi trước chứ.", "「네가 하고 싶은 걸 먼저 물어볼래.」": "\"Tớ muốn hỏi trước xem cậu muốn làm gì.\"", "네가 하고 싶은 걸 먼저 물어볼래.": "Tớ muốn hỏi trước xem cậu muốn làm gì.", "내가 하고 싶은 거?": "Việc tớ muốn làm á?", "응. 넌 늘 해야 하는 걸 하잖아. 하고 싶은 건 뭔데?": "Ừ. Cậu lúc nào cũng làm việc phải làm. Còn việc cậu muốn làm là gì?", "수아가 한참 생각했다.": "Sua nghĩ rất lâu.", "……{@picture} 규칙표. 그거 계속 만들고 싶어. {@picture}은 네가 그리고.": "...Bảng quy tắc {@picture}. Tớ muốn làm tiếp cái đó. {@picture} thì cậu vẽ.", "{m}, 수아가 처음 만든 규칙표 아직 갖고 있었어. 빨래판 {@stairs} 그대로.": "{m}, Sua vẫn còn giữ bảng quy tắc làm đầu tiên. Cả {@stairs} trông như cái bàn giặt vẫn còn nguyên.", "그 {@stairs}?": "{@stairs} đó á?", "응. 그리고 수아가 나 반장 되면 자기한테 뭘 맡길 거냐고 물었어.": "Vâng. Rồi Sua hỏi nếu con làm lớp trưởng thì sẽ giao cho bạn ấy việc gì.", "네가 잘하는 거, 대신 혼자 다 하지 말고 나눠서 하라고 했어.": "Con bảo việc bạn ấy giỏi, nhưng chia ra, đừng làm hết một mình.", "신청서 때 일 기억하냐고. 알았대.": "Con hỏi bạn ấy có nhớ chuyện lúc làm đơn đăng ký không. Bạn ấy bảo biết rồi.", "아무것도 안 맡기고 내가 다 한다고 했어. 수아 따라 한 거야.": "Con bảo không giao gì cả, con làm hết. Con bắt chước Sua đấy.", "그러다 쓰러진대. 자기가 해 봐서 안대.": "Bạn ấy bảo làm thế là kiệt sức. Bạn ấy làm rồi nên biết.", "부반장 해 달라고 했어. 근데 수아가 물어보지도 않고 정하냐고.": "Con nhờ bạn ấy làm lớp phó. Nhưng Sua bảo sao không hỏi mà đã quyết.", "싫다고 한 거야?": "Bạn ấy bảo không thích à?", "아니. 먼저 물어보래.": "Không ạ. Bạn ấy bảo phải hỏi trước.", "하고 싶은 거 먼저 물어보겠다고 했어. 수아가 한참 생각하더니, {@picture} 규칙표 계속 만들고 싶대.": "Con bảo con muốn hỏi trước xem bạn ấy muốn làm gì. Sua nghĩ rất lâu rồi bảo muốn làm tiếp bảng quy tắc {@picture}.", "수아가 하고 싶은 걸 처음 들었네.": "Lần đầu con nghe điều Sua muốn làm nhỉ.", "수아는 반장 되면 나한테 새 친구 도우미 맡긴대. 내가 뭐가 어려운지 아니까. 근데 먼저 물어보겠대.": "Sua bảo nếu làm lớp trưởng sẽ giao cho con làm người giúp bạn mới. Vì con biết cái gì khó. Nhưng bạn ấy sẽ hỏi trước.", "둘 다 서로한테 물어보네.": "Hai đứa đều hỏi nhau nhỉ.", "응. {m}, 나 처음엔 수아처럼 되고 싶었거든.": "Vâng. {m} ơi, lúc đầu con muốn được giống Sua.", "지금은?": "Còn bây giờ?", "지금은 수아랑 같이 하고 싶어.": "Bây giờ con muốn cùng làm với Sua.", "결과 발표가 끝났다. 교실은 시끄러웠다. 나는 수아를 찾아 복도 창가로 갔다. 수아가 먼저 와 있었다.": "Công bố kết quả xong. Lớp học ồn ào. Mình đi tìm Sua ra cửa sổ hành lang. Sua đã đến trước rồi.", "축하해.": "Chúc mừng cậu.", "솔직히 속상해. 많이.": "Nói thật là tớ buồn. Buồn lắm.", "수아는 울지 않았다. 대신 형광펜을 꽉 쥐고 있었다.": "Sua không khóc. Thay vào đó Sua nắm chặt cây bút dạ quang.", "근데 너 ‘괜찮아?’ 할 때. 나도 거기서 조용해졌어.": "Nhưng lúc cậu nói 'Cậu ổn không?'. Tớ cũng im lặng ở chỗ đó.", "……규칙 정리하는 거 필요하면 말해. 아, 물어보는 거 맞지? 물어볼게. 필요해?": "...Nếu cần người tóm tắt quy tắc thì bảo tớ. À, phải hỏi đúng không? Tớ hỏi nhé. Cậu cần không?", "응. 필요해.": "Ừ. Tớ cần.", "그럼 다음 선거 때 보자. 그땐 진짜 안 질 거야.": "Vậy hẹn kỳ bầu cử sau. Lúc đó tớ nhất định không thua đâu.", "수아가 {@blackboard} 쪽을 돌아봤다. {@blackboard}에는 두 이름이 나란히 적혀 있었다. 내 이름, 그리고 수아 이름.": "Sua quay lại nhìn về phía {@blackboard}. Trên {@blackboard} có hai cái tên viết cạnh nhau. Tên mình, và tên Sua.", "……같이래.": "...Cùng nhau đấy.", "응. 같이.": "Ừ. Cùng nhau.", "나 혼자 되고 싶었어. 조금.": "Tớ đã muốn làm một mình. Một chút.", "나도. 조금.": "Tớ cũng thế. Một chút.", "둘이 동시에 웃음이 터졌다.": "Hai đứa cùng bật cười.", "정리하면, 반장이 둘이야. 그럼 뭐부터 나눠?": "Tóm lại là, có hai lớp trưởng. Vậy chia việc gì trước?", "……그거 먼저 물어보는 거 맞지?": "...Cái đó phải hỏi trước đúng không?", "응. 이번엔 내가 먼저 물을게. 너는 뭐 하고 싶어?": "Ừ. Lần này tớ hỏi trước. Cậu muốn làm gì?", "새로 온 친구 챙기기. 그리고 바뀌는 거 미리 알려 주기.": "Chăm sóc bạn mới đến. Và báo trước những gì sẽ thay đổi.", "그럼 나는 회의 정리랑 시간 재기. 규칙표는 같이.": "Vậy tớ lo tóm tắt cuộc họp với bấm giờ. Bảng quy tắc thì cùng làm.", "{@picture}은 내가.": "{@picture} là tớ.", "{@stairs}도 너.": "{@stairs} cũng là cậu.", "첫날 너 나 보고 멋있다고 생각했지? 민호 막을 때.": "Hôm đầu tiên cậu nhìn tớ và nghĩ tớ ngầu đúng không? Lúc tớ ngăn Minho.", "……어떻게 알았어?": "...Sao cậu biết?", "얼굴에 다 쓰여 있었어. 근데 지금은 내가 너 보고 그래.": "Hiện hết lên mặt cậu rồi. Nhưng giờ thì tớ nhìn cậu và nghĩ thế.", "목이 따끔했다. 나는 창밖만 봤다.": "Cổ họng mình cay cay. Mình chỉ nhìn ra ngoài cửa sổ.", "너 ‘괜찮아?’ 할 때, 애들 다 조용해졌어. 나 그거 무서웠어. 질 줄 알았어.": "Lúc cậu nói 'Cậu ổn không?', cả lớp im phăng phắc. Tớ sợ lắm. Tớ tưởng mình thua rồi.", "……진짜?": "...Thật á?", "응. 그래서 말인데, 새 친구 도우미. 해 볼래? 하고 싶은지 먼저 묻는 거야.": "Ừ. Nên là, người giúp bạn mới. Cậu làm thử không? Tớ hỏi trước xem cậu có muốn không đấy.", "(속상해. 근데 수아가 진짜로 물어봤어.)": "(Buồn lắm. Nhưng Sua đã thật sự hỏi mình.)", "……생각해 볼게. 근데 아마 할 것 같아.": "...Để tớ nghĩ đã. Nhưng chắc là tớ sẽ làm.", "정리하면, 할 거라는 거지?": "Tóm lại là, cậu sẽ làm đúng không?", "……우리 둘 다 떨어졌네.": "...Cả hai đứa mình đều trượt rồi.", "정리하면, 둘이 표를 나눠 가졌다는 거지.": "Tóm lại là, hai đứa chia nhau số phiếu.", "둘 다 잠깐 말이 없었다. 교실 안에서 새 반장이 친구들한테 둘러싸여 있었다.": "Cả hai im lặng một lúc. Trong lớp, lớp trưởng mới đang được các bạn vây quanh.", "……우리 가서 축하해 줄까?": "...Bọn mình ra chúc mừng bạn ấy nhé?", "응. 같이 가자.": "Ừ. Cùng đi.", "그리고 규칙표는 반장 아니어도 만들 수 있잖아.": "Với lại bảng quy tắc thì không phải lớp trưởng cũng làm được mà.", "수아가 먼저 말했다.": "Sua nói trước.", "떨어졌다.": "Tớ trượt rồi.", "……내가 돼서 미안. 아니, 미안한 건 아닌데. 그냥.": "...Xin lỗi vì tớ được bầu. À không, không phải là xin lỗi. Chỉ là...", "……우리 둘 다.": "...Cả hai đứa mình.", "수아가 창틀에 팔을 걸쳤다. 나도 옆에 섰다. 어깨가 거의 닿을 만큼.": "Sua tựa tay lên khung cửa sổ. Mình cũng đứng cạnh. Vai gần như chạm nhau.", "있잖아. 선거 끝나면 경쟁자 아니잖아.": "Này. Bầu cử xong thì không còn là đối thủ nữa.", "그럼 이제 뭐야, 우리?": "Vậy giờ bọn mình là gì?", "……그냥 친구?": "...Chỉ là bạn?", "그냥은 별로야. 정리해 봐.": "'Chỉ là' thì chán lắm. Tóm lại xem nào.", "음…… 제일 친한 친구.": "Ừm... bạn thân nhất.", "수아가 형광펜을 꺼내더니 자기 손등에 작게 별을 그렸다. 그리고 내 손등에도 그렸다.": "Sua lấy bút dạ quang ra, vẽ một ngôi sao nhỏ lên mu bàn tay của bạn ấy. Rồi vẽ lên cả mu bàn tay mình.", "정리 완료. 지워지면 다시 그려 줄게.": "Tóm tắt xong. Phai đi thì tớ vẽ lại cho.", "……떨어졌네.": "...Trượt rồi nhỉ.", "근데 너 아까 발표 끝나자마자 {bff}한테 먼저 갔지?": "Nhưng lúc nãy vừa công bố xong là cậu chạy đến chỗ {bff} trước đúng không?", "……봤어?": "...Cậu thấy à?", "응. {bff}도 너 찾고 있었어. 둘이 똑같은 얼굴이던데.": "Ừ. {bff} cũng đang tìm cậu. Hai đứa mặt y hệt nhau.", "수아가 웃었다.": "Sua cười.", "반장보다 그게 더 어려울걸. 한 사람이랑 진짜 친해지는 거.": "Cái đó còn khó hơn làm lớp trưởng ấy. Thật sự thân với một người.", "……나는 아직 그런 친구 없어. 다들 반장한테 말 거는 거라서.": "...Tớ vẫn chưa có người bạn như thế. Ai cũng nói chuyện với tớ vì tớ là lớp trưởng.", "너도 생길 거야.": "Cậu cũng sẽ có thôi.", "정리하면, 나도 좀 덜 바빠야 한다는 거지.": "Tóm lại là, tớ cũng phải bớt bận đi một chút.", "복도 창가에 나 혼자가 아니었다. 그룹 친구들이 우르르 따라 나왔다. 그 안에 수아도 있었다.": "Ở cửa sổ hành lang không chỉ có mình mình. Các bạn trong nhóm ùa ra theo. Trong đó có cả Sua.", "……떨어졌다.": "...Trượt rồi.", "아, 나는 됐지. 근데 우리 중에선 나 혼자네.": "À, tớ thì được bầu rồi. Nhưng trong nhóm mình chỉ có mỗi tớ.", "친구들이 웃었다.": "Các bạn cười.", "친구들이 서로 어깨를 툭툭 쳤다. 누가 「괜찮아, 괜찮아」 했다. 내가 맨날 하던 말이었다.": "Các bạn vỗ vai nhau. Có ai đó nói: \"Không sao, không sao.\" Câu mà ngày nào mình cũng nói.", "우리 반장 아니어도 할 거 많잖아. 정리해 볼까?": "Không làm lớp trưởng thì bọn mình vẫn có nhiều việc để làm mà. Tóm tắt thử nhé?", "또 정리해?": "Lại tóm tắt à?", "응. 1번, 점심에 같이 앉기. 2번, 규칙표 만들기. 3번……": "Ừ. Số 1, trưa ngồi ăn cùng nhau. Số 2, làm bảng quy tắc. Số 3...", "친구들: 「3번은 놀기!」": "Các bạn: \"Số 3 là đi chơi!\"", "……3번 놀기. 통과.": "...Số 3 đi chơi. Thông qua.", "떨어졌네.": "Trượt rồi nhỉ.", "그때 교실 {@door}이 열리고, 내 그룹 친구들이 나를 찾아 나왔다. 「야, 어디 갔었어!」": "Đúng lúc đó {@door} lớp mở ra, các bạn trong nhóm mình chạy ra tìm mình. \"Này, cậu đi đâu thế!\"", "……너 찾으러 왔네.": "...Các bạn đến tìm cậu kìa.", "부럽다. 반장 되면 다들 일 얘기만 하러 오거든. 너는 그냥 너라서 오는 거잖아.": "Ghen tị thật. Làm lớp trưởng thì ai đến cũng chỉ để nói chuyện công việc. Còn cậu thì mọi người đến vì cậu là cậu.", "……너도 같이 갈래? 점심 같이 먹자.": "...Cậu đi cùng không? Ăn trưa cùng nhau đi.", "수아가 잠깐 망설였다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "Sua ngập ngừng một chút. Rồi bạn ấy đóng nắp bút dạ quang lại, tách một cái.", "……한 번만.": "...Một lần thôi đấy.", "……나는 됐고.": "...Tớ thì được bầu rồi.", "응. 괜찮아.": "Ừ. Không sao.", "그때 교실 안에서 누가 외쳤다.": "Đúng lúc đó có ai trong lớp hét lên.", "야! 이거 너네 나라 말로 뭐라고 해? 빨리 와 봐!": "Này! Cái này tiếng nước cậu gọi là gì? Ra đây nhanh lên!", "교실 뒤 게시판에는 두 나라 말로 된 낱말 카드가 붙어 있었다. {@desk}, {w}, {@cat}, 나비. 아이들이 하나씩 붙인 거였다.": "Trên bảng tin cuối lớp có dán thẻ từ bằng hai thứ tiếng. {@desk}, {w}, {@cat}, con bướm. Các bạn mỗi người dán một cái.", "저거 언제 저렇게 됐어?": "Cái đó thành ra thế từ bao giờ vậy?", "……나도 몰라. 애들이 하나씩 물어보더니.": "...Tớ cũng không biết. Các bạn cứ hỏi từng cái một rồi thành thế.", "{U@notebook}.": "{U@notebook}.", "수아가 우리 말로 말했다. 발음이 좀 틀렸다.": "Sua nói bằng tiếng nước mình. Phát âm hơi sai.", "응. 맞아.": "Ừ. Đúng rồi.", "……반장보다 그게 더 멋있다. 반 애들이 너한테 배우잖아.": "...Cái đó còn ngầu hơn làm lớp trưởng. Các bạn trong lớp học từ cậu đấy.", "정리하면, 너는 선생님이고 나는 학생이야. 오늘만.": "Tóm lại là, cậu là giáo viên, còn tớ là học sinh. Chỉ hôm nay thôi.", "……나는 됐어.": "...Tớ thì được bầu rồi.", "수아가 내 {@hand}에 들린 {w}을 봤다.": "Sua nhìn {w} trên {@hand} mình.", "첫날 쓴 거. 반 친구 이름.": "Cái cậu viết hôm đầu tiên. Tên các bạn trong lớp.", "{w}을 펼쳤다. 첫날 적은 이름 몇 개 밑에, 새 이름이 몇 개 더 있었다. 수아 이름도 있었다.": "Mình mở {w} ra. Bên dưới mấy cái tên viết hôm đầu tiên có thêm vài cái tên mới. Có cả tên Sua.", "다음 학기에 또 나가?": "Học kỳ sau cậu lại ứng cử à?", "……응. 나갈래.": "...Ừ. Tớ sẽ ứng cử.", "그럼 그때는 이름 더 많이 적어 와. 다 적으면 나 진짜 질 수도 있겠다.": "Thế thì lúc đó viết thêm thật nhiều tên nhé. Viết hết thì có khi tớ thua thật đấy.", "다음 학기에 보자. 경쟁자.": "Hẹn học kỳ sau nhé. Đối thủ.", "{m}, 선거 결과 나왔어.": "{m}, có kết quả bầu cử rồi.", "나 됐어! 수아가 축하한다고 했어. 근데 많이 속상하대.": "Con được bầu rồi! Sua chúc mừng con. Nhưng bạn ấy bảo buồn lắm.", "축하해. 그리고 그걸 솔직하게 말해 준 수아도 대단하다.": "Chúc mừng con. Sua thật lòng nói ra như thế cũng giỏi lắm.", "수아가 필요하면 도와준대. 먼저 물어보고.": "Sua bảo nếu cần thì bạn ấy sẽ giúp. Mà sẽ hỏi trước.", "나랑 수아랑 둘 다 반장 됐어! 같이!": "Con với Sua đều được làm lớp trưởng! Cùng nhau!", "둘 다? 와, 축하해!": "Cả hai à? Oa, chúc mừng con!", "수아가 혼자 되고 싶었대, 조금. 나도 조금 그랬다고 했어. 둘이 웃었어.": "Sua bảo đã muốn làm một mình, một chút. Con bảo con cũng thế, một chút. Hai đứa cùng cười.", "솔직한 반장 둘이네.": "Hai lớp trưởng thật thà nhỉ.", "수아가 먼저 뭐 하고 싶냐고 물어봤어. 나는 새 친구 챙기기, 수아는 회의 정리.": "Sua hỏi con trước là muốn làm gì. Con thì chăm sóc bạn mới, Sua thì tóm tắt cuộc họp.", "수아가 됐어.": "Sua được bầu rồi ạ.", "……속상하지?": "...Con buồn lắm phải không?", "응. 근데 수아가 새 친구 도우미 하고 싶은지 물어봤어. 할 것 같아.": "Vâng. Nhưng Sua hỏi con có muốn làm người giúp bạn mới không. Chắc con sẽ làm.", "반장 아니어도 할 수 있는 일이 생겼네.": "Có việc con làm được dù không phải lớp trưởng rồi.", "나도 수아도 떨어졌어. 둘이 같이 가서 새 반장 축하해 줬어.": "Con với Sua đều trượt. Hai đứa cùng đi chúc mừng lớp trưởng mới.", "그거 쉽지 않은데.": "Làm được thế không dễ đâu.", "수아가 규칙표는 반장 아니어도 만들 수 있대.": "Sua bảo không phải lớp trưởng cũng làm bảng quy tắc được.", "떨어졌어. 근데 {m}, 이거 봐.": "Con trượt rồi. Nhưng {m} ơi, xem này.", "나는 손등의 별을 보여 줬다.": "Mình cho mẹ xem ngôi sao trên mu bàn tay.", "이게 뭐야?": "Cái gì đây?", "수아가 그렸어. 제일 친한 친구 표시. 지워지면 다시 그려 준대.": "Sua vẽ đấy. Dấu hiệu bạn thân nhất. Phai đi thì bạn ấy vẽ lại cho.", "……반장보다 귀한 거 받았네.": "...Con được nhận thứ quý hơn chức lớp trưởng rồi.", "떨어졌어. 근데 발표 끝나자마자 {bff}한테 먼저 갔어. 수아가 봤대. 둘이 똑같은 얼굴이었대.": "Con trượt rồi. Nhưng vừa công bố xong con chạy đến chỗ {bff} trước. Sua thấy. Bạn ấy bảo hai đứa mặt y hệt nhau.", "그런 친구가 생겼구나.": "Con có được người bạn như thế rồi nhỉ.", "수아가 한 사람이랑 진짜 친해지는 게 반장보다 어렵대.": "Sua bảo thật sự thân với một người còn khó hơn làm lớp trưởng.", "떨어졌어. 근데 우리 그룹이 다 같이 나와서 괜찮다고 해 줬어. 수아도 있었어. 수아가 할 일 정리했어. 3번은 놀기래.": "Con trượt rồi. Nhưng cả nhóm con cùng ra bảo không sao. Có cả Sua. Sua tóm tắt việc cần làm. Số 3 là đi chơi.", "제일 중요한 게 3번이네.": "Quan trọng nhất là số 3 nhỉ.", "떨어졌어. 근데 우리 그룹 애들이 나 찾으러 왔어. 수아가 부럽대. 나는 그냥 나라서 다들 온다고. 그래서 수아한테 점심 같이 먹자고 했어.": "Con trượt rồi. Nhưng các bạn trong nhóm đến tìm con. Sua bảo ghen tị. Bảo mọi người đến vì con là con. Nên con rủ Sua ăn trưa cùng.", "한 번만, 이래.": "Bạn ấy bảo: một lần thôi.", "떨어졌어. 근데 {m}, 교실 뒤에 우리 말 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "Con trượt rồi. Nhưng {m} ơi, cuối lớp có dán thẻ từ tiếng nước mình! Các bạn cứ hỏi từng cái một rồi thành thế. Sua cũng nói theo {U@notebook}.", "……우리 말을?": "...Tiếng nước mình á?", "응. 내가 선생님이래. 오늘만.": "Vâng. Bạn ấy bảo con là giáo viên. Chỉ hôm nay thôi.", "{m}는 오늘이 제일 기쁘다.": "Hôm nay là ngày {m} vui nhất.", "떨어졌어. 근데 첫날 {w} 봤는데, 이름이 좀 늘었어. 수아 이름도 있어.": "Con trượt rồi. Nhưng con xem {w} viết hôm đầu tiên, tên đã nhiều thêm một chút. Có cả tên Sua.", "다음 학기엔?": "Học kỳ sau thì sao?", "또 나갈 거야. 수아가 그땐 이름 더 많이 적어 오래.": "Con sẽ lại ứng cử. Sua bảo lúc đó viết thêm thật nhiều tên mang đến.", "그럼 내일부터 또 한 명씩.": "Vậy từ mai lại từng người một nhé."});
T.zh=T.zh||{};Object.assign(T.zh,{"아침. 수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "早上。秀雅在教室前面用荧光笔勾着什么。我走到秀雅身边。", "수아야. 규칙…… 외워 왔어.": "秀雅，规则……我背好了。", "진짜? 그럼 확인해 볼까.": "真的？那我来考考你。", "수아가 형광펜 뚜껑을 딸깍 닫았다.": "秀雅“咔嗒”一声盖上了荧光笔。", "규칙 3번.": "规则第3条。", "교실에서 뛰지 않기.": "不在教室里跑。", "5번.": "第5条。", "친구 밀지 않기.": "不推朋友。", "오, 좀 하는데? 그럼 7번.": "哦，挺厉害嘛？那第7条。", "비상시에는 {@handkerchief}으로 입을 막고, 자세를 낮춰 이동한다.": "紧急时用{@handkerchief}捂住嘴，放低身子移动。", "완벽해.": "完美。", "(……근데 ‘자세를 낮춰’가 무슨 뜻이지? 소리만 외웠어.)": "（……可是“放低身子”是什么意思？我只背了声音。）", "삐— 삐— 삐—!": "哔——哔——哔——！", "방송: 「지금부터 화재 대피 훈련을 시작합니다. 담임 선생님의 안내에 따라…….」": "广播：「现在开始火灾逃生演练。请跟着班主任老师的指引……」", "아이들이 한꺼번에 일어났다. 선생님은 교실 뒤에서 남은 아이가 없는지 확인하고 계셨다.": "大家一下子都站了起来。老师在教室后面看有没有人留下。", "규칙 7번! {@handkerchief} 꺼내! 입 막고, 자세 낮추고, 오른쪽 {@stairs}!": "规则第7条！拿出{@handkerchief}！捂住嘴，放低身子，走右边的{@stairs}！", "수아 말이 너무 빨랐다. 아이들이 줄줄이 복도로 나갔다.": "秀雅说得太快了。同学们一个接一个走到走廊。", "({@handkerchief}…… {@handkerchief}이 뭐였지?)": "（{@handkerchief}……{@handkerchief}是什么来着？）", "{@handkerchief}으로 입을 막았다. 그런데 ‘자세를 낮춰’는 아직도 모르겠다. 앞 친구들은 벌써 복도 끝에 있었다.": "我用{@handkerchief}捂住了嘴。可是我还是不懂“放低身子”。前面的同学已经到走廊尽头了。", "왜 안 와? 내가 7번 말했잖아!": "你怎么不过来？我说了第7条啊！", "(외운 건 맞는데…… 뜻을 몰라.)": "（我是背下来了……可是不懂意思。）", "「{x}」으로 내려가기": "走「{x}」下去", "운동장. 훈련이 끝났다. 수아가 출석부를 들고 내 옆으로 왔다.": "操场。演练结束了。秀雅拿着点名册来到我身边。", "아까 ‘낮춰’ 몰랐던 거지? 이렇게, 몸을 낮게.": "刚才你不懂“放低”，对吧？就是这样，把身体放低。", "……응. 이제 알아.": "……嗯。现在懂了。", "규칙은 외우면 끝인 줄 알았어. 뜻을 모를 수도 있구나.": "我以为规则背下来就好了。原来会不懂意思啊。", "반장은 이런 것까지 다 챙겨야 해. 생각보다 어려워.": "班长连这些都要照顾到。比想的难。", "알아. 그래서 나도 하고 싶어.": "我知道。所以我也想当。", "……뭐?": "……什么？", "나도 반장 선거 나갈 거야.": "我也要参加班长选举。", "수아가 나를 빤히 봤다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "秀雅直直地看着我。然后“咔嗒”一声盖上了荧光笔。", "좋아. 그럼 경쟁이네.": "好。那我们就是对手了。", "근데 너, 아까 뭐가 어려웠는지는 나보다 잘 알겠다.": "不过你啊，刚才哪里难，你比我更清楚吧。", "그 자리에서 수아에게 묻는다. 「천천히! ‘낮춰’가 뭐야?」": "当场问秀雅。「慢一点！“放低”是什么？」", "수아야, 천천히! ‘자세를 낮춰’가 뭐야?": "秀雅，慢一点！“放低身子”是什么？", "수아가 멈칫했다. 그러더니 바로 허리를 숙여 보였다.": "秀雅愣了一下。接着马上弯下腰给我看。", "이렇게! 몸을 낮게. 연기는 위로 올라가니까.": "这样！把身体放低。因为烟会往上飘。", "아! 낮춰!": "啊！放低！", "나는 허리를 숙이고 수아 옆에서 오른쪽 {@stairs}으로 걸었다.": "我弯着腰，在秀雅旁边走向右边的{@stairs}。", "뛰지 마. 걸어.": "别跑。走。", "알아. 3번.": "知道。第3条。", "아는 척 고개를 끄덕이고 앞 친구를 따라 한다.": "假装懂了，点点头，跟着前面的同学。", "나는 고개를 끄덕이고 바로 앞 친구를 따라 했다. 그런데 그 친구는 쪼그려 앉아서 뒤뚱뒤뚱 걷고 있었다.": "我点点头，跟着正前面的同学。可是那个同学蹲着，摇摇摆摆地走。", "그건 오리걸음이잖아!": "那是鸭子步啊！", "앞 친구는 장난을 치던 거였다. 나는 얼굴이 빨개졌다.": "前面的同学是在闹着玩。我的脸一下子红了。", "허리만 숙여. 이렇게.": "只弯腰就行。像这样。", "(모르는데 아는 척하니까 더 이상해졌어.)": "（不懂还装懂，结果更奇怪了。）", "내 나라에서 했던 훈련을 떠올려 판단한다.": "想想在我们国家做过的演练，自己判断。", "(우리 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "（我们学校也做过这个。着火时烟往上走，所以要弯下身子。）", "(‘낮춰’는 그거구나!)": "（“放低”就是那个啊！）", "나는 허리를 숙이고, 벽에 붙은 초록색 비상구 {@picture}을 따라 {@stairs} 쪽으로 걸었다.": "我弯着腰，跟着墙上绿色的安全出口{@picture}，朝{@stairs}走去。", "수아가 뒤돌아보다가 눈을 동그랗게 떴다.": "秀雅回头一看，眼睛瞪得圆圆的。", "어? 맞게 하네?": "咦？你做对了？", "우리 학교에서도 했어.": "我们学校也做过。", "「너 말 너무 빨라!」 하고 화부터 낸다.": "先发火：「你说得太快了！」", "너 말 너무 빨라! 하나도 몰라!": "你说得太快了！我一点都听不懂！", "지금 훈련 중이야! 그냥 따라와!": "现在在演练！跟着来就行！", "수아가 내 팔을 잡아끌었다. 둘 다 얼굴이 빨개진 채로 {@stairs}까지 갔다.": "秀雅拉着我的胳膊走。我们两个都红着脸走到了{@stairs}。", "(화는 났는데, ‘낮춰’는 아직도 몰라.)": "（我是生气了，可还是不懂“放低”。）", "{m}, 오늘 대피 훈련 했어. 어제 외운 규칙 7번이 나왔어.": "{m}，今天我们做了逃生演练。昨天背的规则第7条用上了。", "어머, 바로 써먹었네?": "哎呀，马上就用上了？", "근데 나 ‘자세를 낮춰’가 무슨 뜻인지 몰랐어. 소리만 외웠거든.": "可是我不懂“放低身子”是什么意思。我只背了声音。", "그래서 수아한테 천천히 말해 달라고, 낮춰가 뭐냐고 물었어. 수아가 허리 숙여서 보여 줬어.": "所以我请秀雅说慢一点，问她“放低”是什么。秀雅弯下腰给我看了。", "모르는 거 그 자리에서 물어봤구나. {m}가 첫날 말한 거 기억했네.": "不懂的当场就问了啊。你记住了{m}第一天说的话。", "응. 물어보니까 금방이었어.": "嗯。一问就懂了。", "아는 척하고 앞에 애를 따라 했는데, 걔가 오리걸음으로 장난치는 거였어.": "我装懂，跟着前面的同学，结果他是在用鸭子步闹着玩。", "너도 오리걸음 했어?": "你也走鸭子步了？", "{m}! 웃지 마. 수아가 그건 오리걸음이라고 소리쳤어.": "{m}！别笑。秀雅大喊那是鸭子步。", "미안, 미안. 모를 땐 그냥 물어봐도 돼.": "对不起，对不起。不懂的时候直接问就好。", "우리 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "我想起了在我们学校做过的演练。因为有烟，要弯下身子。所以我做对了。", "아, 거기서도 했었지! 기억하고 있었구나.": "啊，那边也做过！你还记得呀。", "수아가 어? 맞게 하네? 그러더라.": "秀雅说：咦？你做对了？", "모르는 말도 아는 걸로 알아낼 수 있구나.": "不懂的话，也能用知道的东西弄明白呢。", "수아한테 너무 빠르다고 화냈어. 수아도 지금 훈련 중이라고 화냈고.": "我对秀雅发火，说她太快了。秀雅也发火，说现在在演练。", "둘 다 급했구나.": "你们两个都着急了啊。", "응. 나중에 수아가 낮춰가 뭔지 알려 줬어.": "嗯。后来秀雅告诉我“放低”是什么了。", "다음엔 화내기 전에 ‘천천히’부터 말해 볼까?": "下次发火之前，先说“慢一点”试试？", "그리고 {m}. 나 수아한테 반장 선거 나간다고 말했어.": "还有，{m}。我跟秀雅说我要参加班长选举了。", "정말? 수아가 뭐래?": "真的？秀雅怎么说？", "좋아, 그럼 경쟁이네, 그랬어.": "她说：好，那我们就是对手了。", "멋있는 경쟁자네.": "真是个帅气的对手。", "도서관 구석 {@desk}. 수아가 큰 {@paper}를 펼쳐 놓고 있었다. 나는 수아 맞은편에 앉았다.": "图书馆角落的{@desk}。秀雅摊开了一张大{@paper}。我坐在秀雅对面。", "수아야, 뭐 해?": "秀雅，你在干什么？", "규칙표 다시 만들어. {@picture}으로.": "重新做规则表。用{@picture}做。", "어제 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "可能还有同学像昨天演练时的你一样，只背了声音呀。", "……그거 좋다.": "……这个好。", "같이 할래? 내가 글 쓰고, 넌 {@picture}.": "一起做吗？我写字，你画{@picture}。", "좋아.": "好。", "「{x}」 고르기": "选「{x}」", "수아는 정말 빨랐다. 순식간에 문장 다섯 개를 써 내려갔다.": "秀雅真的好快。一下子就写了五句话。", "1번, 3번, 5번은 읽을 수 있었다. 그런데 7번 아래 새로 쓴 문장 하나가 걸렸다.": "第1、3、5条我都能读懂。可是第7条下面新写的一句卡住了我。", "{@paper}에 쓰인 글: 「연기가 나면 몸을 낮추고 벽을 짚으며 이동한다.」": "{@paper}上写着：「有烟时，放低身子，扶着墙移动。」", "(낮추고는 알아. 근데 ‘벽을 짚으며’는 뭐지?)": "（“放低”我懂。可是“扶着墙”是什么？）", "자, {@picture} 그리면 돼. 쉬는 시간 10분 남았어.": "好，画{@picture}就行。课间还剩10分钟。", "수아는 벌써 다음 줄을 쓰고 있었다.": "秀雅已经在写下一行了。", "그러다 수아가 {@stairs} {@picture}을 직접 그려 보겠다며 펜을 들었다. {@paper}에 꼬불꼬불한 선이 생겼다.": "后来秀雅说要自己画{@stairs}的{@picture}，拿起了笔。{@paper}上出现了弯弯曲曲的线。", "……그건 뭐야?": "……那是什么？", "{@stairs}.": "{@stairs}。", "빨래판인 줄 알았어.": "我还以为是搓衣板。", "……그러니까 네가 그려.": "……所以你来画。", "({@picture}은 내가 잘할 수 있어. 근데 ‘짚으며’를 모르면 뭘 그려야 하지?)": "（画{@picture}我拿手。可是不懂“扶着”，要画什么呢？）", "쉬는 시간이 끝나기 전에 규칙표가 완성됐다. 수아는 맨 아래에 두 사람 이름을 나란히 적었다.": "课间结束前，规则表做好了。秀雅在最下面并排写了两个人的名字。", "정리하면, 글은 나, {@picture}은 너.": "总结一下，字是我写的，{@picture}是你画的。", "{@stairs}도 나.": "{@stairs}也是我画的。", "……{@stairs}도 너.": "……{@stairs}也是你画的。", "아는 문장만 그리고, 모르는 문장 칸은 비워 둔다.": "只画懂的句子，不懂的那一格空着。", "나는 1번, 3번, 5번만 그렸다. 7번 칸은 비워 뒀다.": "我只画了第1、3、5条。第7条那一格空着。", "7번은?": "第7条呢？", "……그건 나중에.": "……那个以后再说。", "제일 중요한 건데?": "那是最重要的呀？", "‘짚으며’를 몰라서.": "因为我不懂“扶着”。", "아, 그래? 그럼 처음부터 말하지.": "啊，是吗？那你一开始就说嘛。", "모르는 말에 동그라미를 치고 묻는다. 「이거 무슨 뜻이야?」": "把不懂的词圈起来，问：「这是什么意思？」", "나는 ‘짚으며’에 {@pencil}로 동그라미를 쳤다.": "我用{@pencil}把“扶着”圈了起来。", "이거 무슨 뜻이야?": "这是什么意思？", "벽을 짚으며? {@hand}을 벽에 대고 가는 거.": "扶着墙？就是把{@hand}放在墙上走。", "수아가 손바닥을 책장에 붙여 보였다.": "秀雅把手掌贴在书架上给我看。", "아! 그럼 {@hand}을 벽에 대고, 허리 숙이고, 걷는 사람.": "啊！那就是{@hand}放在墙上，弯着腰，走路的人。", "응. 그거.": "嗯。就是那样。", "나는 그 모습을 그렸다. 수아가 {@picture}을 보더니 고개를 끄덕였다.": "我画出了那个样子。秀雅看了{@picture}，点了点头。", "내가 이해한 대로 먼저 그려서 보여 준다. 「이거 맞아?」": "先按自己懂的画出来给她看。「这样对吗？」", "나는 내가 이해한 대로 그렸다. 연기 아래에서 바닥을 짚고 엉금엉금 기어가는 사람.": "我按自己懂的画了。一个人在烟下面，手撑着地，慢慢地爬。", "이거 맞아?": "这样对吗？", "……기어가라는 게 아니고!": "……不是让你爬啦！", "수아가 웃음을 터뜨렸다. 도서관이라 둘 다 입을 막았다.": "秀雅一下子笑了出来。因为在图书馆，我们两个都捂住了嘴。", "바닥 말고 벽. {@hand}을 벽에 대고 걷는 거야.": "不是地，是墙。把{@hand}放在墙上走。", "아, 벽! 그럼 이렇게?": "啊，墙！那是这样？", "나는 {@picture}을 고쳤다. 수아가 {@picture}을 보더니 자기 문장을 다시 봤다.": "我改了{@picture}。秀雅看了{@picture}，又看了看自己写的句子。", "{@picture} 보니까 내 문장이 너무 기네. 줄일게.": "看了{@picture}，我觉得我的句子太长了。我改短一点。", "「수아야, 그냥 네가 다 해. 넌 다 잘하잖아.」": "「秀雅，你全做了吧。你什么都做得好。」", "그냥 네가 다 해. 넌 다 잘하잖아.": "你全做了吧。你什么都做得好。", "나 {@picture} 못 그리는 거 방금 봤잖아.": "你刚才不是看到了吗，我不会画{@picture}。", "……그래도.": "……可是。", "그래도는 무슨. 빨래판 {@stairs} 붙일 거야?": "可是什么呀。你要贴搓衣板{@stairs}吗？", "수아가 {@colored_pencil} 통을 내 쪽으로 밀었다.": "秀雅把{@colored_pencil}盒推到我这边。", "네가 그려. 모르는 거 있으면 물어보고.": "你来画。有不懂的就问。", "{m}, 수아랑 규칙표 만들었어. 수아가 글 쓰고 내가 {@picture} 그렸어.": "{m}，我和秀雅做了规则表。秀雅写字，我画{@picture}。", "오, {@picture}은 네가?": "哦，{@picture}是你画的？", "응. 수아 {@picture} 진짜 못 그려. {@stairs}을 그렸는데 빨래판 같았어.": "嗯。秀雅真的不会画{@picture}。她画了{@stairs}，看起来像搓衣板。", "수아도 못하는 게 있구나.": "原来秀雅也有不会的呀。", "근데 나 모르는 말이 있어서 그 칸은 비워 뒀어. 수아가 제일 중요한 거라고, 처음부터 말하지 그랬냐고 하더라.": "可是有个词我不懂，所以那一格我空着。秀雅说那是最重要的，问我怎么不一开始就说。", "그럼 그 칸은 어떻게 했어?": "那那一格怎么办了？", "결국 물어보고 그렸어.": "最后我问了，然后画了。", "처음부터 물었으면 더 빨랐겠다.": "一开始就问的话会更快吧。", "‘짚으며’를 몰라서 동그라미 치고 물어봤어. 수아가 {@hand}을 책장에 대고 보여 줬어.": "我不懂“扶着”，就圈起来问了。秀雅把{@hand}放在书架上给我看。", "그래서 {@picture}이 맞게 됐어?": "所以{@picture}画对了吗？", "응. 수아가 고개 끄덕였어.": "嗯。秀雅点头了。", "내가 이해한 대로 그렸는데, 사람이 바닥을 기어가고 있었어.": "我按自己懂的画了，结果画的人在地上爬。", "기어가?": "爬？", "수아가 기어가라는 게 아니고! 하면서 웃었어. 근데 수아가 {@picture} 보더니 자기 문장이 너무 길대. 줄였어.": "秀雅一边说“不是让你爬啦！”一边笑。可是秀雅看了{@picture}以后，说自己的句子太长了。她改短了。", "{@picture} 덕분에 글도 바뀌었네.": "因为{@picture}，字也改了呀。", "수아한테 그냥 네가 다 하라고 했어. 넌 다 잘하니까.": "我跟秀雅说你全做了吧。因为你什么都做得好。", "수아가 뭐래?": "秀雅怎么说？", "빨래판 {@stairs} 붙일 거냐고. 그래서 내가 그렸어.": "她问我要不要贴搓衣板{@stairs}。所以我画了。", "수아 말이 맞네. {@picture}은 네가 더 잘하잖아.": "秀雅说得对。{@picture}是你画得更好嘛。", "방금 학급회의가 끝났다. 안건은 ‘금요일 학급 놀이 시간에 뭐 할까’였다.": "班会刚结束。议题是“星期五班级游戏时间玩什么”。", "나는 처음으로 {@hand}을 들고 우리 나라 놀이를 말했다. 떨려서 말이 엉켰다.": "我第一次举起{@hand}，说了我们国家的游戏。我太紧张了，话说得乱七八糟。", "(아까 수아가 한 말) 「음…… 규칙이 복잡해 보여서 어려울 것 같아요. 다음 의견!」": "（刚才秀雅说的话）「嗯……规则看起来很复杂，好像会很难。下一个意见！」", "결국 피구로 정해졌다. 아이들이 {@chair}를 정리하며 흩어졌다. 나는 수아에게 갔다.": "最后定了玩躲避球。同学们整理好{@chair}就散了。我走到秀雅身边。", "「{x}」 넣기": "放进「{x}」", "수아야, 아까 내 놀이…….": "秀雅，刚才我的游戏……", "아, 그거! 나도 얘기하려고 했어.": "啊，那个！我也正想说。", "수아가 주위를 한 번 둘러보더니 목소리를 낮췄다.": "秀雅看了看四周，压低了声音。", "……사실 나, 하나도 못 알아들었어.": "……其实我一点都没听懂。", "어?": "咦？", "네가 말할 때 ‘수건’이랑 ‘같은 편’은 들렸는데, 나머지는 몰랐어. 근데 반장이 못 알아들었다고 하면 이상하잖아.": "你说的时候我听到了“手帕”和“同一队”，别的都不懂。可是班长说没听懂，很奇怪吧。", "그래서 그냥 어렵다고 넘긴 거야.": "所以我就说难，跳过去了。", "(수아도…… 나를 못 알아들었구나.)": "（秀雅也……没听懂我的话啊。）", "(대피 훈련 때 내가 수아 말을 못 알아들은 거랑 똑같네.)": "（跟逃生演练时我没听懂秀雅的话一样。）", "다시 설명해 줄래? 이번엔 진짜 들을게.": "你能再讲一遍吗？这次我真的会好好听。", "수아가 형광펜을 꺼내 학급회의 {w}에 적었다.": "秀雅拿出荧光笔，写在班会{w}上。", "수아의 {w}: 「다음 학급회의 안건: 같은 편 {@handkerchief} 놀이」": "秀雅的{w}：「下次班会议题：同一队{@handkerchief}游戏」", "다음 회의에 다시 올리자. 이번엔 제대로.": "下次班会再提出来吧。这次好好来。", "어떻게 설명할까?": "怎么讲呢？", "「말보다 해 보는 게 빨라.」 하고 직접 보여 준다.": "「做一遍比说更快。」直接做给她看。", "말보다 해 보는 게 빨라. 앉아 봐.": "做一遍比说更快。你坐下。", "나는 수아를 {@chair}에 앉히고 등 뒤로 돌아가 {@handkerchief}을 살짝 놓았다.": "我让秀雅坐在{@chair}上，绕到她背后，轻轻放下{@handkerchief}。", "이제 뒤에 뭐 있는지 봐.": "现在看看你后面有什么。", "어? {@handkerchief}?": "咦？{@handkerchief}？", "그럼 날 잡아야 해. 잡히면 나는 술래 아니고, 네 편이 돼.": "那你就要抓住我。被抓到的话，我就不是鬼了，变成你这一队的。", "……잡히면 같은 편? 그게 다야?": "……被抓到就是同一队？就这样？", "응. 마지막엔 다 같은 편이야.": "嗯。最后大家都是同一队。", "아, 이거 재밌겠다!": "啊，这个好像很好玩！", "「됐어. 어차피 안 된다며.」 하고 돌아선다.": "「算了。反正你说不行。」转身走开。", "됐어. 어차피 안 된다며.": "算了。反正你说不行。", "아니, 그래서 지금 다시…….": "不是，所以现在再……", "피구로 정해졌잖아.": "已经定了玩躲避球嘛。", "나는 {@bag}을 챙겼다. 수아는 형광펜을 만지작거리며 서 있었다.": "我收拾好{@bag}。秀雅摆弄着荧光笔站在那里。", "……다음 학급회의 때 다시 올리면 돼. 마음 바뀌면 말해 줘.": "……下次班会再提出来就行。你改变主意了就告诉我。", "(속상한 건 맞아. 근데 수아는 진짜 듣고 싶어 했는데.)": "（我是很难过。可是秀雅真的很想听。）", "아까 못 한 말까지 한꺼번에 몰아서 설명한다.": "把刚才没说的话一口气全说出来。", "그러니까 동그랗게 앉아서 술래가 돌다가 {@handkerchief}을 뒤에 놓으면 그걸 알아채서 쫓아가는데 잡히면 술래가 안 되고 잡은 사람 편이 되고 그다음엔 그 편이 같이 술래를…….": "就是大家围成圈坐着，鬼转圈，把{@handkerchief}放在谁后面，那个人发现了就去追，被抓到就不当鬼，变成抓的人那一队，然后那一队一起当鬼……", "잠깐, 잠깐! 너도 빨라!": "等等，等等！你也好快！", "수아가 두 {@hand}을 들었다. 우리 둘 다 웃음이 터졌다.": "秀雅举起两只{@hand}。我们两个都笑了出来。", "……대피 훈련 때 너 같았어?": "……逃生演练时，你也像这样？", "응. 딱 나 같았어.": "嗯。跟我一模一样。", "나는 처음부터 다시, 한 문장씩 천천히 말했다.": "我从头开始，一句一句慢慢说。", "아까 속상했던 것부터 말하고, 그다음 설명한다.": "先说刚才难过的事，然后再讲。", "설명할게. 근데 먼저 말할 거 있어.": "我来讲。不过我有话先说。", "아까 바로 다음 의견, 해서 좀 속상했어. 처음으로 {@hand} 들었거든.": "刚才你马上说“下一个意见”，我有点难过。那是我第一次举{@hand}。", "……그랬구나. 미안. 못 알아들은 거 들킬까 봐 빨리 넘긴 거야.": "……原来是这样。对不起。我怕被发现没听懂，就赶快跳过去了。", "이제 천천히 할게. 동그랗게 앉아. 술래가 {@handkerchief}을 뒤에 놓아. 잡히면 같은 편이 돼.": "现在我慢慢说。围成圈坐。鬼把{@handkerchief}放在后面。被抓到就变成同一队。", "세 문장이네. 정리 잘한다.": "三句话啊。总结得真好。", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. 우리 나라 놀이 하자고.": "{m}，今天班会时我第一次举了{@hand}。说要玩我们国家的游戏。", "정말? 어떻게 됐어?": "真的？结果呢？", "수아가 어려울 것 같다고 바로 다음 의견 했어. 근데 끝나고 수아가 사실 하나도 못 알아들었대.": "秀雅说好像会很难，马上说下一个意见。可是结束后，秀雅说其实她一点都没听懂。", "어머, 수아가 그렇게 말했어?": "哎呀，秀雅这么说了？", "그래서 말 말고 직접 보여 줬어. 수아를 앉히고 {@handkerchief} 놓았지.": "所以我没用说的，直接做给她看了。我让秀雅坐下，放了{@handkerchief}。", "수아는?": "秀雅呢？", "이거 재밌겠다! 그랬어.": "她说：这个好像很好玩！", "해 보니까 금방 알았구나.": "做一遍就马上懂了啊。", "근데 나 너무 속상해서 됐다고 하고 그냥 왔어.": "可是我太难过了，说了算了就回来了。", "속상했겠다. 처음 {@hand} 든 거였잖아.": "一定很难过吧。那是你第一次举{@hand}嘛。", "응. 수아가 다음 회의 때 다시 올리면 된대.": "嗯。秀雅说下次班会再提出来就行。", "그럼 다음엔 어떻게 할래?": "那下次你要怎么做？", "아까 못 한 말 한꺼번에 막 했더니, 수아가 너도 빨라! 그랬어.": "我把刚才没说的话一口气全说了，秀雅说：你也好快！", "대피 훈련 때랑 반대네?": "跟逃生演练时反过来了？", "응. 둘이 웃었어. 그다음엔 천천히 했어.": "嗯。我们两个都笑了。然后我就慢慢说了。", "속상했다고 먼저 말했어. 수아가 미안하대. 못 알아들은 거 들킬까 봐 그랬대.": "我先说了我很难过。秀雅说对不起。她说是怕被发现没听懂。", "수아도 솔직하게 말했네.": "秀雅也说了真心话啊。", "그러고 세 문장으로 설명했더니 정리 잘한대.": "然后我用三句话讲完，她说我总结得真好。", "반장도 못 알아들을 때가 있구나.": "原来班长也有听不懂的时候啊。", "응. 나만 그런 줄 알았어.": "嗯。我还以为只有我这样。", "점심시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "午饭时间。秀雅摊开了班会{w}。我坐在秀雅旁边。", "다음 학급회의 내일이야. 놀이 발표 준비하자.": "下次班会是明天。我们准备游戏发言吧。", "「{x}」 보기": "看「{x}」", "학급회의는 한 사람이 2분 안에 말해야 해. 규칙 12번.": "班会上一个人要在2分钟内说完。规则第12条。", "그래서 생각해 봤는데, 발표는 내가 할게.": "所以我想了想，发言由我来。", "……네가?": "……你来？", "응. 나는 2분 안에 정리할 수 있어. 넌 아직 한국말이 느리잖아. 떨어지면 아깝잖아.": "嗯。我能在2分钟内说完。你韩语还说得慢嘛。没通过就可惜了。", "수아 말은 틀린 데가 없었다. 그래서 더 할 말이 없었다.": "秀雅说的没有一点错。所以我更说不出话了。", "(맞는 말이야. 수아가 하면 통과될 거야.)": "（她说得对。秀雅来说的话会通过的。）", "(근데…… 내 놀이인데.)": "（可是……这是我的游戏啊。）", "종이 울렸다. 수아가 형광펜 뚜껑을 딸깍 닫았다.": "铃响了。秀雅“咔嗒”一声盖上了荧光笔。", "내일 떨지 마.": "明天别紧张。", "너도.": "你也是。", "나는 안 떨어.": "我不会紧张。", "「그럼…… 네가 해.」": "「那……你来吧。」", "그럼…… 네가 해.": "那……你来吧。", "좋아. 내가 깔끔하게 정리할게.": "好。我会说得清清楚楚。", "수아가 형광펜으로 줄을 그었다. 나는 옆에서 고개만 끄덕였다.": "秀雅用荧光笔画了一条线。我在旁边只是点点头。", "(이게 맞는 건가.)": "（这样对吗？）", "「내가 할게. 대신 2분 맞추는 연습 같이 해 줘.」": "「我来说。不过陪我一起练习控制在2分钟。」", "내가 할게. 내 놀이니까.": "我来说。因为是我的游戏。", "2분 넘으면?": "超过2分钟怎么办？", "그러니까 연습 같이 해 줘. 네가 {@clock} 봐 줘.": "所以陪我一起练习。你帮我看{@clock}。", "수아가 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "秀雅看着{@clock}。我从头开始讲。超过了3分钟。", "정리하면, 세 문장만 해. 앉는다. 놓는다. 잡히면 같은 편.": "总结一下，只说三句话。坐下。放下。被抓到就是同一队。", "다시 했다. 1분 50초.": "又讲了一遍。1分50秒。", "……됐네.": "……可以了。", "「넌 그냥 반장이라서 다 하고 싶은 거잖아.」": "「你就是因为是班长，才什么都想做吧。」", "넌 그냥 반장이라서 다 하고 싶은 거잖아.": "你就是因为是班长，才什么都想做吧。", "뭐? 나는 통과되라고 그런 건데!": "什么？我是想让它通过才这样的！", "내 놀이인데 왜 네가 해?": "这是我的游戏，为什么你来说？", "둘 다 목소리가 커졌다. 옆에서 밥 먹던 아이들이 쳐다봤다.": "我们两个声音都变大了。旁边吃饭的同学都看了过来。", "……그럼 네가 해 봐. 2분 넘으면 내가 {@hand} 들 거야.": "……那你说说看。超过2分钟我就举{@hand}。", "「나눠서 하자. 시범은 내가, 규칙 설명은 네가.」": "「我们分开做吧。我来示范，你讲规则。」", "나눠서 하자. 시범은 내가 보여 줄게. 규칙 설명은 네가 해.": "我们分开做吧。我来示范给大家看。你来讲规则。", "시범?": "示范？", "말로 하면 애들이 못 알아들어. 너도 못 알아들었잖아.": "只用说的，大家听不懂。你也没听懂嘛。", "……그건 맞아.": "……这倒是。", "수아가 {w}에 두 칸을 그었다. 한쪽에 ‘시범’, 한쪽에 ‘규칙’.": "秀雅在{w}上画了两格。一边写“示范”，一边写“规则”。", "그럼 넌 몸으로, 난 말로.": "那你用身体，我用嘴。", "{m}, 내일 학급회의에서 우리 나라 놀이 다시 발표해.": "{m}，明天班会上，我要再介绍一次我们国家的游戏。", "오, 누가 발표해?": "哦，谁来发言？", "수아가 자기가 하겠대. 나는 한국말이 느려서 2분 안에 못 할 거래.": "秀雅说她来。她说我韩语慢，2分钟内说不完。", "음…… 그래서?": "嗯……然后呢？", "그럼 네가 하라고 했어.": "我说那你来吧。", "수아가 하는 게 더 나을 것 같았어?": "你觉得秀雅来说更好吗？", "응. 근데 좀 이상해. 내 놀이인데.": "嗯。可是有点怪怪的。这是我的游戏啊。", "그 마음이 드는 게 당연하지.": "会有这种感觉很正常。", "내가 한다고 했어. 대신 수아한테 {@clock} 봐 달라고 했어.": "我说我来说。不过请秀雅帮我看{@clock}。", "몇 분 걸렸어?": "用了几分钟？", "처음엔 3분. 수아가 세 문장만 하라고 해서 1분 50초 됐어.": "一开始3分钟。秀雅让我只说三句话，就变成1分50秒了。", "수아는 시간 재 주고, 너는 발표하고. 둘이 잘 나눴네.": "秀雅计时，你发言。你们分工分得真好。", "너는 반장이라서 다 하고 싶은 거라고 했어. 수아도 화냈어.": "我说她是因为是班长才什么都想做。秀雅也生气了。", "수아는 무슨 마음이었을까?": "秀雅是怎么想的呢？", "통과되라고 그랬대.": "她说是想让它通过才那样的。", "그 말을 듣고 나니까 어때?": "听了这句话，你觉得怎么样？", "……좀 미안해. 그래도 내가 할 거야.": "……有点对不起她。可我还是要自己说。", "나눠서 하자고 했어. 시범은 내가, 규칙 설명은 수아가.": "我说我们分开做吧。我来示范，秀雅讲规则。", "수아도 말로는 못 알아들었잖아. 해 보니까 알았어.": "秀雅只听说的也没听懂嘛。做一遍她就懂了。", "네가 잘하는 걸로 맡았구나.": "你挑了自己擅长的事啊。", "학급회의 시간. 두 번째 안건은 내 놀이였다. 나는 앞으로 나가기 전에 수아 자리로 갔다.": "班会时间。第二个议题是我的游戏。上台之前，我走到秀雅的座位。", "준비됐어?": "准备好了吗？", "수아가 먼저 앞에 나가 규칙을 설명했다. 그런데 아이들이 웅성거렸다.": "秀雅先上台讲了规则。可是同学们议论纷纷。", "아이들: 「잘 모르겠어.」 「만든 사람이 보여 줘!」": "同学们：「不太懂。」「让想出来的人做给我们看！」", "수아가 나를 봤다.": "秀雅看着我。", "……네가 나와.": "……你上来吧。", "내가 앞에 나갔다. 수아는 맨 앞자리에서 {@clock}를 보고 있었다.": "我上了台。秀雅坐在第一排看着{@clock}。", "수아가 규칙을 말하고, 나는 시범을 보이려고 앞에 섰다.": "秀雅讲规则，我站到前面准备示范。", "나는 {@blackboard} 앞에 섰다. 아이들 얼굴이 한꺼번에 보였다.": "我站在{@blackboard}前面。一下子看到了所有同学的脸。", "동그랗게 앉아요. 술래가 {@handkerchief}을 뒤에 놓아요.": "大家围成圈坐。鬼把{@handkerchief}放在后面。", "{@hand}을 든 아이가 있었다.": "有个同学举起了{@hand}。", "「{x}」 든 친구 가리키기": "指出举「{x}」的同学", "아이: 「근데 잡히면 어떻게 돼? 술래 되는 거야?」": "同学：「可是被抓到会怎样？变成鬼吗？」", "아니요. 잡히면…… 잡히면…….": "不是。被抓到的话……被抓到的话……", "머릿속이 하얘졌다. 우리 말로는 바로 떠오르는데, 한국말이 생각나지 않았다.": "我脑子一片空白。用我们的话马上就想得到，可就是想不起韩语。", "(같은…… 뭐였지? 어제 수아가 말했는데.)": "（同……什么来着？昨天秀雅说过的。）", "몇몇이 고개를 갸웃했다. 누군가 작게 킥 웃었다. 수아가 맨 앞에서 나를 보고 있었다.": "有几个同学歪着头。有人小声地“嘻”地笑了。秀雅在最前面看着我。", "선생님: 「재미있겠네요. 다음 체육 시간에 한번 해 봅시다.」": "老师：「好像很好玩。下次体育课试一试吧。」", "아이들이 손뼉을 쳤다. 나는 자리로 돌아오면서 다리에 힘이 풀렸다.": "同学们拍起了手。我回座位时，腿都软了。", "학급회의가 끝나고 수아가 내 자리로 왔다.": "班会结束后，秀雅来到我的座位。", "통과됐네.": "通过了啊。", "이상하다. 나는 떨어질까 봐 내가 하겠다고 한 건데.": "好奇怪。我是怕没通过，才说我来的。", "……너 이제 진짜 경쟁자 같다.": "……你现在真像个对手了。", "원래 경쟁자였잖아.": "本来就是对手啊。", "아니. 오늘부터 진짜.": "不。从今天开始是真的。", "수아에게 눈짓해서 대신 말해 달라고 한다.": "用眼神请秀雅帮我说。", "나는 수아를 봤다. 수아가 바로 알아듣고 일어났다.": "我看向秀雅。秀雅马上明白了，站了起来。", "잡히면 잡은 사람 같은 편이 돼요.": "被抓到的话，就和抓的人变成同一队。", "아이: 「아, 그렇구나.」": "同学：「啊，原来是这样。」", "아이들이 고개를 끄덕였다. 나는 그다음 말을 이어 갔다.": "同学们点了点头。我接着说下去。", "(넘어갔어. 근데…… 내 발표였는데.)": "（过去了。可是……那是我的发言啊。）", "말 대신 몸으로 보여 준다.": "不用说的，用身体做给大家看。", "잠깐만요. 보여 줄게요.": "等一下。我做给你们看。", "나는 질문한 아이에게 다가가 {@hand}을 잡았다. 그리고 그 아이를 데리고 내 옆으로 와서 나란히 섰다.": "我走到提问的同学面前，拉住他的{@hand}。然后带着他来到我旁边，并排站着。", "잡히면, 이렇게. 나랑 같이.": "被抓到就像这样。跟我在一起。", "아이: 「아! 같은 편!」": "同学：「啊！同一队！」", "네! 같은 편!": "对！同一队！", "몇 명이 신이 나서 「같은 편!」 하고 따라 했다. 교실이 웃음으로 시끌시끌해졌다. 이번 웃음은 나를 향한 게 아니었다.": "有几个同学兴奋地跟着喊「同一队！」。教室里笑得热热闹闹的。这次的笑不是在笑我。", "솔직하게 말하고 반 친구들에게 묻는다.": "说真心话，问班上的同学。", "그 말이 한국말로 생각이 안 나요.": "那个词我用韩语想不起来。", "우리 말로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "用我们的话马上就想得到。被抓到的话，就和抓的人变成一个队。这个用韩语怎么说？", "아이들: 「같은 편!」": "同学们：「同一队！」", "맞아요! 같은 편이 돼요.": "对！变成同一队。", "아이: 「너네 나라 말로는 뭔데? 다시 해 봐!」": "同学：「用你们国家的话怎么说？再说一遍！」", "아이들이 내 나라 말을 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "同学们跟着说我们国家的话。发音全都乱七八糟。教室里哄堂大笑。我也一起笑了。", "그 부분은 건너뛰고 「아무튼 재밌어요!」 하고 끝낸다.": "跳过那部分，说「反正很好玩！」就结束。", "그건…… 해 보면 알아요. 아무튼 재밌어요!": "那个……玩一下就知道了。反正很好玩！", "아이들이 서로 얼굴을 봤다.": "同学们你看我，我看你。", "아이: 「잡히면 어떻게 되는지 모르는데?」": "同学：「被抓到会怎样都不知道呀？」", "수아가 {@hand}을 들고 일어나 대신 설명했다. 아이들이 그제야 고개를 끄덕였다.": "秀雅举起{@hand}站起来，替我讲了。同学们这才点了点头。", "(빨리 끝내고 싶었는데, 오히려 더 길어졌어.)": "（我想快点结束，结果反而更长了。）", "{m}! 우리 나라 놀이 통과됐어!": "{m}！我们国家的游戏通过了！", "정말? 잘됐다!": "真的？太好了！", "근데 발표하다가 ‘같은 편’이 한국말로 생각이 안 났어. 머리가 하얘졌어.": "可是发言时，我想不起“同一队”用韩语怎么说。脑子一片空白。", "수아한테 눈짓했더니 수아가 대신 말해 줬어.": "我给秀雅使了个眼色，秀雅就替我说了。", "수아가 바로 알아챘구나.": "秀雅马上就懂了啊。", "응. 근데 좀 아쉬워. 내 발표였는데.": "嗯。可是有点可惜。那是我的发言啊。", "그래도 끝까지 서 있었잖아. 다음엔 네 방법도 하나 준비해 가 볼까?": "可你还是站到了最后呀。下次也准备一个你自己的办法去试试？", "말 대신 보여 줬어. 질문한 애 {@hand} 잡고 내 옆에 세웠더니, 걔가 같은 편! 그랬어.": "我没用说的，做给大家看了。我拉住提问同学的{@hand}，让他站在我旁边，他就说：同一队！", "말이 막혔는데 몸으로 했구나.": "话卡住了，你就用身体做了啊。", "애들이 다 같은 편! 하고 따라 했어. 웃었는데 기분 나쁘지 않았어.": "同学们都跟着喊同一队！大家笑了，可是我一点都不难过。", "같이 웃은 거니까.": "因为是一起笑嘛。", "한국말이 생각 안 난다고 솔직하게 말했어. 우리 말로 하고, 한국말로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "我老实说了想不起韩语。我用我们的话说，再问韩语怎么说，同学们就一起告诉我了。", "반 친구들 앞에서 그걸 물었어?": "你在全班同学面前问了？", "응. 애들이 우리 말도 따라 했어. 발음이 엉망이었어.": "嗯。同学们还跟着说我们的话。发音乱七八糟的。", "너한테 한국말 배우고, 너한테 우리 말 배우고.": "他们跟你学韩语，也跟你学我们的话。", "그냥 해 보면 안다고 하고 넘어가려고 했어. 근데 애들이 모르겠다고 해서 수아가 설명했어.": "我想说玩一下就知道，就这样过去。可是同学们说不懂，秀雅就讲了。", "빨리 끝내고 싶었구나.": "你想快点结束啊。", "응. 근데 더 길어졌어.": "嗯。可是变得更长了。", "다음엔 모르는 말 하나쯤은 물어봐도 괜찮아.": "下次问一个不懂的词也没关系的。", "그리고 수아가 나보고 오늘부터 진짜 경쟁자래.": "还有，秀雅说从今天开始我是她真正的对手。", "와. 반장한테 그런 말 들었어?": "哇。班长对你这么说了？", "응. 좀 좋았어.": "嗯。我有点开心。", "체육 시간. 드디어 같은 편 {@handkerchief} 놀이를 하는 날이었다. 반 전체가 운동장에 동그랗게 앉았다.": "体育课。终于到了玩同一队{@handkerchief}游戏的日子。全班同学在操场上围成一圈坐下。", "처음 5분은 좋았다. 그런데 곧 이상해졌다.": "前5分钟很好。可是很快就变得奇怪了。", "아이: 「나 잡혔는데 그냥 계속 도망갈래!」": "同学：「我被抓到了，可我要继续跑！」", "아이: 「반칙이야! 잡히면 같은 편이랬잖아!」": "同学：「犯规！说好被抓到就是同一队的！」", "아이: 「같은 편 되면 뭐 해? 그다음엔?」": "同学：「变成同一队以后做什么？然后呢？」", "잡힌 아이들이 어디로 가야 할지 몰라 우왕좌왕했다. 원이 흐트러지고, 여기저기서 말다툼이 났다. {@handkerchief}이 바닥에 떨어져 있었다.": "被抓到的同学不知道该去哪里，乱成一团。圆圈散了，到处都在吵架。{@handkerchief}掉在地上。", "나는 수아에게 갔다. 수아는 팔짱을 끼고 서 있었다.": "我走到秀雅身边。秀雅抱着胳膊站着。", "이거 안 되겠다. 그냥 피구 하자.": "这样不行。还是玩躲避球吧。", "잠깐만…….": "等一下……", "솔직히 말할게. 네 놀이 지금 엉망이야.": "我直说吧。你的游戏现在乱七八糟。", "(수아 말이 맞아. 엉망이야.)": "（秀雅说得对。乱七八糟。）", "(근데 이건 내가 하자고 한 놀이야.)": "（可这是我说要玩的游戏。）", "체육 시간이 끝났다. 수아가 내 옆으로 왔다.": "体育课结束了。秀雅来到我身边。", "정리하면, 반은 성공.": "总结一下，成功了一半。", "반이나?": "一半？", "처음엔 영이었잖아.": "一开始是零嘛。", "다음에 고쳐서 다시 해 보든가.": "下次改一改再试试吧。", "「1분만. 규칙 하나만 바꿔 볼게.」": "「1分钟就好。我只改一条规则试试。」", "1분만 줘. 규칙 하나만 바꿔 볼게.": "给我1分钟。我只改一条规则试试。", "……1분.": "……1分钟。", "나는 {@handkerchief}을 들고 원 가운데 섰다.": "我拿着{@handkerchief}站到圆圈中间。", "잡히면, 잡은 사람 {@hand}을 잡아요. {@hand} 잡고 같이 다녀요!": "被抓到的话，就拉住抓你的人的{@hand}。拉着{@hand}一起跑！", "아이: 「{@hand} 잡고?」": "同学：「拉着{@hand}？」", "응. 그럼 누가 같은 편인지 보여요.": "嗯。这样就看得出谁是同一队了。", "다시 시작했다. 잡힌 아이들이 {@hand}을 잡고 줄줄이 달렸다. 기차처럼 길어졌다. 아이들이 깔깔 웃었다.": "又开始了。被抓到的同学拉着{@hand}一个接一个地跑。像火车一样越来越长。同学们哈哈大笑。", "「애들이 규칙을 안 지켜서 그래.」": "「是因为大家不守规则。」", "애들이 규칙을 안 지켜서 그래. 내 놀이가 문제가 아니야.": "是因为大家不守规则。不是我的游戏有问题。", "규칙이 헷갈리면 안 지키게 되는 거야.": "规则搞不清楚，就会不守规则。", "…….": "……", "그사이 아이들은 하나둘 피구공을 가지러 갔다.": "这时，同学们一个两个地去拿躲避球了。", "(남 탓을 했는데, 놀이는 그대로 끝났어.)": "（我怪了别人，可游戏还是就这样结束了。）", "「……그래. 그만하자.」": "「……好吧。不玩了。」", "……그래. 그만하자.": "……好吧。不玩了。", "피구 할 사람!": "谁要玩躲避球！", "아이들이 우르르 수아 쪽으로 갔다. 나는 {@handkerchief}을 주머니에 넣었다.": "同学们一窝蜂地跑到秀雅那边。我把{@handkerchief}放进了口袋。", "(그냥 끝나 버렸어.)": "（就这样结束了。）", "아이들에게 직접 묻는다. 「어디가 헷갈렸어?」": "直接问同学们：「哪里搞不清楚？」", "얘들아, 잠깐! 어디가 헷갈렸어?": "大家，等一下！哪里搞不清楚？", "아이: 「잡히고 나서 뭘 해야 할지 모르겠어.」": "同学：「被抓到以后不知道该做什么。」", "아이: 「누가 같은 편인지도 모르겠고.」": "同学：「也不知道谁是同一队。」", "그럼 잡힌 사람은 모자를 벗자! 모자 벗은 사람끼리 같은 편.": "那被抓到的人就把帽子摘掉！摘了帽子的人是同一队。", "아이: 「오, 그거 알겠다.」": "同学：「哦，这个我懂了。」", "다시 시작했다. 모자 벗은 아이들이 한 무리가 되어 함께 술래를 쫓았다. 이번엔 다툼이 줄었다.": "又开始了。摘了帽子的同学变成一伙，一起去追鬼。这次吵架变少了。", "{m}, 오늘 체육 시간에 우리 나라 놀이 했어.": "{m}，今天体育课我们玩了我们国家的游戏。", "드디어! 재밌었어?": "终于！好玩吗？", "처음엔. 근데 애들이 잡히고 나서 뭘 해야 할지 몰라서 엉망이 됐어. 수아가 솔직히 엉망이래.": "一开始好玩。可是同学们被抓到以后不知道该做什么，就乱成一团了。秀雅直说乱七八糟。", "아이고.": "哎呀。", "1분만 달라고 하고, 잡히면 {@hand} 잡고 다니자고 바꿨어. 기차처럼 길어졌어!": "我请她给我1分钟，改成被抓到就拉着{@hand}一起跑。像火车一样越来越长！", "{@hand} 잡고 줄줄이?": "拉着{@hand}一个接一个？", "응. 애들이 엄청 웃었어. 수아가 반은 성공이래.": "嗯。同学们笑得好开心。秀雅说成功了一半。", "애들이 규칙을 안 지켜서 그렇다고 했는데, 수아가 헷갈리면 안 지키게 된대.": "我说是因为大家不守规则，秀雅说规则搞不清楚就会不守。", "수아 말도 일리가 있네.": "秀雅说的也有道理。", "응. 그러는 사이에 다들 피구 하러 갔어.": "嗯。这时大家都去玩躲避球了。", "그냥 그만하자고 했어. 다들 피구 하러 갔어.": "我说算了不玩了。大家都去玩躲避球了。", "많이 실망했겠다.": "你一定很失望吧。", "응. {@handkerchief}만 주머니에 있어.": "嗯。口袋里只剩下{@handkerchief}。", "고쳐서 다시 해 볼 수도 있잖아. 어디가 문제였는지는 알 것 같아?": "也可以改一改再试一次呀。你知道问题出在哪里了吗？", "애들한테 어디가 헷갈렸냐고 물어봤어. 그래서 잡히면 모자 벗기로 했어.": "我问同学们哪里搞不清楚。然后我们决定被抓到就摘帽子。", "애들 말 듣고 바로 고쳤구나.": "听了同学们的话，马上就改了啊。", "응. 다툼이 줄었어.": "嗯。吵架变少了。", "방과 후. 수아가 교실에 남아 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "放学后。秀雅留在教室里写竞选承诺。我也拿着写竞选承诺用的{@pencil}，走到秀雅那边。", "「{x}」 내려놓기": "放下「{x}」", "수아의 공약 {@paper}: 「공약 1. 전학 온 친구를 위한 {@picture} 규칙표를 모든 반에 붙이겠습니다.」": "秀雅的竞选承诺{@paper}：「承诺1. 我会在每个班都贴上给转学同学看的{@picture}规则表。」", "나는 그대로 굳었다. 내 {w} 첫 줄에도 거의 같은 말이 쓰여 있었다.": "我一下子愣住了。我的{w}第一行也写着差不多一样的话。", "이거 좋지? 우리가 만든 규칙표, 반응 좋았잖아.": "这个不错吧？我们做的规则表，大家都很喜欢嘛。", "……나도 이거 1번으로 썼는데.": "……我也把这个写成第1条了。", "어? 진짜?": "咦？真的？", "같이 만든 거니까 나도 써도 되는 줄 알았지.": "是我们一起做的，我以为我也可以写。", "({@picture}은 내가 그렸어. 근데 처음 하자고 한 건 수아야.)": "（{@picture}是我画的。可是一开始说要做的是秀雅。）", "(둘 다 쓰면…… 애들은 누가 만든 걸로 생각할까?)": "（两个人都写的话……同学们会觉得是谁做的呢？）", "집에 가는 길. 나는 내 {w}을 다시 펴 봤다.": "回家的路上。我又打开了我的{w}。", "(내 공약은…… 뭐가 나다운 걸까?)": "（我的竞选承诺……什么才像我呢？）", "서운한 걸 직접 말하고, 같이 정하자고 한다.": "直接说出难过，提出一起决定。", "솔직히 좀 서운해. {@picture}은 내가 그렸는데, 네 공약에만 있으면 네가 다 한 것 같잖아.": "说实话，我有点难过。{@picture}是我画的，只写在你的承诺里，就好像全是你做的。", "……그렇게 보일 수도 있겠다.": "……是有可能看起来那样。", "그러니까 정하자. 둘 다 쓰든지, 하나만 쓰든지.": "所以我们来决定吧。两个人都写，还是只有一个人写。", "둘 다 쓰자. 대신 ‘같이 만든’이라고 넣어.": "两个人都写吧。不过要写上“一起做的”。", "그다음엔 누가 더 잘 지킬지 애들이 정하겠지.": "然后谁做得更好，就让同学们来决定吧。", "수아가 공약 {@paper}에 내 이름을 넣어 ‘같이 만든’이라고 고쳐 썼다.": "秀雅在竞选承诺{@paper}上写上我的名字，改成了“一起做的”。", "다른 애들한테 「수아가 내 아이디어 가져갔어.」라고 말한다.": "跟别的同学说「秀雅拿走了我的点子。」", "다음 날, 나는 친한 친구에게 작게 말했다.": "第二天，我小声地跟好朋友说了。", "수아가 내 아이디어 가져갔어.": "秀雅拿走了我的点子。", "그 말은 점심시간 전에 반 전체로 퍼졌다. 수아가 굳은 얼굴로 나를 찾아왔다.": "这句话在午饭前就传遍了全班。秀雅板着脸来找我。", "나한테 먼저 말하지 그랬어.": "你应该先跟我说呀。", "나는 같이 만든 거라서 쓴 거야.": "我是因为一起做的才写的。", "그건 수아에게 두고, 나만 할 수 있는 다른 공약을 쓴다.": "那个留给秀雅，我写一个只有我能做的承诺。", "그거 너 써. 나는 다른 거 쓸래.": "那个你写吧。我写别的。", "진짜? 너도 같이 만든 건데.": "真的？那也是你一起做的呀。", "응. 나한테는 다른 게 있어.": "嗯。我有别的。", "나는 {w} 첫 줄을 지우고 새로 썼다.": "我擦掉{w}的第一行，重新写了。", "내 {w}: 「공약 1. 모르는 말을 물어봐도 괜찮은 반을 만들겠습니다. ‘천천히 말해 줘’ 카드를 만들겠습니다.」": "我的{w}：「承诺1. 我会让我们班变成可以问不懂的词的班。我会做“请说慢一点”卡片。」", "……그거 나보다 네가 잘하는 거네.": "……这个是你比我做得好的事啊。", "응. 대피 훈련 때 그거 필요했거든.": "嗯。逃生演练时我就需要这个。", "아무 말 안 하고 혼자 서운해한다.": "什么也不说，自己一个人难过。", "……아니야. 써.": "……没事。你写吧。", "그래? 고마워!": "是吗？谢谢！", "수아는 신나서 공약 {@paper}를 다시 정리했다. 나는 {w}을 덮었다.": "秀雅开心地重新整理竞选承诺{@paper}。我合上了{w}。", "(괜찮다고 했는데, 하나도 안 괜찮아.)": "（我说了没事，可是一点也不好。）", "{m}, 수아 공약 1번이 내 공약 1번이랑 똑같았어. 우리 둘이 만든 {@picture} 규칙표.": "{m}，秀雅的承诺第1条跟我的承诺第1条一模一样。就是我们两个一起做的{@picture}规则表。", "어머. 둘이 같이 만든 거?": "哎呀。是你们两个一起做的？", "응. 수아는 같이 만든 거니까 써도 되는 줄 알았대.": "嗯。秀雅说因为是一起做的，她以为可以写。", "서운하다고 말했어. 그래서 둘 다 쓰고 ‘같이 만든’이라고 넣기로 했어.": "我说我很难过。所以我们决定两个人都写，并且写上“一起做的”。", "좋은 방법이네. 수아는 어땠어?": "好办法。秀雅觉得怎么样？", "누가 더 잘 지킬지는 애들이 정할 거래.": "她说谁做得更好，让同学们来决定。", "역시 경쟁자다.": "果然是对手。", "친구한테 수아가 내 거 가져갔다고 했는데, 반 전체에 퍼졌어.": "我跟朋友说秀雅拿走了我的东西，结果传遍了全班。", "아이고. 수아는?": "哎呀。秀雅呢？", "나한테 먼저 말하지 그랬냐고 했어.": "她说我应该先跟她说。", "수아 말이 맞네. 다음엔 수아한테 먼저 말해 보자.": "秀雅说得对。下次先跟秀雅说吧。", "그건 수아 쓰라고 하고, 나는 다른 공약 썼어. 모르는 말 물어봐도 괜찮은 반.": "那个我让秀雅写，我写了别的承诺。可以问不懂的词的班。", "그거 너한테 딱이다.": "这个跟你正合适。", "수아도 그거 나보다 네가 잘하는 거래.": "秀雅也说这个是我比她做得好的事。", "괜찮다고 했어. 근데 안 괜찮아.": "我说了没事。可是一点也不好。", "속으로만 서운했구나.": "你只在心里难过啊。", "응. 말하면 싸울 것 같아서.": "嗯。我怕说出来会吵架。", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 내일 말해 봐도 늦지 않아.": "说出难过和吵架是不一样的。明天再说也不晚。", "쉬는 시간. 수아가 교실을 뛰어다니고 있었다. 오늘 종례까지 체험학습 신청서를 다 걷어야 한다고 했다.": "课间。秀雅在教室里跑来跑去。她说今天放学前要把校外活动报名表都收齐。", "나는 수아 {@desk}으로 갔다. {@desk} 위에 신청서 {@box}가 있었다.": "我走到秀雅的{@desk}旁边。{@desk}上有一个放报名表的{@box}。", "{@box} 안에 신청서가 보였다. 아직 반도 안 찼다.": "{@box}里能看到报名表。还不到一半。", "여덟 명 남았어. 종례까지.": "还剩八个人。放学前要收齐。", "도와줄까?": "要我帮忙吗？", "아니, 괜찮아. 반장 일이야.": "不用，没关系。这是班长的事。", "수아가 다시 뛰어갔다. 그때 같은 모둠 친구가 내 옆으로 와서 작게 말했다.": "秀雅又跑走了。这时，同一组的朋友走到我旁边，小声说。", "친구: 「야, 그냥 내버려 둬. 수아가 실수하면 너한테 좋은 거잖아. 선거 나간다며.」": "朋友：「喂，别管她。秀雅出错的话对你有好处呀。你不是要参加选举吗？」", "(……그런가?)": "（……是这样吗？）", "그때 뒷자리 친구가 신청서를 들고 멍하니 앉아 있는 게 보였다. 신청서를 뒤집었다 폈다 하고 있었다.": "这时我看到后座的同学拿着报名表呆呆地坐着。他把报名表翻过来又打开。", "(저거…… 대피 훈련 때 나 같은 얼굴이다.)": "（那个……跟逃生演练时的我是一样的表情。）", "종례가 끝났다. 수아가 {@box}를 정리하며 나를 봤다.": "放学前的班会结束了。秀雅一边整理{@box}一边看着我。", "……‘회신’을 모르는 애가 있을 줄은 몰랐어.": "……我没想到会有人不懂“回执”。", "나도 몰랐었어.": "我以前也不懂。", "그러니까 네가 알았겠지.": "所以你才发现了吧。", "한 장 내일 받으면 돼. 괜찮아.": "有一张明天收就行。没关系。", "수아는 괜찮다고 했지만, 형광펜을 꽉 쥐고 있었다.": "秀雅说没关系，可她紧紧地握着荧光笔。", "친구 말대로 모른 척한다.": "听朋友的话，装作没看见。", "나는 내 자리로 돌아갔다. 수아는 종례 직전까지 뛰어다녔다.": "我回到了自己的座位。秀雅一直跑到放学班会前。", "종례 시간. 수아가 선생님께 {@box}를 내밀었다.": "放学班会时间。秀雅把{@box}交给了老师。", "……한 장 빠졌어요.": "……少了一张。", "(내가 이긴 것 같지가 않아.)": "（我一点也不觉得自己赢了。）", "「내가 뒤쪽 줄만 걷을게. 싫으면 말해.」": "「我只收后面那几排。不愿意就告诉我。」", "수아야. 내가 뒤쪽 줄만 걷을게. 싫으면 말해.": "秀雅。我只收后面那几排。不愿意就告诉我。", "괜찮다니까, 내가…….": "我说了没关系，我自己……", "뒤쪽 줄만이야.": "只是后面那几排。", "수아가 잠깐 멈췄다. 숨을 한 번 크게 쉬었다.": "秀雅停了一下。深深地吸了一口气。", "……그럼 뒤쪽만.": "……那就后面那几排。", "나는 뒤쪽 줄을 돌았다. 뒷자리 친구는 ‘회신’이라는 말을 몰라서 못 낸 거였다. 나는 {@picture}으로 설명해 줬다.": "我走了一圈后面那几排。后座的同学是因为不懂“回执”这个词才没交。我用{@picture}给他讲了。", "뒷자리 친구: 「아, 이름 쓰고 다시 내는 거구나!」": "后座的同学：「啊，原来是写上名字再交回来啊！」", "도와준다고 했다가 거절당하자 「그래, 혼자 해.」 하고 돌아선다.": "说要帮忙却被拒绝，就说「好吧，你自己做。」然后转身走开。", "진짜 도와줄게.": "我真的来帮你。", "괜찮다고 했잖아!": "我说了没关系嘛！", "……그래, 혼자 해.": "……好吧，你自己做。", "나는 자리로 돌아갔다. 수아도 나도 기분이 상했다.": "我回到了座位。秀雅和我心里都不舒服。", "종례 시간. 한 장이 빠졌다.": "放学班会时间。少了一张。", "뒷자리 친구에게 가서 신청서를 같이 본다.": "走到后座同学身边，一起看报名表。", "나는 수아를 쫓아가는 대신 뒷자리 친구에게 갔다.": "我没有去追秀雅，而是走到了后座同学身边。", "이거 모르는 말 있어?": "这上面有不懂的词吗？", "뒷자리 친구: 「……‘회신’이 뭐야?」": "后座的同学：「……“回执”是什么？」", "나도 처음에 몰랐어. 이름 쓰고, 부모님 사인 받고, 다시 내는 거야.": "我一开始也不懂。就是写上名字，请爸爸妈妈签字，再交回来。", "나는 {w} 귀퉁이에 순서를 {@picture}으로 그려 줬다. 친구가 이름을 쓰고 신청서를 {@box}에 넣었다.": "我在{w}的角上用{@picture}画出了顺序。同学写上名字，把报名表放进了{@box}。", "수아가 돌아와 {@box}를 보고 눈을 크게 떴다.": "秀雅回来看到{@box}，眼睛瞪得大大的。", "어? 이거 언제 냈어?": "咦？这个什么时候交的？", "뒷자리 친구: 「방금. 쟤가 알려 줬어.」": "后座的同学：「刚刚。是他告诉我的。」", "{m}, 수아가 오늘 종례까지 신청서 다 걷어야 해서 엄청 바빴어.": "{m}，秀雅今天放学前要收齐报名表，忙得不得了。", "반장 일이 많구나.": "班长的事好多啊。", "응. 근데 친구가 수아 내버려 두래. 수아가 실수하면 나한테 좋다고.": "嗯。可是朋友说别管秀雅。他说秀雅出错的话对我有好处。", "그냥 내 자리에 있었어. 결국 한 장 빠졌어.": "我就待在自己的座位上。最后少了一张。", "그러고 나서 기분이 어땠어?": "那之后你感觉怎么样？", "이긴 것 같지 않았어.": "我不觉得自己赢了。", "그렇구나.": "原来是这样。", "뒤쪽 줄만 걷겠다고 했어. 수아가 처음엔 괜찮다고 했는데 결국 그러라고 했어.": "我说我只收后面那几排。秀雅一开始说没关系，最后还是同意了。", "수아가 도움을 받았네.": "秀雅接受了帮助啊。", "응. 그리고 뒷자리 애가 ‘회신’을 몰라서 못 낸 거였어. {@picture}으로 알려 줬어.": "嗯。还有，后座的同学是因为不懂“回执”才没交。我用{@picture}告诉他了。", "네가 아니었으면 몰랐겠다.": "要不是你，就没人发现了。", "도와준다고 했는데 수아가 괜찮다고 화내서, 그럼 혼자 하라고 했어.": "我说要帮忙，秀雅生气地说没关系，我就说那你自己做吧。", "둘 다 기분 상했겠다.": "你们两个心里都不舒服吧。", "응. 그리고 한 장 빠졌어.": "嗯。还少了一张。", "수아는 왜 계속 괜찮다고 했을까?": "秀雅为什么一直说没关系呢？", "……반장 일이라서?": "……因为是班长的事？", "뒷자리 애가 신청서를 뒤집었다 폈다 하고 있었어. 대피 훈련 때 나 같아서 가 봤어.": "后座的同学把报名表翻过来又打开。他跟逃生演练时的我一样，所以我就过去了。", "무슨 일이었어?": "怎么回事？", "‘회신’을 몰랐대. 나도 처음엔 몰랐잖아. {@picture}으로 알려 줬어.": "他不懂“回执”。我一开始也不懂嘛。我用{@picture}告诉他了。", "네가 겪어 봐서 알아본 거네.": "因为你经历过，所以你看出来了。", "근데 경쟁자를 도와주는 거, 이상하진 않았어?": "可是帮助对手，你不觉得奇怪吗？", "……모르겠어. 그냥 반 일이잖아.": "……我不知道。这就是班上的事嘛。", "오늘은 내 생일이었다. {m}가 새벽부터 우리 나라 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "今天是我的生日。{m}一大早就做了我们国家的点心，装在{@bowl}里给我，让我和班上的同学一起分着吃。", "나는 {@bowl}을 안고 수아에게 갔다.": "我抱着{@bowl}去找秀雅。", "수아야! 오늘 내 생일이야. 이거 언제 나눠 주면 돼?": "秀雅！今天是我的生日。这个什么时候分给大家好？", "「{x}」 뚜껑 열기": "打开「{x}」的盖子", "{@bowl} 안에 우리 나라 간식이 가득했다.": "{@bowl}里装满了我们国家的点心。", "와, 생일 축하해! 근데…….": "哇，生日快乐！可是……", "수아가 {@bowl}을 보더니 표정이 바뀌었다.": "秀雅看了看{@bowl}，脸色变了。", "그거 나눠 주면 안 돼. 규칙 9번. 집에서 만든 음식은 학교에서 나눠 먹지 않기.": "那个不能分。规则9号：家里做的食物不在学校分着吃。", "……안 돼?": "……不行吗？", "응. 안 돼.": "嗯，不行。", "수아는 또 빠르고 짧게 말했다. {@bowl}이 갑자기 무거워졌다.": "秀雅又说得又快又短。{@bowl}一下子变重了。", "({m}가 새벽부터 만든 건데.)": "（这是{m}一大早做的呢。）", "(우리 나라에서는 생일에 이걸 나눠 먹는데…….)": "（在我们国家，过生日都要分着吃这个……）", "종례 시간. 선생님이 내 생일이라고 말씀하셨다. 반 아이들이 생일 노래를 불러 줬다.": "放学前的班会。老师说今天是我的生日。全班同学给我唱了生日歌。", "수아가 제일 크게 불렀다. 음이 조금 틀렸다.": "秀雅唱得最大声，有点跑调。", "「우리 나라 음식이라서 싫은 거지?」": "「是因为这是我们国家的食物，你才不喜欢吧？」", "우리 나라 음식이라서 안 된다는 거지?": "是因为这是我们国家的食物，所以才不行吧？", "아니야! 그런 거 아니야!": "不是！不是那样的！", "수아 얼굴이 빨개졌다.": "秀雅的脸红了。", "누가 가져와도 안 되는 거야. 나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "谁带来都不行。我去年过生日也带了年糕，又带回家了。", "……아.": "……啊。", "우리 둘 다 한동안 말이 없었다.": "我们俩好一会儿都没说话。", "「왜 안 돼?」 하고 이유를 묻는다.": "问她「为什么不行？」", "왜 안 돼?": "为什么不行？", "음식에 알레르기 있는 애들이 있어. 뭐가 들어갔는지 모르면 위험할 수 있대.": "有的同学对食物过敏。不知道里面放了什么的话，可能会很危险。", "나도 작년 생일에 떡 가져왔다가 다시 가져갔어.": "我去年过生日也带了年糕，又带回家了。", "너도?": "你也是？", "응. 엄청 속상했어.": "嗯。我特别难过。", "(나만 안 되는 게 아니구나.)": "（原来不是只有我不行啊。）", "아무 말 없이 {@bowl}을 다시 {@bag}에 넣는다.": "什么也不说，把{@bowl}放回{@bag}里。", "나는 아무 말도 하지 않았다. 뚜껑을 닫고 {@bowl}을 {@bag} 깊숙이 넣었다.": "我什么也没说。我盖上盖子，把{@bowl}放进{@bag}的最里面。", "……저기.": "……那个。", "나는 대답하지 않고 자리로 갔다. 하루 종일 {@bag}이 무거웠다.": "我没有回答，回到了座位上。一整天{@bag}都很重。", "「그럼 먹는 거 말고, 다른 방법은 돼?」 하고 묻는다.": "问她「那不吃的话，别的办法可以吗？」", "그럼 먹는 거 말고 다른 방법은 돼?": "那不吃的话，别的办法可以吗？", "다른 방법?": "别的办法？", "사진 보여 주면서 우리 나라에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "就是一边给大家看照片，一边说我们国家过生日吃这个。做法也可以用{@picture}画出来。", "그건 돼! 음식만 안 되는 거니까.": "那个可以！只是食物不行嘛。", "수아가 형광펜을 꺼냈다.": "秀雅拿出了荧光笔。", "종례 때 1분 줄게. 반장 권한.": "放学班会的时候给你1分钟。班长的权力。", "{m}…… 학교에서 그거 못 나눠 줬어.": "{m}……我在学校没能把那个分给大家。", "응? 왜?": "嗯？为什么？", "집에서 만든 음식은 학교에서 나눠 먹으면 안 된대. 규칙 9번. 수아가 알려 줬어.": "家里做的食物不能在学校分着吃。规则9号。是秀雅告诉我的。", "어머…… {m}가 몰랐네. 새벽부터 만들었는데. 미안해.": "哎呀……{m}不知道呢。一大早就做好了。对不起。", "{m}가 왜 미안해.": "{m}为什么要说对不起。", "나 수아한테 우리 나라 음식이라서 싫은 거냐고 했어.": "我问秀雅，是不是因为是我们国家的食物才不喜欢。", "아니래. 수아도 작년에 떡 가져왔다가 못 나눠 줬대.": "她说不是。秀雅去年也带了年糕，也没能分给大家。", "그랬구나. 수아도 놀랐겠다.": "原来是这样。秀雅也被你吓了一跳吧。", "……응. 내가 좀 심했어.": "……嗯。我有点过分了。", "왜 안 되냐고 물었더니, 알레르기 있는 애들 때문이래. 수아도 작년에 떡 가져갔다가 다시 가져갔대.": "我问为什么不行，她说是因为有的同学会过敏。秀雅去年也带了年糕，又带回家了。", "다 같이 지키는 규칙이었구나.": "原来是大家都要遵守的规则啊。", "응. 나만 안 되는 줄 알았어.": "嗯。我还以为只有我不行。", "그냥 아무 말 안 하고 {@bag}에 넣었어. 하루 종일 {@bag}이 무거웠어.": "我什么也没说，就放进{@bag}里了。一整天{@bag}都很重。", "많이 속상했구나.": "你一定很难过吧。", "수아가 뭐라고 하려고 했는데 그냥 갔어.": "秀雅好像想说什么，可我直接走了。", "수아가 무슨 말 하려고 했을까? 내일 물어봐도 되겠다.": "秀雅想说什么呢？明天可以问问她。", "그럼 사진 보여 주고 만드는 법 {@picture}으로 그려 와도 되냐고 했어. 수아가 종례 때 1분 준대.": "我问她，能不能给大家看照片，再用{@picture}画出做法带过去。秀雅说放学班会时给我1分钟。", "어머, 그거 좋다! 그럼 {m}가 사진 찍어 줄게.": "哎呀，这个好！那{m}帮你拍照片。", "만드는 법도 알려 줘. {@picture}으로 그릴게.": "也教我怎么做吧。我用{@picture}画出来。", "이건 우리 둘이 먹자. 생일 축하해.": "这个我们俩一起吃吧。生日快乐。", "응. 그리고 오늘 애들이 생일 노래 불러 줬어. 수아가 제일 크게 불렀어. 음 틀리게.": "嗯。还有，今天同学们给我唱了生日歌。秀雅唱得最大声，还跑调了。", "반장은 노래도 크게 하는구나.": "班长唱歌也很大声呢。", "점심시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "午饭时间。秀雅正急急忙忙地收拾{@bag}。我走到秀雅那里。", "마침 잘 왔다.": "你来得正好。", "옆 반 선생님이 우리 {@picture} 규칙표 보시고, 애들한테 설명해 달래. 근데 나 지금 학생회 회의 가야 해.": "隔壁班的老师看了我们的{@picture}规则表，想请我们给他们班的同学讲一讲。可是我现在要去学生会开会。", "너 혼자 가 볼래? {@picture}은 네가 그렸잖아.": "你一个人去试试？{@picture}是你画的嘛。", "(혼자? 옆 반은 아는 애가 하나도 없는데.)": "（一个人？隔壁班我一个人都不认识。）", "옆 반 앞.": "隔壁班门口。", "「{x}」 두드리기": "敲「{x}」", "똑똑. 옆 반 {@door}이 열렸다.": "咚咚。隔壁班的{@door}开了。", "낯선 얼굴 스무 개가 나를 봤다. 다리가 떨렸다. 그래도 {@picture}을 가리켰다.": "二十张陌生的脸看着我。我的腿在发抖。但我还是指着{@picture}。", "이건 규칙 7번이에요. 연기가 나면 몸을 낮추고, 벽을 짚어요.": "这是规则7号。有烟的时候，要把身体放低，手扶着墙。", "옆 반 아이: 「벽은 왜 짚어요?」": "隔壁班的同学：「为什么要扶着墙？」", "연기 때문에 앞이 안 보여요. 벽을 따라가면 길을 안 잃어요.": "因为有烟，前面看不见。跟着墙走，就不会迷路。", "옆 반 선생님: 「설명 잘하는구나. {@picture}도 네가 그렸니?」": "隔壁班的老师：「你讲得真好。{@picture}也是你画的吗？」", "네!": "是的！", "회의가 끝나고 둘이 갔을 때는 벌써 수업이 시작되어 있었다.": "开完会，我们俩一起过去的时候，已经开始上课了。", "옆 반 선생님: 「아, 지금은 좀 그렇고…… 내일 다시 와 줄래?」": "隔壁班的老师：「啊，现在不太方便……明天再来一次好吗？」", "수아가 나를 힐끗 봤다. 나는 시선을 피했다.": "秀雅偷偷看了我一眼。我躲开了她的目光。", "나는 규칙표를 {@blackboard} 옆에 붙이고 나가려 했다.": "我把规则表贴在{@blackboard}旁边，就想出去。", "옆 반 선생님: 「설명도 조금 해 줄 수 있니?」": "隔壁班的老师：「你能稍微讲一讲吗？」", "……이건, 규칙…… 7번…… 이에요.": "……这是，规则……7号……", "옆 반 아이들이 고개를 갸웃했다. 나는 꾸벅 인사하고 나왔다.": "隔壁班的同学们歪着头。我鞠了个躬就出来了。", "안녕하세요! 옆 반 반장 양수아예요. 이 규칙표는 얘가 그렸어요. 설명도 얘가 할게요.": "大家好！我是隔壁班的班长杨秀雅。这张规则表是他画的。也由他来讲。", "수아가 1분을 딱 채우고 나갔다. 이제 나 혼자였다. 그래도 수아가 열어 준 {@door}이라 덜 떨렸다.": "秀雅正好待了1分钟就走了。现在只剩我一个人了。但因为是秀雅帮我打开的{@door}，我没那么紧张了。", "교실로 돌아오니 수아도 막 회의에서 돌아와 있었다.": "回到教室，秀雅也刚开完会回来。", "어땠어?": "怎么样？", "벽 왜 짚냐고 물어봐서 대답했어.": "他们问为什么要扶着墙，我回答了。", "……나보다 잘했겠다. 나는 ‘규칙이니까’라고 했을 거야.": "……你肯定比我讲得好。我大概只会说「因为这是规则」。", "……잘 못 했어.": "……我讲得不好。", "다음에 또 기회 있어.": "下次还有机会。", "「알았어. 내가 갈게.」": "「好的。我去。」", "알았어. 내가 갈게.": "好的。我去。", "진짜? 고마워. {@picture} 보여 주면서 하면 돼.": "真的？谢谢。你一边给他们看{@picture}一边讲就行。", "수아가 둘둘 만 규칙표를 내 {@hand}에 쥐여 주고 뛰어갔다.": "秀雅把卷起来的规则表塞到我{@hand}里，就跑走了。", "「반장이니까 네가 해야지.」": "「你是班长，应该你去。」", "반장이니까 네가 해야지.": "你是班长，应该你去。", "그건 그런데…… 회의가 있다니까.": "话是这么说……可我要开会啊。", "회의 끝나고 가.": "开完会再去。", "……그럼 늦어. 알았어, 끝나고 같이 가자. 대신 말은 네가 해.": "……那就晚了。好吧，开完会一起去。不过由你来讲。", "「규칙표만 붙이고 올게.」": "「我只去贴一下规则表。」", "설명은 못 하고, 규칙표만 붙이고 올게.": "我讲不了，只去贴一下规则表。", "음…… 그래도 가 주면 고맙지.": "嗯……那你肯去我也很感谢。", "수아가 규칙표를 건네고 뛰어갔다.": "秀雅把规则表递给我，就跑走了。", "「처음 1분만 같이 가 줘. 나머지는 내가 할게.」": "「开头1分钟陪我一起去。剩下的我来。」", "처음 1분만 같이 가 줘. 인사만. 나머지는 내가 할게.": "开头1分钟陪我一起去。打个招呼就好。剩下的我来。", "1분?": "1分钟？", "……좋아. 1분이면 회의 안 늦어.": "……好。1分钟的话，开会不会迟到。", "수아가 {@clock}를 보더니 앞장섰다.": "秀雅看了看{@clock}，走在了前面。", "{m}, 오늘 수아가 옆 반에 가서 우리 규칙표 설명해 달래. 혼자서.": "{m}，今天秀雅让我去隔壁班讲我们的规则表。一个人去。", "혼자? 아는 애도 없는 반에?": "一个人？去一个人都不认识的班？", "응. 수아가 회의 가야 한대서.": "嗯。因为秀雅要去开会。", "그래서 혼자 갔어. 다리 떨렸는데 {@picture} 가리키면서 했어. 벽 왜 짚냐고 물어봐서 대답도 했어.": "所以我一个人去了。腿在发抖，但我指着{@picture}讲完了。他们问为什么要扶着墙，我也回答了。", "와, 혼자서 질문까지?": "哇，一个人连问题都回答了？", "응. 수아가 자기보다 잘했겠대.": "嗯。秀雅说我肯定比她讲得好。", "수아가 너를 믿고 맡긴 거네.": "秀雅是相信你，才交给你的。", "반장이니까 수아가 하라고 했어. 근데 회의 끝나고 갔더니 벌써 수업 시작했어.": "我说你是班长，让秀雅去。可是等开完会再去，已经开始上课了。", "아이고, 못 했구나.": "哎呀，没讲成啊。", "응. 내일 다시 오래. 수아가 나를 쳐다봤어.": "嗯。他们让明天再去。秀雅看了我一眼。", "내일은 어떻게 할래?": "明天你打算怎么办？", "……내가 할래.": "……我来讲。", "규칙표만 붙이고 오려고 했는데, 선생님이 설명도 해 달래서 버벅거렸어.": "我本来只想去贴规则表，可老师让我讲一讲，我讲得结结巴巴的。", "갑자기 하려니까 어려웠겠다.": "突然要讲，一定很难吧。", "응. 준비할 걸 그랬어.": "嗯。早知道先准备一下了。", "처음 1분만 같이 가 달라고 했어. 수아가 인사하고, 얘가 그렸다고 말해 주고 나갔어. 그다음엔 내가 했어.": "我请秀雅开头1分钟陪我去。秀雅打了招呼，说是我画的，然后就走了。后面是我讲的。", "필요한 만큼만 도움을 받았구나.": "你只请别人帮了需要的那一点忙呢。", "응. 수아가 {@door} 열어 주니까 덜 떨렸어.": "嗯。秀雅帮我打开{@door}，我就没那么紧张了。", "쉬는 시간. 옆 반 아이들이 우리 규칙표를 따라 만들기로 했다는 소식을 들었다. 나는 신이 나서 수아 자리로 갔다.": "下课时间。我听说隔壁班决定照着我们的规则表做一张。我高兴地跑到秀雅的座位。", "수아는 학급 게시물을 붙이고 있었다. {@desk} 위에 뚜껑 열린 {@glue}이 굴러다녔다.": "秀雅正在贴班级的通知。{@desk}上，打开盖子的{@glue}滚来滚去。", "「{x}」 뚜껑 닫기": "盖上「{x}」的盖子", "수아야! 옆 반이 우리 규칙표 따라 만든대!": "秀雅！隔壁班要照着我们的规则表做呢！", "옆 반 선생님이 {@picture} 좋다고…….": "隔壁班的老师说{@picture}很好……", "지금 그 얘기 할 때 아니야!": "现在不是说这个的时候！", "수아가 게시물을 탁 내려놓았다.": "秀雅啪地把通知放下了。", "이거 종례 전까지 다 붙여야 하고, 학생회 회의 내용도 정리해야 하고. 너는 반장 안 해 봐서 몰라.": "这些要在放学班会前全部贴好，还要整理学生会开会的内容。你没当过班长，你不懂。", "교실이 잠깐 조용해졌다. 몇몇이 우리를 봤다.": "教室里一下子安静了。有几个同学看着我们。", "(……뭐야. 나는 좋은 소식 말하러 온 건데.)": "（……什么嘛。我是来说好消息的。）", "(‘반장 안 해 봐서 몰라’. 그 말이 콕 찔렸어.)": "（「你没当过班长，你不懂。」这句话扎到我了。）", "종례가 끝나고 {@bag}을 메는데, {@pcase} 위에 쪽지 하나가 있었다. 형광펜 글씨였다.": "放学班会结束，我背上{@bag}的时候，{@pcase}上有一张小纸条。是荧光笔写的字。", "쪽지: 「아까 말 심하게 했어. 학생회 회의에서 내 안건이 다 떨어져서 그랬어. 그건 너랑 상관없는데. — 수아」": "纸条：「刚才我话说重了。学生会开会时，我的提议全都没通过，所以才那样。这跟你没关系的。——秀雅」", "(아팠던 건 아팠던 거야. 근데 수아도 오늘 힘들었구나.)": "（难过就是难过。可是秀雅今天也很辛苦啊。）", "「그래, 넌 반장이라 잘났다.」 하고 맞받아친다.": "回她一句「是啊，你是班长，你了不起。」", "그래, 넌 반장이라 잘났다.": "是啊，你是班长，你了不起。", "그런 뜻 아니잖아!": "我不是那个意思！", "그런 뜻이었잖아.": "你就是那个意思。", "수아가 입을 꾹 다물고 다시 게시물을 붙였다. 나도 자리로 돌아갔다. 둘 다 하루 종일 말을 안 했다.": "秀雅紧紧闭上嘴，又去贴通知了。我也回到了座位。我们俩一整天都没说话。", "「지금 그 말 좀 아팠어. 근데 무슨 일 있어?」": "「你刚才那句话让我有点难过。不过你怎么了？」", "지금 그 말 좀 아팠어.": "你刚才那句话让我有点难过。", "근데 너 오늘 좀 이상해. 무슨 일 있어?": "不过你今天有点奇怪。发生什么事了？", "수아가 {@glue}을 내려놓았다. 한참 있다가 작게 말했다.": "秀雅放下了{@glue}。过了好一会儿，她小声说：", "학생회 회의에서 내 안건이 다 떨어졌어. 세 개 다.": "学生会开会时，我的提议全都没通过。三个全都没有。", "그거랑 너는 상관없는데. ……미안. 말 심하게 했어.": "那跟你没关系的。……对不起。我话说重了。", "나는 남은 게시물 한 장을 집어 수아에게 내밀었다.": "我拿起剩下的一张通知，递给了秀雅。", "「알았어. 이따 다시 올게.」 하고 자리를 비켜 준다.": "说「好吧。我等会儿再来。」，然后走开。", "알았어. 이따 다시 올게.": "好吧。我等会儿再来。", "나는 내 자리로 돌아갔다. 마음이 쿡쿡 쑤셨다. 그래도 지금은 더 말하지 않았다.": "我回到了自己的座位。心里一阵一阵地疼。但现在我不再多说了。", "점심시간. 수아가 먼저 내 자리로 왔다.": "午饭时间。秀雅先来到了我的座位。", "……아까 무슨 얘기 하려고 했어?": "……刚才你想说什么？", "옆 반이 우리 규칙표 따라 만든대.": "隔壁班要照着我们的规则表做。", "진짜? ……아까 그거 기쁜 소식이었네.": "真的？……原来刚才是好消息啊。", "「하하, 그렇지.」 하고 웃어넘긴다.": "笑着说「哈哈，是啊。」", "하하, 그렇지. 나는 모르지.": "哈哈，是啊。我不懂嘛。", "나는 웃으면서 자리로 돌아왔다.": "我笑着回到了座位。", "(웃었는데…… 하나도 안 웃겨.)": "（我笑了……可一点都不好笑。）", "수아는 내가 웃는 걸 보고 그냥 괜찮은 줄 알았다.": "秀雅看见我在笑，就以为我没事。", "{m}, 옆 반이 우리 규칙표 따라 만든대서 수아한테 말하러 갔거든.": "{m}，我听说隔壁班要照着我们的规则表做，就去告诉秀雅。", "좋은 소식이네!": "是好消息呀！", "근데 수아가 지금 그 얘기 할 때 아니래. 너는 반장 안 해 봐서 모른대.": "可秀雅说现在不是说这个的时候。还说我没当过班长，我不懂。", "어머, 그 말 듣고 속상했겠다.": "哎呀，听到这句话一定很难过吧。", "그래, 넌 반장이라 잘났다, 그랬어.": "我说：「是啊，你是班长，你了不起。」", "하루 종일 말 안 했어. 근데 수아가 쪽지 줬어. 학생회에서 안건이 다 떨어졌대.": "我们一整天都没说话。可是秀雅给了我一张纸条。她说在学生会，她的提议全都没通过。", "둘 다 안 좋은 날이었구나.": "原来你们俩今天都不顺啊。", "그 말 아팠다고 했어. 그리고 무슨 일 있냐고 물었어.": "我说那句话让我很难过。然后我问她发生什么事了。", "아픈 말을 듣고 그걸 물어보기 쉽지 않은데.": "听了让人难过的话，还能这样问，可不容易呢。", "수아가 학생회에서 안건 세 개가 다 떨어졌대. 그리고 미안하다고 했어.": "秀雅说在学生会，她的三个提议全都没通过。然后她跟我说了对不起。", "이따 다시 오겠다고 하고 갔어. 근데 수아가 점심때 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "我说等会儿再来，就走了。可是午饭时秀雅先来找我，问我刚才想说什么。", "기다렸더니 수아가 왔구나.": "你等了一下，秀雅就来了呀。", "응. 그리고 쪽지도 줬어.": "嗯。她还给了我纸条。", "그냥 웃어넘겼어. 근데 하나도 안 웃겼어.": "我就笑着带过去了。可一点都不好笑。", "웃었으니까 수아는 괜찮은 줄 알았겠다.": "你笑了，秀雅一定以为你没事吧。", "응. 쪽지는 받았는데…… 나 아팠다는 건 수아가 몰라.": "嗯。纸条是收到了……可秀雅不知道我很难过。", "내일이라도 말해 볼래? 그 말 좀 아팠다고.": "明天要不要跟她说说？说那句话让你有点难过。", "도서관. 선거 연설문을 쓰다가 막혔다. 마침 수아가 맞은편에 앉아 있었다. 나는 {w}을 들고 수아에게 갔다.": "图书馆。我写竞选演讲稿，写不下去了。正好秀雅坐在对面。我拿着{w}去找秀雅。", "수아야, 내 연설문 처음 부분만 봐 줄래?": "秀雅，能帮我看看演讲稿的开头吗？", "경쟁자 연설문을?": "看对手的演讲稿？", "처음 부분만.": "只看开头。", "내 {w}: 「안녕하세요. 저는 규칙을 잘 지키는 반장이 되겠습니다. 규칙 3번, 교실에서 뛰지 않기. 규칙 5번, 친구 밀지 않기. 규칙은 누구나 지키는 것입니다. 예외는 없습니다.」": "我的{w}：「大家好。我会做一个遵守规则的班长。规则3号，不在教室里跑。规则5号，不推同学。规则是每个人都要遵守的。没有例外。」", "수아가 읽다가 고개를 들었다.": "秀雅读着读着，抬起了头。", "……이거 나잖아.": "……这不就是我嘛。", "규칙 번호까지. ‘예외는 없습니다’는 내가 첫날 최민호한테 한 말이고.": "连规则号码都一样。「没有例外」是我第一天对崔敏浩说的话。", "얼굴이 화끈거렸다. 첫날 밤 {w}에 썼던 말이 생각났다.": "我的脸一下子热了。我想起第一天晚上在{w}上写的话。", "이거면 애들이 왜 너를 뽑아? 나 뽑지.": "这样的话，同学们为什么要选你？选我就好了。", "너는 뭐가 하고 싶은데?": "那你想做什么？", "고친 거 선거 때 들으면 되겠네. 지금은 안 볼래.": "改好的稿子，竞选那天听就好了。现在我不看了。", "경쟁자 연설문 너무 많이 보면 반칙 같아.": "看太多对手的演讲稿，好像是犯规。", "「네가 잘하니까 너처럼 하면 될 것 같았어. 그냥 둘래.」": "「你做得好，我想像你一样就行。就这样吧。」", "너 잘하잖아. 너처럼 하면 될 것 같았어. 그냥 둘래.": "你做得很好嘛。我想像你一样就行。就这样吧。", "……그럼 나랑 너랑 뭐가 달라?": "……那你和我有什么不一样？", "난 경쟁자가 나랑 똑같은 건 재미없어.": "对手跟我一模一样，就没意思了。", "수아가 {w}을 돌려줬다. {w}이 이상하게 무거웠다.": "秀雅把{w}还给了我。{w}变得好重。", "「그럼 너랑 반대로 할래. 규칙 없는 반!」": "「那我跟你反着来。没有规则的班！」", "그럼 너랑 반대로 할래. 규칙 없는 자유로운 반!": "那我跟你反着来。没有规则、自由自在的班！", "애들이 좋아하긴 하겠다.": "同学们肯定会喜欢。", "근데 너 대피 훈련 때 규칙 7번 덕분에 길 찾았잖아.": "可是你在逃生演习的时候，是靠规则7号才找到路的呀。", "……그건 그렇지.": "……那倒是。", "(반대로 하는 것도 결국 수아를 보고 정한 거네.)": "（反着来，其实也是看着秀雅决定的。）", "「그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 거 말해 줄게.」": "「那你觉得我擅长什么？我也说说你的。」", "그럼 너는 내가 뭘 잘하는 것 같아? 나도 네 장점 말해 줄게.": "那你觉得我擅长什么？我也说说你的优点。", "음…… 너는 못 알아듣는 애를 알아봐. 신청서 때도, 옆 반 때도.": "嗯……你能看出谁听不懂。报名表那次是这样，隔壁班那次也是。", "그리고 막히면 몸으로 해. 학급회의 때처럼.": "还有，说不出来的时候，你会用身体来比画。就像班会那次一样。", "너는 빨라. 정리 잘하고. 다들 네 말 들어.": "你很快。很会整理。大家都听你的。", "그럼 됐네. 나는 빠른 반장, 너는…….": "那就好了。我是快快的班长，你是……", "……천천히 물어보는 반장?": "……慢慢问的班长？", "나는 {w}을 새 쪽으로 넘겼다.": "我把{w}翻到了新的一页。", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다.」": "我的{w}：「我会做一个先问「你还好吗？」的班长。」", "지우고, 내가 겪은 일로 다시 쓴다.": "擦掉，用自己经历过的事重新写。", "……다시 쓸게. 잠깐만.": "……我重新写。等一下。", "나는 처음 문장을 지웠다. 첫날이 생각났다. 깨진 관찰 통. 민호를 막은 수아. 그리고 아무도 묻지 않았던 시우.": "我擦掉了第一句。我想起了第一天。摔碎的观察瓶。拦住敏浩的秀雅。还有没有人问一句的诗宇。", "내 {w}: 「저는 ‘괜찮아?’라고 먼저 묻는 반장이 되겠습니다. 저는 전학 온 첫날, 아무것도 못 알아들었습니다. 누가 먼저 물어봐 주면 좋겠다고 생각했습니다.」": "我的{w}：「我会做一个先问「你还好吗？」的班长。我转学来的第一天，什么都听不懂。我很希望有人先来问问我。」", "수아가 그걸 읽었다. 한참 말이 없었다.": "秀雅读完了。好久都没说话。", "……이건 내가 못 쓰는 거다.": "……这个我写不出来。", "{m}, 수아한테 내 연설문 보여 줬는데, 수아가 이거 나잖아, 그랬어.": "{m}，我给秀雅看了我的演讲稿，秀雅说：「这不就是我嘛。」", "응? 무슨 말이야?": "嗯？什么意思？", "규칙 번호도 수아처럼 쓰고, 수아가 첫날 한 말도 썼거든. 나도 모르게.": "我像秀雅一样写了规则号码，还写了秀雅第一天说的话。我自己都没发现。", "아…… 수아처럼 되고 싶다고 했었지.": "啊……你说过想变成秀雅那样嘛。", "수아가 잘하니까 그냥 두겠다고 했어. 근데 수아가 그럼 너랑 나랑 뭐가 다르냐고 했어.": "我说秀雅做得好，我就这样不改了。可秀雅问：「那你和我有什么不一样？」", "뭐라고 대답했어?": "你怎么回答的？", "……대답 못 했어.": "……我没答上来。", "그 질문은 오늘 밤에 천천히 생각해 봐도 돼.": "这个问题，今晚可以慢慢想。", "그럼 반대로 규칙 없는 반 하겠다고 했어. 근데 수아가 나 대피 훈련 때 규칙 덕분에 길 찾았잖아, 그러더라.": "那我就说反过来，做一个没有规则的班。可秀雅说，我逃生演习的时候是靠规则才找到路的。", "수아한테 한 방 맞았네.": "被秀雅说中了呀。", "응. 반대로 하는 것도 결국 수아 따라 한 거래.": "嗯。她说反着来，其实也是在学她。", "수아한테 내 장점 말해 달라고 했어. 나도 수아 장점 말해 주고.": "我请秀雅说说我的优点。我也说了秀雅的优点。", "나는 못 알아듣는 애를 알아본대. 막히면 몸으로 하고. 그래서 ‘괜찮아?’라고 먼저 묻는 반장이라고 썼어.": "她说我能看出谁听不懂。说不出来的时候会用身体比画。所以我写了，要做一个先问「你还好吗？」的班长。", "와, 그거 너다.": "哇，这就是你呀。", "지우고 다시 썼어. 첫날 시우 생각이 났거든. 아무도 시우한테 괜찮냐고 안 물어봤잖아.": "我擦掉重新写了。因为我想起了第一天的诗宇。那天没有一个人问诗宇还好吗。", "그날 {w}에 썼던 거?": "就是那天你在{w}上写的？", "응. 수아가 그건 자기가 못 쓰는 거래.": "嗯。秀雅说这个她写不出来。", "네가 겪은 일이니까 너만 쓸 수 있지.": "因为是你经历过的事，只有你能写呀。", "방과 후. 수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "放学后。我和秀雅说好互相听对方的演讲。走进空教室时，秀雅已经先到了。", "나 먼저 할게. 시간 재 줘.": "我先来。帮我计时。", "「{x}」로 시간 재기": "用「{x}」计时", "수아의 연설은 1분 40초. 막힘이 없었다.": "秀雅的演讲是1分40秒。一点都没卡住。", "좋아. 근데 중간에 너무 빨라. 공약 2번에서 숨 한 번 쉬어.": "很好。不过中间太快了。讲到第2条竞选承诺的时候，吸一口气。", "……알았어. 숨 쉬기.": "……知道了。吸气。", "이번엔 내 차례였다. 나는 {w}을 들고 섰다. 고친 연설문이었다. 2분 30초가 걸렸다.": "这次轮到我了。我拿着{w}站起来。是改过的演讲稿。用了2分30秒。", "수아가 팔짱을 꼈다.": "秀雅抱起了胳膊。", "솔직히 말해도 돼?": "我可以说实话吗？", "무슨 말인지 모르겠어. 너무 길고, 끝에 그래서 뭘 하겠다는 건지 안 나와.": "我听不懂你想说什么。太长了，最后也听不出你到底要做什么。", "그리고 ‘괜찮아?’ 부분, 좋은데 너무 빨리 지나가.": "还有「你还好吗？」那部分，很好，可是一下子就过去了。", "(밤새 고친 건데.)": "（这是我熬夜改的。）", "「{x}」 한 모금 마시기": "喝一口「{x}」", "교실 창밖이 붉어졌다. 수아가 손바닥을 내밀었다.": "教室窗外变红了。秀雅伸出了手掌。", "이기려고 최선을 다하자.": "为了赢，我们都尽全力吧。", "나는 그 손바닥을 바로 마주치지 못했다. 수아가 {@hand}을 거두고 먼저 나갔다.": "我没能马上和她击掌。秀雅收回了{@hand}，先走了。", "나도 손바닥을 마주쳤다. 짝!": "我也和她击了掌。啪！", "「너 이기려고 일부러 그러는 거지?」": "「你是为了赢我，故意这么说的吧？」", "너 이기려고 일부러 그러는 거지?": "你是为了赢我，故意这么说的吧？", "아니거든. 너도 나한테 숨 쉬라고 했잖아. 나 그거 고칠 거야.": "才不是。你也让我吸口气了呀。我会改的。", "그럼 다른 사람한테 들어 봐. 그게 낫겠다.": "那你去听听别人的意见吧。那样更好。", "수아가 {@bag}을 챙겼다. 연습은 거기서 끝났다.": "秀雅收拾好了{@bag}。练习就到这里结束了。", "「어디가 제일 모르겠어?」 하고 구체적으로 묻는다.": "具体地问她「哪里最听不懂？」", "어디가 제일 모르겠어?": "哪里最听不懂？", "중간에 전학 온 날 얘기. 길어. 그 얘기만 1분이야.": "中间讲转学那天的事。太长了。光那部分就1分钟。", "그럼 그거 반으로 줄이면?": "那把它减一半呢？", "그리고 끝에 한 줄만 넣어. 반장 되면 뭘 할 건지.": "还有，最后只加一句话。当上班长要做什么。", "‘천천히 말해 줘’ 카드 만들기. 그거 넣을게.": "做「请慢慢说」卡片。我加上这个。", "다시 했다. 1분 55초.": "又讲了一遍。1分55秒。", "……이제 알겠다.": "……现在听懂了。", "「길다는 건 고칠게. 근데 ‘괜찮아?’ 부분은 내 방식대로 할래.」": "「太长的地方我会改。不过「你还好吗？」那部分，我要按我的方式来。」", "길다는 건 맞아. 줄일게.": "太长是真的。我会减短。", "근데 ‘괜찮아?’ 부분은 빨리 지나가는 게 아니라 천천히 말할 거야. 그게 나니까.": "不过「你还好吗？」那部分，我不会一下子带过去，我要慢慢说。因为那就是我。", "……천천히?": "……慢慢说？", "응. 거기서 멈췄다가 말할 거야.": "嗯。我会在那里停一下再说。", "다시 했다. 이번엔 ‘괜찮아?’에서 숨을 한 번 멈췄다. 교실이 조용해졌다.": "又讲了一遍。这次讲到「你还好吗？」的时候，我停了一下。教室里安静了。", "……그거 좋다. 그건 너 맞네.": "……这个好。这就是你。", "수아가 말한 대로 전부 고친다.": "秀雅说的全都照着改。", "알았어. 네 말대로 다 고칠게.": "好吧。我全都按你说的改。", "나는 수아가 지적한 걸 다 고쳤다. 전학 온 날 얘기도 빼고, ‘괜찮아?’도 뺐다.": "秀雅指出的地方，我全都改了。转学那天的事删了，「你还好吗？」也删了。", "다시 했다. 1분 30초. 짧고 깔끔했다.": "又讲了一遍。1分30秒。又短又整齐。", "……근데 이제 누구 연설인지 모르겠다.": "……可是现在听不出是谁的演讲了。", "(시키는 대로 했는데.)": "（我是照着她说的做的呀。）", "{m}, 수아랑 서로 연설 들어 줬어.": "{m}，我和秀雅互相听了演讲。", "수아는 1분 40초. 진짜 잘해. 근데 수아가 내 거는 무슨 말인지 모르겠대. 너무 길대.": "秀雅是1分40秒。她真的很厉害。可秀雅说我的听不懂在说什么。说太长了。", "아이고, 밤새 고친 거잖아.": "哎呀，那是你熬夜改的呀。", "나 이기려고 일부러 그러는 거냐고 했어. 수아가 그럼 다른 사람한테 들어 보래.": "我问她是不是为了赢我故意这么说。秀雅说那我去听听别人的意见。", "속상한 마음에 그렇게 말했구나.": "你是心里难过，才那么说的吧。", "근데 나도 수아한테 숨 쉬라고 했잖아. 수아는 그거 고친대.": "可我也让秀雅吸口气了呀。秀雅说她会改。", "……내일 다시 들어 달라고 해 볼래?": "……明天要不要再请她听一次？", "어디가 제일 모르겠냐고 물었어. 전학 온 날 얘기가 너무 길대. 반으로 줄였어.": "我问她哪里最听不懂。她说转学那天的事太长了。我减了一半。", "몇 분 됐어?": "变成几分钟了？", "1분 55초! 수아가 이제 알겠대.": "1分55秒！秀雅说现在听懂了。", "길다는 건 고치겠다고 했어. 근데 ‘괜찮아?’는 내 방식대로 천천히 하겠다고 했어.": "我说太长的地方会改。不过「你还好吗？」我要按自己的方式慢慢说。", "그거 좋대. 그건 나 맞대.": "她说这个好。说这就是我。", "들을 건 듣고, 지킬 건 지켰네.": "该听的听了，该守住的也守住了。", "수아 말대로 다 고쳤어. 짧아졌어. 근데 수아가 이제 누구 연설인지 모르겠대.": "我全都按秀雅说的改了。变短了。可秀雅说现在听不出是谁的演讲了。", "다 빼 버렸구나.": "你全都删掉了呀。", "응. ‘괜찮아?’도 뺐어.": "嗯。「你还好吗？」也删了。", "그건 다시 넣고 싶지 않아?": "那部分你不想再加回去吗？", "……넣을래.": "……我要加回去。", "창체 시간. 선생님이 수아와 나를 앞으로 부르셨다.": "综合活动课。老师把秀雅和我叫到前面。", "선생님: 「오늘 자리 바꾸기는 반장 후보 둘이 같이 진행해 볼래요? 연습이라고 생각하고.」": "老师：「今天换座位，由两位班长候选人一起来主持好吗？就当作练习。」", "나는 수아 옆에 섰다. 수아가 작게 말했다.": "我站到秀雅旁边。秀雅小声说：", "번호 뽑기로 하자. 빠르고 공평해.": "我们抽号码吧。又快又公平。", "「{x}」 줄 맞추기": "把「{x}」排整齐", "그런데 맨 뒤에 앉은 친구가 {@blackboard}을 보느라 눈을 찡그리고 있었다. 지난번 자리 바꿀 때 뒤로 갔던 친구였다.": "可是坐在最后面的同学，为了看{@blackboard}一直眯着眼睛。上次换座位时，他就被换到后面去了。", "(번호 뽑기면…… 또 뒤로 갈 수도 있잖아.)": "（抽号码的话……他可能又会坐到后面。）", "수아야, 근데 눈 나쁜 애들은 앞에 앉아야 하지 않을까? 먼저 물어보면…….": "秀雅，可是眼睛不好的同学，是不是应该坐前面？先问问的话……", "그럼 다들 앞에 앉고 싶다고 하면? 시간 없어. 번호 뽑기가 공평해.": "那要是大家都说想坐前面呢？没时间了。抽号码最公平。", "반 아이들이 우리 둘을 보고 있었다. 누군가 「빨리 해!」 하고 외쳤다.": "全班同学都看着我们俩。有人喊：「快点！」", "자리 바꾸기가 끝났다. 선생님이 둘을 보고 웃으셨다.": "换座位结束了。老师看着我们俩笑了。", "선생님: 「둘이 이끄는 방식이 다르네요.」": "老师：「你们俩带大家的方法不一样呢。」", "수아가 나를 힐끗 봤다.": "秀雅偷偷看了我一眼。", "다르다는 게 칭찬이야, 아니야?": "说不一样，是表扬还是不是？", "……칭찬이겠지?": "……是表扬吧？", "「둘 다 하자. 꼭 앞이어야 하는 사람만 먼저, 나머지는 뽑기.」": "「两个都用。真的必须坐前面的人先选，其他人抽号码。」", "둘 다 하자. 눈 때문에 꼭 앞이어야 하는 사람만 먼저 {@hand} 들고, 나머지는 번호 뽑기.": "两个都用。因为眼睛一定要坐前面的人先举{@hand}，其他人抽号码。", "……‘꼭’인 사람만?": "……只有「一定要」的人？", "응. 그냥 앞이 좋은 건 안 되고.": "嗯。只是喜欢前面可不行。", "좋아. 정리하면, 꼭인 사람 먼저, 나머지 뽑기.": "好。总结一下，一定要的人先选，其他人抽号码。", "세 명이 {@hand}을 들었다. 나머지는 수아가 번호를 뽑았다. 5분 만에 끝났다.": "三个人举起了{@hand}。剩下的由秀雅抽号码。5分钟就结束了。", "반 친구들에게 어떤 방식이 좋은지 묻는다.": "问全班同学哪种方法好。", "얘들아, 두 가지 방법이 있어. 번호 뽑기, 아니면 먼저 사정 있는 사람 물어보고 정하기. {@hand} 들어 줘.": "同学们，有两种方法。抽号码，或者先问问有特殊情况的人再决定。请举{@hand}。", "아이들이 {@hand}을 들었다. 거의 반반이었다.": "同学们举起了{@hand}。差不多一半一半。", "반반이네.": "一半一半呢。", "아이: 「그럼 섞어!」": "同学：「那就混在一起！」", "결국 사정 있는 사람 먼저, 나머지는 뽑기가 됐다.": "最后决定，有特殊情况的人先选，其他人抽号码。", "……애들이 정하니까 아무도 불만이 없네.": "……让同学们自己决定，就没有人不满意了。", "「알았어. 네 방식대로 하자.」": "「好吧。按你的方法来。」", "……알았어. 네 방식대로 하자.": "……好吧。按你的方法来。", "번호 뽑기로 정했다. 빨랐다. 눈을 찡그리던 친구는 이번에도 맨 뒤가 됐다.": "最后决定抽号码。很快。那个眯眼睛的同学这次又坐到了最后面。", "(아까 말할 걸.)": "（刚才应该说出来的。）", "「내 방식이 더 좋아. 다 물어보고 정하자.」": "「我的方法更好。全都问一遍再决定吧。」", "내 방식이 더 좋아. 한 명씩 다 물어보고 정하자.": "我的方法更好。一个一个全都问一遍再决定吧。", "스물네 명을 다?": "二十四个人全都问？", "한 명씩 물어보니 다들 앞이나 창가에 앉고 싶다고 했다. 시간이 다 갔다. 결국 종이 울려서 선생님이 정하셨다.": "一个一个问下来，大家都说想坐前面或者窗边。时间全用完了。最后铃响了，是老师决定的。", "{m}, 오늘 수아랑 둘이 자리 바꾸기 진행했어. 반장 후보 연습이래.": "{m}，今天我和秀雅一起主持了换座位。说是班长候选人的练习。", "와, 둘이서? 어떻게 했어?": "哇，你们俩一起？怎么做的？", "수아는 번호 뽑기가 공평하대. 근데 맨 뒤 애가 {@blackboard} 보느라 눈을 찡그리고 있었어.": "秀雅说抽号码最公平。可是最后面的同学为了看{@blackboard}一直眯着眼睛。", "꼭 앞이어야 하는 사람만 먼저 하고, 나머지는 뽑기로 하자고 했어.": "我说真的必须坐前面的人先选，其他人抽号码。", "수아 방식이랑 네 방식을 섞었구나.": "你把秀雅的方法和你的方法合在一起了呀。", "응. 5분 만에 끝났어. 수아가 정리하면, 이러면서 정리했어.": "嗯。5分钟就结束了。秀雅说着「总结一下」，把事情理清楚了。", "애들한테 어떤 방법이 좋냐고 물어봤어. 반반이었는데 누가 섞자고 해서 섞었어.": "我问同学们哪种方法好。结果一半一半，有人说混在一起，我们就混在一起了。", "반 아이들이 정했네.": "是全班同学自己决定的呢。", "응. 수아가 애들이 정하니까 불만이 없대.": "嗯。秀雅说让同学们决定，就没人不满意了。", "그냥 수아 방식대로 했어. 근데 그 애가 또 맨 뒤 됐어.": "我就按秀雅的方法做了。可那个同学又坐到了最后面。", "아쉬웠겠다.": "一定很可惜吧。", "응. 아까 말할 걸.": "嗯。刚才应该说出来的。", "다음엔 말해 봐. 너 그 애 눈 찡그리는 거 봤잖아.": "下次说说看。你看见那个同学眯眼睛了嘛。", "내 방식대로 다 물어보자고 했는데, 다들 앞이나 창가래. 결국 시간 다 가서 선생님이 정하셨어.": "我说按我的方法全都问一遍，可大家都说要前面或者窗边。最后时间用完了，是老师决定的。", "스물네 명한테 다 물어봤어?": "你把二十四个人全都问了？", "응…… 수아 말도 맞았어. 시간이 없었어.": "嗯……秀雅说得也对。时间不够。", "방과 후. 복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "放学后。秀雅站在走廊的窗边。我走到秀雅旁边。", "{@window}이 열리고 운동장 소리가 들어왔다.": "{@window}开着，操场的声音传了进来。", "이거 기억나?": "你还记得这个吗？", "수아가 {@bag}에서 접힌 {@paper}를 꺼냈다.": "秀雅从{@bag}里拿出一张折起来的{@paper}。", "처음 도서관에서 만든 규칙표였다. 귀퉁이에 수아가 그린 빨래판 {@stairs}도 그대로 있었다.": "是第一次在图书馆做的规则表。角落里秀雅画的、像洗衣板一样的{@stairs}还在。", "이거 아직 갖고 있었어?": "这个你还留着？", "응. 버리기 아까워서.": "嗯。舍不得扔。", "수아가 창밖 운동장을 봤다.": "秀雅看着窗外的操场。", "있잖아. 만약에 네가 반장 되면, 나한테 뭘 맡길 거야?": "我问你。要是你当上班长，你会交给我什么事？", "……갑자기?": "……怎么突然问这个？", "궁금해서. 진짜로.": "我想知道。真的。", "수아가 규칙표를 다시 접어 내 {@hand}에 쥐여 줬다.": "秀雅把规则表重新折好，塞到我{@hand}里。", "그럼 너는? 네가 반장 되면 나한테 뭘 맡길 거야?": "那你呢？要是你当上班长，你会交给我什么事？", "너한테는 ‘새 친구 도우미’. 넌 뭐가 어려운지 아니까.": "给你「新朋友小帮手」。因为你知道什么事难。", "……아, 근데 그 전에 물어볼게. 하고 싶은지.": "……啊，不过在那之前我会先问你。问你想不想做。", "(처음엔 수아처럼 되고 싶었어.)": "（一开始，我想变成秀雅那样。）", "(지금은…… 수아랑 같이 하고 싶어.)": "（现在……我想和秀雅一起做。）", "「네가 잘하는 거. 대신 혼자 다 안 하게 나눠서.」": "「你擅长的事。不过要分着做，不能一个人全做。」", "네가 잘하는 거. 정리하는 거, 시간 재는 거.": "你擅长的事。整理东西，还有计时。", "대신 혼자 다 안 하게 나눠서. 신청서 때처럼 혼자 뛰어다니면 안 돼.": "不过要分着做，不能一个人全做。不能像报名表那次一样，一个人跑来跑去。", "……그거 기억하네.": "……你还记得那件事啊。", "알았어. 나눠서.": "好。分着做。", "「아무것도. 내가 다 할 거야.」": "「什么都不交给你。我全都自己做。」", "아무것도 안 맡길 거야. 내가 다 할 거야.": "什么都不交给你。我全都自己做。", "……그거 나잖아.": "……这不就是我嘛。", "응. 너 따라 해 봤어.": "嗯。我学你的。", "그러다 쓰러져. 나 해 봐서 알아.": "那样会累倒的。我试过，我知道。", "수아가 웃었다. 농담이었지만, 수아는 진짜 대답을 기다리는 얼굴이었다.": "秀雅笑了。虽然是开玩笑，可秀雅的脸像在等一个真正的回答。", "「부반장 해 줘.」": "「当副班长吧。」", "부반장 해 줘.": "当副班长吧。", "벌써 정했어? 나한테 물어보지도 않고?": "你已经决定了？都不问问我？", "부반장이 싫다는 게 아니라, 먼저 물어보라고.": "我不是不想当副班长，是要你先问我。", "「네가 하고 싶은 걸 먼저 물어볼래.」": "「我想先问问你想做什么。」", "네가 하고 싶은 걸 먼저 물어볼래.": "我想先问问你想做什么。", "내가 하고 싶은 거?": "我想做的事？", "응. 넌 늘 해야 하는 걸 하잖아. 하고 싶은 건 뭔데?": "嗯。你总是做必须做的事嘛。那你想做什么？", "수아가 한참 생각했다.": "秀雅想了好久。", "……{@picture} 규칙표. 그거 계속 만들고 싶어. {@picture}은 네가 그리고.": "……{@picture}规则表。我想一直做下去。{@picture}由你来画。", "{m}, 수아가 처음 만든 규칙표 아직 갖고 있었어. 빨래판 {@stairs} 그대로.": "{m}，秀雅还留着第一次做的规则表。像洗衣板的{@stairs}也还在。", "그 {@stairs}?": "那个{@stairs}？", "응. 그리고 수아가 나 반장 되면 자기한테 뭘 맡길 거냐고 물었어.": "嗯。还有，秀雅问我，要是我当上班长，会交给她什么事。", "네가 잘하는 거, 대신 혼자 다 하지 말고 나눠서 하라고 했어.": "我说交给她擅长的事，不过不要一个人全做，要分着做。", "신청서 때 일 기억하냐고. 알았대.": "我问她还记不记得报名表那次。她说知道了。", "아무것도 안 맡기고 내가 다 한다고 했어. 수아 따라 한 거야.": "我说什么都不交给她，我全都自己做。我是在学秀雅。", "그러다 쓰러진대. 자기가 해 봐서 안대.": "她说那样会累倒的。她说她试过，所以知道。", "부반장 해 달라고 했어. 근데 수아가 물어보지도 않고 정하냐고.": "我请她当副班长。可是秀雅说，都不问问她就决定了吗。", "싫다고 한 거야?": "她说不愿意吗？", "아니. 먼저 물어보래.": "不是。她让我先问她。", "하고 싶은 거 먼저 물어보겠다고 했어. 수아가 한참 생각하더니, {@picture} 규칙표 계속 만들고 싶대.": "我说想先问问她想做什么。秀雅想了好久，说想一直做{@picture}规则表。", "수아가 하고 싶은 걸 처음 들었네.": "你第一次听到秀雅想做的事呢。", "수아는 반장 되면 나한테 새 친구 도우미 맡긴대. 내가 뭐가 어려운지 아니까. 근데 먼저 물어보겠대.": "秀雅说如果她当上班长，会让我当新朋友小帮手。因为我知道什么事难。不过她会先问我。", "둘 다 서로한테 물어보네.": "你们俩都在问对方呢。", "응. {m}, 나 처음엔 수아처럼 되고 싶었거든.": "嗯。{m}，我一开始想变成秀雅那样。", "지금은?": "现在呢？", "지금은 수아랑 같이 하고 싶어.": "现在我想和秀雅一起做。", "결과 발표가 끝났다. 교실은 시끄러웠다. 나는 수아를 찾아 복도 창가로 갔다. 수아가 먼저 와 있었다.": "结果公布完了。教室里很吵。我去走廊窗边找秀雅。秀雅已经先到了。", "축하해.": "恭喜你。", "솔직히 속상해. 많이.": "说实话，我很难过。非常难过。", "수아는 울지 않았다. 대신 형광펜을 꽉 쥐고 있었다.": "秀雅没有哭。但她紧紧握着荧光笔。", "근데 너 ‘괜찮아?’ 할 때. 나도 거기서 조용해졌어.": "不过你说「你还好吗？」的时候，我也在那里安静下来了。", "……규칙 정리하는 거 필요하면 말해. 아, 물어보는 거 맞지? 물어볼게. 필요해?": "……要是需要整理规则，就跟我说。啊，要先问对吧？我问你。需要吗？", "응. 필요해.": "嗯。需要。", "그럼 다음 선거 때 보자. 그땐 진짜 안 질 거야.": "那下次选举再见。到时候我真的不会输了。", "수아가 {@blackboard} 쪽을 돌아봤다. {@blackboard}에는 두 이름이 나란히 적혀 있었다. 내 이름, 그리고 수아 이름.": "秀雅回头看向{@blackboard}。{@blackboard}上并排写着两个名字。我的名字，还有秀雅的名字。", "……같이래.": "……说是一起。", "응. 같이.": "嗯。一起。", "나 혼자 되고 싶었어. 조금.": "我想一个人当选。有一点点。", "나도. 조금.": "我也是。有一点点。", "둘이 동시에 웃음이 터졌다.": "我们俩同时笑了出来。", "정리하면, 반장이 둘이야. 그럼 뭐부터 나눠?": "总结一下，班长有两个。那先分什么？", "……그거 먼저 물어보는 거 맞지?": "……这个要先问，对吧？", "응. 이번엔 내가 먼저 물을게. 너는 뭐 하고 싶어?": "嗯。这次我先问。你想做什么？", "새로 온 친구 챙기기. 그리고 바뀌는 거 미리 알려 주기.": "照顾新来的同学。还有提前告诉大家会有什么变化。", "그럼 나는 회의 정리랑 시간 재기. 규칙표는 같이.": "那我负责整理会议和计时。规则表一起做。", "{@picture}은 내가.": "{@picture}我来画。", "{@stairs}도 너.": "{@stairs}也是你。", "첫날 너 나 보고 멋있다고 생각했지? 민호 막을 때.": "第一天你看着我，觉得我很帅吧？就是拦住敏浩的时候。", "……어떻게 알았어?": "……你怎么知道？", "얼굴에 다 쓰여 있었어. 근데 지금은 내가 너 보고 그래.": "全都写在你脸上了。不过现在，是我看着你这么想。", "목이 따끔했다. 나는 창밖만 봤다.": "我的喉咙有点刺痛。我只看着窗外。", "너 ‘괜찮아?’ 할 때, 애들 다 조용해졌어. 나 그거 무서웠어. 질 줄 알았어.": "你说「你还好吗？」的时候，同学们全都安静了。我好害怕。我以为我会输。", "……진짜?": "……真的？", "응. 그래서 말인데, 새 친구 도우미. 해 볼래? 하고 싶은지 먼저 묻는 거야.": "嗯。所以我想说，新朋友小帮手，你想试试吗？我是先问你想不想做哦。", "(속상해. 근데 수아가 진짜로 물어봤어.)": "（我很难过。可是秀雅真的问我了。）", "……생각해 볼게. 근데 아마 할 것 같아.": "……我想一想。不过我应该会做。", "정리하면, 할 거라는 거지?": "总结一下，就是你会做，对吧？", "……우리 둘 다 떨어졌네.": "……我们俩都落选了。", "정리하면, 둘이 표를 나눠 가졌다는 거지.": "总结一下，就是我们俩把票分掉了。", "둘 다 잠깐 말이 없었다. 교실 안에서 새 반장이 친구들한테 둘러싸여 있었다.": "我们俩都沉默了一会儿。教室里，新班长被同学们围着。", "……우리 가서 축하해 줄까?": "……我们要不要去祝贺他？", "응. 같이 가자.": "嗯。一起去吧。", "그리고 규칙표는 반장 아니어도 만들 수 있잖아.": "还有，规则表不当班长也能做嘛。", "수아가 먼저 말했다.": "秀雅先开口了。", "떨어졌다.": "我落选了。", "……내가 돼서 미안. 아니, 미안한 건 아닌데. 그냥.": "……我当选了，对不起。不，也不是对不起。就是……", "……우리 둘 다.": "……我们俩都是。", "수아가 창틀에 팔을 걸쳤다. 나도 옆에 섰다. 어깨가 거의 닿을 만큼.": "秀雅把胳膊搭在窗台上。我也站在她旁边。肩膀都快碰到了。", "있잖아. 선거 끝나면 경쟁자 아니잖아.": "我问你。选举结束了，我们就不是对手了吧。", "그럼 이제 뭐야, 우리?": "那我们现在算什么？", "……그냥 친구?": "……普通朋友？", "그냥은 별로야. 정리해 봐.": "「普通」不太好。总结一下。", "음…… 제일 친한 친구.": "嗯……最好的朋友。", "수아가 형광펜을 꺼내더니 자기 손등에 작게 별을 그렸다. 그리고 내 손등에도 그렸다.": "秀雅拿出荧光笔，在自己的手背上画了一颗小星星。然后在我的手背上也画了一颗。", "정리 완료. 지워지면 다시 그려 줄게.": "总结完毕。擦掉了我再给你画。", "……떨어졌네.": "……落选了呢。", "근데 너 아까 발표 끝나자마자 {bff}한테 먼저 갔지?": "不过你刚才结果一公布，就先去找{bff}了吧？", "……봤어?": "……你看见了？", "응. {bff}도 너 찾고 있었어. 둘이 똑같은 얼굴이던데.": "嗯。{bff}也在找你。你们俩的表情一模一样。", "수아가 웃었다.": "秀雅笑了。", "반장보다 그게 더 어려울걸. 한 사람이랑 진짜 친해지는 거.": "那可能比当班长还难。跟一个人真正成为好朋友。", "……나는 아직 그런 친구 없어. 다들 반장한테 말 거는 거라서.": "……我还没有那样的朋友。大家跟我说话，都是因为我是班长。", "너도 생길 거야.": "你也会有的。", "정리하면, 나도 좀 덜 바빠야 한다는 거지.": "总结一下，就是我也得少忙一点。", "복도 창가에 나 혼자가 아니었다. 그룹 친구들이 우르르 따라 나왔다. 그 안에 수아도 있었다.": "走廊窗边不只有我一个人。小组的朋友们一窝蜂地跟了出来。秀雅也在里面。", "……떨어졌다.": "……落选了。", "아, 나는 됐지. 근데 우리 중에선 나 혼자네.": "啊，我是当选了。不过我们中间只有我一个。", "친구들이 웃었다.": "朋友们笑了。", "친구들이 서로 어깨를 툭툭 쳤다. 누가 「괜찮아, 괜찮아」 했다. 내가 맨날 하던 말이었다.": "朋友们互相拍了拍肩膀。有人说「没关系，没关系」。那是我每天都说的话。", "우리 반장 아니어도 할 거 많잖아. 정리해 볼까?": "我们不当班长，也有很多事可以做嘛。要不要总结一下？", "또 정리해?": "又要总结？", "응. 1번, 점심에 같이 앉기. 2번, 규칙표 만들기. 3번……": "嗯。1号，午饭一起坐。2号，做规则表。3号……", "친구들: 「3번은 놀기!」": "朋友们：「3号是玩！」", "……3번 놀기. 통과.": "……3号，玩。通过。", "떨어졌네.": "落选了呢。", "그때 교실 {@door}이 열리고, 내 그룹 친구들이 나를 찾아 나왔다. 「야, 어디 갔었어!」": "这时教室的{@door}开了，我小组的朋友们出来找我。「喂，你去哪儿了！」", "……너 찾으러 왔네.": "……他们来找你了。", "부럽다. 반장 되면 다들 일 얘기만 하러 오거든. 너는 그냥 너라서 오는 거잖아.": "真羡慕。当了班长，大家来找我都只是说事情。你不一样，大家来找你，就因为你是你。", "……너도 같이 갈래? 점심 같이 먹자.": "……你也一起去吗？一起吃午饭吧。", "수아가 잠깐 망설였다. 그러더니 형광펜 뚜껑을 딸깍 닫았다.": "秀雅犹豫了一下。然后咔嗒一声盖上了荧光笔的盖子。", "……한 번만.": "……就一次。", "……나는 됐고.": "……我是当选了。", "응. 괜찮아.": "嗯。没关系。", "그때 교실 안에서 누가 외쳤다.": "这时教室里有人喊：", "야! 이거 너네 나라 말로 뭐라고 해? 빨리 와 봐!": "喂！这个用你们国家的话怎么说？快过来看！", "교실 뒤 게시판에는 두 나라 말로 된 낱말 카드가 붙어 있었다. {@desk}, {w}, {@cat}, 나비. 아이들이 하나씩 붙인 거였다.": "教室后面的公告栏上，贴着用两个国家的语言写的单词卡。{@desk}、{w}、{@cat}、蝴蝶。是同学们一张一张贴上去的。", "저거 언제 저렇게 됐어?": "那是什么时候变成那样的？", "……나도 몰라. 애들이 하나씩 물어보더니.": "……我也不知道。同学们一个一个来问我，就变成这样了。", "{U@notebook}.": "{U@notebook}。", "수아가 우리 말로 말했다. 발음이 좀 틀렸다.": "秀雅用我们国家的话说了一句。发音有点不对。", "응. 맞아.": "嗯。对了。", "……반장보다 그게 더 멋있다. 반 애들이 너한테 배우잖아.": "……这比当班长还厉害。全班同学都在跟你学呢。", "정리하면, 너는 선생님이고 나는 학생이야. 오늘만.": "总结一下，你是老师，我是学生。只限今天。", "……나는 됐어.": "……我当选了。", "수아가 내 {@hand}에 들린 {w}을 봤다.": "秀雅看着我{@hand}里拿着的{w}。", "첫날 쓴 거. 반 친구 이름.": "第一天写的那个。班上同学的名字。", "{w}을 펼쳤다. 첫날 적은 이름 몇 개 밑에, 새 이름이 몇 개 더 있었다. 수아 이름도 있었다.": "我打开了{w}。第一天写的几个名字下面，又多了几个新名字。秀雅的名字也在。", "다음 학기에 또 나가?": "下学期你还参选吗？", "……응. 나갈래.": "……嗯。我要参选。", "그럼 그때는 이름 더 많이 적어 와. 다 적으면 나 진짜 질 수도 있겠다.": "那到时候多写几个名字来。全都写满的话，我可能真的会输。", "다음 학기에 보자. 경쟁자.": "下学期见。对手。", "{m}, 선거 결과 나왔어.": "{m}，选举结果出来了。", "나 됐어! 수아가 축하한다고 했어. 근데 많이 속상하대.": "我当选了！秀雅说恭喜我。可她说她很难过。", "축하해. 그리고 그걸 솔직하게 말해 준 수아도 대단하다.": "恭喜你。还有，秀雅能这么诚实地说出来，也很了不起。", "수아가 필요하면 도와준대. 먼저 물어보고.": "秀雅说需要的话她会帮我。会先问我。", "나랑 수아랑 둘 다 반장 됐어! 같이!": "我和秀雅都当上班长了！一起！", "둘 다? 와, 축하해!": "两个人都当上了？哇，恭喜！", "수아가 혼자 되고 싶었대, 조금. 나도 조금 그랬다고 했어. 둘이 웃었어.": "秀雅说她想一个人当选，有一点点。我说我也有一点点。我们俩都笑了。", "솔직한 반장 둘이네.": "两个诚实的班长呢。", "수아가 먼저 뭐 하고 싶냐고 물어봤어. 나는 새 친구 챙기기, 수아는 회의 정리.": "秀雅先问我想做什么。我负责照顾新朋友，秀雅负责整理会议。", "수아가 됐어.": "秀雅当选了。", "……속상하지?": "……很难过吧？", "응. 근데 수아가 새 친구 도우미 하고 싶은지 물어봤어. 할 것 같아.": "嗯。可是秀雅问我想不想当新朋友小帮手。我应该会做。", "반장 아니어도 할 수 있는 일이 생겼네.": "不当班长，也有能做的事了呢。", "나도 수아도 떨어졌어. 둘이 같이 가서 새 반장 축하해 줬어.": "我和秀雅都落选了。我们俩一起去祝贺了新班长。", "그거 쉽지 않은데.": "那可不容易呢。", "수아가 규칙표는 반장 아니어도 만들 수 있대.": "秀雅说规则表不当班长也能做。", "떨어졌어. 근데 {m}, 이거 봐.": "我落选了。可是{m}，你看这个。", "나는 손등의 별을 보여 줬다.": "我给她看了手背上的星星。", "이게 뭐야?": "这是什么？", "수아가 그렸어. 제일 친한 친구 표시. 지워지면 다시 그려 준대.": "秀雅画的。是最好的朋友的记号。她说擦掉了会再给我画。", "……반장보다 귀한 거 받았네.": "……你得到了比班长还珍贵的东西呢。", "떨어졌어. 근데 발표 끝나자마자 {bff}한테 먼저 갔어. 수아가 봤대. 둘이 똑같은 얼굴이었대.": "我落选了。可是结果一公布，我就先去找{bff}了。秀雅看见了。她说我们俩的表情一模一样。", "그런 친구가 생겼구나.": "你有了这样的朋友呀。", "수아가 한 사람이랑 진짜 친해지는 게 반장보다 어렵대.": "秀雅说，跟一个人真正成为好朋友，比当班长还难。", "떨어졌어. 근데 우리 그룹이 다 같이 나와서 괜찮다고 해 줬어. 수아도 있었어. 수아가 할 일 정리했어. 3번은 놀기래.": "我落选了。可是我们小组的人一起出来，跟我说没关系。秀雅也在。秀雅把要做的事总结了一下。她说3号是玩。", "제일 중요한 게 3번이네.": "最重要的是3号呢。", "떨어졌어. 근데 우리 그룹 애들이 나 찾으러 왔어. 수아가 부럽대. 나는 그냥 나라서 다들 온다고. 그래서 수아한테 점심 같이 먹자고 했어.": "我落选了。可是我们小组的同学出来找我了。秀雅说她很羡慕。说大家来找我，就因为我是我。所以我请秀雅一起吃午饭。", "한 번만, 이래.": "她说：「就一次。」", "떨어졌어. 근데 {m}, 교실 뒤에 우리 말 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "我落选了。可是{m}，教室后面贴着我们国家语言的单词卡！同学们一个一个来问我，就变成那样了。秀雅也跟着说了{U@notebook}。", "……우리 말을?": "……我们国家的话？", "응. 내가 선생님이래. 오늘만.": "嗯。她说我是老师。只限今天。", "{m}는 오늘이 제일 기쁘다.": "{m}今天最开心了。", "떨어졌어. 근데 첫날 {w} 봤는데, 이름이 좀 늘었어. 수아 이름도 있어.": "我落选了。可是我看了第一天的{w}，名字多了一些。秀雅的名字也在。", "다음 학기엔?": "下学期呢？", "또 나갈 거야. 수아가 그땐 이름 더 많이 적어 오래.": "我还要参选。秀雅说到时候让我多写几个名字来。", "그럼 내일부터 또 한 명씩.": "那从明天开始，再一个一个来。"});
// 10/24 time-neutral wording and {HC}/{HL}/{SN} (양수아_Day2-16R_전면개정.md is the source)
Object.assign(T.en,{"수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "Sua was at the front of the classroom, checking something off with a highlighter. I went over to her.", "{HC}에서 했던 훈련을 떠올려 판단한다.": "Think back to the drills in {HC} and figure it out.", "(전에 다니던 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "(We did this at my old school too. When there's a fire, smoke goes up, so we bent down.)", "전에 다니던 학교에서도 했어.": "We did this at my old school too.", "전에 다니던 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "I remembered the drills at my old school. We bent down because of the smoke. So I did it right.", "{m}, 오늘 대피 훈련 했어. 외워 간 규칙 7번이 나왔어.": "{m}, we had a fire drill today. Rule 7, the one I memorized, came up.", "지난번 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "There might be other kids who only memorized the sounds, like you did at the drill last time.", "나는 처음으로 {@hand}을 들고 {HC}에서 하던 놀이를 말했다. 떨려서 말이 엉켰다.": "For the first time, I raised my {@hand} and talked about a game we played in {HC}. I was nervous, and my words got all tangled.", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. {HC}에서 하던 놀이 하자고.": "{m}, at the class meeting today I raised my {@hand} for the first time. I said we should play a game from {HC}.", "쉬는 시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "Break time. Sua had the class meeting {w} open. I sat down next to her.", "다음 학급회의 때 놀이 발표하잖아. 준비하자.": "We're presenting the game at the next class meeting. Let's get ready.", "둘 다 목소리가 커졌다. 옆에 있던 아이들이 쳐다봤다.": "We both got loud. The kids nearby looked over at us.", "발표 때 떨지 마.": "Don't be nervous when we present.", "{m}, 다음 학급회의에서 {HC} 놀이 다시 발표해.": "{m}, I'm presenting the game from {HC} again at the next class meeting.", "머릿속이 하얘졌다. {HL}로는 바로 떠오르는데, 한국어 낱말이 생각나지 않았다.": "My mind went blank. It came to me right away in {HL}, but I couldn't think of the Korean word.", "(같은…… 뭐였지? 지난번에 수아가 말했는데.)": "(Same... what was it? Sua said it last time.)", "{HL}로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "It comes to me right away in {HL}. If you get caught, you're on one team with the person who caught you. What do you call that in Korean?", "아이: 「{HL}로는 뭔데? 다시 해 봐!」": "A kid: \"What is it in {HL}? Say it again!\"", "아이들이 {HL}를 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "The kids copied the {HL}. Their pronunciation was all wrong. The whole class burst out laughing. I laughed with them.", "{m}! {HC} 놀이 통과됐어!": "{m}! The game from {HC} passed!", "한국말이 생각 안 난다고 솔직하게 말했어. {HL}로 하고, 한국어로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "I said honestly that I couldn't think of it in Korean. I said it in {HL} and asked what it was in Korean, and all the kids told me together.", "응. 애들이 {HL}도 따라 했어. 발음이 엉망이었어.": "Yeah. The kids copied the {HL} too. Their pronunciation was all wrong.", "너는 애들한테 한국어 배우고, 애들은 너한테 {HL} 배우고.": "You learned Korean from them, and they learned {HL} from you.", "{m}, 오늘 체육 시간에 {HC} 놀이 했어.": "{m}, we played the game from {HC} in P.E. class today.", "쉬는 시간. 수아가 자기 자리에서 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "Break time. Sua was at her desk writing her campaign promises. I picked up the {@pencil} I'd been writing my promises with and went over to her.", "수아가 공약 {@paper} 끝에 ‘같이 만든 사람: {SN}’ 하고 고쳐 썼다.": "At the bottom of her campaign {@paper}, Sua wrote: \"Made together with: {SN}.\"", "교실을 나서다가, 복도에서 만난 친한 친구에게 작게 말했다.": "On my way out of the classroom, I quietly told a close friend I ran into in the hallway.", "그 말은 교실에 있던 아이들한테까지 금방 퍼졌다. 수아가 굳은 얼굴로 복도로 나왔다.": "It quickly spread to the kids in the classroom. Sua came out into the hallway with a stiff face.", "자리로 돌아와서 나는 내 {w}을 다시 펴 봤다.": "Back at my seat, I opened my {w} again.", "오늘은 내 생일이었다. {m}가 새벽부터 {HC} 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "Today was my birthday. {m} got up before dawn to make snacks from {HC} and put them in a {@bowl}. To share with my classmates.", "{@bowl} 안에 {HC} 간식이 가득했다.": "The {@bowl} was full of snacks from {HC}.", "({HC}에서는 생일에 이걸 나눠 먹는데…….)": "(In {HC}, we share these on birthdays...)", "「{HC} 음식이라서 싫은 거지?」": "\"You don't like it because it's food from {HC}, right?\"", "{HC} 음식이라서 안 된다는 거지?": "You're saying no because it's food from {HC}, right?", "사진 보여 주면서 {HC}에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "I show a photo and tell everyone we eat this on birthdays in {HC}. I can draw how to make it as a {@picture} too.", "나 수아한테 {HC} 음식이라서 싫은 거냐고 했어.": "I asked Sua if she didn't like it because it's food from {HC}.", "쉬는 시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "Break time. Sua was hurrying to pack her {@bag}. I went over to her.", "다음 쉬는 시간. 수아가 먼저 내 자리로 왔다.": "Next break. Sua came to my seat first.", "이따 다시 오겠다고 하고 갔어. 근데 수아가 다음 쉬는 시간에 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "I said I'd come back later and left. But at the next break Sua came to me first and asked what I wanted to say earlier.", "수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "Sua and I agreed to listen to each other's speeches. When I walked into the empty classroom, Sua was already there.", "수아가 손바닥을 내밀었다.": "Sua held up her palm.", "복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "Sua was standing by the hallway window. I went over next to her.", "야! 이거 {HL}로 뭐라고 해? 빨리 와 봐!": "Hey! How do you say this in {HL}? Come here, quick!", "수아가 {HL}로 말했다. 발음이 좀 틀렸다.": "Sua said it in {HL}. Her pronunciation was a little off.", "떨어졌어. 근데 {m}, 교실 뒤에 {HL} 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "I lost. But {m}, there are {HL} word cards at the back of the classroom! The kids kept asking one at a time, and now it's like that. Sua even repeated {U@notebook}.", "……{HL}를?": "...{HL}?", "수아가 벽에 걸린 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "Sua watched the {@clock} on the wall. I explained from the beginning. It went over 3 minutes."});
Object.assign(T.id,{"수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "Sua sedang mencentang sesuatu dengan stabilo di depan kelas. Aku menghampiri Sua.", "{HC}에서 했던 훈련을 떠올려 판단한다.": "Mengingat latihan di {HC} untuk memutuskan.", "(전에 다니던 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "(Di sekolahku dulu juga ada latihan ini. Kalau ada kebakaran, asap naik ke atas, jadi kami membungkuk.)", "전에 다니던 학교에서도 했어.": "Di sekolahku dulu juga ada latihan ini.", "전에 다니던 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "Aku ingat latihan di sekolahku dulu. Waktu itu kami membungkuk karena asap. Jadi aku melakukannya dengan benar.", "{m}, 오늘 대피 훈련 했어. 외워 간 규칙 7번이 나왔어.": "{m}, hari ini ada latihan evakuasi. Aturan nomor 7 yang aku hafalkan keluar.", "지난번 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "Siapa tahu masih ada anak lain yang cuma menghafal bunyinya, seperti kamu waktu latihan dulu.", "나는 처음으로 {@hand}을 들고 {HC}에서 하던 놀이를 말했다. 떨려서 말이 엉켰다.": "Untuk pertama kalinya aku mengangkat {@hand} dan menceritakan permainan yang dulu kumainkan di {HC}. Aku gugup, jadi bicaraku berantakan.", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. {HC}에서 하던 놀이 하자고.": "{m}, hari ini di rapat kelas aku mengangkat {@hand} untuk pertama kalinya. Aku usul main permainan dari {HC}.", "쉬는 시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "Jam istirahat. Sua sedang membuka {w} rapat kelas. Aku duduk di sebelah Sua.", "다음 학급회의 때 놀이 발표하잖아. 준비하자.": "Di rapat kelas berikutnya kita presentasi permainannya. Ayo bersiap.", "둘 다 목소리가 커졌다. 옆에 있던 아이들이 쳐다봤다.": "Suara kami berdua makin keras. Anak-anak di sebelah menoleh.", "발표 때 떨지 마.": "Waktu presentasi jangan gugup.", "{m}, 다음 학급회의에서 {HC} 놀이 다시 발표해.": "{m}, di rapat kelas berikutnya aku presentasi permainan dari {HC} lagi.", "머릿속이 하얘졌다. {HL}로는 바로 떠오르는데, 한국어 낱말이 생각나지 않았다.": "Kepalaku jadi kosong. Dalam {HL} langsung terpikir, tapi kata bahasa Koreanya tidak teringat.", "(같은…… 뭐였지? 지난번에 수아가 말했는데.)": "(Satu... apa, ya? Dulu Sua sudah bilang.)", "{HL}로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "Dalam {HL} langsung terpikir. Kalau tertangkap, jadi satu kelompok dengan yang menangkap. Ini bahasa Koreanya apa?", "아이: 「{HL}로는 뭔데? 다시 해 봐!」": "Seorang anak: \"Kalau dalam {HL} apa? Coba ucapkan lagi!\"", "아이들이 {HL}를 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "Anak-anak menirukan {HL}. Pengucapannya kacau semua. Kelas tertawa riuh. Aku juga ikut tertawa.", "{m}! {HC} 놀이 통과됐어!": "{m}! Permainan dari {HC} diterima!", "한국말이 생각 안 난다고 솔직하게 말했어. {HL}로 하고, 한국어로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "Aku jujur bilang tidak ingat bahasa Koreanya. Aku bilang dalam {HL}, lalu tanya bahasa Koreanya apa, terus anak-anak sama-sama memberi tahu.", "응. 애들이 {HL}도 따라 했어. 발음이 엉망이었어.": "Iya. Anak-anak juga menirukan {HL}. Pengucapannya kacau.", "너는 애들한테 한국어 배우고, 애들은 너한테 {HL} 배우고.": "Kamu belajar bahasa Korea dari mereka, mereka belajar {HL} darimu.", "{m}, 오늘 체육 시간에 {HC} 놀이 했어.": "{m}, hari ini di jam olahraga kami main permainan dari {HC}.", "쉬는 시간. 수아가 자기 자리에서 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "Jam istirahat. Sua sedang menulis janji kampanye di mejanya. Aku juga membawa {@pencil} yang aku pakai menulis janji kampanye dan menghampiri Sua.", "수아가 공약 {@paper} 끝에 ‘같이 만든 사람: {SN}’ 하고 고쳐 썼다.": "Di ujung {@paper} janji kampanyenya, Sua menulis: \"Dibuat bersama: {SN}.\"", "교실을 나서다가, 복도에서 만난 친한 친구에게 작게 말했다.": "Waktu keluar kelas, aku bilang pelan-pelan ke teman dekat yang kutemui di lorong.", "그 말은 교실에 있던 아이들한테까지 금방 퍼졌다. 수아가 굳은 얼굴로 복도로 나왔다.": "Kata-kata itu cepat menyebar sampai ke anak-anak di kelas. Sua keluar ke lorong dengan wajah kaku.", "자리로 돌아와서 나는 내 {w}을 다시 펴 봤다.": "Kembali ke tempat duduk, aku membuka {w}-ku lagi.", "오늘은 내 생일이었다. {m}가 새벽부터 {HC} 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "Hari ini ulang tahunku. Sejak subuh {m} membuat camilan dari {HC} dan menaruhnya di {@bowl}. Supaya kubagi dengan teman-teman sekelas.", "{@bowl} 안에 {HC} 간식이 가득했다.": "{@bowl} itu penuh camilan dari {HC}.", "({HC}에서는 생일에 이걸 나눠 먹는데…….)": "(Di {HC}, makanan ini dibagi-bagi waktu ulang tahun...)", "「{HC} 음식이라서 싫은 거지?」": "\"Kamu nggak suka karena ini makanan dari {HC}, kan?\"", "{HC} 음식이라서 안 된다는 거지?": "Nggak boleh karena ini makanan dari {HC}, kan?", "사진 보여 주면서 {HC}에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "Aku tunjukkan foto, terus bilang di {HC} ini dimakan waktu ulang tahun. Cara membuatnya juga bisa kugambar jadi {@picture}.", "나 수아한테 {HC} 음식이라서 싫은 거냐고 했어.": "Aku tanya ke Sua, dia nggak suka karena ini makanan dari {HC}, ya.", "쉬는 시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "Jam istirahat. Sua sedang buru-buru membereskan {@bag}. Aku pergi ke Sua.", "다음 쉬는 시간. 수아가 먼저 내 자리로 왔다.": "Jam istirahat berikutnya. Sua yang datang duluan ke tempat dudukku.", "이따 다시 오겠다고 하고 갔어. 근데 수아가 다음 쉬는 시간에 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "Aku bilang nanti datang lagi, terus pergi. Tapi di jam istirahat berikutnya Sua datang duluan dan tanya tadi aku mau ngomong apa.", "수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "Aku dan Sua sepakat saling mendengarkan pidato. Waktu aku masuk ke kelas yang kosong, Sua sudah datang duluan.", "수아가 손바닥을 내밀었다.": "Sua menyodorkan telapak tangannya.", "복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "Sua berdiri di dekat jendela lorong. Aku menghampiri Sua.", "야! 이거 {HL}로 뭐라고 해? 빨리 와 봐!": "Hei! Ini dalam {HL} apa? Cepat ke sini!", "수아가 {HL}로 말했다. 발음이 좀 틀렸다.": "Sua mengucapkannya dalam {HL}. Pengucapannya agak salah.", "떨어졌어. 근데 {m}, 교실 뒤에 {HL} 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "Aku kalah. Tapi {m}, di belakang kelas ada kartu kata {HL}! Anak-anak tanya satu per satu, terus jadi begitu. Sua juga ikut bilang {U@notebook}.", "……{HL}를?": "...{HL}?", "수아가 벽에 걸린 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "Sua melihat {@clock} di dinding. Aku menjelaskan dari awal. Lebih dari 3 menit."});
Object.assign(T.vi,{"수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "Sua đang dùng bút dạ quang đánh dấu gì đó ở phía trước lớp. Mình đi đến chỗ Sua.", "{HC}에서 했던 훈련을 떠올려 판단한다.": "Nhớ lại buổi diễn tập ở {HC} để phán đoán.", "(전에 다니던 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "(Ở trường cũ mình cũng tập cái này. Khi có cháy, khói bay lên trên nên phải cúi người.)", "전에 다니던 학교에서도 했어.": "Ở trường cũ tớ cũng tập rồi.", "전에 다니던 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "Con nhớ ra buổi diễn tập ở trường cũ. Cúi người vì khói ấy. Nên con làm đúng.", "{m}, 오늘 대피 훈련 했어. 외워 간 규칙 7번이 나왔어.": "{m} ơi, hôm nay con diễn tập sơ tán. Quy tắc số 7 con học thuộc có xuất hiện đấy.", "지난번 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "Biết đâu cũng có bạn chỉ thuộc âm giống cậu lần diễn tập trước.", "나는 처음으로 {@hand}을 들고 {HC}에서 하던 놀이를 말했다. 떨려서 말이 엉켰다.": "Lần đầu tiên mình giơ {@hand} lên và kể về trò chơi hồi ở {HC}. Vì run nên lời nói bị rối.", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. {HC}에서 하던 놀이 하자고.": "{m} ơi, hôm nay ở buổi sinh hoạt lớp con giơ {@hand} lần đầu tiên. Con đề nghị chơi trò hồi ở {HC}.", "쉬는 시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "Giờ ra chơi. Sua đang mở {w} sinh hoạt lớp. Mình ngồi cạnh Sua.", "다음 학급회의 때 놀이 발표하잖아. 준비하자.": "Buổi sinh hoạt lớp tới mình trình bày trò chơi mà. Chuẩn bị nào.", "둘 다 목소리가 커졌다. 옆에 있던 아이들이 쳐다봤다.": "Cả hai đều to tiếng. Các bạn bên cạnh quay sang nhìn.", "발표 때 떨지 마.": "Lúc trình bày đừng run nhé.", "{m}, 다음 학급회의에서 {HC} 놀이 다시 발표해.": "{m} ơi, buổi sinh hoạt lớp tới con sẽ trình bày lại trò chơi của {HC}.", "머릿속이 하얘졌다. {HL}로는 바로 떠오르는데, 한국어 낱말이 생각나지 않았다.": "Đầu óc mình trống rỗng. Bằng {HL} thì nghĩ ra ngay, nhưng từ tiếng Hàn thì không nhớ ra.", "(같은…… 뭐였지? 지난번에 수아가 말했는데.)": "(Cùng... là gì nhỉ? Lần trước Sua nói rồi mà.)", "{HL}로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "Bằng {HL} thì tớ nghĩ ra ngay. Bị bắt thì thành một đội với người bắt. Cái này tiếng Hàn nói thế nào?", "아이: 「{HL}로는 뭔데? 다시 해 봐!」": "Một bạn: \"Tiếng {HL} nói thế nào? Nói lại đi!\"", "아이들이 {HL}를 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "Các bạn nói theo tiếng {HL}. Phát âm lung tung hết. Cả lớp cười ồ. Mình cũng cười theo.", "{m}! {HC} 놀이 통과됐어!": "{m} ơi! Trò chơi của {HC} được thông qua rồi!", "한국말이 생각 안 난다고 솔직하게 말했어. {HL}로 하고, 한국어로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "Con nói thật là không nhớ ra tiếng Hàn. Con nói bằng {HL} rồi hỏi tiếng Hàn là gì, thế là các bạn cùng chỉ cho con.", "응. 애들이 {HL}도 따라 했어. 발음이 엉망이었어.": "Vâng. Các bạn còn nói theo tiếng {HL}. Phát âm lung tung hết.", "너는 애들한테 한국어 배우고, 애들은 너한테 {HL} 배우고.": "Con học tiếng Hàn từ các bạn, còn các bạn học tiếng {HL} từ con.", "{m}, 오늘 체육 시간에 {HC} 놀이 했어.": "{m} ơi, hôm nay giờ thể dục con chơi trò của {HC}.", "쉬는 시간. 수아가 자기 자리에서 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "Giờ ra chơi. Sua đang ngồi ở chỗ mình viết lời hứa tranh cử. Mình cũng cầm cây {@pencil} đang viết lời hứa đi về phía Sua.", "수아가 공약 {@paper} 끝에 ‘같이 만든 사람: {SN}’ 하고 고쳐 썼다.": "Ở cuối {@paper} lời hứa, Sua viết thêm: \"Cùng làm với: {SN}.\"", "교실을 나서다가, 복도에서 만난 친한 친구에게 작게 말했다.": "Lúc ra khỏi lớp, mình khẽ nói với một bạn thân gặp ở hành lang.", "그 말은 교실에 있던 아이들한테까지 금방 퍼졌다. 수아가 굳은 얼굴로 복도로 나왔다.": "Lời đó nhanh chóng lan đến các bạn trong lớp. Sua mặt lạnh tanh đi ra hành lang.", "자리로 돌아와서 나는 내 {w}을 다시 펴 봤다.": "Về lại chỗ ngồi, mình mở {w} của mình ra xem lại.", "오늘은 내 생일이었다. {m}가 새벽부터 {HC} 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "Hôm nay là sinh nhật mình. {m} đã dậy từ sáng sớm làm món ăn vặt của {HC} rồi cho vào {@bowl}. Để mình chia cho các bạn trong lớp cùng ăn.", "{@bowl} 안에 {HC} 간식이 가득했다.": "Trong {@bowl} đầy món ăn vặt của {HC}.", "({HC}에서는 생일에 이걸 나눠 먹는데…….)": "(Ở {HC}, sinh nhật là chia nhau ăn món này mà...)", "「{HC} 음식이라서 싫은 거지?」": "\"Vì là món ăn của {HC} nên cậu không thích, đúng không?\"", "{HC} 음식이라서 안 된다는 거지?": "Vì là món ăn của {HC} nên mới không được, đúng không?", "사진 보여 주면서 {HC}에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "Cho mọi người xem ảnh và kể là ở {HC} sinh nhật thì ăn món này. Tớ còn có thể vẽ cách làm thành {@picture} mang đến nữa.", "나 수아한테 {HC} 음식이라서 싫은 거냐고 했어.": "Con hỏi Sua có phải vì là món ăn của {HC} nên bạn ấy không thích không.", "쉬는 시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "Giờ ra chơi. Sua đang vội vàng xếp {@bag}. Mình đi đến chỗ Sua.", "다음 쉬는 시간. 수아가 먼저 내 자리로 왔다.": "Giờ ra chơi sau. Sua chủ động đến chỗ mình trước.", "이따 다시 오겠다고 하고 갔어. 근데 수아가 다음 쉬는 시간에 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "Con bảo lát quay lại rồi đi. Nhưng giờ ra chơi sau Sua đến trước, hỏi lúc nãy con định nói gì.", "수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "Mình và Sua hẹn nghe bài phát biểu của nhau. Vào lớp trống thì Sua đã đến trước rồi.", "수아가 손바닥을 내밀었다.": "Sua chìa lòng bàn tay ra.", "복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "Sua đứng cạnh cửa sổ hành lang. Mình đến bên Sua.", "야! 이거 {HL}로 뭐라고 해? 빨리 와 봐!": "Này! Cái này tiếng {HL} gọi là gì? Ra đây nhanh lên!", "수아가 {HL}로 말했다. 발음이 좀 틀렸다.": "Sua nói bằng tiếng {HL}. Phát âm hơi sai.", "떨어졌어. 근데 {m}, 교실 뒤에 {HL} 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "Con trượt rồi. Nhưng {m} ơi, cuối lớp có dán thẻ từ tiếng {HL}! Các bạn cứ hỏi từng cái một rồi thành thế. Sua cũng nói theo {U@notebook}.", "……{HL}를?": "...Tiếng {HL} á?", "수아가 벽에 걸린 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "Sua nhìn {@clock} trên tường. Mình giải thích từ đầu. Hơn 3 phút."});
Object.assign(T.zh,{"수아가 교실 앞에서 형광펜으로 뭔가를 체크하고 있었다. 나는 수아에게 갔다.": "秀雅在教室前面用荧光笔勾着什么。我走到秀雅身边。", "{HC}에서 했던 훈련을 떠올려 판단한다.": "想想在{HC}做过的演练，自己判断。", "(전에 다니던 학교에서도 이거 했어. 불이 나면 연기가 위로 가니까 몸을 숙였지.)": "（我以前的学校也做过这个。着火时烟往上走，所以要弯下身子。）", "전에 다니던 학교에서도 했어.": "我以前的学校也做过。", "전에 다니던 학교에서 했던 훈련이 생각났어. 연기 때문에 몸 숙였던 거. 그래서 맞게 했어.": "我想起了以前学校做过的演练。因为有烟，要弯下身子。所以我做对了。", "{m}, 오늘 대피 훈련 했어. 외워 간 규칙 7번이 나왔어.": "{m}，今天我们做了逃生演练。我背过的规则第7条用上了。", "지난번 훈련 때 너처럼 소리만 외운 애들이 또 있을 수도 있잖아.": "可能还有同学像上次演练时的你一样，只背了声音呀。", "나는 처음으로 {@hand}을 들고 {HC}에서 하던 놀이를 말했다. 떨려서 말이 엉켰다.": "我第一次举起{@hand}，说了在{HC}玩过的游戏。我太紧张了，话说得乱七八糟。", "{m}, 오늘 학급회의 때 처음으로 {@hand} 들었어. {HC}에서 하던 놀이 하자고.": "{m}，今天班会时我第一次举了{@hand}。说要玩在{HC}玩过的游戏。", "쉬는 시간. 수아가 학급회의 {w}을 펴 놓고 있었다. 나는 수아 옆에 앉았다.": "课间休息。秀雅摊开了班会{w}。我坐在秀雅旁边。", "다음 학급회의 때 놀이 발표하잖아. 준비하자.": "下次班会要介绍游戏嘛。我们准备一下吧。", "둘 다 목소리가 커졌다. 옆에 있던 아이들이 쳐다봤다.": "我们两个声音都变大了。旁边的同学都看了过来。", "발표 때 떨지 마.": "发言的时候别紧张。", "{m}, 다음 학급회의에서 {HC} 놀이 다시 발표해.": "{m}，下次班会上，我要再介绍一次{HC}的游戏。", "머릿속이 하얘졌다. {HL}로는 바로 떠오르는데, 한국어 낱말이 생각나지 않았다.": "我脑子一片空白。用{HL}马上就想得到，可就是想不起韩语的词。", "(같은…… 뭐였지? 지난번에 수아가 말했는데.)": "（同……什么来着？上次秀雅说过的。）", "{HL}로는 바로 생각나는데요. 잡히면 잡은 사람이랑 한 팀이 돼요. 이걸 한국말로 뭐라고 해요?": "用{HL}马上就想得到。被抓到的话，就和抓的人变成一个队。这个用韩语怎么说？", "아이: 「{HL}로는 뭔데? 다시 해 봐!」": "同学：「用{HL}怎么说？再说一遍！」", "아이들이 {HL}를 따라 했다. 발음이 다 엉망이었다. 교실이 와르르 웃었다. 나도 같이 웃었다.": "同学们跟着说{HL}。发音全都乱七八糟。教室里哄堂大笑。我也一起笑了。", "{m}! {HC} 놀이 통과됐어!": "{m}！{HC}的游戏通过了！", "한국말이 생각 안 난다고 솔직하게 말했어. {HL}로 하고, 한국어로 뭐냐고 물었더니 애들이 다 같이 알려 줬어.": "我老实说了想不起韩语。我用{HL}说，再问韩语怎么说，同学们就一起告诉我了。", "응. 애들이 {HL}도 따라 했어. 발음이 엉망이었어.": "嗯。同学们还跟着说{HL}。发音乱七八糟的。", "너는 애들한테 한국어 배우고, 애들은 너한테 {HL} 배우고.": "你跟他们学韩语，他们跟你学{HL}。", "{m}, 오늘 체육 시간에 {HC} 놀이 했어.": "{m}，今天体育课我们玩了{HC}的游戏。", "쉬는 시간. 수아가 자기 자리에서 공약을 쓰고 있었다. 나도 공약을 쓰던 {@pencil}을 들고 수아 쪽으로 갔다.": "课间休息。秀雅在自己座位上写竞选承诺。我也拿着写竞选承诺用的{@pencil}，走到秀雅那边。", "수아가 공약 {@paper} 끝에 ‘같이 만든 사람: {SN}’ 하고 고쳐 썼다.": "秀雅在竞选承诺{@paper}的最后写上：“一起做的人：{SN}”。", "교실을 나서다가, 복도에서 만난 친한 친구에게 작게 말했다.": "走出教室时，我小声地跟在走廊碰到的好朋友说了。", "그 말은 교실에 있던 아이들한테까지 금방 퍼졌다. 수아가 굳은 얼굴로 복도로 나왔다.": "这句话很快就传到了教室里的同学那儿。秀雅板着脸走到了走廊。", "자리로 돌아와서 나는 내 {w}을 다시 펴 봤다.": "回到座位上，我又打开了我的{w}。", "오늘은 내 생일이었다. {m}가 새벽부터 {HC} 간식을 만들어 {@bowl}에 담아 주셨다. 반 친구들이랑 나눠 먹으라고.": "今天是我的生日。{m}一大早就做了{HC}的点心，装在{@bowl}里给我，让我和班上的同学一起分着吃。", "{@bowl} 안에 {HC} 간식이 가득했다.": "{@bowl}里装满了{HC}的点心。", "({HC}에서는 생일에 이걸 나눠 먹는데…….)": "（在{HC}，过生日都要分着吃这个……）", "「{HC} 음식이라서 싫은 거지?」": "「是因为这是{HC}的食物，你才不喜欢吧？」", "{HC} 음식이라서 안 된다는 거지?": "是因为这是{HC}的食物，所以才不行吧？", "사진 보여 주면서 {HC}에선 생일에 이거 먹는다고 말하는 거. 만드는 법도 {@picture}으로 그려 올 수 있어.": "就是一边给大家看照片，一边说在{HC}过生日吃这个。做法也可以用{@picture}画出来。", "나 수아한테 {HC} 음식이라서 싫은 거냐고 했어.": "我问秀雅，是不是因为是{HC}的食物才不喜欢。", "쉬는 시간. 수아가 급하게 {@bag}을 챙기고 있었다. 나는 수아에게 갔다.": "课间休息。秀雅正急急忙忙地收拾{@bag}。我走到秀雅那里。", "다음 쉬는 시간. 수아가 먼저 내 자리로 왔다.": "下一个课间。秀雅先来到了我的座位。", "이따 다시 오겠다고 하고 갔어. 근데 수아가 다음 쉬는 시간에 먼저 와서 아까 무슨 얘기였냐고 물어봤어.": "我说等会儿再来，就走了。可是下一个课间秀雅先来找我，问我刚才想说什么。", "수아와 서로 연설을 들어 주기로 했다. 빈 교실에 들어서자 수아가 먼저 와 있었다.": "我和秀雅说好互相听对方的演讲。走进空教室时，秀雅已经先到了。", "수아가 손바닥을 내밀었다.": "秀雅伸出了手掌。", "복도 창가에 수아가 서 있었다. 나는 수아 옆으로 갔다.": "秀雅站在走廊的窗边。我走到秀雅旁边。", "야! 이거 {HL}로 뭐라고 해? 빨리 와 봐!": "喂！这个用{HL}怎么说？快过来看！", "수아가 {HL}로 말했다. 발음이 좀 틀렸다.": "秀雅用{HL}说了一句。发音有点不对。", "떨어졌어. 근데 {m}, 교실 뒤에 {HL} 낱말 카드가 붙어 있어! 애들이 하나씩 물어보더니 저렇게 됐어. 수아도 {U@notebook} 따라 했어.": "我落选了。可是{m}，教室后面贴着{HL}单词卡！同学们一个一个来问我，就变成那样了。秀雅也跟着说了{U@notebook}。", "……{HL}를?": "……{HL}？", "수아가 벽에 걸린 {@clock}를 봤다. 나는 처음부터 설명했다. 3분이 넘었다.": "秀雅看着墙上的{@clock}。我从头开始讲。超过了3分钟。"});
// 10/25 writer revision
T.en=T.en||{};Object.assign(T.en,{"{m}, 오늘 대피 훈련 했어. 첫날 수아가 물어본다고 해서 외워 간 규칙 7번이 나왔어.": "{m}, we had a fire drill today. Rule 7 came up, the one I memorized because Sua said on my first day she’d ask.", "모르는 거 그 자리에서 물어봤구나. 잘했네.": "You asked about what you didn’t know right then. Well done.", "회의 때 떨지 마.": "Don’t be nervous at the meeting.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 다음에 말해 봐도 늦지 않아.": "Saying you feel hurt and fighting are different things. It’s not too late to say it next time.", "수아가 무슨 말 하려고 했을까? 다음에 물어봐도 되겠다.": "I wonder what Sua wanted to say. Maybe you can ask her next time.", "다음에라도 말해 볼래? 그 말 좀 아팠다고.": "Want to tell her, even next time? That it kind of hurt.", "……다음에 다시 들어 달라고 해 볼래?": "...Want to ask her to listen again next time?"});
T.id=T.id||{};Object.assign(T.id,{"{m}, 오늘 대피 훈련 했어. 첫날 수아가 물어본다고 해서 외워 간 규칙 7번이 나왔어.": "{m}, hari ini ada latihan evakuasi. Aturan nomor 7 keluar, yang aku hafalkan karena di hari pertama Sua bilang mau menanyakannya.", "모르는 거 그 자리에서 물어봤구나. 잘했네.": "Kamu langsung bertanya waktu tidak tahu, ya. Bagus.", "회의 때 떨지 마.": "Waktu rapat jangan gugup.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 다음에 말해 봐도 늦지 않아.": "Bilang kecewa dan bertengkar itu beda. Bilang lain kali juga belum terlambat.", "수아가 무슨 말 하려고 했을까? 다음에 물어봐도 되겠다.": "Sua mau bilang apa, ya? Lain kali kamu bisa tanya dia.", "다음에라도 말해 볼래? 그 말 좀 아팠다고.": "Mau coba bilang lain kali? Bahwa kata-kata itu agak menyakitkan.", "……다음에 다시 들어 달라고 해 볼래?": "...Mau coba minta dia dengar lagi lain kali?"});
T.vi=T.vi||{};Object.assign(T.vi,{"{m}, 오늘 대피 훈련 했어. 첫날 수아가 물어본다고 해서 외워 간 규칙 7번이 나왔어.": "{m} ơi, hôm nay con diễn tập sơ tán. Quy tắc số 7 có xuất hiện đấy, cái con học thuộc vì hôm đầu Sua bảo sẽ hỏi.", "모르는 거 그 자리에서 물어봤구나. 잘했네.": "Con hỏi ngay tại chỗ điều mình không biết à. Giỏi lắm.", "회의 때 떨지 마.": "Lúc họp đừng run nhé.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 다음에 말해 봐도 늦지 않아.": "Nói là mình buồn và cãi nhau là hai chuyện khác nhau. Lần sau nói cũng chưa muộn đâu.", "수아가 무슨 말 하려고 했을까? 다음에 물어봐도 되겠다.": "Sua định nói gì nhỉ? Lần sau con hỏi thử cũng được đấy.", "다음에라도 말해 볼래? 그 말 좀 아팠다고.": "Lần sau con thử nói xem? Là câu đó làm con hơi đau.", "……다음에 다시 들어 달라고 해 볼래?": "...Lần sau con thử nhờ bạn ấy nghe lại nhé?"});
T.zh=T.zh||{};Object.assign(T.zh,{"{m}, 오늘 대피 훈련 했어. 첫날 수아가 물어본다고 해서 외워 간 규칙 7번이 나왔어.": "{m}，今天我们做了逃生演练。第一天秀雅说要考我，我背下来的规则第7条用上了。", "모르는 거 그 자리에서 물어봤구나. 잘했네.": "不懂的当场就问了啊。做得好。", "회의 때 떨지 마.": "开会的时候别紧张。", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 다음에 말해 봐도 늦지 않아.": "说出难过和吵架是不一样的。下次再说也不晚。", "수아가 무슨 말 하려고 했을까? 다음에 물어봐도 되겠다.": "秀雅想说什么呢？下次可以问问她。", "다음에라도 말해 볼래? 그 말 좀 아팠다고.": "下次要不要跟她说说？说那句话让你有点难过。", "……다음에 다시 들어 달라고 해 볼래?": "……下次要不要再请她听一次？"});
T.ja=T.ja||{};Object.assign(T.ja,{"{m}, 오늘 대피 훈련 했어. 첫날 수아가 물어본다고 해서 외워 간 규칙 7번이 나왔어.": "{m}、今日避難訓練があったよ。初日にスアが聞くって言ったから覚えていったルール7番が出たんだ。", "모르는 거 그 자리에서 물어봤구나. 잘했네.": "わからないことをその場で聞いたのね。えらいね。", "회의 때 떨지 마.": "会議のとき、緊張しないでね。", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 다음에 말해 봐도 늦지 않아.": "さみしかったって言うのと、けんかするのは違うことよ。今度言っても遅くないわ。", "수아가 무슨 말 하려고 했을까? 다음에 물어봐도 되겠다.": "スアは何を言おうとしたのかしら？今度聞いてみてもいいわね。", "다음에라도 말해 볼래? 그 말 좀 아팠다고.": "今度でもいいから言ってみる？あの言葉、ちょっと痛かったって。", "……다음에 다시 들어 달라고 해 볼래?": "……今度、もう一度聞いてってお願いしてみる？"});
T.ru=T.ru||{};Object.assign(T.ru,{"{m}, 오늘 대피 훈련 했어. 첫날 수아가 물어본다고 해서 외워 간 규칙 7번이 나왔어.": "{m}, сегодня была учебная эвакуация. Попалось правило номер 7 — то самое, которое Суа в первый день обещала спросить.", "모르는 거 그 자리에서 물어봤구나. 잘했네.": "Не понятно — сразу спрашиваешь. Молодец.", "회의 때 떨지 마.": "Не волнуйся на собрании.", "서운하다고 말하는 거랑 싸우는 건 다른 거야. 다음에 말해 봐도 늦지 않아.": "Сказать, что тебе обидно, и поссориться — это разные вещи. Можно сказать и в следующий раз, ещё не поздно.", "수아가 무슨 말 하려고 했을까? 다음에 물어봐도 되겠다.": "Интересно, что Суа хотела сказать? В следующий раз можешь её спросить.", "다음에라도 말해 볼래? 그 말 좀 아팠다고.": "Может, скажешь ей, хоть в следующий раз? Что эти слова немного ранили.", "……다음에 다시 들어 달라고 해 볼래?": "...Может, попросишь её послушать ещё раз в следующий раз?"});
